# ==============================================================================================
# ROUNDED BUTTONS - every tk.Button below is created as a RoundedButton (rounded corners).
# Set BUTTON_RADIUS to 0 for square corners again, or delete this block (and the
# `tk.Button = RoundedButton` line) to go back to plain Tk buttons.
# ==============================================================================================
BUTTON_RADIUS = 8


def _shade(color, factor):
    """Lighten (>1) or darken (<1) a #rrggbb colour; anything else is returned unchanged."""
    try:
        h = color.lstrip("#")
        if len(h) != 6:
            return color
        r, g, b = (int(h[i:i + 2], 16) for i in (0, 2, 4))
        return "#%02x%02x%02x" % tuple(max(0, min(255, int(c * factor))) for c in (r, g, b))
    except Exception:
        return color


class RoundedButton(tk.Canvas):
    """tk.Button look-alike drawn on a Canvas so the corners can be rounded.

    Understands the options this app uses (text, command, bg, fg, active*, font, padx, pady, width,
    state, cursor, highlightthickness/highlightbackground as an outline) and the usual
    config()/configure()/invoke(). Options that make no sense on a canvas (relief, bd, ...) are ignored.
    """
    _IGNORED = ("relief", "bd", "borderwidth", "anchor", "justify", "wraplength", "takefocus",
                "image", "compound", "height", "overrelief", "underline", "highlightcolor",
                "repeatdelay", "repeatinterval", "textvariable", "default")

    def __init__(self, parent, text="", command=None, bg=None, fg="black", font=None,
                 activebackground=None, activeforeground=None, disabledforeground="#a3a3a3",
                 padx=8, pady=4, width=None, state="normal", cursor="hand2",
                 highlightthickness=0, highlightbackground=None, **kw):
        for k in self._IGNORED:
            kw.pop(k, None)
        kw.pop("background", None)
        kw.pop("foreground", None)
        self._parent_bg = self._lookup_parent_bg(parent, "#f0f0f0")
        self._bg = bg if bg is not None else self._parent_bg
        super().__init__(parent, bg=self._parent_bg, highlightthickness=0, bd=0, cursor=cursor, **kw)
        self._text, self._command = text, command
        self._fg, self._font = fg, font
        self._abg, self._afg, self._dfg = activebackground, activeforeground, disabledforeground
        self._padx, self._pady, self._wchars = int(padx), int(pady), width
        self._state = str(state)
        self._hl = int(highlightthickness or 0)
        self._hlc = highlightbackground
        self._hover = self._pressed = False
        self._resize()
        self.bind("<Enter>", lambda e: self._set_hover(True), add="+")
        self.bind("<Leave>", lambda e: self._set_hover(False), add="+")
        self.bind("<ButtonPress-1>", self._on_press, add="+")
        self.bind("<ButtonRelease-1>", self._on_release, add="+")
        self.bind("<Configure>", lambda e: self._draw(), add="+")

    @staticmethod
    def _lookup_parent_bg(parent, fallback):
        try:
            return parent.cget("bg")
        except Exception:
            return fallback

    def _resize(self):
        try:
            import tkinter.font as _tkfont
            f = _tkfont.Font(font=self._font) if self._font else _tkfont.nametofont("TkDefaultFont")
            tw = f.measure("0") * int(self._wchars) if self._wchars else f.measure(self._text)
            h = f.metrics("linespace")
        except Exception:
            tw, h = 8 * len(self._text), 16
        tk.Canvas.configure(self, width=tw + 2 * self._padx + 2, height=h + 2 * self._pady + 2)
        self._draw()

    def _draw(self):
        try:
            self._parent_bg = self._lookup_parent_bg(self.master, self._parent_bg)
            tk.Canvas.configure(self, bg=self._parent_bg)
            self.delete("all")
            w, h = self.winfo_width(), self.winfo_height()
            if w < 4 or h < 4:                       # not mapped yet - use the requested size
                w, h = self.winfo_reqwidth(), self.winfo_reqheight()
            fill, fg = self._bg, self._fg
            if self._state == "disabled":
                fg = self._dfg
            elif self._pressed:
                fill = _shade(self._bg, 0.85)
                fg = self._afg or fg
            elif self._hover:
                if self._abg and self._abg != self._bg:
                    fill = self._abg
                elif self._bg != self._parent_bg:    # flat "link" buttons (same colour as parent) get no hover pill
                    fill = _shade(self._bg, 1.12)
                fg = self._afg or fg
            outline = self._hlc if (self._hl and self._hlc) else fill
            lw = max(self._hl, 1) if (self._hl and self._hlc) else 1
            m = lw / 2.0
            x1, y1, x2, y2 = m, m, w - m - 1, h - m - 1
            r = max(0, min(BUTTON_RADIUS, (x2 - x1) / 2, (y2 - y1) / 2))
            pts = [x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r, x2, y2 - r, x2, y2, x2 - r, y2,
                   x1 + r, y2, x1, y2, x1, y2 - r, x1, y1 + r, x1, y1]
            self.create_polygon(pts, smooth=True, fill=fill, outline=outline, width=lw)
            self.create_text(w / 2, h / 2, text=self._text, fill=fg,
                             **({"font": self._font} if self._font else {}))
        except tk.TclError:
            pass

    def _set_hover(self, v):
        self._hover = v
        if not v:
            self._pressed = False
        self._draw()

    def _on_press(self, _e):
        if self._state != "disabled":
            self._pressed = True
            self._draw()

    def _on_release(self, e):
        if self._state == "disabled" or not self._pressed:
            return
        self._pressed = False
        self._draw()
        if 0 <= e.x < self.winfo_width() and 0 <= e.y < self.winfo_height():
            self.invoke()

    def invoke(self):
        if self._state != "disabled" and self._command:
            return self._command()

    def configure(self, cnf=None, **kw):
        if cnf:
            kw.update(cnf)
        resize = redraw = False
        for k in list(kw):
            v = kw[k]
            if k in self._IGNORED:
                kw.pop(k)
            elif k == "text":
                self._text = v; resize = True; kw.pop(k)
            elif k == "command":
                self._command = v; kw.pop(k)
            elif k in ("bg", "background"):
                self._bg = v; redraw = True; kw.pop(k)
            elif k in ("fg", "foreground"):
                self._fg = v; redraw = True; kw.pop(k)
            elif k == "activebackground":
                self._abg = v; kw.pop(k)
            elif k == "activeforeground":
                self._afg = v; kw.pop(k)
            elif k == "disabledforeground":
                self._dfg = v; redraw = True; kw.pop(k)
            elif k == "font":
                self._font = v; resize = True; kw.pop(k)
            elif k == "padx":
                self._padx = int(v); resize = True; kw.pop(k)
            elif k == "pady":
                self._pady = int(v); resize = True; kw.pop(k)
            elif k == "state":
                self._state = str(v); redraw = True; kw.pop(k)
            elif k == "highlightthickness":
                self._hl = int(v); redraw = True; kw.pop(k)
            elif k == "highlightbackground":
                self._hlc = v; redraw = True; kw.pop(k)
        if kw:
            tk.Canvas.configure(self, **kw)
        if resize:
            self._resize()
        elif redraw:
            self._draw()

    config = configure

    def cget(self, key):
        mapping = {"text": self._text, "state": self._state, "bg": self._bg, "background": self._bg,
                   "fg": self._fg, "foreground": self._fg, "font": self._font, "command": self._command}
        return mapping[key] if key in mapping else tk.Canvas.cget(self, key)


