def _app_dir():
    return (os.path.dirname(sys.executable) if getattr(sys, "frozen", False)
            else os.path.dirname(os.path.abspath(__file__)))


SETTINGS_FILE = "gguf_settings.json"     # Settings panel choices that must survive a restart


def load_app_settings():
    """Reads gguf_settings.json (next to the script / .exe). Missing or damaged file = defaults."""
    try:
        with open(os.path.join(_app_dir(), SETTINGS_FILE), encoding="utf-8") as fh:
            data = json.load(fh)
        return data if isinstance(data, dict) else {}
    except (OSError, ValueError):
        return {}


def save_app_settings(data):
    try:
        with open(os.path.join(_app_dir(), SETTINGS_FILE), "w", encoding="utf-8") as fh:
            json.dump(data, fh, indent=1)
        return True
    except OSError:                       # read-only folder: the choices just last this session
        return False


APP_SETTINGS = load_app_settings()       # keys: quick_boot, vram_gb, models_folder, save_folder, mode, accent, update_url


# ----------------------------------------------------------------------------------------------
#  BACKENDS - two ways to run a .gguf inside this process: llama.cpp (llama-cpp-python) and the
#  built-in loader (its own engine on numpy / CuPy, no llama.cpp; its source is NATIVE_ENGINE_SOURCE at the
#  end of this file). Settings > Backends switches each one on or off and holds the built-in loader's
#  options; the choices are saved in gguf_settings.json. A model stays on the engine that loaded it.
# ----------------------------------------------------------------------------------------------
BACKEND_LLAMA, BACKEND_NATIVE = "llama", "native"
BACKEND_NAMES = {BACKEND_LLAMA: "llama.cpp", BACKEND_NATIVE: "Built-in loader"}
BACKEND_DEFAULTS = {
    "backend_llama": True,            # llama.cpp switched on
    "backend_native": False,          # built-in loader switched on
    "backend_prefer": BACKEND_LLAMA,  # which one loads a model first when both are on
    "backend_fallback": True,         # if that one can't load a model, try the other
    "native_gpu": True,               # built-in loader: use the GPU through CuPy when it is there
    "native_fused": True,             # built-in loader: fused decode-and-multiply GPU kernels
    "native_dense": False,            # built-in loader: decode weights once at load (faster, more memory)
    "native_kv32": False,             # built-in loader: key/value memory in float32 instead of float16
}


def backend_setting(key):
    v = APP_SETTINGS.get(key, BACKEND_DEFAULTS[key])
    return v if isinstance(v, type(BACKEND_DEFAULTS[key])) else BACKEND_DEFAULTS[key]


def _module_installed(name):
    try:
        import importlib.util
        return importlib.util.find_spec(name) is not None
    except Exception:                                                    # noqa: BLE001
        return False


def backend_usable(name):
    """True when this engine is switched on in Settings > Backends and what it needs is installed."""
    if name == BACKEND_LLAMA:
        return bool(backend_setting("backend_llama")) and LLAMA_CPP_AVAILABLE
    if name == BACKEND_NATIVE:
        return bool(backend_setting("backend_native")) and _module_installed("numpy")
    return False


def backend_order():
    """The engines a load will try, in order. Empty means nothing is switched on (or installed)."""
    first = backend_setting("backend_prefer")
    first = first if first in BACKEND_NAMES else BACKEND_LLAMA
    second = BACKEND_NATIVE if first == BACKEND_LLAMA else BACKEND_LLAMA
    order = [b for b in (first, second) if backend_usable(b)]
    if len(order) > 1 and not backend_setting("backend_fallback"):
        order = order[:1]
    return order


