BUGNOTES_FILE = "gguf_bugnotes.json"     # the Home notepad for bugs found while using the app


def load_bugnotes():
    try:
        with open(os.path.join(_app_dir(), BUGNOTES_FILE), encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return []
    out = []
    for n in (data if isinstance(data, list) else []):
        if isinstance(n, dict) and isinstance(n.get("text"), str) and n["text"].strip():
            out.append({"id": n.get("id") or (int(time.time() * 1000) + len(out)), "text": n["text"],
                        "when": str(n.get("when", "")), "edited": str(n.get("edited", ""))})
    return out


def save_bugnotes(notes):
    try:
        with open(os.path.join(_app_dir(), BUGNOTES_FILE), "w", encoding="utf-8") as fh:
            json.dump(notes, fh, indent=1, ensure_ascii=False)
        return True
    except OSError:
        return False


PROJECTS_FILE = "gguf_projects.json"
PROJECT_CONTEXT_MAX_CHARS = 12000        # instructions + files together, roughly 3,000 tokens


def _new_id():
    import uuid
    return uuid.uuid4().hex[:10]


def load_projects():
    """{"active": id or None, "projects": [{id, name, instructions, files, chats}], "chats": [saved chats outside
    any project]}. Damaged = empty."""
    out = {"active": None, "projects": [], "chats": []}
    try:
        with open(os.path.join(_app_dir(), PROJECTS_FILE), encoding="utf-8") as fh:
            data = json.load(fh)
    except (OSError, ValueError):
        return out
    if not isinstance(data, dict):
        return out
    for p in data.get("projects") or []:
        if not isinstance(p, dict) or not p.get("id"):
            continue
        out["projects"].append({
            "id": str(p["id"]),
            "name": str(p.get("name") or "Untitled project"),
            "instructions": str(p.get("instructions") or ""),
            "files": [str(f) for f in (p.get("files") or []) if isinstance(f, str)],
            "chats": [c for c in (p.get("chats") or []) if isinstance(c, dict) and c.get("id")
                      and isinstance(c.get("conversation"), list)],
        })
    out["chats"] = [c for c in (data.get("chats") or []) if isinstance(c, dict) and c.get("id")
                    and isinstance(c.get("conversation"), list)]
    ids = {p["id"] for p in out["projects"]}
    out["active"] = data.get("active") if data.get("active") in ids else None
    return out


def save_projects(data):
    try:
        with open(os.path.join(_app_dir(), PROJECTS_FILE), "w", encoding="utf-8") as fh:
            json.dump(data, fh, indent=1, ensure_ascii=False)
        return True
    except OSError:
        return False


