def _mem_filled(mem):
    return bool(mem["text"].strip())


# ---- memory cards: usage colours, and finding things a character has said twice ----------------------------------
USAGE_GREEN, USAGE_ORANGE, USAGE_RED = "#3fb950", "#f0883e", "#f85149"


def _usage_colour(used, max_used):
    """Border / chip colour for a card: green = barely used, orange = used often, red = used most. It is relative to
    the busiest card (but never scaled below 3, so one lone use is not 'the most')."""
    if not used or used <= 0:
        return None
    t = used / float(max(max_used, 3))
    return USAGE_GREEN if t < 0.34 else (USAGE_ORANGE if t < 0.67 else USAGE_RED)


def _mem_words(sentence):
    return set(re.findall(r"[a-z0-9']+", sentence.lower()))


def _find_memory_repeats(memories, threshold=0.8, min_words=4):
    """Finds sentences that a card repeats from another card (or from earlier in itself).

    The card that gets used most keeps its sentences (ties: the earlier card). Every other card loses any sentence that
    is the same, or nearly the same (word overlap >= threshold), as one already kept. Sentences shorter than min_words
    are never counted as repeats. Returns a list of dicts, one per card that changes:
      {"index", "id", "title", "removed": [sentences], "new_text", "clear": True when nothing is left}
    Nothing is modified here."""
    order = sorted((i for i, m in enumerate(memories) if _mem_filled(m)),
                   key=lambda i: (-int(memories[i].get("used") or 0), i))
    kept = []                                              # word sets of every sentence kept so far
    changes = {}
    for i in order:
        parts = re.split(r"((?<=[.!?…])\s+|\n+)", memories[i]["text"].strip())
        pieces = [(parts[k], parts[k + 1] if k + 1 < len(parts) else "") for k in range(0, len(parts), 2)]
        keep_txt, removed = [], []
        for sent, sep in pieces:
            if not sent.strip():
                continue
            words = _mem_words(sent)
            dup = False
            if len(words) >= min_words:
                for other in kept:
                    union = len(words | other)
                    if union and len(words & other) / float(union) >= threshold:
                        dup = True
                        break
            if dup:
                removed.append(sent.strip())
            else:
                keep_txt.append(sent + sep)
                if len(words) >= min_words:
                    kept.append(words)
        if removed:
            new_text = "".join(keep_txt).strip()
            changes[i] = {"index": i, "id": memories[i]["id"], "title": memories[i]["title"].strip(),
                          "removed": removed, "new_text": new_text, "clear": not new_text}
    return [changes[i] for i in sorted(changes)]


