# ----------------------------------------------------------------------------------------------
#  Load output capture. llama-cpp-python prints llama.cpp's load messages (and Python's "Exception
#  ignored ..." traces) through sys.stderr, so wrapping sys.stderr is enough to show them inside
#  the chat log - no file-descriptor redirection (that approach broke the app once, see the
#  bug log). Everything is still forwarded to the real stderr, so the cmd window is unchanged.
# ----------------------------------------------------------------------------------------------
_LOG_LOCK = threading.Lock()
_LOG_CAP = 200_000
_LOG_MIN_LEVEL = 1           # llama.cpp levels: 1 debug, 2 info, 3 warn, 4 error (5 = continuation)
_LOG_LAST_SHOW = True
_LLAMA_LOG_CB = None         # must stay referenced or ctypes frees the callback


_LOAD_ACTIVE = False         # True only while a real model load is running (not the metadata probes)
_LOAD_BUF = ""               # text printed during real loads only
_LOAD_TOTAL = 0              # -> this is what the main window's chat box shows


def _log_append(text):
    global _LOAD_BUF, _LOAD_TOTAL
    if text:
        with _LOG_LOCK:
            if _LOAD_ACTIVE:
                _LOAD_BUF = (_LOAD_BUF + text)[-_LOG_CAP:]
                _LOAD_TOTAL += len(text)


def _load_log_begin(title):
    global _LOAD_ACTIVE
    _LOAD_ACTIVE = True
    _log_append(f"Loading {title} ...\n")


def _load_log_end(ok=True, seconds=None):
    global _LOAD_ACTIVE
    _log_append((f"Loaded in {seconds:.1f}s.\n" if ok and seconds is not None else
                 ("" if ok else "Load failed.\n")) + "\n")
    _LOAD_ACTIVE = False


def _real_stderr():
    cur = sys.stderr
    return cur._orig if isinstance(cur, _StderrTee) else cur


class _StderrTee:
    """Python-level stderr (tracebacks, 'Exception ignored ...', anything printed with file=sys.stderr)."""

    def __init__(self, original):
        self._orig = original

    def write(self, text):
        try:
            if self._orig is not None:
                self._orig.write(text)
        except Exception:                                                   # noqa: BLE001
            pass
        if isinstance(text, bytes):
            text = text.decode("utf-8", "replace")
        _log_append(text)
        return len(text) if text else 0

    def flush(self):
        try:
            if self._orig is not None:
                self._orig.flush()
        except Exception:                                                   # noqa: BLE001
            pass

    def __getattr__(self, name):                 # isatty(), fileno(), encoding ... -> the real stream
        return getattr(self._orig, name)


def install_llama_log_hook():
    """Routes llama.cpp's own native log output (load progress, warnings, errors) through a Python
    callback via llama_log_set. That text is written by C code, so it never passes through
    sys.stderr - hooking the library's logger is the only reliable way to see it, and unlike
    redirecting file descriptors it can't break the app. The text is still echoed to the real
    stderr, so the cmd window looks the same. Safe to call repeatedly (re-registers the hook in
    case something replaced it); does nothing if llama-cpp-python isn't available."""
    global _LLAMA_LOG_CB
    if not LLAMA_CPP_AVAILABLE:
        return False
    try:
        import ctypes
        import llama_cpp
        if _LLAMA_LOG_CB is None:
            @llama_cpp.llama_log_callback
            def _cb(level, text, user_data):                            # noqa: ARG001
                global _LOG_LAST_SHOW
                try:
                    s = text.decode("utf-8", "replace") if isinstance(text, bytes) else str(text)
                    show = _LOG_LAST_SHOW if level == 5 else (level >= _LOG_MIN_LEVEL)
                    if level != 5:
                        _LOG_LAST_SHOW = show
                    if not show:
                        return
                    _log_append(s)
                    out = _real_stderr()
                    if out is not None:
                        out.write(s)
                        out.flush()
                except Exception:                                       # noqa: BLE001
                    pass
            _LLAMA_LOG_CB = _cb
        llama_cpp.llama_log_set(_LLAMA_LOG_CB, ctypes.c_void_p(0))
        return True
    except Exception:                                                   # noqa: BLE001
        return False


def install_stderr_tee():
    if not isinstance(sys.stderr, _StderrTee):
        sys.stderr = _StderrTee(sys.stderr)

