C = {}


def set_theme(name):
    C.clear()
    C.update(THEMES[name])
    C["name"] = name


F = {}


def build_fonts(root):
    """Picks the best installed family for each role. Windows 10/11 has all the first choices."""
    fams = set(tkfont.families(root))

    def pick(*names):
        for n in names:
            if n in fams:
                return n
        return "TkDefaultFont"

    ui = pick("Segoe UI Variable Text", "Segoe UI", "Helvetica Neue", "DejaVu Sans")
    serif = pick("Constantia", "Georgia", "Cambria", "Lora", "DejaVu Serif")
    mono = pick("Cascadia Mono", "Consolas", "Menlo", "DejaVu Sans Mono")
    F.update(
        ui=(ui, 10), ui_b=(ui, 10, "bold"), ui_l=(ui, 11), small=(ui, 9), small_b=(ui, 9, "bold"),
        tiny=(ui, 8), title=(serif, 20), h3=(serif, 14, "bold"), brand=(serif, 14, "bold"),
        body=(serif, 12), body_i=(serif, 12, "italic"), hero=(serif, 26), mono=(mono, 9),
        mono_s=(mono, 8), num=(ui, 15, "bold"),
    )


# ==============================================================================================
#  SMALL HELPERS
# ==============================================================================================
def _rgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) for i in (0, 2, 4))


def mix(a, b, t):
    """Blend colour a toward b by t (0..1)."""
    ra, rb = _rgb(a), _rgb(b)
    return "#%02x%02x%02x" % tuple(int(x + (y - x) * t) for x, y in zip(ra, rb))


def rrect(cv, x1, y1, x2, y2, r, **kw):
    r = max(0, min(r, (x2 - x1) / 2, (y2 - y1) / 2))
    pts = [x1 + r, y1, x2 - r, y1, x2, y1, x2, y1 + r, x2, y2 - r, x2, y2, x2 - r, y2,
           x1 + r, y2, x1, y2, x1, y2 - r, x1, y1 + r, x1, y1]
    return cv.create_polygon(pts, smooth=True, **kw)


def draw_icon(cv, name, cx, cy, r, col, w=1.6, bg=None):
    """Line icons drawn from primitives so nothing depends on an emoji or icon font."""
    def L(pts, **k):
        return cv.create_line(*pts, fill=col, width=w, capstyle="round", joinstyle="round", **k)

    if name == "chat":
        rrect(cv, cx - r, cy - r * .85, cx + r, cy + r * .45, r * .45, fill="", outline=col, width=w)
        L([cx - r * .45, cy + r * .45, cx - r * .45, cy + r * .95, cx + r * .1, cy + r * .45])
    elif name == "draw":
        L([cx - r, cy + r * .5, cx - r * .45, cy - r * .7, cx + r * .15, cy + r * .6, cx + r, cy - r * .5],
          smooth=True)
    elif name == "music":
        cv.create_oval(cx - r * .8, cy + r * .2, cx - r * .1, cy + r * .85, fill=col, outline=col)
        L([cx - r * .12, cy + r * .5, cx - r * .12, cy - r * .9, cx + r * .7, cy - r * .45])
    elif name == "images":
        rrect(cv, cx - r, cy - r * .8, cx + r, cy + r * .8, r * .25, fill="", outline=col, width=w)
        L([cx - r * .8, cy + r * .5, cx - r * .25, cy - r * .1, cx + r * .1, cy + r * .3,
           cx + r * .35, cy + r * .05, cx + r * .8, cy + r * .5])
        cv.create_oval(cx + r * .3, cy - r * .5, cx + r * .6, cy - r * .2, fill=col, outline=col)
    elif name == "saved":
        L([cx - r * .6, cy - r, cx + r * .6, cy - r, cx + r * .6, cy + r, cx, cy + r * .45, cx - r * .6, cy + r,
           cx - r * .6, cy - r])
    elif name == "home":
        L([cx - r, cy - r * .05, cx, cy - r * .9, cx + r, cy - r * .05])
        L([cx - r * .72, cy - r * .2, cx - r * .72, cy + r * .85, cx + r * .72, cy + r * .85, cx + r * .72, cy - r * .2])
        L([cx - r * .22, cy + r * .85, cx - r * .22, cy + r * .3, cx + r * .22, cy + r * .3, cx + r * .22, cy + r * .85])
    elif name == "blocks":
        rrect(cv, cx - r, cy - r, cx - r * .05, cy - r * .1, r * .2, fill="", outline=col, width=w)
        rrect(cv, cx + r * .05, cy + r * .1, cx + r, cy + r, r * .2, fill="", outline=col, width=w)
        L([cx - r * .5, cy - r * .1, cx - r * .5, cy + r * .55, cx + r * .05, cy + r * .55])
    elif name == "power":
        cv.create_polygon(cx + r * .2, cy - r, cx - r * .6, cy + r * .1, cx - r * .05, cy + r * .1,
                          cx - r * .2, cy + r, cx + r * .6, cy - r * .1, cx + r * .05, cy - r * .1,
                          fill="", outline=col, width=w, joinstyle="round")
    elif name == "persona":
        cv.create_oval(cx - r * .4, cy - r * .95, cx + r * .4, cy - r * .15, outline=col, width=w)
        L([cx - r * .95, cy + r * .95, cx - r * .8, cy + r * .4, cx, cy + r * .2, cx + r * .8, cy + r * .4,
           cx + r * .95, cy + r * .95], smooth=True)
    elif name == "prompts":
        L([cx - r, cy - r * .6, cx + r, cy - r * .6])
        L([cx - r, cy, cx + r * .4, cy])
        L([cx - r, cy + r * .6, cx + r * .8, cy + r * .6])
    elif name == "projects":
        L([cx - r, cy - r * .6, cx - r * .25, cy - r * .6, cx + r * .05, cy - r * .3, cx + r, cy - r * .3,
           cx + r, cy + r * .7, cx - r, cy + r * .7, cx - r, cy - r * .6])
    elif name == "world":
        cv.create_oval(cx - r * .9, cy - r * .9, cx + r * .9, cy + r * .9, outline=col, width=w)
        cv.create_oval(cx - r * .38, cy - r * .9, cx + r * .38, cy + r * .9, outline=col, width=w)
        L([cx - r * .9, cy, cx + r * .9, cy])
    elif name == "bug":
        cv.create_oval(cx - r * .55, cy - r * .5, cx + r * .55, cy + r * .9, outline=col, width=w)
        L([cx - r * .55, cy + r * .2, cx + r * .55, cy + r * .2])
        L([cx, cy - r * .5, cx, cy + r * .9])
        L([cx - r * .35, cy - r * .62, cx - r * .6, cy - r * .95])
        L([cx + r * .35, cy - r * .62, cx + r * .6, cy - r * .95])
        L([cx - r * .55, cy - r * .05, cx - r, cy - r * .25])
        L([cx + r * .55, cy - r * .05, cx + r, cy - r * .25])
        L([cx - r * .5, cy + r * .6, cx - r, cy + r * .85])
        L([cx + r * .5, cy + r * .6, cx + r, cy + r * .85])
    elif name == "settings":
        L([cx - r, cy - r * .5, cx + r, cy - r * .5])
        L([cx - r, cy + r * .5, cx + r, cy + r * .5])
        cv.create_oval(cx + r * .05, cy - r * .8, cx + r * .6, cy - r * .25, fill=col, outline=col)
        cv.create_oval(cx - r * .6, cy + r * .25, cx - r * .05, cy + r * .8, fill=col, outline=col)
    elif name == "gear":
        pts, teeth, lw = [], 6, min(w, 1.3)
        step = 2 * math.pi / teeth
        for i in range(teeth):
            a = i * step - math.pi / 2
            for off, rad in ((-.30, .78), (-.17, 1.12), (.17, 1.12), (.30, .78)):
                pts += [cx + math.cos(a + off * step) * r * rad, cy + math.sin(a + off * step) * r * rad]
        cv.create_polygon(*pts, fill="", outline=col, width=lw, joinstyle="round")
        cv.create_oval(cx - r * .34, cy - r * .34, cx + r * .34, cy + r * .34, outline=col, width=lw)
    elif name == "plus":
        L([cx - r * .7, cy, cx + r * .7, cy])
        L([cx, cy - r * .7, cx, cy + r * .7])
    elif name == "send":
        L([cx, cy + r * .8, cx, cy - r * .8])
        L([cx - r * .65, cy - r * .15, cx, cy - r * .8, cx + r * .65, cy - r * .15])
    elif name == "chev_down":
        L([cx - r * .6, cy - r * .25, cx, cy + r * .35, cx + r * .6, cy - r * .25])
    elif name == "chev_right":
        L([cx - r * .25, cy - r * .6, cx + r * .35, cy, cx - r * .25, cy + r * .6])
    elif name == "search":
        cv.create_oval(cx - r * .8, cy - r * .8, cx + r * .45, cy + r * .45, outline=col, width=w)
        L([cx + r * .3, cy + r * .3, cx + r * .9, cy + r * .9])
    elif name == "contrast":
        cv.create_oval(cx - r * .9, cy - r * .9, cx + r * .9, cy + r * .9, outline=col, width=w)
        cv.create_arc(cx - r * .9, cy - r * .9, cx + r * .9, cy + r * .9, start=90, extent=180,
                      style="chord", fill=col, outline=col)
    elif name == "panel":
        rrect(cv, cx - r, cy - r * .8, cx + r, cy + r * .8, r * .25, fill="", outline=col, width=w)
        L([cx + r * .3, cy - r * .8, cx + r * .3, cy + r * .8])
    elif name == "terminal":
        L([cx - r * .8, cy - r * .5, cx - r * .1, cy, cx - r * .8, cy + r * .5])
        L([cx + r * .1, cy + r * .55, cx + r * .8, cy + r * .55])
    elif name == "close":
        L([cx - r * .6, cy - r * .6, cx + r * .6, cy + r * .6])
        L([cx - r * .6, cy + r * .6, cx + r * .6, cy - r * .6])
    elif name == "play":
        cv.create_polygon(cx - r * .55, cy - r * .7, cx + r * .75, cy, cx - r * .55, cy + r * .7,
                          fill=col, outline=col, joinstyle="round")
    elif name == "stop":
        rrect(cv, cx - r * .6, cy - r * .6, cx + r * .6, cy + r * .6, r * .15, fill=col, outline=col)
    elif name == "speaker":
        cv.create_polygon(cx - r, cy - r * .3, cx - r * .45, cy - r * .3, cx + r * .1, cy - r * .8,
                          cx + r * .1, cy + r * .8, cx - r * .45, cy + r * .3, cx - r, cy + r * .3,
                          fill="", outline=col, width=w, joinstyle="round")
        cv.create_arc(cx - r * .3, cy - r * .5, cx + r * .6, cy + r * .5, start=-50, extent=100,
                      style="arc", outline=col, width=w)
    elif name == "dot":
        cv.create_oval(cx - r * .5, cy - r * .5, cx + r * .5, cy + r * .5, fill=col, outline=col)


# ==============================================================================================
#  WIDGETS (all drawn on canvases so corners, states and colours are fully ours)
# ==============================================================================================
class Btn(tk.Canvas):
    """kind: primary | soft | ghost | tab. Optional icon on the left; icon-only if text is empty."""

    def __init__(self, parent, text="", command=None, kind="soft", icon=None, height=30,
                 font=None, radius=9, padx=12, active=False, width=None, anchor="center"):
        self._pbg = parent.cget("bg")
        super().__init__(parent, bg=self._pbg, highlightthickness=0, bd=0, cursor="hand2")
        self.text, self.command, self.kind, self.icon = text, command, kind, icon
        self.font, self.radius, self.active = font or F["ui"], radius, active
        self.anchor, self.padx = anchor, padx
        self.hover = False
        f = tkfont.Font(font=self.font)
        tw = f.measure(text) if text else 0
        iw = 16 if icon else 0
        gap = 7 if (icon and text) else 0
        w = width or (tw + iw + gap + 2 * (padx if text else 7))
        self.configure(width=w, height=height)
        self._tw, self._iw, self._gap = tw, iw, gap
        self.bind("<Enter>", lambda e=None: self._hv(True))
        self.bind("<Leave>", lambda e=None: self._hv(False))
        self.bind("<Button-1>", lambda e=None: self.command and self.command())
        self.bind("<Configure>", lambda e=None: self._draw())

    def _hv(self, v):
        self.hover = v
        self._draw()

    def set_active(self, v):
        self.active = v
        self._draw()

    def _draw(self):
        self.delete("all")
        w, h = max(self.winfo_width(), int(self["width"])), max(self.winfo_height(), int(self["height"]))
        k = self.kind
        if k == "primary":
            fill = mix(C["accent"], "#ffffff", .14) if self.hover else C["accent"]
            fg, outline = C["on_accent"], fill
        elif k == "soft":
            fill = mix(C["raised"], C["text"], .07) if self.hover else C["raised"]
            fg, outline = C["text"], C["line"]
        elif k == "tab":
            fill, outline = "", ""
            fg = C["text"] if (self.active or self.hover) else C["muted"]
        else:  # ghost
            fill = C["raised"] if self.hover else ""
            fg, outline = (C["accent"] if self.active else (C["text"] if self.hover else C["muted"])), ""
        if k != "tab":
            rrect(self, 1, 1, w - 1, h - 1, self.radius, fill=fill, outline=outline or fill, width=1)
        total = self._iw + self._gap + self._tw
        x = (w - total) / 2 if self.anchor == "center" else self.padx + 4
        if self.icon:
            draw_icon(self, self.icon, x + 8, h / 2, 7.5, fg)
            x += self._iw + self._gap
        if self.text:
            self.create_text(x, h / 2, text=self.text, anchor="w", fill=fg, font=self.font)
        if k == "tab" and self.active:
            self.create_rectangle(2, h - 3, w - 2, h - 1, fill=C["accent"], outline="")


class Chip(tk.Canvas):
    """Small outlined pill with an optional status dot. Used for model, API and phone state."""

    def __init__(self, parent, text, dot=None, command=None, height=26, font=None, padx=10):
        self._pbg = parent.cget("bg")
        super().__init__(parent, bg=self._pbg, highlightthickness=0, bd=0,
                         cursor="hand2" if command else "")
        self.font, self.command, self.padx = font or F["small"], command, padx
        self.text, self.dot, self.hover = text, dot, False
        self.configure(height=height)
        self.bind("<Enter>", lambda e=None: self._hv(True))
        self.bind("<Leave>", lambda e=None: self._hv(False))
        self.bind("<Button-1>", lambda e=None: self.command and self.command())
        self._fit()

    def _hv(self, v):
        self.hover = v
        self._draw()

    def set(self, text=None, dot="keep"):
        if text is not None:
            self.text = text
        if dot != "keep":
            self.dot = dot
        self._fit()

    def _fit(self):
        f = tkfont.Font(font=self.font)
        self.configure(width=f.measure(self.text) + 2 * self.padx + (14 if self.dot else 0))
        self._draw()

    def _draw(self):
        self.delete("all")
        w, h = int(self["width"]), int(self["height"])
        rrect(self, 1, 1, w - 1, h - 1, h / 2, fill=C["raised"] if self.hover else "", outline=C["line"])
        x = self.padx
        if self.dot:
            self.create_oval(x - 1, h / 2 - 3.5, x + 6, h / 2 + 3.5, fill=self.dot, outline=self.dot)
            x += 14
        self.create_text(x, h / 2, text=self.text, anchor="w", fill=C["text"], font=self.font)


class TabPill(tk.Canvas):
    """Fully rounded pill used for chat tabs, the + button and Split. Optional x on the right closes it."""

    def __init__(self, parent, text, command=None, on_close=None, active=False, height=28, font=None,
                 padx=14, fg=None, min_w=0):
        self._pbg = parent.cget("bg")
        super().__init__(parent, bg=self._pbg, highlightthickness=0, bd=0, cursor="hand2")
        self.text, self.command, self.on_close, self.active = text, command, on_close, active
        self.font, self.padx, self.fg_override = font or F["small"], padx, fg
        self.hover, self.hover_x = False, False
        f = tkfont.Font(font=self.font)
        self._tw = f.measure(text)
        self._xw = 26 if on_close else 0
        self.configure(width=max(min_w, self._tw + 2 * padx + self._xw - (padx // 2 if on_close else 0)), height=height)
        self.bind("<Enter>", lambda e=None: self._hv(True, False))
        self.bind("<Leave>", lambda e=None: self._hv(False, False))
        self.bind("<Motion>", self._motion)
        self.bind("<Button-1>", self._click)
        self.bind("<Configure>", lambda e=None: self._draw())
        self._draw()

    def _in_x(self, x):
        return bool(self.on_close) and x >= int(self["width"]) - self._xw

    def _motion(self, e):
        hx = self._in_x(e.x)
        if hx != self.hover_x:
            self._hv(True, hx)

    def _hv(self, v, hx):
        self.hover, self.hover_x = v, hx
        self._draw()

    def _click(self, e):
        if self._in_x(e.x):
            if self.on_close:
                self.on_close()
        elif self.command:
            self.command()

    def _draw(self):
        self.delete("all")
        w, h = int(self["width"]), int(self["height"])
        if self.active:
            fill, outline = C["bg"], C["line_hi"]
        else:
            fill, outline = (mix(C["raised"], C["text"], .07) if self.hover else C["raised"]), C["line"]
        rrect(self, 1, 1, w - 1, h - 1, h / 2, fill=fill, outline=outline, width=1)
        fg = self.fg_override or (C["text"] if (self.active or self.hover) else C["muted"])
        if self.on_close:
            self.create_text(self.padx, h / 2, text=self.text, anchor="w", fill=fg, font=self.font)
            draw_icon(self, "close", w - self._xw / 2 - 2, h / 2, 5, C["text"] if self.hover_x else C["muted"])
        else:
            self.create_text(w / 2, h / 2, text=self.text, anchor="center", fill=fg, font=self.font)


class Toggle(tk.Canvas):
    def __init__(self, parent, value=False, command=None):
        super().__init__(parent, width=38, height=22, bg=parent.cget("bg"), highlightthickness=0,
                         bd=0, cursor="hand2")
        self.value, self.command = value, command
        self.bind("<Button-1>", self._click)
        self._draw()

    def _click(self, _e=None):
        self.value = not self.value
        self._draw()
        if self.command:
            self.command(self.value)

    def _draw(self):
        self.delete("all")
        track = C["accent"] if self.value else C["line_hi"]
        rrect(self, 1, 1, 37, 21, 10, fill=track, outline=track)
        cx = 27 if self.value else 11
        knob = C["on_accent"] if self.value else C["muted"]
        self.create_oval(cx - 7, 4, cx + 7, 18, fill=knob, outline=knob)


