class Segmented(tk.Canvas):
    def __init__(self, parent, options, value, command=None, height=28, font=None, tints=None, gap_before=()):
        super().__init__(parent, bg=parent.cget("bg"), highlightthickness=0, bd=0, cursor="hand2")
        self.tints = tints or {}               # option -> (idle text colour, selected fill) for warning tones
        self.options, self.value, self.command = options, value, command
        self.font = font or F["small"]
        f = tkfont.Font(font=self.font)
        self.gaps = [12 if o in gap_before else 0 for o in options]   # extra space + a divider before these options
        self.ws = [f.measure(o) + 24 + g for o, g in zip(options, self.gaps)]
        self.configure(width=sum(self.ws) + 4, height=height)
        self.bind("<Button-1>", self._click)
        self._draw()

    def _click(self, e=None):
        if e is None:
            return
        x = e.x - 2
        for o, w in zip(self.options, self.ws):
            if x < w:
                self.value = o
                self._draw()
                if self.command:
                    self.command(o)
                return
            x -= w

    def _draw(self):
        self.delete("all")
        w, h = int(self["width"]), int(self["height"])
        rrect(self, 0, 0, w - 1, h - 1, h / 2, fill=C["bg"], outline=C["line"])
        x = 2
        for o, ow, g in zip(self.options, self.ws, self.gaps):
            sel = o == self.value
            tint = self.tints.get(o)
            if g:
                self.create_line(x + g / 2, 7, x + g / 2, h - 7, fill=C["line_hi"])
            if sel:
                fl = tint[1] if tint else C["accent"]
                rrect(self, x + g, 2, x + ow, h - 3, (h - 5) / 2, fill=fl, outline=fl)
            self.create_text(x + g + (ow - g) / 2, h / 2 - 0.5, text=o, font=self.font,
                             fill=(("#ffffff" if tint else C["on_accent"]) if sel else (tint[0] if tint else C["muted"])))
            x += ow


class Slider(tk.Canvas):
    def __init__(self, parent, lo, hi, value, step=1, fmt="{:g}", command=None):
        super().__init__(parent, height=26, bg=parent.cget("bg"), highlightthickness=0, bd=0,
                         cursor="hand2")
        self.lo, self.hi, self.value, self.step, self.fmt, self.command = lo, hi, value, step, fmt, command
        self.bind("<Configure>", lambda e=None: self._draw())
        self.bind("<Button-1>", self._drag)
        self.bind("<B1-Motion>", self._drag)

    def _geo(self):
        w = max(self.winfo_width(), 120)
        return 8, w - 64, w

    def _drag(self, e=None):
        if e is None:
            return
        x0, x1, _ = self._geo()
        t = min(1, max(0, (e.x - x0) / max(1, x1 - x0)))
        v = self.lo + t * (self.hi - self.lo)
        v = round(v / self.step) * self.step
        self.value = min(self.hi, max(self.lo, v))
        self._draw()
        if self.command:
            self.command(self.value)

    def _draw(self):
        self.delete("all")
        x0, x1, w = self._geo()
        y = 13
        t = (self.value - self.lo) / (self.hi - self.lo)
        xv = x0 + t * (x1 - x0)
        rrect(self, x0, y - 2, x1, y + 2, 2, fill=C["line"], outline=C["line"])
        rrect(self, x0, y - 2, max(x0 + 2, xv), y + 2, 2, fill=C["accent"], outline=C["accent"])
        self.create_oval(xv - 7, y - 7, xv + 7, y + 7, fill=C["accent"], outline=C["panel"], width=2)
        txt = self.fmt(self.value) if callable(self.fmt) else self.fmt.format(self.value)
        self.create_text(w - 2, y, text=txt, anchor="e", fill=C["text"], font=F["small"])


class Select(tk.Canvas):
    def __init__(self, parent, options, value, command=None, height=30):
        super().__init__(parent, height=height, bg=parent.cget("bg"), highlightthickness=0, bd=0,
                         cursor="hand2")
        self.options, self.value, self.command = options, value, command
        self.bind("<Configure>", lambda e=None: self._draw())
        self.bind("<Button-1>", self._open)

    def _open(self, _e=None):
        m = tk.Menu(self, tearoff=0, bg=C["raised"], fg=C["text"], activebackground=C["accent"],
                    activeforeground=C["on_accent"], bd=0, font=F["ui"])
        for o in self.options:
            m.add_command(label=o, command=lambda o=o: self._pick(o))
        try:
            m.tk_popup(self.winfo_rootx(), self.winfo_rooty() + self.winfo_height() + 2)
        finally:
            m.grab_release()

    def _pick(self, o):
        self.value = o
        self._draw()
        if self.command:
            self.command(o)

    def _draw(self):
        self.delete("all")
        w, h = max(self.winfo_width(), 60), int(self["height"])
        rrect(self, 1, 1, w - 1, h - 1, 9, fill=C["raised"], outline=C["line"])
        self.create_text(12, h / 2, text=self.value, anchor="w", fill=C["text"], font=F["ui"])
        draw_icon(self, "chev_down", w - 16, h / 2, 6, C["muted"])


class Card(tk.Canvas):
    """Rounded container. Put children in card.body. Height follows the content."""

    def __init__(self, parent, fill=None, outline=None, radius=14, pad=10, autow=False):
        super().__init__(parent, bg=parent.cget("bg"), highlightthickness=0, bd=0, height=48, width=60)
        self.fill, self.outline, self.r, self.pad, self.autow = (fill or C["raised"], outline, radius, pad, autow)
        self.body = tk.Frame(self, bg=self.fill)
        self._win = self.create_window(pad, pad, anchor="nw", window=self.body)
        self._cw = self._ch = 0
        self.bind("<Configure>", self._on_cfg)
        self.body.bind("<Configure>", self._on_body)

    def _on_cfg(self, e=None):
        if e is None:
            return
        if not self.autow:
            self.itemconfigure(self._win, width=max(1, e.width - 2 * self.pad))
        self._cw, self._ch = e.width, e.height
        self._paint()

    def _on_body(self, e=None):
        if e is None:
            return
        need_h = e.height + 2 * self.pad
        if int(float(self.cget("height"))) != need_h:
            self.configure(height=need_h)
        if self.autow:
            need_w = e.width + 2 * self.pad
            if int(float(self.cget("width"))) != need_w:
                self.configure(width=need_w)

    def _paint(self):
        self.delete("bg")
        rrect(self, 1, 1, self._cw - 1, self._ch - 1, self.r, fill=self.fill,
              outline=self.outline or self.fill, width=1, tags="bg")
        self.tag_lower("bg")


WALLPAPER_STYLES = ["Off", "Breathing", "Aurora", "Lava", "Mesh", "Plasma", "Earth", "Black hole", "Custom"]
WALLPAPER_SPEEDS = {"Slow": 0.5, "Normal": 1.0, "Fast": 2.0}     # old names, only used to read a saved setting
WALLPAPER_SPEED_MAX = 3.0                                          # the Speed slider runs 0 (paused) .. this
WALLPAPER_VIDEO = "earth_spin_loop.mp4"          # the "Earth" wallpaper: looked for next to this script (or pick one in Settings)
WALLPAPER_DIMS = {"Dim": 0.35, "Medium": 0.6, "Bright": 0.9}     # how strongly the video shows over the theme background
# Video wallpapers: style -> (default clip looked for next to this script, Settings key that holds a clip the user picked).
# "Earth" keeps its original key, so a video chosen in an older version still works.
WALLPAPER_VIDEOS = {
    "Earth": (WALLPAPER_VIDEO, "wallpaper_video"),
    "Black hole": ("blackhole_loop.mp4", "wallpaper_video_blackhole"),
    "Custom": ("", "wallpaper_video_custom"),            # your own video or picture; no default file
}
WALLPAPER_IMAGE_EXTS = (".png", ".jpg", ".jpeg", ".bmp", ".webp", ".tif", ".tiff")   # still pictures for Custom


class _StillCap:
    """Stands in for cv2.VideoCapture when the Custom wallpaper is a picture: one frame, returned forever,
    so the video loop (fit, Brightness, glass tiles) works on it unchanged."""
    def __init__(self, cv2, path):
        self.frame = None
        try:
            data = _np.fromfile(path, dtype=_np.uint8)           # fromfile + imdecode copes with non-ASCII paths
            self.frame = cv2.imdecode(data, cv2.IMREAD_COLOR)
        except Exception:                                        # noqa: BLE001
            self.frame = None

    def isOpened(self):
        return self.frame is not None

    def get(self, prop):
        return 30.0

    def read(self):
        return (True, self.frame) if self.frame is not None else (False, None)

    def set(self, prop, val):
        return True

    def grab(self):
        return True

    def release(self):
        self.frame = None

WALLPAPER_ZOOM_STYLES = ("Black hole",)                # video styles that get the Closeness slider
WALLPAPER_ZOOM_MIN, WALLPAPER_ZOOM_MAX = 0.5, 2.5      # <1 pulls back (black hole small in the dark), >1 zooms in on the disc
try:
    import numpy as _np
except ImportError:                      # wallpapers need numpy; without it they stay off
    _np = None


class _WallTarget:
    def __init__(self, cv, item):
        self.cv, self.item, self.photo = cv, item, None


class Wallpaper:
    """Animated backgrounds drawn behind scrolling pages. Frames are computed small with numpy, handed to Tk
    as a PPM image and zoomed up, so there is no Pillow dependency. Colours come from the current theme."""

    def __init__(self, root):
        self.root, self.targets, self.job, self.t0 = root, [], None, time.time()
        st = APP_SETTINGS.get("wallpaper", "Breathing")
        self.style = st if st in WALLPAPER_STYLES else "Breathing"
        sp = APP_SETTINGS.get("wallpaper_speed", 1.0)
        if isinstance(sp, str):                                  # older versions saved Slow / Normal / Fast
            sp = WALLPAPER_SPEEDS.get(sp, 1.0)
        try:
            self.speed = min(WALLPAPER_SPEED_MAX, max(0.0, float(sp)))
        except (TypeError, ValueError):
            self.speed = 1.0
        self._t, self._tlast = 0.0, time.time()                  # animation clock: advances by real time x speed
        try:
            gp = int(APP_SETTINGS.get("wallpaper_glass", 78))
        except (TypeError, ValueError):
            gp = 78
        self.glass_pct = min(100, max(20, gp))                   # how solid the Home tiles are (100 = fully solid)
        self.glass_op = self.glass_pct / 100.0
        self.glass_items = []                                    # tiles that show the wallpaper through themselves
        dm = APP_SETTINGS.get("wallpaper_dim", "Medium")
        self.dim = dm if dm in WALLPAPER_DIMS else "Medium"
        try:
            zm = float(APP_SETTINGS.get("wallpaper_bh_zoom", 1.0))
        except (TypeError, ValueError):
            zm = 1.0
        self.zoom = min(WALLPAPER_ZOOM_MAX, max(WALLPAPER_ZOOM_MIN, zm))   # Black hole "Closeness"
        try:
            zc = float(APP_SETTINGS.get("wallpaper_custom_zoom", 1.0))
        except (TypeError, ValueError):
            zc = 1.0
        self.zoom_custom = min(WALLPAPER_ZOOM_MAX, max(WALLPAPER_ZOOM_MIN, zc))   # Custom "Closeness"
        self.error = None
        # Earth (video) state. A worker thread decodes with OpenCV; the Tk thread only turns frames into images.
        self._vthread, self._vstop = None, None
        self._vwant = None                   # (w, h) the visible canvas wants, or None = nobody is looking, don't decode
        self._vframe, self._vseq, self._verr = None, 0, None
        self._vbg = None
        self._vstyle = None                  # the video style the decoder thread is currently playing
        self._pil = None                     # None = not tried yet, False = unavailable, else (Image, ImageTk)

    def available(self):
        return _np is not None

    # ---- Earth / video wallpaper -----------------------------------------------------------
    def is_video(self, style=None):
        """True for the wallpapers that play a video clip (Earth, Black hole)."""
        return (style or self.style) in WALLPAPER_VIDEOS

    def _vinfo(self, style=None):
        st = style or self.style
        return WALLPAPER_VIDEOS.get(st) or WALLPAPER_VIDEOS["Earth"]

    def video_name(self, style=None):
        """The clip file name this style looks for next to the script."""
        return self._vinfo(style)[0]

    def video_key(self, style=None):
        """The Settings key that remembers a clip the user chose for this style."""
        return self._vinfo(style)[1]

    def find_video(self, style=None):
        """The clip chosen for this style, else its default file (earth_spin_loop.mp4 / blackhole_loop.mp4)
        next to the script / in the working folder."""
        name, key = self._vinfo(style)
        cands = [APP_SETTINGS.get(key)]
        for d in (_app_dir(), os.getcwd()):
            cands.append(os.path.join(d, name))
        for c in cands:
            if c and os.path.isfile(c):
                return c
        return None

    def set_video(self, path, style=None):
        APP_SETTINGS[self.video_key(style)] = path or ""
        save_app_settings(APP_SETTINGS)
        self._video_stop()
        self.error = None
        if self.is_video():
            self.start()

    def register_glass(self, tile):
        if tile not in self.glass_items:
            self.glass_items.append(tile)

    def set_glass(self, pct):
        try:
            self.glass_pct = int(min(100, max(20, round(float(pct)))))
        except (TypeError, ValueError):
            self.glass_pct = 78
        self.glass_op = self.glass_pct / 100.0
        APP_SETTINGS["wallpaper_glass"] = self.glass_pct
        save_app_settings(APP_SETTINGS)
        for tg in self.targets:
            tg.seq = -1                                          # repaint the tiles on the next frame
        self.start()

    def _pilmods(self):
        if self._pil is None:
            try:
                from PIL import Image, ImageTk
                self._pil = (Image, ImageTk)
            except Exception:                                    # noqa: BLE001
                self._pil = False
        return self._pil

    def _update_glass(self, tg, arr, z):
        """Gives each tile on this canvas its see-through look: the part of the current wallpaper frame behind it,
        mixed with the tile's own colour at glass_pct. arr is the small RGB frame, z how many pixels one of its
        pixels covers."""
        alive = []
        for t in self.glass_items:
            try:
                if not t.winfo_exists():
                    continue
                alive.append(t)
                if t.master is not tg.cv:
                    continue
                if self.glass_op >= 0.99:
                    t.set_glass_image(None, 0, 0)
                    continue
                if not t.winfo_viewable():
                    continue
                x, y, w, h = t.winfo_x(), t.winfo_y(), t.winfo_width(), t.winfo_height()
                if w < 40 or h < 20:
                    continue
                gh_, gw_ = arr.shape[:2]
                sx0, sy0 = max(0, x // z), max(0, y // z)
                sx1, sy1 = min(gw_, -(-(x + w) // z)), min(gh_, -(-(y + h) // z))
                if sx1 - sx0 < 2 or sy1 - sy0 < 2:
                    continue
                region = arr[sy0:sy1, sx0:sx1].astype(_np.float32)
                tint = _np.array(_rgb(C["raised"] if t.hover else C["panel"]), dtype=_np.float32)
                xs = (_np.arange(sx1 - sx0, dtype=_np.float32) + 0.5 + sx0) * z - x
                ys = (_np.arange(sy1 - sy0, dtype=_np.float32) + 0.5 + sy0) * z - y
                r = 14.0                                          # same corner radius the tile draws
                dx = _np.maximum(_np.abs(xs - w / 2.0) - (w / 2.0 - r), 0)[None, :]
                dy = _np.maximum(_np.abs(ys - h / 2.0) - (h / 2.0 - r), 0)[:, None]
                inside = ((_np.hypot(dx, dy) <= r) & (xs[None, :] >= 0) & (xs[None, :] <= w)
                          & (ys[:, None] >= 0) & (ys[:, None] <= h))
                a = (inside * self.glass_op).astype(_np.float32)[..., None]
                small = _np.ascontiguousarray((region * (1.0 - a) + tint * a).astype(_np.uint8))
                bw, bh = small.shape[1], small.shape[0]
                pil = self._pilmods()
                if pil:
                    Image, ImageTk = pil
                    img = Image.fromarray(small)
                    if z > 1:
                        img = img.resize((bw * z, bh * z), Image.BILINEAR)
                    photo = ImageTk.PhotoImage(img, master=t)
                else:
                    ph = tk.PhotoImage(master=t, data=b"P6 %d %d 255\n" % (bw, bh) + small.tobytes())
                    photo = ph.zoom(z, z) if z > 1 else ph
                t.set_glass_image(photo, sx0 * z - x, sy0 * z - y)
            except tk.TclError:
                continue
        self.glass_items = alive

    def set_dim(self, name):
        self.dim = name if name in WALLPAPER_DIMS else "Medium"
        APP_SETTINGS["wallpaper_dim"] = self.dim
        save_app_settings(APP_SETTINGS)

    def set_zoom(self, v, style=None):
        """Closeness for the Black hole clip (or, with style="Custom", for the Custom wallpaper). Read live by the
        decoder thread, so it takes effect immediately."""
        try:
            z = round(min(WALLPAPER_ZOOM_MAX, max(WALLPAPER_ZOOM_MIN, float(v))), 3)
        except (TypeError, ValueError):
            z = 1.0
        if style == "Custom":
            self.zoom_custom = z
            APP_SETTINGS["wallpaper_custom_zoom"] = z
        else:
            self.zoom = z
            APP_SETTINGS["wallpaper_bh_zoom"] = z
        save_app_settings(APP_SETTINGS)

    def _video_stop(self):
        if self._vstop is not None:
            self._vstop.set()
        self._vthread = self._vstop = None
        self._vframe, self._vwant, self._verr = None, None, None

    def _video_start(self):
        """Starts the decoder thread if it isn't running. False (and self.error set) when it can't."""
        if self._vthread is not None and self._vthread.is_alive():
            if self._vstyle == self.style:
                return True
            self._video_stop()                         # Earth <-> Black hole: play the other clip
        try:
            import cv2
        except ImportError:
            self.error = "%s needs OpenCV. Install it with: pip install opencv-python" % self.style
            return False
        path = self.find_video()
        if not path:
            if self.style == "Custom":
                self.error = "No custom wallpaper chosen yet. Use Choose file\u2026 below to pick a picture or a video."
            else:
                self.error = ("Couldn't find %s. Put it next to this script, or choose a video below." % self.video_name())
            return False
        self._verr, self._vframe = None, None
        self._vstyle = self.style
        self._vstop = threading.Event()
        self._vthread = threading.Thread(target=self._video_loop, args=(cv2, path, self._vstop), daemon=True)
        self._vthread.start()
        return True

    def _video_loop(self, cv2, path, stop):
        """Worker thread: plays the video in a loop at fps x Speed. Between two source frames it cross-fades, so very
        slow speeds stay smooth instead of stepping; at 0 it holds the current frame. Each output frame is cropped to
        cover the canvas, blended toward the theme background by Brightness, and left in self._vframe.
        Nothing here touches Tk."""
        try:
            still = path.lower().endswith(WALLPAPER_IMAGE_EXTS)
            cap = _StillCap(cv2, path) if still else cv2.VideoCapture(path)
            if not cap.isOpened():
                self._verr = ("Couldn't open the picture: " if still else "Couldn't open the video: ") + path
                return
            fps = cap.get(cv2.CAP_PROP_FPS) or 30.0
            if fps < 1 or fps > 240:
                fps = 30.0

            def read():
                ok, f = cap.read()
                if not ok:                                    # end of the clip: wrap to the start
                    cap.set(cv2.CAP_PROP_POS_FRAMES, 0)
                    ok, f = cap.read()
                return f if ok else None

            edge_cache = {}

            def fit(fr, gw, gh):
                h0, w0 = fr.shape[:2]
                if gw * h0 > gh * w0:                         # canvas is wider than the video: crop top/bottom
                    ch = max(1, int(round(w0 * gh / float(gw))))
                    y0 = (h0 - ch) // 2
                    fr = fr[y0:y0 + ch, :]
                else:                                         # canvas is taller: crop the sides
                    cw = max(1, int(round(h0 * gw / float(gh))))
                    x0 = (w0 - cw) // 2
                    fr = fr[:, x0:x0 + cw]
                if self._vstyle == "Custom":
                    zm = self.zoom_custom
                else:
                    zm = self.zoom if self._vstyle in WALLPAPER_ZOOM_STYLES else 1.0
                if zm > 1.001:                                # closer: crop toward the centre, then enlarge
                    h1, w1 = fr.shape[:2]
                    cw, ch = max(2, int(round(w1 / zm))), max(2, int(round(h1 / zm)))
                    x0, y0 = (w1 - cw) // 2, (h1 - ch) // 2
                    return cv2.resize(fr[y0:y0 + ch, x0:x0 + cw], (gw, gh), interpolation=cv2.INTER_LINEAR)
                if zm < 0.999:                                # further away: shrink and sit it in the dark, edges feathered
                    sw, sh = max(4, int(round(gw * zm))), max(4, int(round(gh * zm)))
                    small = cv2.resize(fr, (sw, sh), interpolation=cv2.INTER_AREA)
                    m = edge_cache.get((sw, sh))
                    if m is None:
                        f = float(max(3, int(min(sw, sh) * 0.12)))
                        rx = _np.minimum(_np.arange(sw), _np.arange(sw)[::-1]) / f
                        ry = _np.minimum(_np.arange(sh), _np.arange(sh)[::-1]) / f
                        rx, ry = _np.clip(rx, 0, 1), _np.clip(ry, 0, 1)
                        m = (ry[:, None] * rx[None, :]).astype(_np.float32)
                        m = (m * m * (3.0 - 2.0 * m))[..., None]
                        edge_cache.clear()
                        edge_cache[(sw, sh)] = m
                    out = _np.zeros((gh, gw, 3), dtype=_np.uint8)
                    xo, yo = (gw - sw) // 2, (gh - sh) // 2
                    out[yo:yo + sh, xo:xo + sw] = (small.astype(_np.float32) * m).astype(_np.uint8)
                    return out
                return cv2.resize(fr, (gw, gh), interpolation=cv2.INTER_AREA)

            cur = read()
            nxt = read()
            if cur is None or nxt is None:
                self._verr = "The video has no readable frames: " + path
                return
            frac = 0.0                                        # how far we are from cur toward nxt
            out_dt = 1.0 / 30.0
            next_t = time.time()
            while not stop.is_set():
                want = self._vwant
                if want is None:                              # wallpaper not on screen: idle, no decoding
                    stop.wait(0.15)
                    next_t = time.time()
                    continue
                speed = 1.0 if self._vstyle == "Custom" else self.speed     # Custom ignores the Speed setting
                frac += fps * speed * out_dt                  # source frames to advance this output step
                n = int(frac)
                frac -= n
                if n >= 1:
                    if n == 1:
                        cur, nxt = nxt, read()
                    else:
                        for _ in range(n - 2):                # fast: skip the frames in between
                            cap.grab()
                        cur, nxt = read(), read()
                    if cur is None or nxt is None:
                        self._verr = "The video has no readable frames: " + path
                        return
                gw, gh = want
                a = fit(cur, gw, gh)
                if frac > 0.02:
                    a = cv2.addWeighted(a, 1.0 - frac, fit(nxt, gw, gh), frac, 0)
                bg = self._vbg if self._vbg is not None else _np.zeros(3, dtype=_np.float32)
                dim = WALLPAPER_DIMS.get(self.dim, 0.6)
                rgb = a[:, :, ::-1].astype(_np.float32) * dim + bg * (1.0 - dim)           # BGR -> RGB, then dim
                self._vframe = (gw, gh, _np.ascontiguousarray(rgb.astype(_np.uint8)))
                self._vseq += 1
                next_t += out_dt if speed > 0 else 0.1        # paused: just keep the picture fresh for resizes
                wait = next_t - time.time()
                if wait > 0:
                    stop.wait(wait)
                else:
                    next_t = time.time()
            cap.release()
        except Exception as exc:                              # noqa: BLE001 - report it in Settings, don't crash
            self._verr = "%s: %s" % (type(exc).__name__, exc)

    def _to_photo(self, cv, arr, gw, gh, w, h):
        """numpy RGB frame -> Tk image sized w x h. Pillow gives a smooth upscale; without it, PPM + integer zoom."""
        if self._pil is None:
            try:
                from PIL import Image, ImageTk
                self._pil = (Image, ImageTk)
            except Exception:                                 # noqa: BLE001
                self._pil = False
        if self._pil:
            Image, ImageTk = self._pil
            img = Image.fromarray(arr)
            if (gw, gh) != (w, h):
                img = img.resize((w, h), Image.BILINEAR)
            return ImageTk.PhotoImage(img, master=cv)
        small = tk.PhotoImage(master=cv, data=b"P6 %d %d 255\n" % (gw, gh) + arr.tobytes())
        z = max(1, int(round(w / float(gw))))
        return small.zoom(z, z) if z > 1 else small

    def _tick_video(self, live):
        if not self._video_start():
            self._clear()
            return
        if self._verr:
            self.error, self._verr = self._verr, None
            self._video_stop()
            self._clear()
            return
        self._vbg = _np.array(_rgb(C["bg"]), dtype=_np.float32)
        want = None
        for tg in live:
            try:
                cv = tg.cv
                if not cv.winfo_viewable():
                    continue
                w, h = cv.winfo_width(), cv.winfo_height()
                if w < 80 or h < 80:
                    continue
                z = 1 if w <= 1100 else 2                    # big windows decode at half size, then scale up
                gw, gh = -(-w // z), -(-h // z)
                if want is None:
                    want = (gw, gh)
                fr = self._vframe
                if fr is None or (fr[0], fr[1]) != (gw, gh):  # decoder is still catching up with this size
                    continue
                if getattr(tg, "seq", -1) != self._vseq:
                    tg.photo = self._to_photo(cv, fr[2], gw, gh, w, h)
                    tg.seq = self._vseq
                    cv.itemconfigure(tg.item, image=tg.photo)
                    self._update_glass(tg, fr[2], z)
                cv.coords(tg.item, cv.canvasx(0), cv.canvasy(0))
            except tk.TclError:
                continue
            except Exception as exc:                          # noqa: BLE001
                self.error = "%s: %s" % (type(exc).__name__, exc)
                self._video_stop()
                self._clear()
                return
        self._vwant = want
        self.job = self.root.after(40, self._tick)

    def register(self, cv, item):
        self.targets.append(_WallTarget(cv, item))
        self.start()

    def set_style(self, style):
        self.style = style if style in WALLPAPER_STYLES else "Off"
        APP_SETTINGS["wallpaper"] = self.style
        save_app_settings(APP_SETTINGS)
        self.error = None
        if not self.is_video():
            self._video_stop()
        for tg in self.targets:
            tg.seq = -1
        self.start()

    def set_speed(self, name):
        try:
            self.speed = round(min(WALLPAPER_SPEED_MAX, max(0.0, float(name))), 3)
        except (TypeError, ValueError):
            self.speed = 1.0
        APP_SETTINGS["wallpaper_speed"] = self.speed
        save_app_settings(APP_SETTINGS)

    def start(self):
        if self.job is None:
            self.job = self.root.after(30, self._tick)

    def _clear(self):
        for tg in self.targets:
            try:
                tg.cv.itemconfigure(tg.item, image="")
            except tk.TclError:
                pass
            tg.photo = None
        for t in self.glass_items:
            try:
                t.set_glass_image(None, 0, 0)
            except tk.TclError:
                pass

    def _tick(self):
        self.job = None
        live = []
        for tg in self.targets:
            try:
                if tg.cv.winfo_exists():
                    live.append(tg)
            except tk.TclError:
                pass
        self.targets = live
        if not live:
            return
        if self.style == "Off" or _np is None or self.error:
            self._clear()
            if not self.is_video() or self.error:
                self._video_stop()
            return
        if self.is_video():
            self._tick_video(live)
            return
        now = time.time()
        self._t += min(0.25, max(0.0, now - self._tlast)) * self.speed
        self._tlast = now
        t = self._t
        for tg in live:
            try:
                cv = tg.cv
                if not cv.winfo_viewable():
                    continue
                w, h = cv.winfo_width(), cv.winfo_height()
                if w < 80 or h < 80:
                    continue
                z = max(4, int(math.sqrt(w * h / 60000.0)))
                gw, gh = -(-w // z), -(-h // z)
                arr = self._frame(self.style, gw, gh, t)
                small = tk.PhotoImage(master=cv, data=b"P6 %d %d 255\n" % (gw, gh) + arr.tobytes())
                tg.photo = small.zoom(z, z)
                cv.itemconfigure(tg.item, image=tg.photo)
                cv.coords(tg.item, cv.canvasx(0), cv.canvasy(0))
                self._update_glass(tg, arr, z)
            except tk.TclError:
                continue
            except Exception as exc:                         # noqa: BLE001 - never let a background take the app down
                self.error = "%s: %s" % (type(exc).__name__, exc)
                self._clear()
                return
        self.job = self.root.after(66, self._tick)

    def _frame(self, style, gw, gh, t):
        np = _np
        ax = gw / float(gh)
        Xn = (np.arange(gw, dtype=np.float32) / gw)[None, :]
        X = Xn * ax
        Y = (np.arange(gh, dtype=np.float32) / gh)[:, None]
        col = lambda h: np.array(_rgb(h), dtype=np.float32)                      # noqa: E731
        bg, acc, hot = col(C["bg"]), col(C["accent"]), col(C["hot"])
        sg = [col(x) for x in C["seg"]]
        img = np.empty((gh, gw, 3), dtype=np.float32)
        img[:] = bg
        if style == "Breathing":
            b = 0.5 + 0.5 * math.sin(t * 0.7)
            d = np.hypot(X - ax / 2, Y - 0.5)
            g1 = np.exp(-(d / (0.30 + 0.10 * b)) ** 2) * (0.30 + 0.35 * b)
            g2 = np.exp(-(d / (0.75 + 0.20 * b)) ** 2) * (0.22 + 0.14 * b)
            img += (acc - bg) * g1[..., None] + (sg[0] - bg) * g2[..., None]
        elif style == "Aurora":
            for base, sp, ph, c in ((.38, .40, 0.0, sg[0]), (.50, .30, 2.0, sg[2]), (.62, .35, 4.0, sg[1])):
                yc = base + .11 * np.sin(Xn * 5.5 + t * sp * 1.5 + ph) + .05 * np.sin(Xn * 11 - t * sp * 2)
                dy = Y - yc
                g = np.where(dy < 0, np.exp(-(dy / .035) ** 2), np.exp(-(dy / .20) ** 2)) * .5
                img += (c - bg) * g[..., None]
        elif style == "Lava":
            cols = (hot, acc, sg[2], acc * .8 + hot * .2, hot * .7 + sg[2] * .3)
            for i in range(5):
                x = ax * (.15 + .7 * ((i * .37 + .1) % 1)) + math.sin(t * .4 + i) * ax * .08
                y = 1.2 - 1.4 * ((t * .05 * (1 + i * .3) + i * .21) % 1)
                r = .28 + .07 * (i % 3)
                g = np.exp(-(((X - x) ** 2 + (Y - y) ** 2) / (r * r))) * .6
                img += (cols[i] - bg) * g[..., None]
        elif style == "Mesh":
            pts = [(.5 + .45 * math.sin(t * .3 * (i + 1) + i * 1.7), .5 + .45 * math.cos(t * .25 * (i + 2) + i))
                   for i in range(4)]
            num, den = 0, 0
            for (px, py), c in zip(pts, (acc, sg[0], sg[2], sg[1])):
                w = 1.0 / (((Xn - px) ** 2 + ((Y - py) * .45) ** 2 + .02) ** 2)
                num = num + c * w[..., None]
                den = den + w
            img = bg * .55 + (num / den[..., None]) * .45
        elif style == "Plasma":
            v = (np.sin(Xn * 11.5 + t * .6) + np.sin(Y * 8 - t * .5) + np.sin(Xn * 7.7 + Y * 3.84 + t * .4)
                 + np.sin(np.hypot((Xn - .5) * 12.8, (Y - .5) * 6.4) - t * .7)) / 4
            u = (v + 1) / 2
            A, B, D = bg * .55 + sg[0] * .45, bg * .45 + sg[2] * .55, bg * .5 + acc * .5
            f1 = np.clip(u * 2, 0, 1)[..., None]
            f2 = np.clip((u - .5) * 2, 0, 1)[..., None]
            img = np.where((u < .5)[..., None], A + (B - A) * f1, B + (D - B) * f2)
        img = bg + (np.clip(img, 0, 255) - bg) * 0.62            # keep it a backdrop, not a spotlight
        return np.clip(img, 0, 255).astype(np.uint8)


class Scroller(tk.Frame):
    """Vertical scroll area with a hairline scrollbar. Content lives in .inner, optionally capped
    to maxw and centred (the chat column)."""
    _n = 0

    def __init__(self, parent, bg, maxw=None, pad=0, align="center", wall=None, free=False):
        super().__init__(parent, bg=bg)
        self.align = align
        Scroller._n += 1
        style = "Q%d.Vertical.TScrollbar" % Scroller._n
        st = ttk.Style()
        st.layout(style, [("Vertical.Scrollbar.trough",
                           {"children": [("Vertical.Scrollbar.thumb", {"expand": "1", "sticky": "nswe"})],
                            "sticky": "ns"})])
        st.configure(style, troughcolor=bg, background=C["line"], bordercolor=bg, lightcolor=C["line"],
                     darkcolor=C["line"], gripcount=0, width=7)
        st.map(style, background=[("active", C["line_hi"])])
        self.maxw, self.pad = maxw, pad
        self.cv = tk.Canvas(self, bg=bg, highlightthickness=0, bd=0, yscrollincrement=18)
        self.sb = ttk.Scrollbar(self, orient="vertical", command=self.cv.yview, style=style)
        self.wall_item = self.cv.create_image(0, 0, anchor="nw") if wall is not None else None
        self.cv.configure(yscrollcommand=self._yscroll)
        self.sb.pack(side="right", fill="y")
        self.cv.pack(side="left", fill="both", expand=True)
        self.free = free                      # free mode: no content frame, the page draws straight onto .cv
        if free:
            self.inner = self._win = None
        else:
            self.inner = tk.Frame(self.cv, bg=bg)
            self._win = self.cv.create_window(0, 0, anchor="nw", window=self.inner)
        if wall is not None:
            wall.register(self.cv, self.wall_item)
        self.cv._scroll_target = self.cv
        if not free:
            self.cv.bind("<Configure>", self._cfg)
            self.inner.bind("<Configure>", lambda e=None: self.cv.configure(scrollregion=(0, 0, e.width, e.height)))

    def set_height(self, h):
        """Free mode: set how tall the drawn page is, so it scrolls only when it has to."""
        try:
            self.cv.configure(scrollregion=(0, 0, max(1, self.cv.winfo_width()), max(int(h), self.cv.winfo_height())))
        except tk.TclError:
            pass

    def _yscroll(self, lo, hi):
        self.sb.set(lo, hi)
        if self.wall_item is not None:           # keep the wallpaper pinned to the visible area while scrolling
            try:
                self.cv.coords(self.wall_item, self.cv.canvasx(0), self.cv.canvasy(0))
            except tk.TclError:
                pass

    def _cfg(self, e=None):
        if e is None:
            return
        w = e.width - 2 * self.pad
        if self.maxw:
            w = min(w, self.maxw)
        w = max(w, 200)
        self.cv.itemconfigure(self._win, width=w)
        self.cv.coords(self._win, 0 if self.align == "left" else (e.width - w) // 2, 0)

    def to_bottom(self):
        try:
            self.update_idletasks()
            self.cv.yview_moveto(1.0)
        except tk.TclError:
            pass


class RailButton(tk.Canvas):
    def __init__(self, parent, label, icon, command, active=False):
        super().__init__(parent, width=76, height=58, bg=C["panel"], highlightthickness=0, bd=0,
                         cursor="hand2")
        self.label, self.icon, self.command, self.active, self.hover = label, icon, command, active, False
        self.bind("<Enter>", lambda e=None: self._hv(True))
        self.bind("<Leave>", lambda e=None: self._hv(False))
        self.bind("<Button-1>", lambda e=None: self.command())
        self._draw()

    def _hv(self, v):
        self.hover = v
        self._draw()

    def set_active(self, v):
        self.active = v
        self._draw()

    def _draw(self):
        self.delete("all")
        if self.active:
            rrect(self, 9, 3, 67, 55, 13, fill=C["raised"], outline=C["raised"])
            rrect(self, 0, 17, 3, 41, 1.5, fill=C["accent"], outline=C["accent"])
        elif self.hover:
            rrect(self, 9, 3, 67, 55, 13, fill=mix(C["panel"], C["raised"], .5), outline="")
        col = C["accent"] if self.active else (C["text"] if self.hover else C["muted"])
        draw_icon(self, self.icon, 38, 21, 9, col, w=1.7)
        self.create_text(38, 43, text=self.label, font=F["tiny"], fill=C["text"] if self.active else C["muted"])


def canvas_view(parent, draw, bg=None):
    """Canvas that repaints itself through draw(cv, w, h) whenever it is resized."""
    cv = tk.Canvas(parent, bg=bg or C["bg"], highlightthickness=0, bd=0)

    def go(e=None):
        cv.delete("all")
        w, h = cv.winfo_width(), cv.winfo_height()
        if w > 20 and h > 20:
            draw(cv, w, h)

    cv.bind("<Configure>", go)
    cv.redraw = go
    return cv


class Section(tk.Frame):
    """Collapsible inspector section."""

    def __init__(self, parent, title, open_=True, meta=None):
        super().__init__(parent, bg=C["panel"])
        self.open = open_
        hd = tk.Frame(self, bg=C["panel"], cursor="hand2")
        hd.pack(fill="x")
        self.chev = tk.Canvas(hd, width=16, height=16, bg=C["panel"], highlightthickness=0, bd=0)
        self.chev.pack(side="left", padx=(0, 6))
        lbl = tk.Label(hd, text=title, bg=C["panel"], fg=C["text"], font=F["ui_b"])
        lbl.pack(side="left")
        widgets = [hd, self.chev, lbl]
        if meta:
            m = tk.Label(hd, text=meta, bg=C["panel"], fg=C["muted"], font=F["small"])
            m.pack(side="right")
            widgets.append(m)
        for w in widgets:
            w.bind("<Button-1>", lambda e=None: self.toggle())
        self.body = tk.Frame(self, bg=C["panel"])
        self.sep = tk.Frame(self, bg=C["line"], height=1)
        self.sep.pack(fill="x", pady=(12, 0))
        self._apply()

    def toggle(self):
        self.open = not self.open
        self._apply()

    def _apply(self):
        self.chev.delete("all")
        draw_icon(self.chev, "chev_down" if self.open else "chev_right", 8, 8, 6, C["muted"])
        if self.open:
            self.body.pack(fill="x", pady=(10, 2), before=self.sep)
        else:
            self.body.pack_forget()





class HomeTile(tk.Canvas):
    """A front-cover tile: icon, name and one line of what it does. Click to open that workspace."""
    H = 96

    def __init__(self, parent, icon, title, blurb, command):
        super().__init__(parent, height=self.H, bg=C["bg"], highlightthickness=0, bd=0, cursor="hand2")
        self.icon, self.title, self.blurb, self.command, self.hover = icon, title, blurb, command, False
        self._glassy, self._gphoto, self._gpos = False, None, (0, 0)    # see-through mode, fed by Wallpaper._update_glass
        self.bind("<Configure>", lambda e=None: self._draw())
        self.bind("<Enter>", lambda e=None: self._hv(True))
        self.bind("<Leave>", lambda e=None: self._hv(False))
        self.bind("<Button-1>", lambda e=None: self.command())

    def _hv(self, v):
        self.hover = v
        self._draw()

    def _title_text(self, w):
        return self.title

    def set_glass_image(self, photo, ox, oy):
        """Wallpaper hands over the backdrop (already tinted with this tile's colour) so the tile looks see-through.
        photo=None puts the plain solid tile back."""
        self._gphoto, self._gpos = photo, (ox, oy)
        want = photo is not None
        if want != self._glassy:
            self._glassy = want
            self._draw()
        elif want:
            self.itemconfigure("gimg", image=photo)
            self.coords("gimg", ox, oy)

    def _draw(self):
        self.delete("all")
        w, h = self.winfo_width(), self.H
        if w < 40:
            return
        fill = C["raised"] if self.hover else C["panel"]
        if self._glassy and self._gphoto is not None:
            self.create_image(self._gpos[0], self._gpos[1], anchor="nw", image=self._gphoto, tags="gimg")
            fill = ""
        rrect(self, 1, 1, w - 1, h - 1, 14, fill=fill, outline=C["accent"] if self.hover else C["line"])
        draw_icon(self, self.icon, 30, 30, 10, C["accent"] if self.hover else C["muted"], w=1.8)
        self.create_text(52, 30, text=self._title_text(w), anchor="w", fill=C["text"], font=F["ui_b"])
        self.create_text(18, 58, text=self.blurb, anchor="nw", fill=C["muted"], font=F["small"], width=max(60, w - 36))


class QuickTile(HomeTile):
    """HomeTile with a context-length text box on the right of the title row. The model name in the title is a
    drop-down: click the name to pick a different model, click anywhere else on the tile to launch it."""
    H = 60                                 # one line tall: no description text under the title

    def __init__(self, parent, icon, prefix, name, blurb, command, ctx_var, pick=None):
        self.pick = pick
        super().__init__(parent, icon, prefix + name + ("  \u25be" if pick else ""), blurb, command)
        self.bind("<Button-1>", self._click)
        self.bind("<Motion>", self._motion)
        self.ctx_var = ctx_var
        self.box = tk.Frame(self, bg=C["panel"])
        self.lbl = tk.Label(self.box, text="Context", bg=C["panel"], fg=C["muted"], font=F["small"])
        self.lbl.pack(side="left", padx=(0, 6))
        self.spin = tk.Entry(self.box, width=8, textvariable=ctx_var, font=F["ui"], bg=C["raised"], fg=C["text"],
                             insertbackground=C["accent"], relief="flat", highlightthickness=1,
                             highlightbackground=C["line"], highlightcolor=C["accent"],
                             selectbackground=C["line_hi"], justify="right")
        self.spin.pack(side="left")

    def _title_text(self, w):
        """The title, shortened with an ellipsis when it would run into the Context box."""
        try:
            f = tkfont.Font(font=F["ui_b"])
            avail = w - 18 - self.box.winfo_reqwidth() - 14 - 52
            suffix = "  \u25be" if self.pick else ""
            base = self.title[:-len(suffix)] if suffix and self.title.endswith(suffix) else self.title
            if f.measure(base + suffix) <= avail:
                return base + suffix
            while base and f.measure(base + "\u2026" + suffix) > avail:
                base = base[:-1]
            return base + "\u2026" + suffix
        except tk.TclError:
            return self.title

    def _on_title(self, e):
        if not self.pick:
            return False
        try:
            wide = tkfont.Font(font=F["ui_b"]).measure(self._title_text(max(self.winfo_width(), 100)))
        except tk.TclError:
            return False
        return 40 <= e.x <= 52 + wide + 8 and 12 <= e.y <= 48

    def _motion(self, e):
        try:
            self.configure(cursor="hand2")
        except tk.TclError:
            pass

    def _click(self, e):
        if self._on_title(e):
            self.pick(e)
        else:
            self.command()

    def _draw(self):
        super()._draw()
        w = self.winfo_width()
        if w < 40:
            return
        bg = C["raised"] if self.hover else C["panel"]
        self.box.configure(bg=bg)
        self.lbl.configure(bg=bg)
        self.create_window(w - 18, 30, window=self.box, anchor="e")


class SuggestRow(tk.Canvas):
    def __init__(self, parent, icon, text, dest, command):
        super().__init__(parent, height=48, bg=C["bg"], highlightthickness=0, bd=0, cursor="hand2")
        self.icon, self.text, self.dest, self.command, self.hover = icon, text, dest, command, False
        self.bind("<Configure>", lambda e=None: self._draw())
        self.bind("<Enter>", lambda e=None: self._hv(True))
        self.bind("<Leave>", lambda e=None: self._hv(False))
        self.bind("<Button-1>", lambda e=None: self.command())

    def _hv(self, v):
        self.hover = v
        self._draw()

    def _draw(self):
        self.delete("all")
        w, h = self.winfo_width(), 48
        if self.hover:
            rrect(self, 0, 2, w, h - 2, 10, fill=C["raised"], outline=C["raised"])
        draw_icon(self, self.icon, 24, h / 2, 8, C["accent"] if self.hover else C["muted"])
        self.create_text(48, h / 2, text=self.text, anchor="w", fill=C["text"], font=F["ui_l"])
        self.create_text(w - 14, h / 2, text=self.dest, anchor="e", fill=C["faint"], font=F["small"])
        if not self.hover:
            self.create_line(0, h - 1, w, h - 1, fill=C["line"])





