def _tab_prop(name):
    def get(self):
        t = getattr(_TAB_TL, "tab", None) or self._tabs[self._tab_cur]
        if name not in t:
            t[name] = _TAB_DEFAULTS[name]()
        return t[name]

    def set_(self, v):
        t = getattr(_TAB_TL, "tab", None) or self._tabs[self._tab_cur]
        t[name] = v
    return property(get, set_)


class SimpleChat:
    """The Studio shell. The chat logic, backend and tool handling are carried over unchanged."""


    def __init__(self, root):
        self._tabs_ensure()
        self.root = root
        self.t = dict(PALETTE, family=FONT_UI, size=10, small=9, title=11)
        self._models_win = None
        self._settings_panel = None              # the in-app Settings panel (built on first open)
        _sf = APP_SETTINGS.get("save_folder") or ""
        self.save_folder = _sf if _sf and os.path.isdir(_sf) else None   # Settings > Output save location
        self.last_response_text = ""   # most recently completed model reply, for the console's `copy`

        self.server_connected = False
        self.server_model = None
        self.server_instance_id = None
        self.server_catalog = []   # last backend catalog, shared with Models window

        # Local backend: runs models directly in-process, with llama-cpp-python and / or the built-in loader
        # (Settings > Backends). Connect refuses with a message when neither is switched on and installed.
        _mf = APP_SETTINGS.get("models_folder") or ""
        self.local_models_root = _mf if _mf and os.path.isdir(_mf) else DEFAULT_LOCAL_MODELS_ROOT
        self.local_backend = LocalLlamaBackend(self)
        self.backend = self.local_backend
        self.conversation = []     # [{"role": "user"/"assistant", "content": str}, ...]
        QWEN_VOICE.on_change = self._voice_model_notify
        self.total_tokens = 0
        self.awaiting_reply = False
        self.mode_kind = "chat"        # what the pill does: chat / images / music / draw
        self.mode_busy = False         # an image / music / drawing job started from the pill is running
        self._mode_job = None
        self._mode_photos = []         # keeps result images alive while they are in the chat log

        self.reasoning_enabled = True   # Local backend: let the model think (Qwen on/off; GPT-OSS low effort when off)
        self.reasoning_level = "Medium" # Local backend: Low / Medium / High (GPT-OSS; Qwen ignores it)
        self.show_thinking = True       # show the muted "Thinking" block in the chat log
        self.show_load_log = True       # show llama.cpp's load output in the chat log while a model loads
        self._load_log_pos = 0
        self.ram_spillover = bool(APP_SETTINGS.get("ram_spillover", True))   # Local backend: let layers spill from VRAM into system RAM
        self.gpu_layers_override = None # Local backend: manual n_gpu_layers (None = auto)
        _gs = APP_SETTINGS.get("gpu_share_pct")
        self.gpu_share_pct = _gs if isinstance(_gs, int) and 0 <= _gs <= 100 else None  # GPU % of layers (None = Auto)
        self.http_bridge = HttpBridge(self)   # optional 127.0.0.1 API for other local programs
        self.image_engine = ImageEngine(self)   # stable-diffusion.cpp subprocess wrapper
        self.sd_exe = ""                        # path to sd-cli.exe / sd.exe (session-only)
        self.sd_model = ""                      # path to the SD 1.5 checkpoint (session-only)
        self.block_editor = BlockEditorServer(self)   # built-in Block Editor (opened from the title-bar menu)
        self.auto_max_context = bool(APP_SETTINGS.get("auto_max_context", False))   # mirrors the "Auto-max context" checkbox; remembered

        # Live streaming state for the single request currently in flight (only one call is ever
        # active at a time). Reset by _begin_stream_turn() right before each request goes out.
        self._stream_parse_state = {"mode": "pre", "buffer": ""}
        self._stream_reasoning_started = False
        self._stream_answer_started = False
        self._stream_full_reasoning = ""
        self._stream_full_answer = ""
        self._stream_usage = None

        self._init_studio()

    def _shortcuts_file(self):
        return os.path.join(os.path.dirname(self._theme_file()), "gguf_shortcuts.json")

    def _shortcuts_save(self):
        try:
            with open(self._shortcuts_file(), "w", encoding="utf-8") as fh:
                json.dump(self.shortcuts, fh, indent=1)
        except OSError:
            pass                                    # read-only folder: the shortcuts just last this session

    def _shortcuts_restore(self):
        try:
            with open(self._shortcuts_file(), encoding="utf-8") as fh:
                saved = json.load(fh)
        except (OSError, ValueError):
            return
        if isinstance(saved, list):
            for i, sc in enumerate(saved[:3]):
                if isinstance(sc, dict) and str(sc.get("name", "")).strip() and str(sc.get("target", "")).strip():
                    self.shortcuts[i] = {"name": str(sc["name"]).strip(), "target": str(sc["target"]).strip()}
        self.stage.set_shortcuts(self.shortcuts)

    BUILTIN_SHORTCUTS = (("Power Monitor", "Power", "power"), ("Drawing", "Drawing", "drawing"),
                         ("Music", "Music", "music"), ("Images", "Images", "images"),
                         ("Block Editor", "Blocks", "blockeditor"))

    def _set_shortcut(self, slot, name, target):
        self.shortcuts[slot] = {"name": name, "target": target}
        self._shortcuts_save()
        self.stage.set_shortcuts(self.shortcuts)

    def _edit_shortcut(self, slot):
        result = self._shortcut_dialog(self.shortcuts[slot])
        if result:
            self.shortcuts[slot] = result
            self._shortcuts_save()
            self.stage.set_shortcuts(self.shortcuts)

    def _remove_shortcut(self, slot):
        self.shortcuts[slot] = None
        self._shortcuts_save()
        self.stage.set_shortcuts(self.shortcuts)

    def _run_shortcut(self, sc):
        """Opens the shortcut's target: a web address in the browser, a file / folder with its default
        program, or - if it is neither - runs it as a command."""
        target = sc["target"].strip()
        if target.lower().startswith("app:"):                           # built-in tool, e.g. app:power
            self._open_builtin(target[4:])
            return
        try:
            path = os.path.expanduser(target)
            if re.match(r"^(https?://|www\.)", target, re.I):
                webbrowser.open(target if "://" in target else "https://" + target)
            elif os.path.exists(path):
                if os.name == "nt":
                    os.startfile(path)
                elif sys.platform == "darwin":
                    subprocess.Popen(["open", path])
                else:
                    subprocess.Popen(["xdg-open", path])
            else:
                subprocess.Popen(target, shell=True)
        except Exception as exc:                                        # noqa: BLE001
            self._append(f"Shortcut \u201c{sc['name']}\u201d failed: {exc}\n\n", "system_msg")

    def _shortcut_dialog(self, initial=None):
        """Small modal form: a name for the bubble and what it opens. Returns {"name", "target"} or None."""
        t = self.t
        font = (t["family"], t["size"])
        dlg = tk.Toplevel(self.root)
        dlg.title("Edit shortcut" if initial else "Add shortcut")
        dlg.configure(bg=t["bg"])
        dlg.resizable(False, False)
        dlg.transient(self.root)
        dlg.grab_set()
        tk.Label(dlg, text="Name (shown on the bubble):", bg=t["bg"], fg=t["muted"], font=font).pack(
            padx=16, pady=(16, 0), anchor=tk.W)
        name_e = tk.Entry(dlg, font=font, bg=t["input"], fg=t["text"], insertbackground=t["text"], relief=tk.FLAT,
                          bd=0, highlightthickness=1, highlightbackground=t["border"], highlightcolor=t["accent"])
        name_e.pack(padx=16, pady=(4, 10), fill=tk.X)
        tk.Label(dlg, text="Opens (a built-in tool, file, folder, web address, or a command):", bg=t["bg"], fg=t["muted"],
                 font=font).pack(padx=16, anchor=tk.W)
        row = tk.Frame(dlg, bg=t["bg"])
        row.pack(padx=16, pady=(4, 4), fill=tk.X)
        target_e = tk.Entry(row, font=font, width=44, bg=t["input"], fg=t["text"], insertbackground=t["text"],
                            relief=tk.FLAT, bd=0, highlightthickness=1, highlightbackground=t["border"],
                            highlightcolor=t["accent"])
        target_e.pack(side=tk.LEFT, fill=tk.X, expand=True)

        def pick(kind):
            chosen = (filedialog.askopenfilename(parent=dlg, title="Choose a file") if kind == "file"
                      else filedialog.askdirectory(parent=dlg, title="Choose a folder"))
            if chosen:
                target_e.delete(0, tk.END)
                target_e.insert(0, chosen)
                if not name_e.get().strip():
                    name_e.insert(0, (os.path.basename(chosen.rstrip("/\\")) or chosen)[:14])

        def pick_builtin():
            menu = self._mk_menu(dlg)

            def choose(label, short, key):
                target_e.delete(0, tk.END)
                target_e.insert(0, "app:" + key)
                if not name_e.get().strip():
                    name_e.insert(0, short)
            for label, short, key in self.BUILTIN_SHORTCUTS:
                menu.add_command(label=label, command=lambda a=(label, short, key): choose(*a))
            bx, by = builtin_btn.winfo_rootx(), builtin_btn.winfo_rooty() + builtin_btn.winfo_height()
            self._popup(menu, bx, by)

        builtin_btn = tk.Button(row, text="Built-in\u2026", command=pick_builtin, bg=t["neutral"], fg=t["text"],
                                activebackground=t["neutral"], relief=tk.FLAT, bd=0, padx=8, pady=4,
                                cursor="hand2", font=(t["family"], t["small"]))
        builtin_btn.pack(side=tk.LEFT, padx=(6, 0))
        for label, kind in (("Folder\u2026", "dir"), ("File\u2026", "file")):
            tk.Button(row, text=label, command=lambda k=kind: pick(k), bg=t["neutral"], fg=t["text"],
                      activebackground=t["neutral"], relief=tk.FLAT, bd=0, padx=8, pady=4, cursor="hand2",
                      font=(t["family"], t["small"])).pack(side=tk.LEFT, padx=(6, 0))
        err = tk.Label(dlg, text="", bg=t["bg"], fg="#d64545", font=(t["family"], t["small"]))
        err.pack(padx=16, anchor=tk.W)
        if initial:
            name_e.insert(0, initial["name"])
            target_e.insert(0, initial["target"])
        result = {"v": None}

        def confirm():
            name, target = name_e.get().strip(), target_e.get().strip()
            if not name or not target:
                err.config(text="Enter both a name and what it opens.")
                return
            result["v"] = {"name": name, "target": target}
            dlg.destroy()

        btns = tk.Frame(dlg, bg=t["bg"])
        btns.pack(padx=16, pady=(8, 16), fill=tk.X)
        tk.Button(btns, text="Cancel", command=dlg.destroy, bg=t["neutral"], fg=t["text"],
                  activebackground=t["neutral"], relief=tk.FLAT, bd=0, padx=10, pady=5, cursor="hand2",
                  font=font).pack(side=tk.RIGHT, padx=(6, 0))
        tk.Button(btns, text="Save", command=confirm, bg=t["accent"], fg=t["on_accent"],
                  activebackground=t["accent"], activeforeground=t["on_accent"], relief=tk.FLAT, bd=0, padx=12,
                  pady=5, cursor="hand2", font=font).pack(side=tk.RIGHT)
        dlg.bind("<Return>", lambda _e: confirm())
        dlg.bind("<Escape>", lambda _e: dlg.destroy())
        self._sc_dialog = {"name": name_e, "target": target_e, "ok": confirm, "win": dlg}     # (for tests)
        name_e.focus_set()
        dlg.wait_window()
        self._sc_dialog = None
        return result["v"]

    _MODE_WIN_ATTR = {"images": "_images_win", "music": "_music_win", "draw": "_drawing_win"}

    _MODE_OPENERS = {"images": "_open_images", "music": "_open_music", "draw": "_open_drawing"}

    _MODE_NAMES = {"images": "Images", "music": "Music", "draw": "Draw"}

    def _mode_win(self, kind):
        """The tool window for a mode: the open one if there is one, else a new one kept hidden."""
        attr = self._MODE_WIN_ATTR[kind]
        win = getattr(self, attr, None)
        try:
            if win is not None and win.win.winfo_exists():
                return win
        except tk.TclError:
            pass
        getattr(self, self._MODE_OPENERS[kind])()
        win = getattr(self, attr)
        try:
            win.win.withdraw()
        except tk.TclError:
            pass
        return win

    def _mode_show(self, kind):
        win = getattr(self, self._MODE_WIN_ATTR[kind], None)
        try:
            win.win.deiconify()
            win.win.lift()
            win.win.focus_force()
        except Exception:                                           # noqa: BLE001 - window was closed
            pass

    def _mode_new(self, kind):
        win = getattr(self, self._MODE_WIN_ATTR[kind], None)
        try:
            if win is not None and win.win.winfo_exists() and not win.busy:
                win._new()
                self._append(f"{self._MODE_NAMES[kind]}: the next one starts fresh.\n\n", "load_log")
        except tk.TclError:
            pass

    def _mode_reset(self):
        """New chat: forget Draw / Music edit history and drop the result images."""
        for kind in ("draw", "music"):
            win = getattr(self, self._MODE_WIN_ATTR[kind], None)
            try:
                if win is not None and win.win.winfo_exists() and not win.busy:
                    win._new()
            except tk.TclError:
                pass
        self._mode_photos.clear()

    def _mode_hook(self, kind, win):
        """Once per window: mirror its status text (and, for Draw / Music, its streamed output)."""
        if getattr(win, "_mode_hooked", False):
            return
        win._mode_hooked = True
        orig_status = win._set_status

        def status(*args, **kw):
            orig_status(*args, **kw)
            text = args[0] if args else kw.get("text", "")
            try:
                self.root.after(0, self._mode_on_status, kind, str(text))
            except Exception:                                       # noqa: BLE001 - app closing
                pass
        win._set_status = status
        if kind in ("draw", "music"):
            orig_piece = win._on_piece

            def piece(k, text):
                orig_piece(k, text)
                self._mode_on_piece(kind, k, text)
            win._on_piece = piece

    def _mode_on_status(self, kind, text):
        job = self._mode_job
        if not job or job["kind"] != kind or not text:
            return
        job["status"] = text
        self._mode_line(text + "   (Esc to stop)")

    def _send_mode(self, text):
        kind = self.mode_kind
        self.ws_state[kind]["prompt"] = text
        name = self._MODE_NAMES[kind]
        try:
            win = self._mode_win(kind)
        except Exception as exc:                                    # noqa: BLE001
            self._append(f"{name}: couldn't open the tool ({exc}).\n\n", "system_msg")
            return
        job = {"kind": kind, "win": win, "text": text, "idle_n": 0, "status": "", "stopped": False,
               "prev": None}
        self._mode_job = job
        self.mode_busy = True
        self.stage.set_activity("thinking")
        self._mode_hook(kind, win)
        try:
            getattr(self, "_mode_start_" + kind)(job)
        except _ModeSetup as exc:
            self._mode_end(job, error=str(exc), show_window=True)
            return
        except Exception as exc:                                    # noqa: BLE001
            self._mode_end(job, error=f"{type(exc).__name__}: {exc}")
            return
        self.root.after(400, self._mode_poll, job)

    def _mode_start_images(self, job):
        win = job["win"]
        job["prev"] = win.last_path
        win.prompt_box.delete("1.0", tk.END)
        win.prompt_box.insert("1.0", job["text"])
        self._mode_line("Starting\u2026   (Esc to stop)")
        win._generate()

    def _mode_idle(self, job):
        win, kind = job["win"], job["kind"]
        if kind == "images":
            return not (win.engine.busy or win._scanning or win._retry_after_scan)
        return not win.busy

    def _mode_poll(self, job):
        """Every 0.4s: has the tool gone quiet? (Its own callbacks are the progress; this decides when
        the job is over, so a tool that quietly refuses to start can't leave the pill stuck.)"""
        if job is not self._mode_job:
            return
        try:
            idle = self._mode_idle(job)
        except tk.TclError:                                         # its window was closed mid-job
            self._mode_end(job, error="The tool's window was closed.")
            return
        job["idle_n"] = job["idle_n"] + 1 if idle else 0
        if job["idle_n"] >= (3 if job["kind"] == "images" else 2):
            self._mode_resolve(job)
            return
        self.root.after(400, self._mode_poll, job)

    def _mode_resolve(self, job):
        kind, win = job["kind"], job["win"]
        card = None
        try:
            if kind == "images":
                p = win.last_path
                if p and p != job["prev"] and os.path.isfile(p):
                    card = lambda: self._card_images(job, p)
            elif kind == "draw":
                if win.svg_text and win.svg_text != job["prev"]:
                    card = lambda: self._card_draw(job)
            elif kind == "music":
                if len(win.messages) > job["prev"]:
                    card = lambda: self._card_music(job)
        except tk.TclError:
            pass
        if card:
            self._mode_end(job, card=card)
        elif job["stopped"]:
            self._mode_end(job, error="Stopped.")
        else:
            msg = job["status"] or "Nothing was produced."
            setup = kind == "images" and any(
                k in msg for k in ("Pick", "Missing", "executable", "checkpoint", "Python"))
            self._mode_end(job, error=msg, show_window=setup)

    def _mode_end(self, job, error=None, card=None, show_window=False):
        if job is not self._mode_job:
            return
        self._mode_job = None
        self.mode_busy = False
        self._mode_line_clear()
        self.stage.set_activity("idle")
        name = self._MODE_NAMES[job["kind"]]
        if error:
            msg = f"{name}: {error}"
            if show_window:
                msg += "\nI've opened its window so you can set that up."
                self._mode_show(job["kind"])
            self._append(msg + "\n\n", "system_msg")
        elif card:
            try:
                card()
            except Exception as exc:                                # noqa: BLE001
                self._append(f"{name}: couldn't show the result ({exc}).\n\n", "system_msg")

    def _mode_stop(self):
        """Esc / '+' menu / console 'stop': stop the running job. True if there was one."""
        job = self._mode_job
        if not job:
            return False
        job["stopped"] = True
        win, kind = job["win"], job["kind"]
        try:
            if kind == "images":
                win.engine.stop()
            else:
                win._stop()
        except Exception:                                           # noqa: BLE001
            pass
        self._mode_line("Stopping\u2026")
        return True

    def _messages_for_model(self, memory_block=""):
        """The chat history sent to the model (plus the active project's instructions)."""
        conv = [dict(m) for m in self.conversation[max(0, getattr(self, "_ctx_from", 0)):]]
        while conv and conv[0].get("role") != "user":          # after a Fresh start the history must open on a user turn
            conv.pop(0)
        return self._with_persona(self._with_project(conv), memory_block)

    def _with_project(self, msgs):
        """Folds the active project's instructions + files into the LAST user message (works with every chat
        template, including ones with no system role). Nothing is stored in self.conversation."""
        ctx = self._project_context()
        if ctx:
            for m in reversed(msgs):
                if m.get("role") == "user":
                    m["content"] = ctx + "\n\n---\nUser message:\n" + m["content"]
                    break
        return msgs

    def _chat_worker(self, model):
        """Chat's worker thread: first let the character pick a memory (one short extra call to the model), then build
        the messages and stream the reply. A failed pick never stops the reply."""
        stop = self._turn_stop
        cards = []
        try:
            cards = self._choose_memories(model)
        except Exception:                                               # noqa: BLE001
            cards = []
        if stop is not None and stop.is_set():                          # Stop pressed during the memory pick
            self._ra(self._stream_finish, True)
            return
        try:
            pe = self._active_persona()
            messages = self._messages_for_model(self._memory_block(cards, pe["name"] if pe else ""))
        except Exception as exc:                                        # noqa: BLE001
            self._ra(self._stream_error, exc)
            return
        if cards:
            self._ra(self._mem_mark_used, cards)
        self._stream_worker(messages, model)

    def _choose_memories(self, model):
        """Worker thread. The cards to offer for this message ([] for none). The model sees a short list of every
        card that is on and not yet used in this chat, and says which one fits. If it can't answer, the trigger
        words (then luck) choose instead. Once every card has had a turn, the cycle starts again."""
        pe = self._active_persona()
        if pe is None:
            return []
        live = [m for m in pe["memories"] if m.get("on", True) and _mem_filled(m)]
        if not live or random.random() >= pe.get("recall", 1.0):
            return []
        pool = [m for m in live if m["id"] not in self._mem_used]
        if not pool:
            self._mem_used = set()
            pool = live
        last = next((m["content"] for m in reversed(self.conversation) if m.get("role") == "user"), "")
        picked = self._ask_model_to_pick(model, pool)
        return picked if picked is not None else pick_memories(pool, last, set())

    def _ask_model_to_pick(self, model, pool):
        """[card] = the model chose one, [] = it says none fit, None = it couldn't be asked or the answer made no
        sense. One short, cold (low temperature) call; it stops reading as soon as it has a number."""
        def one_line(m):
            body = " ".join(m["text"].split())
            body = body if len(body) <= MEMORY_MENU_CHARS else body[:MEMORY_MENU_CHARS - 1] + "\u2026"
            title = m["title"].strip()
            return (title + ": " if title else "") + body

        recent = [c for c in self.conversation if c.get("role") in ("user", "assistant")][-2:]
        talk = "\n".join(("Person: " if c["role"] == "user" else "Character: ") + " ".join(c["content"].split())[:400]
                         for c in recent)
        prompt = ("A character is about to reply in a conversation. Choose which of their memories, if any, comes to "
                  "mind.\n\nMEMORIES\n" + "\n".join("%d. %s" % (i + 1, one_line(m)) for i, m in enumerate(pool)) +
                  "\n\nRECENT CONVERSATION\n" + talk + "\n\nWhich memory fits what the person just said best? "
                  "If none of them fit at all, answer 0. Answer with only the number.")
        msgs = [{"role": "user", "content": prompt}]
        try:
            try:
                gen = self.backend.stream_chat(model, msgs, reasoning=(False, "Medium"), temperature=0.1)
            except TypeError:
                gen = self.backend.stream_chat(model, msgs)
            raw = ""
            try:
                for delta, _finish, _usage in gen:
                    raw += delta.get("content") or ""
                    clean = re.sub(r"<think>.*?</think>", "", raw, flags=re.S)
                    if re.search(r"\d+\D", clean) or len(clean.strip()) >= 16 or len(raw) > 400:
                        break
            finally:
                gen.close()
        except Exception:                                               # noqa: BLE001
            return None
        clean = re.sub(r"<think>.*?</think>", "", raw, flags=re.S)
        num = re.search(r"\d+", clean)
        if num:
            n = int(num.group())
            if n == 0:
                return []
            return [pool[n - 1]] if 1 <= n <= len(pool) else None
        return [] if re.search(r"\bnone\b", clean.lower()) else None

    def _memory_block(self, cards, name=""):
        """The text that offers the chosen card to the model ("" for none)."""
        lines = []
        for mem in cards:
            title = mem["title"].strip()
            lines.append("- " + (title + ": " if title else "") + _strip_speaker(mem["text"], name)[:MEMORY_MAX_CHARS])
        if not lines:
            return ""
        return ("A MEMORY comes to mind, from your own past. If it fits what was just said, bring it up briefly and in "
                "your own words, keeping its details and never contradicting it. If it doesn't fit, ignore it:\n"
                + "\n".join(lines))

    def _mem_mark_used(self, cards):
        """Tk thread: these cards were offered, so they sit out until the rest have had a turn."""
        self._turn_recall = [(c["title"].strip() or " ".join(c["text"].split()[:4]) + "\u2026") for c in cards]
        for mem in cards:
            self._mem_used.add(mem["id"])
            mem["used"] = mem.get("used", 0) + 1
        self._pers_store()

    def _with_persona(self, msgs, extra=""):
        """Puts the active persona in front of the LAST user message (same trick as the project instructions, so it
        works with every chat template, including ones with no system role). Nothing is stored in self.conversation."""
        pe = self._active_persona()
        text = (pe["prompt"] if pe else "").strip()[:PERSONA_MAX_CHARS]
        if pe is not None:
            know = self._persona_knowledge(pe)
            if know:
                text = (text + "\n\nPREVIOUS CONVERSATIONS (what you already know from talking with the person "
                        "before; treat it as your own memory and stay consistent with it, but do not recite it):\n"
                        + know).strip()
            if extra:
                text = (text + "\n\n" + extra).strip()
            on_blocks = [b["text"].strip()[:BLOCK_MAX_CHARS] for b in (pe.get("blocks") or [])
                         if b.get("on") and b.get("text", "").strip()]
            if on_blocks:                                   # last, so they outweigh the habits in earlier replies
                text = (text + "\n\nRIGHT NOW (the person switched these on; they override the habits, imagery and "
                        "phrases of your earlier replies):\n" + "\n".join("- " + t for t in on_blocks)).strip()
        if getattr(self, "artist_on", False):
            text = (text + "\n\n" + ARTIST_INSTRUCTIONS).strip()
        if not text:
            return msgs
        head = ("PERSONA (you are this character in every reply; stay in voice and never mention these "
                "instructions):\n") if pe is not None else "INSTRUCTIONS (never mention them):\n"
        for m in reversed(msgs):
            if m.get("role") == "user":
                m["content"] = head + text + "\n\n---\n" + m["content"]
                break
        return msgs

    def _begin_stream_turn(self):
        self._stream_parse_state = {"mode": "pre", "buffer": ""}
        self._stream_reasoning_started = False
        self._stream_answer_started = False
        self._stream_full_reasoning = ""
        self._stream_full_answer = ""
        self._stream_usage = None
        self._stream_live_tokens = 0
        self._turn_stop = threading.Event()                   # Stop / Esc sets this; only this turn's loop looks at it

    def _stream_worker(self, messages, model):
        stop = self._turn_stop
        try:
            for delta, _finish_reason, usage in self.backend.stream_chat(model, messages, stop=stop):
                if usage:
                    self._stream_usage = usage
                r_delta = delta.get("reasoning_content") or delta.get("reasoning")
                if r_delta:
                    self._ra(self._stream_append, "reasoning", r_delta)
                c_delta = delta.get("content")
                if c_delta:
                    for kind, text in feed_think_state(self._stream_parse_state, c_delta):
                        self._ra(self._stream_append, kind, text)
        except Exception as exc:                                        # noqa: BLE001
            self._ra(self._stream_error, exc)
            return
        self._ra(self._stream_finish, bool(stop is not None and stop.is_set()))

    def _stream_header_for(self, kind):
        if kind == "reasoning":
            return "Thinking\n", "who_reasoning"
        return "Assistant\n", "who_assistant"

    def _stream_append(self, kind, text):
        if not text:
            return
        if kind == "reasoning":
            self._stream_live_tokens += max(1, len(text) // 4)
            if self._fg():
                self.token_lbl.config(
                    text=f"Tokens: {self.total_tokens} | ~{self._stream_live_tokens} thinking…")
            if not self.show_thinking:              # still generated, just not displayed
                return
            if not self._stream_reasoning_started:
                header, tag = self._stream_header_for("reasoning")
                self._append(header, tag)
                self._stream_reasoning_started = True
            self._append(text, "reasoning_text")
            self._stream_full_reasoning += text
        else:
            self._stream_live_tokens += max(1, len(text) // 4)
            if self._fg():
                self.token_lbl.config(
                    text=f"Tokens: {self.total_tokens} | ~{self._stream_live_tokens} gen…")
            if not self._stream_answer_started:
                if self._stream_reasoning_started:
                    self._append("\n\n")
                header, tag = self._stream_header_for("answer")
                self._append(header, tag)
                self._stream_answer_started = True
                if self._fg():
                    self.stage.set_activity("answering")     # softer pulse while the answer streams
            self._append(text)
            self._stream_full_answer += text

    def _stream_finish(self, stopped=False):
        """Tk thread. The reply ended: normally, or because the user pressed Stop (stopped=True, not an error)."""
        if not stopped or self._stream_reasoning_started or self._stream_answer_started:
            self._append("\n\n")        # (a Stop before anything was shown must not append to the previous reply)
        self.last_response_text = self._stream_full_answer
        if self._stream_usage:
            total = self._stream_usage.get("total_tokens")
            if total is None:
                total = self._stream_usage.get("prompt_tokens", 0) + self._stream_usage.get(
                    "completion_tokens", 0)
            self.total_tokens += total
        else:
            self.total_tokens += self._stream_live_tokens
        self.awaiting_reply = False
        if self._fg():
            self.token_lbl.config(text=f"Tokens: {self.total_tokens}")
            self.stage.set_activity("idle")
            self.send_btn.config(state=tk.NORMAL, text="Send")
            self.new_chat_btn.config(state=tk.NORMAL)
        self._tabs_render()
        if stopped and not self._stream_full_answer.strip():
            if self.conversation and self.conversation[-1]["role"] == "user":
                self.conversation.pop()                        # nothing was answered: don't leave a dangling user turn
        else:
            self.conversation.append({"role": "assistant", "content": self._stream_full_answer})
        if stopped:
            self._append("Stopped.\n\n", "system_msg")
        else:
            self._artist_after_reply(self._stream_full_answer)
        self._maybe_auto_unload()

    def _chat_stop(self):
        """Stop button and Esc: end the reply being generated for the tab on screen. True if there was one."""
        ev = self._turn_stop
        if not self.awaiting_reply or ev is None or ev.is_set():
            return False
        ev.set()
        self.toast("Stopping\u2026")
        return True

    def _send_or_stop(self):
        """The round button in the chat composer: Stop while a reply is running, otherwise Send."""
        if self.ws == "chat" and self.awaiting_reply:
            self._chat_stop()
        else:
            self.on_send()

    def _sync_send_btn(self):
        b = getattr(self, "_send_btn_w", None)
        if b is None:
            return
        try:
            if not b.winfo_exists():
                return
            want = "stop" if (self.ws == "chat" and self.awaiting_reply) else "send"
            if b.icon != want:
                b.icon = want
                b._draw()
        except (tk.TclError, AttributeError):
            pass

    def _stream_error(self, exc):
        self.awaiting_reply = False
        if self._fg():
            self.stage.set_activity("idle")
            self.send_btn.config(state=tk.NORMAL, text="Send")
            self.new_chat_btn.config(state=tk.NORMAL)
        self._tabs_render()
        if self.conversation and self.conversation[-1]["role"] == "user":
            self.conversation.pop()                            # don't poison history with a failed turn
        self._append(f"Request failed: {exc}\n\n", "system_msg")

    def _maybe_auto_unload(self):
        if not self.auto_unload_var.get():
            return
        if not self.server_connected or not self.server_model:
            return
        instance_id = self.server_instance_id or self.server_model
        tab = self._ctx_tab()
        threading.Thread(target=self._auto_unload_worker, args=(instance_id, tab), daemon=True).start()

    def _auto_unload_worker(self, instance_id, tab=None):
        try:
            self.backend.unload_model(instance_id)
        except Exception as exc:                                # noqa: BLE001
            self.root.after(0, self._run_in, tab, self._auto_unload_failed, exc)
            return
        self.root.after(0, self._run_in, tab, self._auto_unload_done)

    def _auto_unload_done(self):
        key = self.server_model
        self.server_model = None
        self.server_instance_id = None
        self.update_server_button()
        self._append("Model unloaded.\n\n", "system_msg")
        if key is not None and self._models_win is not None:
            try:
                if self._models_win.win.winfo_exists():
                    self._models_win.mark_unloaded(key)
            except tk.TclError:
                pass

    def _auto_unload_failed(self, exc):
        self._append(f"Auto-unload failed \u2014 {exc}\n\n", "system_msg")

    def _on_auto_max_ctx_toggle(self):
        self.auto_max_context = self.auto_max_ctx_var.get()
        self._settings_store(auto_max_context=bool(self.auto_max_context))
        if not self.auto_max_context:
            return
        if not self.server_connected:
            self._append("Auto-max context enabled \u2014 will apply the next time you load a model.\n\n",
                         "system_msg")
            return
        targets = []
        for entry in self.server_catalog:
            key = entry.get("key")
            max_ctx = entry.get("max_context_length")
            instances = entry.get("loaded_instances") or []
            if not key or not max_ctx or not instances:
                continue
            inst = instances[0]
            cur_ctx = (inst.get("config") or {}).get("context_length")
            if cur_ctx == max_ctx:
                continue
            targets.append((key, entry.get("display_name", key), inst.get("id") or key, max_ctx))
        if not targets:
            self._append("Auto-max context enabled. New loads will use each model's max context "
                         "automatically.\n\n", "system_msg")
            return
        self._append(f"Auto-max context enabled \u2014 reloading {len(targets)} loaded model(s) at "
                     f"their max context\u2026\n\n", "system_msg")
        for key, name, instance_id, max_ctx in targets:
            threading.Thread(target=self._auto_max_reload_worker, args=(key, name, instance_id, max_ctx),
                             daemon=True).start()

    def _auto_max_reload_worker(self, key, name, old_instance_id, new_ctx):
        try:
            self.backend.unload_model(old_instance_id)
        except Exception as exc:                                        # noqa: BLE001
            self.root.after(0, self._auto_max_reload_failed, key, name, exc)
            return
        try:
            data = self.backend.load_model(key, new_ctx)
        except Exception as exc:                                        # noqa: BLE001
            self.root.after(0, self._auto_max_reload_failed, key, name, exc)
            return
        self.root.after(0, self._auto_max_reload_done, key, name, data, new_ctx)

    def _auto_max_reload_done(self, key, name, data, new_ctx):
        new_instance_id = data.get("instance_id") or key
        if self.server_model == key:
            self.server_instance_id = new_instance_id
        self._append(f"Reloaded {name} at {new_ctx} tokens (auto-max).\n\n", "system_msg")
        if self._models_win is not None:
            try:
                if self._models_win.win.winfo_exists():
                    self._models_win.mark_reloaded(key, new_instance_id, new_ctx)
            except tk.TclError:
                pass

    def _auto_max_reload_failed(self, key, name, exc):
        if self.server_model == key:
            self.server_model = None
            self.server_instance_id = None
            self.update_server_button()
        self._append(f"Auto-max reload failed for {name} \u2014 {exc}. It may now be unloaded.\n\n",
                     "system_msg")
        if self._models_win is not None:
            try:
                if self._models_win.win.winfo_exists():
                    self._models_win.mark_unloaded(key)
            except tk.TclError:
                pass

    def _on_ram_spill_toggle(self):
        self.ram_spillover = self.ram_spill_var.get()
        self._settings_store(ram_spillover=bool(self.ram_spillover))

    def _on_gpu_layers_slider(self, _val=None):
        v = self.gpu_layers_slider_var.get()
        self.gpu_layers_override = None if v == 0 else v
        if v != 0 and self.gpu_share_pct is not None:
            self._set_gpu_share(None)          # a manual layer count replaces the % split
        self._update_gpu_layers_label()

    def _gpu_layers_text(self):
        v = self.gpu_layers_slider_var.get()
        if v == 0:
            return "GPU layers: Auto"
        text = f"GPU layers: {v}"
        try:
            if self.backend is not None:
                slots = self.backend.slots
                if slots:
                    handle = next(iter(slots.values()))
                    size_bytes = os.path.getsize(handle.path)
                    meta = self.backend._get_metadata(handle.path, size_bytes)
                    n_layers = meta.get("n_layers", 0)
                    if n_layers > 0:
                        model_mb = size_bytes / (1024 * 1024)
                        kv_mb = handle.ctx * 0.06
                        per_layer = (model_mb + kv_mb) / n_layers
                        actual_v = min(v, n_layers)
                        gpu_mb = actual_v * per_layer + 250
                        ram_mb = max(0, (n_layers - actual_v)) * per_layer
                        text = (f"{v} layers  |  ~{gpu_mb/1024:.1f} GB GPU"
                                f" / ~{ram_mb/1024:.1f} GB RAM")
        except Exception:
            pass
        return text

    def _update_gpu_layers_label(self):
        lbl = self.gpu_layers_label
        if lbl is None:
            return
        try:
            lbl.config(text=self._gpu_layers_text())
        except tk.TclError:
            self.gpu_layers_label = None

    def _on_reasoning_changed(self):
        self.reasoning_enabled = self.reasoning_var.get()
        self.reasoning_level = self.reasoning_level_var.get() or "Medium"
        self._refresh_reasoning_controls()

    def _on_show_thinking_changed(self):
        self.show_thinking = self.show_thinking_var.get()
        self._sync_think_btn()

    def _poll_load_log(self):
        """Streams llama.cpp's model-load output into the chat log (muted, monospace) while a model
        loads. Runs on the Tk thread; the load itself happens on a worker thread and only appends
        to a shared buffer."""
        global _LOAD_BUF, _LOAD_TOTAL
        with _LOG_LOCK:
            new = _LOAD_TOTAL - self._load_log_pos
            if new > 0:
                chunk = _LOAD_BUF[-new:] if new <= len(_LOAD_BUF) else _LOAD_BUF
                self._load_log_pos = _LOAD_TOTAL
            else:
                chunk = ""
        if chunk and self.show_load_log:
            chunk = chunk.replace("\r\n", "\n").replace("\r", "\n")
            self._append(chunk, "load_log")
        try:
            self.root.after(120, self._poll_load_log)
        except tk.TclError:
            pass

    def _active_model_name(self):
        """Display name of the model chat is using right now, or None."""
        key = self.server_model
        if not key:
            return None
        for entry in self.server_catalog:
            if entry.get("key") == key:
                return entry.get("display_name") or os.path.basename(str(key))
        return os.path.basename(str(key))

    def _refresh_reasoning_controls(self):
        """Keeps the chip in the input box in step with the settings, Claude-style:
        '<model>  <effort> \u25BE' - effort reads 'Off' while Reasoning is off."""
        if not hasattr(self, "reasoning_btn"):
            return
        # The model's name is shown in the status pill under the bubbles, so the chip only needs the effort.
        effort = self.reasoning_level if self.reasoning_enabled else "Off"
        self.reasoning_btn.config(text=f"Reasoning: {effort}")

    def _model_is_loaded(self, key):
        be = self.backend
        return bool(be is not None and be.slots.get(be.key_to_instance.get(key)) is not None)

    def _pick_model(self, key):
        """Load (or, if already loaded, switch chat to) a model chosen from the chip menu. Uses
        the Models window's own loader, so eviction, context length and spillover all behave
        exactly like double-clicking there."""
        if self.awaiting_reply:
            self._append("Can't change models mid-reply \u2014 wait for it to finish.\n\n", "system_msg")
            return
        viewer = self._ensure_models_viewer()
        if not viewer.models or not any(e.get("key") == key for e in viewer.models):
            viewer.apply_catalog(self.server_catalog)
        index = next((i for i, e in enumerate(viewer.models) if e.get("key") == key), None)
        if index is None:
            return
        state = viewer.model_state[key]
        if state["loaded"]:
            self.server_model = key
            self.server_instance_id = state["instance_id"]
            self.update_server_button()
            return
        self._append(f"Loading {viewer.models[index].get('display_name', key)}\u2026\n\n", "system_msg")
        viewer._load(index)

    def _settings_store(self, **kw):
        APP_SETTINGS.update(kw)
        save_app_settings(APP_SETTINGS)

    def _on_quick_boot_toggled(self):
        self._settings_store(quick_boot=bool(self.quick_boot_var.get()))

    def _set_models_folder(self, path):
        path = os.path.abspath(os.path.expanduser(str(path).strip().strip('"')))
        self.local_models_root = path
        if self.local_backend is not None:
            self.local_backend.models_root = path
        self.models_folder_var.set(path)
        self._settings_store(models_folder=path)
        self._st_scan_models()

    def _set_save_folder(self, path):
        self.save_folder = path or None
        self.save_folder_var.set(path or "")
        self._settings_store(save_folder=path or "")

    def _save_models_folder_from_settings(self):
        p = os.path.expanduser(self.models_folder_var.get().strip().strip('"'))
        if not p or not os.path.isdir(p):
            self._st_state["models_count"] = "missing"
            self._st_state["folder_msg"] = ""
            return
        self._set_models_folder(p)
        self._st_state["folder_msg"] = "Saved. Authenticate again to refresh the Models list."

    def _browse_models_folder(self):
        chosen = filedialog.askdirectory(title="Models folder", initialdir=self.local_models_root or os.getcwd())
        if chosen:
            self.models_folder_var.set(chosen)
            self._save_models_folder_from_settings()

    def _st_scan_models(self):
        """Counts the .gguf files under the models folder on a worker thread (same rule as the Models list)."""
        root_dir = self.local_models_root
        st = self._st_state
        if not root_dir or not os.path.isdir(root_dir):
            st["models_count"] = "missing"
            return
        tok = object()
        st["scan_tok"] = tok
        st["models_count"] = "scanning"

        def work():
            n = size = 0
            try:
                for d, _dirs, files in os.walk(root_dir):
                    for f in files:
                        if f.lower().endswith(".gguf"):
                            n += 1
                            try:
                                size += os.path.getsize(os.path.join(d, f))
                            except OSError:
                                pass
                res = (n, size)
            except OSError:
                res = "missing"
            if st.get("scan_tok") is tok:
                st["models_count"] = res
                st["dirty"] = True
        threading.Thread(target=work, daemon=True).start()

    def _save_output_folder_from_settings(self):
        p = os.path.expanduser(self.save_folder_var.get().strip().strip('"'))
        if not p:
            self._set_save_folder("")
        elif os.path.isdir(p):
            self._set_save_folder(os.path.abspath(p))
        else:
            try:
                os.makedirs(p, exist_ok=True)
                self._set_save_folder(os.path.abspath(p))
            except OSError as exc:
                messagebox.showerror(APP_TITLE, "Couldn't use that folder:\n%s" % exc)

    def _browse_output_folder(self):
        chosen = filedialog.askdirectory(title="Output save location", initialdir=self.save_folder or os.getcwd())
        if chosen:
            self._set_save_folder(os.path.abspath(chosen))

    def _clear_output_folder(self):
        self._set_save_folder("")

    @staticmethod
    def _st_fetch(url, limit=12_000_000, timeout=20):
        import urllib.request
        req = urllib.request.Request(url, headers={"User-Agent": "Voidloader-updater"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read(limit + 1)[:limit]

    def _st_check_update(self):
        url = self.update_url_var.get().strip()
        st = self._st_state
        st["update_data"] = None
        if not url.lower().startswith(("http://", "https://")):
            st["update_msg"] = "Paste a web address (http:// or https://) for the update file first."
            return
        self._settings_store(update_url=url)
        st["update_msg"] = "Checking\u2026"

        def work():
            try:
                data = self._st_fetch(url)
                text = data.decode("utf-8", "replace")
                m = re.search(r'^APP_VERSION\s*=\s*["\']([^"\']+)["\']', text, re.M)
                if b"class SimpleChat" not in data:
                    st["update_msg"] = "\u2717 That file doesn't look like GGUFllama_Interface.py."
                elif not m:
                    st["update_msg"] = ("The file at that address has no APP_VERSION line, so there's nothing to "
                                        "compare. Add one to the hosted file.")
                else:
                    rv = tuple(int(x) for x in re.findall(r"\d+", m.group(1)))
                    lv = tuple(int(x) for x in re.findall(r"\d+", APP_VERSION))
                    if rv > lv:
                        st["update_data"] = data
                        st["update_msg"] = "\u2713 Version %s is available (you have %s). Press Update now." % (
                            m.group(1), APP_VERSION)
                    else:
                        st["update_msg"] = "\u2713 You're up to date (installed %s, online %s)." % (
                            APP_VERSION, m.group(1))
            except Exception as exc:                                       # noqa: BLE001
                st["update_msg"] = "\u2717 Couldn't check: %s" % exc
            st["dirty"] = True
        threading.Thread(target=work, daemon=True).start()

    def _st_do_update(self):
        st = self._st_state
        data = st.get("update_data")
        if not data:
            st["update_msg"] = "Press Check for update first."
            return
        if getattr(sys, "frozen", False):
            st["update_msg"] = "This is a compiled .exe, which can't replace itself. Download the new build instead."
            return
        path = os.path.abspath(__file__)
        try:
            compile(data.decode("utf-8"), path, "exec")
        except (SyntaxError, UnicodeDecodeError, ValueError) as exc:
            st["update_msg"] = "\u2717 The downloaded file didn't pass a syntax check, so nothing was changed: %s" % exc
            return
        if not messagebox.askyesno(APP_TITLE, "Replace\n%s\nwith the downloaded version?\n\n"
                                   "The current file is kept as a .bak copy next to it. The new file is code that "
                                   "will run on this PC, so only continue if you trust the address you pasted." % path):
            return
        try:
            shutil.copy2(path, path + ".bak")
            tmp = path + ".new"
            with open(tmp, "wb") as fh:
                fh.write(data)
            os.replace(tmp, path)
        except OSError as exc:
            st["update_msg"] = "\u2717 Couldn't write the update: %s" % exc
            return
        st["update_data"] = None
        st["update_msg"] = "\u2713 Updated. The old version is saved as %s.bak. Restart to use the new one." % os.path.basename(path)
        if messagebox.askyesno(APP_TITLE, "Updated. Restart now?"):
            self._do_reboot()

    @staticmethod
    def _st_get(url, token="", timeout=5):
        import urllib.request
        import urllib.error
        req = urllib.request.Request(url)
        if token:
            req.add_header("X-Token", token)
        opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))     # never via a system proxy
        t0 = time.time()
        try:
            with opener.open(req, timeout=timeout) as r:
                return r.status, r.read(3_000_000), (time.time() - t0) * 1000
        except urllib.error.HTTPError as exc:
            return exc.code, exc.read(), (time.time() - t0) * 1000

    def _st_test_api(self):
        st, br = self._st_state, self.http_bridge
        if not br.running:
            st["api_msg"] = ("\u2717 The HTTP API is off. Turn it on with the API chip in the status bar "
                             "(or the inspector), then test again.")
            return
        st["api_msg"] = "Testing\u2026"
        port, token, lan = br.port, br.token, br.lan

        def work():
            lines = []
            try:
                base = "http://127.0.0.1:%d" % port
                code, body, ms = self._st_get(base + "/api/status", token)
                if code != 200:
                    lines.append("\u2717 /api/status answered HTTP %d" % code)
                else:
                    info = json.loads(body.decode("utf-8", "replace"))
                    lines.append("\u2713 /api/status answered in %d ms" % ms)
                    if info.get("connected") and info.get("loaded"):
                        lines.append("\u2713 Model ready: %s" % (info.get("model") or "loaded"))
                    elif info.get("connected"):
                        lines.append("\u2022 Connected, but no model is loaded - chat requests would get an error until one is")
                    else:
                        lines.append("\u2022 Voidloader isn't authenticated yet - chat requests need Authenticate and a loaded model")
                    code, body, ms = self._st_get(base + "/api/models", token)
                    if code == 200:
                        models = json.loads(body.decode("utf-8", "replace"))
                        n = len(models.get("models", models)) if isinstance(models, (dict, list)) else 0
                        lines.append("\u2713 /api/models lists %d model%s" % (n, "" if n == 1 else "s"))
                    else:
                        lines.append("\u2717 /api/models answered HTTP %d" % code)
            except Exception as exc:                                           # noqa: BLE001
                lines.append("\u2717 Couldn't reach the API: %s" % exc)
            st["api_msg"] = "\n".join(lines)
            st["dirty"] = True
        threading.Thread(target=work, daemon=True).start()

    def _st_run_setup_check(self):
        """Run every setup check in a background thread and report pass/warn/fail per category."""
        st = self._st_state
        st["setup_msg"] = "Checking\u2026"
        root = self.local_models_root
        ie = self.image_engine

        def work():
            try:
                run()
            except Exception as exc:                                        # noqa: BLE001
                st["setup_msg"] = "\u2717 The setup check itself failed: %s: %s" % (type(exc).__name__, exc)
                st["dirty"] = True

        def run():
            ok, warn, fail = "\u2713", "\u2022", "\u2717"
            lines = []

            # ---- 1. GGUF models folder -----------------------------------------------
            lines.append("--- Chat models (GGUF / LM Studio) ---")
            if not root or not os.path.isdir(root):
                lines.append("%s Models folder not set or missing. Go to Settings > Folders." % fail)
            else:
                lines.append("%s Models folder: %s" % (ok, root))
                gguf_files = []
                for dirpath, _dirs, files in os.walk(root):
                    for f in files:
                        if f.lower().endswith(".gguf"):
                            gguf_files.append(os.path.join(dirpath, f))
                if not gguf_files:
                    lines.append("%s No .gguf files found in the models folder." % fail)
                else:
                    lines.append("%s %d .gguf model%s found." % (ok, len(gguf_files), "" if len(gguf_files)==1 else "s"))
                    for f in sorted(gguf_files)[:5]:
                        lines.append("     %s" % os.path.basename(f))
                    if len(gguf_files) > 5:
                        lines.append("     ... and %d more" % (len(gguf_files)-5))

            # ---- 2. LM Studio connection ---------------------------------------------
            lines.append("")
            lines.append("--- LM Studio server ---")
            if self.server_connected:
                lines.append("%s Authenticated and connected." % ok)
            else:
                lines.append("MINOR Not connected yet. Click Authenticate in Chat controls when you want to chat.")

            # ---- 3. Image generation (stable-diffusion.cpp) -------------------------
            lines.append("")
            lines.append("--- Image generation (stable-diffusion.cpp) ---")
            # paths already chosen in the Images window win; otherwise scan (returns (exes, models))
            sd_exe = (getattr(self, "sd_exe", "") or "").strip()
            sd_model = (getattr(self, "sd_model", "") or "").strip()
            if not os.path.isfile(sd_exe) or not os.path.isfile(sd_model):
                try:
                    exes, models = scan_for_sd([root] if root else (), not os.path.isfile(sd_exe),
                                               not os.path.isfile(sd_model), 6.0)
                except Exception:                                           # noqa: BLE001
                    exes, models = [], []
                if not os.path.isfile(sd_exe) and exes:
                    sd_exe = exes[0]
                if not os.path.isfile(sd_model) and models:
                    sd_model = models[0]
            if os.path.isfile(sd_exe):
                lines.append("%s %s found: %s" % (ok, os.path.basename(sd_exe), sd_exe))
            else:
                lines.append("%s sd-cli.exe / sd.exe not found. Download stable-diffusion.cpp (CUDA build) and "
                             "use Browse in the Images window." % fail)
            if os.path.isfile(sd_model):
                gb = os.path.getsize(sd_model) / 1073741824.0
                if gb < 1.0:
                    lines.append("%s %s is only %.2f GB - too small for a full SD 1.5 checkpoint (maybe a LoRA/VAE)."
                                 % (warn, os.path.basename(sd_model), gb))
                elif gb > 8.0:
                    lines.append("%s %s is %.1f GB - larger than SD 1.5 (~2-4 GB); it may be SDXL/Flux, which "
                                 "this tool doesn't support." % (warn, os.path.basename(sd_model), gb))
                else:
                    lines.append("%s SD checkpoint: %s (%.1f GB)" % (ok, os.path.basename(sd_model), gb))
            else:
                lines.append("%s No SD 1.5 checkpoint (.safetensors/.ckpt) found. v1-5-pruned-emaonly.safetensors "
                             "works; place it anywhere on this PC or in your models folder." % fail)
            if os.path.isfile(sd_exe) and os.name == "nt":
                dlls = [f for f in os.listdir(os.path.dirname(os.path.abspath(sd_exe))) if f.lower().endswith(".dll")]
                if not any("cudart" in f.lower() or "cublas" in f.lower() for f in dlls):
                    lines.append("%s No CUDA runtime DLLs next to the exe. Fine if CUDA is installed system-wide; "
                                 "otherwise grab the release's cudart zip." % warn)

            # ---- 4. GPU / nvidia-smi ------------------------------------------------
            lines.append("")
            lines.append("--- GPU (CUDA / nvidia-smi) ---")
            gpu_w = _pm_read_gpu()
            if gpu_w is not None:
                lines.append("%s nvidia-smi found. GPU drawing %.1f W." % (ok, gpu_w))
            else:
                lines.append("%s nvidia-smi not found or returned nothing. GPU features (image gen, power monitor GPU) need CUDA drivers." % warn)

            # ---- 5. Power monitor (PowerShell + WMI battery) ------------------------
            lines.append("")
            lines.append("--- Power monitor (battery / PowerShell) ---")
            if sys.platform != "win32":
                lines.append("%s Not Windows - power monitor won't run." % fail)
            else:
                batt = _pm_read_battery()
                if batt:
                    lines.append("%s PowerShell + WMI battery OK. %s, %.0f%% charged." % (
                        ok, "AC" if batt["ac"] else "On battery",
                        batt["percent"] if batt["percent"] is not None else 0))
                else:
                    lines.append("%s PowerShell battery query returned nothing. Power monitor may not work." % warn)

            # ---- 7. Save folder -----------------------------------------------------
            lines.append("")
            lines.append("--- Save folder ---")
            sf = getattr(self, "save_folder", None)
            if sf and os.path.isdir(sf):
                lines.append("%s Save folder: %s" % (ok, sf))
            else:
                lines.append("MINOR No save folder set (optional). Set one in Settings > Folders.")

            total_ok    = sum(1 for l in lines if l.startswith(ok))
            total_fail  = sum(1 for l in lines if l.startswith(fail))
            total_warn  = sum(1 for l in lines if l.startswith(warn))
            total_minor = sum(1 for l in lines if l.startswith("MINOR"))
            if total_fail == 0 and total_warn == 0:
                summary = ("%s Script is in perfect health: %d passed%s." % (
                    ok, total_ok, (", %d minor (optional, nothing to fix)" % total_minor) if total_minor else ""))
            else:
                summary = "Summary: %d passed, %d warning%s, %d failed%s." % (
                    total_ok, total_warn, "" if total_warn == 1 else "s", total_fail,
                    (", %d minor" % total_minor) if total_minor else "")
            st["setup_msg"] = summary + "\n" + "\n".join(lines)
            st["dirty"] = True

        threading.Thread(target=work, daemon=True).start()

    def _st_test_http(self):
        st, br = self._st_state, self.http_bridge
        be_running = bool(getattr(self.block_editor, "running", False))
        st["http_msg"] = "Testing\u2026"
        running, port, token, lan = br.running, br.port, br.token, br.lan

        def work():
            import socket
            lines = []
            if not running:
                lines.append("\u2022 HTTP server is off (turn on the HTTP API or the phone app from the status bar)")
            else:
                try:
                    socket.create_connection(("127.0.0.1", port), timeout=3).close()
                    lines.append("\u2713 Port %d is accepting connections (%s)" % (
                        port, "network mode, PIN required" if lan else "this PC only"))
                    code, body, ms = self._st_get("http://127.0.0.1:%d/" % port)
                    if code == 200:
                        lines.append("\u2713 Phone page served (%d KB, %d ms)" % (len(body) // 1024, ms))
                    elif code == 404:
                        lines.append("\u2717 Phone page missing - put GGUFllama_Phone.html next to the script")
                    else:
                        lines.append("\u2717 Phone page answered HTTP %d" % code)
                    code, _b, _ms = self._st_get("http://127.0.0.1:%d/api/status" % port)
                    if lan:
                        lines.append(("\u2713 API rejects requests without the PIN (HTTP 401)" if code == 401 else
                                      "\u2717 API answered HTTP %d without a PIN - it should be 401" % code))
                        code, _b, _ms = self._st_get("http://127.0.0.1:%d/api/status" % port, token)
                        lines.append("\u2713 API accepts the PIN" if code == 200 else
                                     "\u2717 API answered HTTP %d with the PIN" % code)
                        ip = lan_ip()
                        if ip == "127.0.0.1":
                            lines.append("\u2022 No network address found, so the phone can't reach this PC")
                        else:
                            try:
                                socket.create_connection((ip, port), timeout=3).close()
                                lines.append("\u2713 Reachable on the network at http://%s:%d/" % (ip, port))
                                lines.append("\u2022 If the phone still can't connect, Windows Firewall may be blocking other devices")
                            except OSError as exc:
                                lines.append("\u2717 Not reachable at %s:%d (%s)" % (ip, port, exc))
                    else:
                        lines.append(("\u2713 API answers without a PIN (local-only mode)" if code == 200 else
                                      "\u2717 API answered HTTP %d" % code))
                except OSError as exc:
                    lines.append("\u2717 Couldn't connect to port %d: %s" % (port, exc))
            lines.append("\u2022 Block Editor server: %s" % ("running" if be_running else "off"))
            st["http_msg"] = "\n".join(lines)
            st["dirty"] = True
        threading.Thread(target=work, daemon=True).start()

    def connect_server(self):
        if self.backend is None:
            self._append("llama-cpp-python isn't installed in this environment \u2014 can't connect. "
                         "Install it with: pip install llama-cpp-python\n\n", "system_msg")
            return
        self.connect_btn.config(state=tk.DISABLED, text="Authenticating\u2026")
        threading.Thread(target=self._connect_worker, daemon=True).start()

    def _connect_worker(self):
        try:
            self.backend.connect()
        except Exception as exc:                                # noqa: BLE001
            self.root.after(0, self._connect_failed, exc)
            return
        self.root.after(0, self._connect_done)

    def _connect_done(self):
        self.connect_btn.config(state=tk.DISABLED, text="Authenticate")
        self.on_server_connected()
        self._append(f"Connected \u2014 using {self.backend.display_name}.\n\n", "system_msg")
        self.fetch_model_catalog()             # auto-populate the Models window's matches

    def _connect_failed(self, exc):
        self.connect_btn.config(state=tk.NORMAL, text="Authenticate")
        self._append(f"Could not connect ({self.backend.display_name}) \u2014 {exc}\n\n", "system_msg")
        if getattr(self, "_quick", False):
            self._quick_abort("Quick launch stopped: could not connect.")

    def disconnect_server(self):
        try:
            self.backend.disconnect()           # frees GPU VRAM for the Local backend
        except Exception:                       # noqa: BLE001 - best-effort cleanup
            pass
        self.on_server_disconnected()
        self.connect_btn.config(state=tk.NORMAL, text="Authenticate")

    def fetch_model_catalog(self):
        """Pull the active backend's model catalog and, if the Models window is open, push the
        refreshed matches into it right away - this is the "automatic" half of Connect."""
        threading.Thread(target=self._fetch_catalog_worker, daemon=True).start()

    def _fetch_catalog_worker(self):
        try:
            models = self.backend.fetch_catalog()
        except Exception as exc:                                # noqa: BLE001
            self.root.after(0, self._fetch_catalog_failed, exc)
            return
        self.root.after(0, self._fetch_catalog_done, models)

    def _fetch_catalog_failed(self, exc):
        self._append(f"Connected, but could not fetch the model catalog \u2014 {exc}\n\n", "system_msg")
        if getattr(self, "_quick", False):
            self._quick_abort("Quick launch stopped: could not read the model list.")
        if self._models_win is not None:
            try:
                if self._models_win.win.winfo_exists():
                    self._models_win._set_status(f"Could not fetch the server's model catalog \u2014 {exc}")
            except tk.TclError:
                pass

    def on_server_connected(self):
        self.server_connected = True
        self.update_server_button()

    def on_server_disconnected(self):
        self.server_connected = False
        self.server_model = None
        self.server_instance_id = None
        self.server_catalog = []
        self.update_server_button()

    _CON_ALIASES = {"?": "help", "ls": "models", "list": "models", "cls": "clear", "reset": "new",
                    "newchat": "new", "auth": "connect", "authenticate": "connect", "think": "thinking",
                    "q": "quit", "close": "exit", "ram": "spill", "gpu": "gpulayers", "unloadall": "disconnect",
                    "caches": "cache", "cleanup": "cache", "restart": "reboot", "cache//reboot": "cachereboot", "clearcache": "factoryreset", "default": "factoryreset", "factory": "factoryreset", "11": "eleven", "max": "maximum"}

    def _con_history(self, step):
        if not self.console_history:
            return "break"
        self.console_hist_pos = max(0, min(len(self.console_history), self.console_hist_pos + step))
        self.console_entry.delete(0, tk.END)
        if self.console_hist_pos < len(self.console_history):
            self.console_entry.insert(0, self.console_history[self.console_hist_pos])
        return "break"

    def _con_command_names(self):
        names = {n[4:] for n in dir(self) if n.startswith("_cc_")}
        return sorted(names)

    def _con_tab(self, _event=None):
        text = self.console_entry.get()
        if " " in text:
            return "break"
        matches = [n for n in self._con_command_names() if n.startswith(text.lower())]
        if len(matches) == 1:
            self.console_entry.delete(0, tk.END)
            self.console_entry.insert(0, matches[0] + " ")
        elif matches:
            self._con_print("  ".join(matches), "c_dim")
        return "break"

    def _con_on_return(self, _event=None):
        line = self.console_entry.get().strip()
        self.console_entry.delete(0, tk.END)
        if not line:
            return "break"
        self._con_print("> " + line, "c_cmd")
        self.console_history.append(line)
        self.console_hist_pos = len(self.console_history)
        self._con_execute(line)
        self._refresh_inspector_soft()
        return "break"

    def _con_execute(self, line):
        import shlex
        try:
            parts = shlex.split(line)
        except ValueError:
            parts = line.split()
        if not parts:
            return
        if len(parts) >= 3 and parts[0].lower().lstrip("/") == "cache" and parts[1] == "//" \
                and parts[2].lower() == "reboot":                      # "cache // reboot" -> "cache//reboot"
            parts = ["cache//reboot"] + parts[3:]
        elif len(parts) >= 2 and parts[0].lower().lstrip("/") == "cache" and parts[1].lower() == "//reboot":
            parts = ["cache//reboot"] + parts[2:]
        cmd = parts[0].lower().lstrip("/")
        cmd = self._CON_ALIASES.get(cmd, cmd)
        handler = getattr(self, "_cc_" + cmd, None)
        if handler is None:
            close = difflib.get_close_matches(cmd, self._con_command_names(), n=1)
            hint = f" Did you mean '{close[0]}'?" if close else ""
            self._con_err(f"Unknown command '{cmd}'.{hint} Type 'help'.")
            return
        try:
            handler(parts[1:], line)
        except Exception as exc:                                        # noqa: BLE001
            self._con_err(f"{cmd} failed: {exc}")

    def _con_bool(self, args, current):
        """on/off/toggle argument -> bool, or None if it isn't understood."""
        if not args:
            return not current
        a = args[0].lower()
        if a in ("on", "1", "true", "yes", "enable", "enabled"):
            return True
        if a in ("off", "0", "false", "no", "disable", "disabled"):
            return False
        self._con_err("Use on or off.")
        return None

    def _con_sorted_catalog(self):
        return sorted(self.server_catalog, key=lambda e: e.get("size_bytes") or 0, reverse=True)

    def _con_find_model(self, query):
        """Number from `models`, or a (partial) name -> catalog entry, or None (already reported)."""
        if not self.server_connected:
            self._con_err("Not connected. Run 'connect' first.")
            return None
        cat = self._con_sorted_catalog()
        if not cat:
            self._con_err("No .gguf models found. Check the models folder ('folder').")
            return None
        if query.isdigit():
            i = int(query)
            if 1 <= i <= len(cat):
                return cat[i - 1]
            self._con_err(f"No model #{i}. Run 'models' to see the list.")
            return None
        q = query.lower()
        hits = [e for e in cat if q in (e.get("display_name") or os.path.basename(str(e.get("key")))).lower()]
        if len(hits) == 1:
            return hits[0]
        if not hits:
            self._con_err(f"No model matches '{query}'.")
        else:
            self._con_err(f"'{query}' matches {len(hits)} models - be more specific or use its number:")
            for e in hits:
                self._con_print("  #%d  %s" % (cat.index(e) + 1, e.get("display_name")), "c_dim")
        return None

    def _con_busy(self):
        if self.awaiting_reply:
            self._con_err("Busy - a reply is running. Wait for it to finish.")
            return True
        return False

    def _con_watch_load(self, key, name, tries=0):
        """Reports in the console when a load started from it has finished."""
        if self._model_is_loaded(key) and self.server_model == key:
            self._con_ok(f"Loaded {name} - chat now uses it.")
            return
        if tries > 1200:                                    # ~10 minutes
            self._con_err(f"Gave up waiting for {name} - check the chat log for a load error.")
            return
        self.root.after(500, self._con_watch_load, key, name, tries + 1)

    def _cc_help(self, args, _line=None):
        """help [command] - list commands"""
        names = self._con_command_names()
        if args:
            h = getattr(self, "_cc_" + self._CON_ALIASES.get(args[0].lower(), args[0].lower()), None)
            self._con_print((h.__doc__ or "No help.").strip() if h else f"No command '{args[0]}'.")
            return
        for n in names:
            doc = (getattr(self, "_cc_" + n).__doc__ or "").strip().splitlines()[0:1]
            self._con_print(f"  {doc[0] if doc else n}")
        self._con_print("Tab completes command names, Up/Down recall history.", "c_dim")

    def _cc_status(self, args, _line=None):
        """status - connection, model, settings"""
        be = self.backend
        self._con_print(f"Backend:    {'connected' if self.server_connected else 'NOT connected'}"
                        f"  ({be.display_name if be else 'llama-cpp-python missing'})")
        self._con_print(f"Chat model: {self._active_model_name() or 'none'}")
        handle = be.slots.get(be.key_to_instance.get(self.server_model)) if be and self.server_model else None
        if handle:
            self._con_print(f"Context:    {handle.ctx}")
        if be:
            self._con_print(f"VRAM:       ~{be._current_vram_mb()} / {be.TOTAL_VRAM_MB} MB (estimate), "
                            f"{len(be.slots)} model(s) loaded")
        self._con_print(f"Reasoning:  {'on, ' + self.reasoning_level if self.reasoning_enabled else 'off'}   "
                        f"show thinking: {self.show_thinking}")
        self._con_print(f"Auto-max ctx: {self.auto_max_context}   RAM spillover: {self.ram_spillover}   "
                        f"GPU layers: {self.gpu_layers_override or 'Auto'}")
        self._con_print(f"Unload after reply: {bool(self.auto_unload_var.get())}")
        self._con_print(f"Tokens: {self.total_tokens}   HTTP API: {'on' if self.http_bridge.running else 'off'}   "
                        f"Block Editor: {'on' if self.block_editor.running else 'off'}")

    def _cc_connect(self, args, _line=None):
        """connect - authenticate (checks the models folder, loads the catalog)"""
        self.connect_server()
        self._con_print("Authenticating... run 'models' in a moment.", "c_dim")

    def _cc_disconnect(self, args, _line=None):
        """disconnect - unload every model and disconnect"""
        self.disconnect_server()
        self._con_ok("Disconnected; all models unloaded.")

    def _cc_folder(self, args, _line=None):
        """folder [path] - show or set the models folder (then run 'connect')"""
        if not args:
            self._con_print(self.local_models_root)
            return
        path = os.path.expanduser(" ".join(args))
        if not os.path.isdir(path):
            self._con_err(f"Not a folder: {path}")
            return
        self._set_models_folder(path)
        self._con_ok(f"Models folder set. Run 'connect' to rescan.")

    def _cc_models(self, args, _line=None):
        """models - numbered list of .gguf models (✓ loaded, * chat model)"""
        if not self.server_connected:
            self._con_err("Not connected. Run 'connect' first.")
            return
        cat = self._con_sorted_catalog()
        if not cat:
            self._con_err("No .gguf models found.")
            return
        for i, e in enumerate(cat, 1):
            key = e.get("key")
            mark = "✓" if self._model_is_loaded(key) else " "
            star = "*" if key == self.server_model else " "
            size = _format_size(e.get("size_bytes") or 0)
            self._con_print(f"{i:>3} {mark}{star} {e.get('display_name')}  ({size})")

    def _cc_load(self, args, _line=None):
        """load <# or name> - load a model and use it for chat"""
        if not args:
            self._con_err("Usage: load <number or part of the name>")
            return
        if self._con_busy():
            return
        entry = self._con_find_model(" ".join(args))
        if entry is None:
            return
        key, name = entry.get("key"), entry.get("display_name") or entry.get("key")
        if self._model_is_loaded(key):
            self._pick_model(key)
            self._con_ok(f"{name} is already loaded - chat now uses it.")
            return
        self._pick_model(key)
        self._con_print(f"Loading {name}...", "c_dim")
        self._con_watch_load(key, name)

    def _con_viewer_index(self, key):
        viewer = self._ensure_models_viewer()
        if not any(e.get("key") == key for e in viewer.models):
            viewer.apply_catalog(self.server_catalog)
        idx = next((i for i, e in enumerate(viewer.models) if e.get("key") == key), None)
        return viewer, idx

    def _cc_unload(self, args, _line=None):
        """unload [# or name] - unload a model (default: the chat model)"""
        if args:
            entry = self._con_find_model(" ".join(args))
            if entry is None:
                return
            key = entry.get("key")
        else:
            key = self.server_model
            if not key:
                self._con_err("No chat model is loaded.")
                return
        if not self._model_is_loaded(key):
            self._con_err("That model isn't loaded.")
            return
        viewer, idx = self._con_viewer_index(key)
        if idx is None:
            self._con_err("Model not found in the catalog.")
            return
        viewer._unload(idx)
        self._con_ok(f"Unloading {os.path.basename(str(key))}...")

    def _cc_new(self, args, _line=None):
        """new - clear the chat (keeps models loaded)"""
        if self._con_busy():
            return
        self.new_chat()
        self._con_ok("Chat cleared.")

    def _cc_reasoning(self, args, _line=None):
        """reasoning [on|off] - let the model think"""
        v = self._con_bool(args, self.reasoning_enabled)
        if v is None:
            return
        self.reasoning_var.set(v)
        self._on_reasoning_changed()
        self._con_ok(f"Reasoning {'on' if v else 'off'}.")

    def _cc_effort(self, args, _line=None):
        """effort [low|medium|high|extreme|ultra] - reasoning effort"""
        if not args:
            self._con_print(self.reasoning_level)
            return
        lvl = args[0].capitalize()
        if lvl not in REASONING_LEVELS[1:]:
            self._con_err("Use " + ", ".join(x.lower() for x in REASONING_LEVELS[1:]) + ".")
            return
        self.reasoning_level_var.set(lvl)
        self._on_reasoning_changed()
        self._con_ok(f"Effort: {lvl}")

    def _cc_thinking(self, args, _line=None):
        """thinking [on|off] - show the model's thinking block"""
        v = self._con_bool(args, self.show_thinking)
        if v is None:
            return
        self.show_thinking_var.set(v)
        self._on_show_thinking_changed()
        self._con_ok(f"Show thinking {'on' if v else 'off'}.")

    def _cc_automax(self, args, _line=None):
        """automax [on|off] - auto-max context for all models"""
        v = self._con_bool(args, self.auto_max_context)
        if v is None:
            return
        self.auto_max_ctx_var.set(v)
        self._on_auto_max_ctx_toggle()
        self._con_ok(f"Auto-max context {'on' if v else 'off'}.")

    def _cc_spill(self, args, _line=None):
        """spill [on|off] - allow RAM spillover (Local)"""
        v = self._con_bool(args, self.ram_spillover)
        if v is None:
            return
        self.ram_spill_var.set(v)
        self._on_ram_spill_toggle()
        self._con_ok(f"RAM spillover {'on' if v else 'off'}.")

    def _cc_split(self, args, _line=None):
        """split [gpu%|auto] - share of layers on the GPU; the rest run from RAM (next load)"""
        if not args:
            p = self.gpu_share_pct
            self._con_print("Auto" if p is None else "GPU %d%% / RAM %d%%" % (p, 100 - p))
            return
        a = args[0].lower().rstrip("%")
        if a == "auto":
            self._set_gpu_share(None)
            self._con_ok("Split cleared (Auto).")
        elif a.isdigit() and int(a) <= 100:
            self._set_gpu_share(int(a))
            self._con_ok("GPU %d%% / RAM %d%% (applies to the next load)." % (int(a), 100 - int(a)))
        else:
            self._con_err("Use a number 0-100 (GPU %), or auto.")

    def _cc_gpulayers(self, args, _line=None):
        """gpulayers [N|auto] - GPU layers for the next load (needs spill on)"""
        if not args:
            self._con_print(str(self.gpu_layers_override or "Auto"))
            return
        a = args[0].lower()
        if a == "auto":
            n = 0
        elif a.isdigit() and int(a) <= 60:
            n = int(a)
        else:
            self._con_err("Use a number 0-60, or auto.")
            return
        self.gpu_layers_slider_var.set(n)
        self._on_gpu_layers_slider()
        self._con_ok(f"GPU layers: {n or 'Auto'} (applies to the next load).")
        if not self.ram_spillover:
            self._con_print("Note: only used while RAM spillover is on ('spill on').", "c_dim")

    def _cc_autounload(self, args, _line=None):
        """autounload [on|off] - unload the model after each reply"""
        v = self._con_bool(args, bool(self.auto_unload_var.get()))
        if v is None:
            return
        self._set_auto_unload(v)
        self._con_ok(f"Unload after each reply {'on' if v else 'off'}.")

    def _cc_maximum(self, args, _line=None):
        """maximum [on|off] - maximum context + RAM spillover + unlimited saved knowledge, all at once (experimental)"""
        cur = bool(self.auto_max_context and APP_SETTINGS.get("knowledge_unlimited", False))
        v = self._con_bool(args, cur)
        if v is None:
            return
        if v:
            self._settings_store(knowledge_unlimited=True)
            self._set_spill(True)
            self._set_auto_max(True)                                     # last: it reloads loaded models
            self._con_ok("Maximum on: maximum context, RAM spillover and unlimited saved knowledge. Experimental, "
                         "loads can be slow. 'maximum off' undoes it.")
        else:
            self._settings_store(knowledge_unlimited=False)
            self._set_auto_max(False)
            self._con_ok("Maximum off: maximum context and unlimited saved knowledge are off (RAM spillover left as "
                         "it was). Loaded models keep their context until the next load.")
        self._ctx_redraw()

    def _cc_eleven(self, args, _line=None):
        """eleven [on|off] - absolutely everything maxed out (maximum + Auto split + keep model loaded); off restores your earlier settings (experimental)"""
        cur = isinstance(APP_SETTINGS.get("pre_eleven"), dict)
        v = self._con_bool(args, cur)
        if v is None:
            return
        if v:
            self._ctx_go_eleven(confirm=False)
            self._con_ok("Everything is at 11. Experimental. 'eleven off' puts your earlier settings back.")
        elif cur:
            self._ctx_back_to_normal()
            self._con_ok("Back to your earlier settings.")
        else:
            self._con_print("Nothing to restore: 11 is not on.", "c_dim")

    def _cc_vram(self, args, _line=None):
        """vram [GB] - show or set how much VRAM your GPU has (rescales the VRAM limits; already-loaded models keep their estimates)"""
        if args:
            gb = parse_vram_gb(" ".join(args))
            if gb is None:
                self._con_err("Give an amount of GB between %g and %g, e.g.  vram 12" % (VRAM_GB_MIN, VRAM_GB_MAX))
                return
            apply_vram_gb(gb)
            self._settings_store(vram_gb=gb)
            try:
                self.redraw_ledgers()
            except Exception:                                           # noqa: BLE001
                pass
        total = LocalLlamaBackend.TOTAL_VRAM_MB
        self._con_ok("VRAM limit: %s MB total, %s MB safety margin  (%g GB)." % (
            format(total, ","), format(LOCAL_VRAM_SAFETY_MARGIN_MB, ","),
            APP_SETTINGS.get("vram_gb") or VRAM_GB_DEFAULT))

    def _cc_api(self, args, _line=None):
        """api [on|off] - HTTP API on 127.0.0.1"""
        v = self._con_bool(args, self.http_bridge.running)
        if v is None:
            return
        if v != self.http_bridge.running:
            self._toggle_http_bridge()
        self._con_ok(f"HTTP API {'on' if self.http_bridge.running else 'off'}.")

    def _cc_phone(self, args, _line=None):
        """phone [on|off|qr] - serve the phone web app on your Wi-Fi; `phone qr` shows the QR code"""
        now = self.http_bridge.running and self.http_bridge.lan
        if args and args[0].lower() == "qr":
            self._show_phone_qr()
            return
        v = self._con_bool(args, now)
        if v is None:
            return
        if v != now:
            self._toggle_phone_app()
        on = self.http_bridge.running and self.http_bridge.lan
        self._con_ok(f"Phone app {'on - see the chat log for the address and PIN' if on else 'off'}.")

    def _cc_tokens(self, args, _line=None):
        """tokens - token count for this chat"""
        self._con_print(f"Tokens: {self.total_tokens}")

    def _cc_copy(self, args, _line=None):
        """copy - copy the last reply to the clipboard"""
        if not self.last_response_text.strip():
            self._con_err("No reply yet.")
            return
        self.root.clipboard_clear()
        self.root.clipboard_append(self.last_response_text)
        self._con_ok("Last reply copied.")

    def _cache_targets(self):
        """name -> (description, [paths]). Only looks - nothing is created or deleted here.
        Generated images are matched by their own filename pattern (sd_*.png)
        so anything else you keep in those folders is never touched."""
        import glob
        tmp = tempfile.gettempdir()
        base = self.save_folder or tmp
        return {
            "blocks":     ("Block Editor run files in the temp folder",
                           glob.glob(os.path.join(tmp, "block_app_*.py"))
                           + glob.glob(os.path.join(tmp, "block_test_*"))),
            "images":     ("generated images (Images window)",
                           glob.glob(os.path.join(base, "GGUFllama_images", "sd_*.png"))),
        }

    @staticmethod
    def _path_bytes(path):
        try:
            if os.path.isdir(path):
                return sum(os.path.getsize(os.path.join(d, f)) for d, _, fs in os.walk(path) for f in fs)
            return os.path.getsize(path)
        except OSError:
            return 0

    @staticmethod
    def _fmt_bytes(n):
        for unit in ("B", "KB", "MB", "GB"):
            if n < 1024 or unit == "GB":
                return f"{n:.0f} {unit}" if unit == "B" else f"{n:.1f} {unit}"
            n /= 1024.0

    def _gen_busy(self):
        """True if any loaded model is mid-generation for ANY caller (a chat reply, the Draw / Music windows, the HTTP
        API or the phone). This is the same lock the streaming code holds, so the Tk thread can ask without waiting."""
        be = self.local_backend
        return bool(be is not None and any(h.gen_lock.locked() for h in list(be.slots.values())))

    def _clear_all_conversations(self):
        """Resets every chat tab to a blank start and wipes each loaded model's context cache, so nothing from
        earlier conversations can carry over. Returns (ok, message). Models stay loaded; saved chats, projects and
        persona notes are left alone."""
        self._tabs_ensure()
        if any(t.get("awaiting_reply") for t in self._tabs) or self.mode_busy or self._story_busy:
            return False, "A reply is still running. Wait for it to finish, then try again."
        if self._gen_busy():                                    # Draw / Music / API / phone also hold the model lock
            return False, "A model is still generating (chat, drawing, music or an API request). Wait for it to finish, then try again."
        for t in self._tabs:
            for name, make in _TAB_DEFAULTS.items():
                if name in ("server_model", "server_instance_id"):
                    continue                                    # the tab keeps its model
                t[name] = make()
        n_kv = 0
        be = self.local_backend
        for h in list(be.slots.values()) if be is not None else []:
            if not h.gen_lock.acquire(blocking=False):            # never wait for a model on the Tk thread
                continue                                        # it started generating a moment ago: leave its cache alone
            try:
                if h.llm is not None:
                    h.llm.reset()                               # forget the evaluated tokens / KV cache
                    try:
                        h.llm._ctx.kv_cache_clear()
                    except Exception:                           # noqa: BLE001
                        pass
                    n_kv += 1
            except Exception:                                   # noqa: BLE001
                pass
            finally:
                h.gen_lock.release()
        self._mh = {}
        self._followup_card = None
        try:
            self._mode_reset()
            self.token_lbl.config(text="Tokens: 0")
            self.send_btn.config(state=tk.NORMAL, text="Send")
            self.new_chat_btn.config(state=tk.NORMAL)
        except (tk.TclError, AttributeError):
            pass
        self._tabs_render()
        if self.ws == "chat":
            self.render_center()
        return True, "Cleared %d chat tab(s) and the context cache of %d loaded model(s)." % (len(self._tabs), n_kv)

    @staticmethod
    def _ram_free_gb():
        """Free physical RAM in GB (Windows), or None if it can't be read."""
        if sys.platform != "win32":
            return None
        try:
            import ctypes

            class _MS(ctypes.Structure):
                _fields_ = [("dwLength", ctypes.c_ulong), ("dwMemoryLoad", ctypes.c_ulong),
                            ("ullTotalPhys", ctypes.c_ulonglong), ("ullAvailPhys", ctypes.c_ulonglong),
                            ("ullTotalPageFile", ctypes.c_ulonglong), ("ullAvailPageFile", ctypes.c_ulonglong),
                            ("ullTotalVirtual", ctypes.c_ulonglong), ("ullAvailVirtual", ctypes.c_ulonglong),
                            ("ullAvailExtendedVirtual", ctypes.c_ulonglong)]
            ms = _MS()
            ms.dwLength = ctypes.sizeof(_MS)
            if not ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(ms)):
                return None
            return ms.ullAvailPhys / 1024 ** 3
        except Exception:                                       # noqa: BLE001
            return None

    def _clear_ram(self):
        """Frees what this app is holding in system RAM without unloading anything: Python garbage, the model
        metadata cache, and the idle pages of the app's working set. Returns a message."""
        import gc
        before = self._ram_free_gb()
        meta = getattr(self.local_backend, "_meta_cache", None) if self.local_backend else None
        if meta is not None:
            meta.clear()
        gc.collect()
        if sys.platform == "win32":
            try:
                import ctypes
                k32 = ctypes.windll.kernel32
                k32.GetCurrentProcess.restype = ctypes.c_void_p
                ctypes.windll.psapi.EmptyWorkingSet(ctypes.c_void_p(k32.GetCurrentProcess()))
            except Exception:                                   # noqa: BLE001
                pass
        gc.collect()
        after = self._ram_free_gb()
        msg = "Released cached data and trimmed this app's idle memory."
        if before is not None and after is not None:
            msg += "  Free RAM: %.1f GB -> %.1f GB." % (before, after)
        return msg + "  (Model layers held in RAM stay put; use 'cache clear vram' or 'unload' to free those.)"

    def _clear_vram(self, report):
        """Unloads every chat model and the voice model so the GPU memory is released. Chats are kept, but each tab
        loses its model. report(ok, message) is called on the Tk thread when it is done."""
        self._tabs_ensure()
        if any(t.get("awaiting_reply") for t in self._tabs) or self.mode_busy or self._story_busy:
            report(False, "A reply is still running. Wait for it to finish, then try again.")
            return
        be = self.local_backend
        n = len(be.slots) if be is not None else 0

        def work():
            err = None
            try:
                if self.backend is not None:
                    self.backend.unload_all()
            except Exception as exc:                            # noqa: BLE001
                err = exc
            try:
                QWEN_VOICE.unload_safe()
            except Exception:                                   # noqa: BLE001
                pass
            self.root.after(0, done, err)

        def done(err):
            import gc
            for t in self._tabs:
                t["server_model"], t["server_instance_id"] = None, None
            mv = self._models_win
            if mv is not None:
                for key in list(getattr(mv, "model_state", {})):
                    try:
                        mv.mark_unloaded(key)
                    except Exception:                           # noqa: BLE001
                        pass
            gc.collect()
            try:
                import torch
                if torch.cuda.is_available():
                    torch.cuda.empty_cache()
            except Exception:                                   # noqa: BLE001
                pass
            self.update_server_button()
            if err is not None:
                report(False, "Some models didn't unload cleanly: %s" % err)
            else:
                report(True, "Unloaded %d model(s) and the voice model. VRAM released; load a model again to chat." % n)
        threading.Thread(target=work, daemon=True).start()

    def _clear_conversations_ui(self):
        ok, msg = self._clear_all_conversations()
        self.toast(msg)

    def _cc_cache(self, args, _line=None):
        """cache [clear <blocks|memory|images|conversation|all>] - show or clear caches and generated files"""
        import gc
        targets = self._cache_targets()
        meta = getattr(self.local_backend, "_meta_cache", None) if self.local_backend else None
        sub = args[0].lower() if args else ""
        if sub.startswith("clear") and len(sub) > 5:           # "clearram", "clearvram", "clearconversation"
            args = ["clear", sub[5:]] + list(args[1:])
            sub = "clear"

        if sub in ("", "list", "show", "status"):
            self._con_print("What's taking space (nothing is deleted until you run 'cache clear <name>'):")
            for name, (desc, paths) in targets.items():
                size = sum(self._path_bytes(p) for p in paths if os.path.exists(p))
                count = sum(1 for p in paths if os.path.exists(p))
                self._con_print(f"  {name:<11} {count:>3} item(s)  {self._fmt_bytes(size):>9}   {desc}")
            self._con_print(f"  {'memory':<11} {len(meta) if meta is not None else 0:>3} item(s)  "
                            f"{'(in RAM)':>9}   model metadata cache (re-read on the next Authenticate)")
            self._con_print(f"  {'conversation':<11} {len(self._tabs):>3} tab(s)  {'(in RAM)':>9}   every chat tab plus each model's context cache")
            self._con_print("Clear with: cache clear blocks | memory | images | conversation | ram | vram | all", "c_dim")
            self._con_print("images are your generated files - they are only deleted when named "
                            "(or with 'all').", "c_dim")
            return

        if sub != "clear":
            self._con_err("Use: cache   or   cache clear <blocks|memory|images|all>")
            return
        want = [a.lower() for a in args[1:]]
        if not want:
            self._con_err("Say what to clear: blocks, memory, images, conversation, ram, vram, or all.")
            return
        want = ["conversation" if w in ("conversations", "chats", "chat", "convo") else w for w in want]
        want = ["vram" if w in ("gpu", "gpumemory") else w for w in want]
        valid = set(targets) | {"memory", "all", "conversation", "ram", "vram"}
        bad = [w for w in want if w not in valid]
        if bad:
            self._con_err(f"Unknown target: {', '.join(bad)}. Choose from: {', '.join(sorted(valid))}.")
            return
        if "all" in want:
            want = list(targets) + ["memory"]          # 'all' never touches your chats: name 'conversation' for that

        freed = 0
        for name in want:
            if name == "ram":
                self._con_ok("ram: " + self._clear_ram())
                continue
            if name == "vram":
                self._clear_vram(lambda ok, msg: (self._con_ok if ok else self._con_err)("vram: " + msg))
                continue
            if name == "conversation":
                ok, msg = self._clear_all_conversations()
                (self._con_ok if ok else self._con_err)("conversation: " + msg)
                continue
            if name == "memory":
                n = len(meta) if meta is not None else 0
                if meta is not None:
                    meta.clear()
                gc.collect()
                self._con_ok(f"memory: cleared {n} cached model record(s) and ran garbage collection. "
                             "(Loaded models are not affected - use 'unload' to free those.)")
                continue
            if name == "images" and self.image_engine.busy:
                self._con_err("images: skipped - an image is being generated right now.")
                continue
            desc, paths = targets[name]
            removed = failed = 0
            for path in paths:
                if not os.path.exists(path):
                    continue
                size = self._path_bytes(path)
                try:
                    if os.path.isdir(path):
                        shutil.rmtree(path)
                    else:
                        os.remove(path)
                    if os.path.exists(path):
                        raise OSError("still present")
                    removed += 1
                    freed += size
                except OSError:
                    failed += 1
            msg = f"{name}: removed {removed} item(s)"
            if failed:
                self._con_err(msg + f", {failed} could not be deleted (in use or no permission).")
            else:
                self._con_ok(msg + ("." if removed else " (nothing to remove)."))
        if freed:
            self._con_print(f"Freed about {self._fmt_bytes(freed)} on disk.", "c_dim")

    def _cc_cacheclear(self, args, _line=None):
        """cacheclear <blocks|memory|images|conversation|ram|vram|all> - same as 'cache clear ...'"""
        self._cc_cache(["clear"] + list(args))

    def _cc_echo(self, args, _line=None):
        """echo <text> - print text"""
        self._con_print(" ".join(args))

    def _cc_history(self, args, _line=None):
        """history - commands entered this session"""
        for i, c in enumerate(self.console_history, 1):
            self._con_print(f"{i:>3}  {c}", "c_dim")

    def _cc_exit(self, args, _line=None):
        """exit - close the console"""
        self._toggle_console(False)

    def _cc_quit(self, args, _line=None):
        """quit - close the app"""
        for stopper in (self.image_engine.stop,):
            try:
                stopper()
            except Exception:                                               # noqa: BLE001
                pass
        try:
            if self.backend is not None:
                self.backend.disconnect()
        except Exception:                                               # noqa: BLE001
            pass
        self.root.destroy()

    def _cc_mode(self, args, _line=None):
        """mode [chat|images|music|draw] - show or switch what the input pill does"""
        names = ("chat", "images", "music", "draw")
        if not args:
            self._con_print(f"Mode: {self.mode_kind}   ({', '.join(names)})")
            return
        key = {"image": "images", "drawing": "draw", "paint": "draw", "compose": "music"}.get(args[0].lower(), args[0].lower())
        if key not in names:
            self._con_err(f"Unknown mode '{args[0]}'. Use: {', '.join(names)}")
            return
        if self.mode_busy or self.awaiting_reply:
            self._con_err("Busy - wait for the current job to finish (or 'stop').")
            return
        self._on_mode_pick(key)
        self._con_ok(f"Mode: {key}")

    def _cc_stop(self, args, _line=None):
        """stop - stop the running image / music / drawing job"""
        self._con_print("Stopping..." if self._mode_stop() else "Nothing is running.")

    def _cc_reboot(self, args, _line=None):
        """reboot - restart Voidloader (unloads every model, resets session-only settings)"""
        if self._con_busy():
            return
        self._do_reboot()

    def _cc_cachereboot(self, args, _line=None):
        """cache//reboot [targets] - clear caches, then restart (default: blocks, memory; add images/all to include generated files)"""
        if self._con_busy():
            return
        targets = [a.lower() for a in args] or ["blocks", "memory"]
        self._cc_cache(["clear"] + targets)
        self._do_reboot()

    def _cc_factoryreset(self, args, _line=None):
        """factoryreset [confirm] - wipe ALL saved settings and reboot to factory defaults (colours, theme, folders, projects, power calibration, everything)"""
        if not args or args[0].lower() != "confirm":
            self._con_print("This will DELETE every saved setting and reboot to factory defaults:", "c_dim")
            self._con_print("  gguf_settings.json  (theme, accent, folders, quick-boot, etc.)", "c_dim")
            self._con_print("  gguf_projects.json  (all projects, their instructions and file lists)", "c_dim")
            self._con_print("  power calibration   (on-battery CPU-to-watts learning data)", "c_dim")
            self._con_print("Chat history and files you saved are NOT touched.", "c_dim")
            self._con_print("Type  reset confirm  to go ahead, or press Enter to cancel.", "c_err")
            return
        if self._con_busy():
            return
        errs = []
        # --- wipe settings file ---
        sf = os.path.join(_app_dir(), SETTINGS_FILE)
        try:
            if os.path.exists(sf):
                os.remove(sf)
            APP_SETTINGS.clear()
            self._con_ok("gguf_settings.json deleted.")
        except OSError as exc:
            errs.append(f"settings: {exc}")
            self._con_err(f"Could not delete settings file: {exc}")
        # --- wipe projects file ---
        pf = os.path.join(_app_dir(), PROJECTS_FILE)
        try:
            if os.path.exists(pf):
                os.remove(pf)
            self._con_ok("gguf_projects.json deleted.")
        except OSError as exc:
            errs.append(f"projects: {exc}")
            self._con_err(f"Could not delete projects file: {exc}")
        if errs:
            self._con_err("Some files could not be deleted (see above). Fix the permissions and try again.")
            return
        self._con_ok("All settings wiped. Rebooting to factory defaults...")
        self.root.after(600, self._do_reboot)

    def _do_reboot(self):
        """Start a fresh copy of this script, then shut this one down the same way 'quit' does. The new
        process skips the Y/N boot question (GGUFLLAMA_REBOOT=1). Everything session-only - Save Locations,
        chat, loaded models, toggles - starts from scratch, exactly like a normal launch."""
        if getattr(sys, "frozen", False):                      # compiled .exe
            argv = [sys.executable] + sys.argv[1:]
        else:
            argv = [sys.executable, os.path.abspath(sys.argv[0])] + sys.argv[1:]
        env = dict(os.environ, GGUFLLAMA_REBOOT="1")
        kwargs = {}
        if os.name == "nt":
            try:
                has_console = sys.stdin is not None and sys.stdin.isatty()
            except Exception:                                           # noqa: BLE001
                has_console = False
            if has_console:                                             # keep a real prompt window for the new copy
                kwargs["creationflags"] = subprocess.CREATE_NEW_CONSOLE
        else:
            kwargs["start_new_session"] = True
        try:
            subprocess.Popen(argv, env=env, cwd=os.getcwd(), **kwargs)
        except Exception as exc:                                        # noqa: BLE001
            self._con_err(f"Couldn't start a new copy, so nothing was closed: {exc}")
            return
        self._con_ok("Rebooting...")
        for stopper in (self.image_engine.stop,
                        lambda: getattr(getattr(self, "_power_win", None), "stop", lambda: None)(),
                        self.http_bridge.stop, self.block_editor.stop):
            try:
                stopper()
            except Exception:                                           # noqa: BLE001
                pass
        try:
            if self.backend is not None:
                self.backend.disconnect()
        except Exception:                                               # noqa: BLE001
            pass
        self.root.destroy()

    def _open_drawing(self):
        """Watch the loaded model draw (see the DRAWING section)."""
        win = getattr(self, "_drawing_win", None)
        try:
            if win is not None and win.win.winfo_exists():
                win.win.lift()
                win.win.focus_force()
                return
        except tk.TclError:
            pass
        self._drawing_win = DrawingWindow(self.root, self.t, self)

    def _open_music(self):
        """Have the loaded model compose music (see the MUSIC section)."""
        win = getattr(self, "_music_win", None)
        try:
            if win is not None and win.win.winfo_exists():
                win.win.lift()
                win.win.focus_force()
                return
        except tk.TclError:
            pass
        self._music_win = MusicWindow(self.root, self.t, self)

    def _open_images(self):
        """Generate images with stable-diffusion.cpp (see the IMAGE GENERATION section)."""
        win = getattr(self, "_images_win", None)
        try:
            if win is not None and win.win.winfo_exists():
                win.win.lift()
                win.win.focus_force()
                return
        except tk.TclError:
            pass
        self._images_win = ImagesWindow(self.root, self.t, self)

    def _open_block_editor(self):
        """Start the built-in Block Editor (if needed) and open it in the browser."""
        try:
            already = self.block_editor.running
            self.block_editor.start()
        except ImportError:
            self._append("The Block Editor needs Flask. Run:  pip install flask   then try again.\n\n", "system_msg")
            return
        except OSError as exc:
            self._append(f"Couldn't start the Block Editor: {exc}\n\n", "system_msg")
            return
        if not already:
            self._append(f"Block Editor running at {self.block_editor.url}\n", "system_msg")
            if not self.server_connected or self.local_backend is None:
                self._append("It uses the Local model loaded here: press Authenticate and load a model "
                             "in Memory before pressing Build.\n", "system_msg")
            self._append("\n", "system_msg")
        webbrowser.open(self.block_editor.url)

    def _stop_block_editor(self):
        self.block_editor.stop()
        self._append("Block Editor stopped.\n\n", "system_msg")

    def _toggle_http_bridge(self):
        """Session-only on/off for the HTTP bridge (see HTTP BRIDGE section)."""
        try:
            if self.http_bridge.running:
                self.http_bridge.stop()
                self._append("HTTP API stopped.\n\n", "system_msg")
            else:
                self.http_bridge.start()
                self._append(f"HTTP API listening on http://{BRIDGE_HOST}:{BRIDGE_PORT} \u2014 other "
                             "programs can now use whichever Local model is loaded here.\n\n",
                             "system_msg")
        except OSError as exc:
            self._append(f"Couldn't start the HTTP API: {exc}\n\n", "system_msg")
        self._refresh_api_button()

    def _toggle_phone_app(self):
        """Serves GGUFllama_Phone.html to other devices on this network, behind a random PIN.
        Same HTTP bridge as the API (port 5178); opening it on this PC works too."""
        br = self.http_bridge
        try:
            if br.running and br.lan:
                br.stop()
                self._close_phone_qr()
                self._append("Phone app stopped.\n\n", "system_msg")
            else:
                if br.running:
                    br.stop()                       # restart in network mode
                import secrets
                pin = "%06d" % secrets.randbelow(1000000)
                br.start(lan=True, token=pin)
                note = "" if find_phone_page() else \
                    "  (GGUFllama_Phone.html wasn't found next to the script - put it there.)"
                self._append(f"Phone app on. Scan the QR code with your phone's camera (same Wi-Fi), or open "
                             f"http://{lan_ip()}:{BRIDGE_PORT}/ and enter PIN {pin}.  "
                             f"On this PC: http://127.0.0.1:{BRIDGE_PORT}/{note}\n\n", "system_msg")
                self._show_phone_qr()
        except OSError as exc:
            self._append(f"Couldn't start the phone app: {exc}\n\n", "system_msg")
        self._refresh_api_button()

    def _close_phone_qr(self):
        win = getattr(self, "_qr_win", None)
        self._qr_win = None
        if win is not None:
            try:
                win.destroy()
            except tk.TclError:
                pass

    def _show_phone_qr(self):
        """A window with a QR code holding the phone app's address + PIN, so a phone can connect by
        just scanning it (the phone's own camera app opens the link; the page's Scan button reads it
        too). The PIN is in the code, so only show it to your own phone."""
        br = self.http_bridge
        if not (br.running and br.lan):
            self._append("Start the phone app first (the Phone chip in the status bar, or the `phone on` command).\n\n", "system_msg")
            return
        url = f"http://{lan_ip()}:{BRIDGE_PORT}/?pin={br.token}"
        try:
            grid = qr_matrix(url)
        except ValueError as exc:
            self._append(f"Couldn't make a QR code: {exc}\n\n", "system_msg")
            return
        self._close_phone_qr()
        t = self.t
        win = tk.Toplevel(self.root)
        self._qr_win = win
        win.title("Phone app \u2014 scan to connect")
        win.configure(bg=t["bg"])
        win.resizable(False, False)
        win.protocol("WM_DELETE_WINDOW", self._close_phone_qr)
        n, quiet = len(grid), 4
        px = max(5, min(14, 440 // (n + 2 * quiet)))
        side = (n + 2 * quiet) * px
        cv = tk.Canvas(win, width=side, height=side, bg="white", highlightthickness=0, bd=0)
        cv.pack(padx=18, pady=(18, 10))
        for y, row in enumerate(grid):                       # merge horizontal runs into one rectangle
            x = 0
            while x < n:
                if row[x]:
                    x2 = x
                    while x2 + 1 < n and row[x2 + 1]:
                        x2 += 1
                    cv.create_rectangle((x + quiet) * px, (y + quiet) * px, (x2 + 1 + quiet) * px,
                                        (y + 1 + quiet) * px, fill="black", outline="black")
                    x = x2 + 1
                else:
                    x += 1
        tk.Label(win, text="Scan with your phone's camera (same Wi-Fi)", bg=t["bg"], fg=t["text"],
                 font=(t["family"], t["title"], "bold")).pack()
        tk.Label(win, text=url, bg=t["bg"], fg=t["text"], font=(t["family"], t["small"])).pack(pady=(4, 0))
        tk.Label(win, text=f"PIN  {br.token}", bg=t["bg"], fg=t["text"],
                 font=(t["family"], t["title"])).pack(pady=(2, 8))
        bar = tk.Frame(win, bg=t["bg"])
        bar.pack(pady=(0, 16))

        def copy_link():
            self.root.clipboard_clear()
            self.root.clipboard_append(url)

        for label, cmd in (("Copy link", copy_link), ("Close", self._close_phone_qr)):
            tk.Button(bar, text=label, command=cmd, bg=t["card"], fg=t["text"], activebackground=t["border"],
                      activeforeground=t["text"], relief=tk.FLAT, bd=0, padx=14, pady=4, cursor="hand2",
                      font=(t["family"], t["small"])).pack(side=tk.LEFT, padx=4)
        win.lift()

    def _refresh_api_button(self):
        """Keeps the little green "API" marker (top right) in step with the HTTP bridge."""
        if not (self.http_bridge.running and self.http_bridge.lan):
            self._close_phone_qr()                  # the QR holds a PIN that no longer works
        st = getattr(self, "stage", None)
        if st is not None:
            st.set_api(bool(self.http_bridge.running))

    def _open_save_locations(self):
        chosen = self._prompt_save_folder(
            title="Save Locations",
            intro=(f"Current save folder:\n{self.save_folder}" if self.save_folder
                   else "No save folder is set - Save actions will ask you to browse each time."))
        if chosen:
            self._set_save_folder(chosen)

    def _open_local_models_folder(self):
        """Where the llama.cpp backend looks for .gguf files. Takes effect the next time
        you Connect."""
        chosen = self._prompt_save_folder(
            title="Local Models Folder",
            intro=f"Folder the Local (llama.cpp) backend scans for .gguf files:\n"
                  f"{self.local_models_root}",
            initial=self.local_models_root)
        if chosen:
            self._set_models_folder(chosen)

    def _prompt_save_folder(self, title="Save Location", intro=None, initial=None):
        """Modal folder picker: type a path directly, or Browse... for the OS folder picker.
        Returns the chosen folder, or None if cancelled / left blank."""
        t = self.t
        font = (t["family"], t["size"])
        dlg = tk.Toplevel(self.root)
        dlg.title(title)
        dlg.configure(bg=t["bg"])
        dlg.resizable(False, False)
        dlg.transient(self.root)
        dlg.grab_set()

        if intro:
            tk.Label(dlg, text=intro, bg=t["bg"], fg=t["text"], font=font,
                    wraplength=360, justify=tk.LEFT).pack(padx=16, pady=(16, 8), anchor=tk.W)

        tk.Label(dlg, text="Folder:", bg=t["bg"], fg=t["muted"], font=font).pack(padx=16, anchor=tk.W)

        row = tk.Frame(dlg, bg=t["bg"])
        row.pack(padx=16, pady=(4, 4), fill=tk.X)
        entry_box = tk.Entry(row, font=font, bg=t["input"], fg=t["text"], relief=tk.FLAT, bd=0, highlightthickness=1, highlightbackground=t["border"], highlightcolor=t["accent"])
        entry_box.insert(0, (initial if initial is not None else self.save_folder) or "")
        entry_box.pack(side=tk.LEFT, fill=tk.X, expand=True)
        entry_box.select_range(0, tk.END)
        entry_box.focus_set()

        def browse():
            chosen = filedialog.askdirectory(title=title, initialdir=entry_box.get().strip() or os.getcwd())
            if chosen:
                entry_box.delete(0, tk.END)
                entry_box.insert(0, chosen)

        tk.Button(row, text="Browse...", command=browse, bg=t["neutral"], fg=t["text"],
                 activebackground=t["neutral"], relief=tk.FLAT, bd=0, padx=8, pady=4,
                 cursor="hand2", font=(t["family"], t["small"])).pack(side=tk.LEFT, padx=(6, 0))

        err_lbl = tk.Label(dlg, text="", bg=t["bg"], fg="#d64545", font=(t["family"], t["small"]))
        err_lbl.pack(padx=16, anchor=tk.W)

        result = {"path": None}

        def confirm():
            path = entry_box.get().strip()
            if not path:
                dlg.destroy()      # blank = same as Skip/Cancel
                return
            if not os.path.isdir(path):
                err_lbl.config(text="That folder doesn't exist.")
                return
            result["path"] = path
            dlg.destroy()

        def cancel():
            dlg.destroy()

        btn_row = tk.Frame(dlg, bg=t["bg"])
        btn_row.pack(padx=16, pady=(8, 16), fill=tk.X)
        cancel_label = "Cancel" if (initial if initial is not None else self.save_folder) else "Skip"
        tk.Button(btn_row, text=cancel_label, command=cancel, bg=t["neutral"], fg=t["text"],
                 activebackground=t["neutral"], relief=tk.FLAT, bd=0, padx=10, pady=5,
                 cursor="hand2", font=font).pack(side=tk.RIGHT, padx=(6, 0))
        tk.Button(btn_row, text="OK", command=confirm, bg=t["accent"], fg=t["on_accent"],
                 activebackground=t["accent"], activeforeground=t["on_accent"], relief=tk.FLAT,
                 bd=0, padx=12, pady=5, cursor="hand2", font=font).pack(side=tk.RIGHT)

        dlg.bind("<Return>", lambda _e: confirm())
        dlg.bind("<Escape>", lambda _e: cancel())
        dlg.wait_window()
        return result["path"]

    def _prompt_filename(self, default_filename, dialog_title):
        """Small modal Entry dialog for just a file name, used when a save folder is already
        configured (so the OS Save As browser can be skipped entirely - only the name is
        still asked). Returns the name, or None if cancelled."""
        t = self.t
        font = (t["family"], t["size"])
        dlg = tk.Toplevel(self.root)
        dlg.title(dialog_title)
        dlg.configure(bg=t["bg"])
        dlg.resizable(False, False)
        dlg.transient(self.root)
        dlg.grab_set()

        tk.Label(dlg, text=f"Save to: {self.save_folder}", bg=t["bg"], fg=t["muted"],
                font=(t["family"], t["small"]), wraplength=360, justify=tk.LEFT).pack(
            padx=16, pady=(16, 4), anchor=tk.W)
        tk.Label(dlg, text="File name:", bg=t["bg"], fg=t["muted"], font=font).pack(padx=16, anchor=tk.W)

        entry_box = tk.Entry(dlg, font=font, bg=t["input"], fg=t["text"], relief=tk.FLAT, bd=0, highlightthickness=1, highlightbackground=t["border"], highlightcolor=t["accent"])
        entry_box.insert(0, default_filename)
        entry_box.pack(padx=16, pady=(4, 12), fill=tk.X)
        entry_box.select_range(0, tk.END)
        entry_box.focus_set()

        err_lbl = tk.Label(dlg, text="", bg=t["bg"], fg="#d64545", font=(t["family"], t["small"]))
        err_lbl.pack(padx=16, anchor=tk.W)

        result = {"name": None}

        def confirm():
            name = entry_box.get().strip()
            if not name:
                err_lbl.config(text="Enter a file name.")
                return
            result["name"] = name
            dlg.destroy()

        def cancel():
            dlg.destroy()

        btn_row = tk.Frame(dlg, bg=t["bg"])
        btn_row.pack(padx=16, pady=(0, 16), fill=tk.X)
        tk.Button(btn_row, text="Cancel", command=cancel, bg=t["neutral"], fg=t["text"],
                 activebackground=t["neutral"], relief=tk.FLAT, bd=0, padx=10, pady=5,
                 cursor="hand2", font=font).pack(side=tk.RIGHT, padx=(6, 0))
        tk.Button(btn_row, text="Save", command=confirm, bg=t["accent"], fg=t["on_accent"],
                 activebackground=t["accent"], activeforeground=t["on_accent"], relief=tk.FLAT,
                 bd=0, padx=12, pady=5, cursor="hand2", font=font).pack(side=tk.RIGHT)

        dlg.bind("<Return>", lambda _e: confirm())
        dlg.bind("<Escape>", lambda _e: cancel())
        dlg.wait_window()
        return result["name"]

    def save_text_content(self, content, default_filename, dialog_title="Save"):
        """Shared save path for every 'Save' action in the app (Drawing today; anything else
        that adds a Save action later should call this too). If a save folder is configured,
        writes straight into it after asking only for a file name - no OS browse dialog.
        Otherwise falls back to a normal Save As file-browser dialog, exactly as before."""
        if self.save_folder:
            filename = self._prompt_filename(default_filename, dialog_title)
            if not filename:
                return
            path = os.path.join(self.save_folder, filename)
        else:
            ext = os.path.splitext(default_filename)[1] or ".txt"
            path = filedialog.asksaveasfilename(
                title=dialog_title, initialfile=default_filename, defaultextension=ext,
                filetypes=([("SVG files", "*.svg")] if ext == ".svg" else [("Text files", "*.txt")])
                          + [("All files", "*.*")])
            if not path:
                return
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
        except Exception as exc:                                        # noqa: BLE001
            messagebox.showerror(dialog_title, f"Couldn't save file:\n{exc}")



