    # ------------------------------------------------------------------ theme
    def _apply_theme_colours(self):
        set_theme(self.theme_name)
        acc = APP_SETTINGS.get("accent_custom")
        if isinstance(acc, str) and re.match(r"^#[0-9a-fA-F]{6}$", acc):
            C["accent"], C["on_accent"] = acc, _contrast_on(acc)
        C["seg1"], C["seg2"] = C["seg"][1], C["seg"][2]
        self._sync_palette()
        self._apply_tk_options()

    def _sync_palette(self):
        PALETTE.update(bg=C["bg"], card=C["raised"], input=C["raised"], text=C["text"], muted=C["muted"],
                       on_accent=C["on_accent"], accent=C["accent"], neutral=C["line"], border=C["line_hi"],
                       soft=C["panel"], warn=C["warn"], on_warn=C["on_accent"], go=C["ok"], on_go=C["bg"])
        try:
            self.t.update(PALETTE)
        except AttributeError:
            pass

    def set_theme_name(self, name):
        self.theme_name = name
        self._settings_store(theme=name)
        self._apply_theme_colours()
        self.build()

    def cycle_theme(self):
        names = list(THEMES)
        self.set_theme_name(names[(names.index(self.theme_name) + 1) % len(names)])

    def _theme_file(self):
        return os.path.join(_app_dir(), "gguf_theme.json")

    def _theme_save(self):
        try:
            with open(self._theme_file(), "w", encoding="utf-8") as fh:
                json.dump(self._theme_state, fh)
        except OSError:
            pass

    def _theme_restore(self):
        try:
            with open(self._theme_file(), encoding="utf-8") as fh:
                saved = json.load(fh)
            self._theme_state["transparent"] = bool(saved.get("transparent", False))
            self._theme_state["opacity"] = max(20, min(100, int(saved.get("opacity", 60))))
        except (OSError, ValueError, TypeError, AttributeError):
            pass

    def _apply_transparency(self):
        """Window -alpha (Windows and macOS; on Linux it needs a compositing window manager)."""
        st = self._theme_state
        on = bool(st.get("transparent"))
        try:
            self.root.attributes("-alpha", (max(20, min(100, int(st.get("opacity", 60)))) / 100.0) if on else 1.0)
        except tk.TclError:
            pass

    def _set_transparent(self, on):
        self._theme_state["transparent"] = bool(on)
        self._apply_transparency()
        self._theme_save()

    def _set_opacity(self, pct):
        self._theme_state["opacity"] = int(pct)
        self._apply_transparency()
        self._theme_save()

    def _pick_accent_custom(self):
        from tkinter import colorchooser
        rgb, hexcol = colorchooser.askcolor(color=C["accent"], title="Accent colour", parent=self.root)
        if hexcol:
            self._settings_store(accent_custom=hexcol)
            self._apply_theme_colours()
            self.build()

    def _reset_accent(self):
        APP_SETTINGS.pop("accent_custom", None)
        save_app_settings(APP_SETTINGS)
        self._apply_theme_colours()
        self.build()

    # ------------------------------------------------------------------ small utilities
    def _wheel(self, e=None, direction=None):
        if e is None:
            return
        try:
            w = self.root.winfo_containing(e.x_root, e.y_root)
        except (KeyError, tk.TclError):
            return
        while w is not None:
            tgt = getattr(w, "_scroll_target", None)
            if tgt is not None:
                step = direction if direction is not None else (-1 if e.delta > 0 else 1)
                tgt.yview_scroll(step * 2, "units")
                return
            w = getattr(w, "master", None)

    def _toggle_fullscreen(self):
        """F12: borderless fullscreen on and off. Tk can't do true exclusive fullscreen, but this covers the whole
        screen including the taskbar and is what most apps mean by it."""
        try:
            on = not bool(self.root.attributes("-fullscreen"))
            self.root.attributes("-fullscreen", on)
            if not on:
                self.root.after(50, lambda: self.root.state("zoomed"))     # back to the maximised window
            self.toast("Fullscreen on. Press F12 to leave." if on else "Fullscreen off.")
        except tk.TclError:
            pass

    def _on_grave(self, _e=None):
        self._toggle_console()
        return "break"

    def _on_escape(self, _e=None):
        if self.palette is not None:
            self.close_palette()
            return "break"
        if self.mode_busy and self._mode_stop():
            return "break"
        if self.ws == "chat" and self.awaiting_reply and self._chat_stop():
            return "break"
        if self.ws == "simworld" and getattr(self, "_sim", None) is not None:
            self._sim.ctl.stop()                                       # stops `auto`
            return "break"
        return None

    def open_void_engine(self):
        """VoidEngine (left menu): run the engine menu script, physics_menu.py, as its own program. The menu is not part of
        this app: it is a separate Python process, so it can be edited, crash or be closed without touching Voidloader.
        The script sits next to this file (or in a VoidEngine folder next to it); the engine, physics_engine.py, goes beside it."""
        folder = _app_dir()
        script = next((p for p in (os.path.join(folder, "physics_menu.py"),
                                   os.path.join(folder, "VoidEngine", "physics_menu.py")) if os.path.isfile(p)), None)
        if script is None:
            self.toast("VoidEngine: physics_menu.py was not found next to Voidloader (%s)." % folder)
            return
        py = _be_python()
        if not py:
            self.toast("VoidEngine: Python wasn't found on PATH, so the engine menu can't start.")
            return
        try:
            subprocess.Popen([py, script], cwd=os.path.dirname(script))
        except OSError as exc:
            self.toast("VoidEngine couldn't start: %s" % exc)
            return
        self.toast("VoidEngine: opening the engine menu…")

    def toast(self, msg):
        try:
            if self._toast is not None and self._toast.winfo_exists():
                self._toast.destroy()
            f = tk.Frame(self.root, bg=C["line_hi"])
            inner = tk.Frame(f, bg=C["raised"])
            inner.pack(padx=1, pady=1)
            tk.Label(inner, text=msg, bg=C["raised"], fg=C["text"], font=F["ui"], padx=18, pady=10,
                     wraplength=700, justify="left").pack()
            f.place(relx=0.5, rely=1.0, y=-70, anchor="s")
            f.lift()
            self._toast = f
            self.root.after(4200, lambda: f.winfo_exists() and f.destroy())
        except tk.TclError:
            pass

    def _set_activity(self, kind):
        self._activity = kind
        if kind == "idle":
            self._finish_live()
        elif not self._pulse_on:
            self._pulse_on = True
            self._pulse(0)
        self._sync_send_btn()

    def _pulse(self, i):
        if self._activity == "idle":
            self._pulse_on = False
            return
        try:
            m = self._live_msg()
            h = self._mh.get(id(m)) if m else None
            if h and h.get("spine") is not None and h["spine"].winfo_exists():
                h["spine"].config(bg=C["accent"] if i % 2 == 0 else mix(C["accent"], C["bg"], .6))
            self.root.after(330, lambda: self._pulse(i + 1))
        except tk.TclError:
            self._pulse_on = False

    # ------------------------------------------------------------------ models (state lives in the hidden Models list)
    def _ensure_models_viewer(self):
        mw = self._models_win
        if mw is not None:
            try:
                if mw.win.winfo_exists():
                    return mw
            except tk.TclError:
                pass
        self._models_win = mw = ModelsViewer(self.root, self.t, self)
        mw.win.withdraw()
        orig = mw._set_status

        def status(text):
            orig(text)
            self.root.after(0, self._models_changed, text)
        mw._set_status = status
        return mw

    def _models_changed(self, text=""):
        quiet = ("Double-click a model", "model(s) found", "No .gguf files")
        if text and not any(q in text for q in quiet):
            self.toast(text)
        self._refresh_chrome()

    def model_rows(self):
        mv, be = self._models_win, self.local_backend
        rows = []
        if mv is None:
            return rows
        loading = self.http_bridge.loading
        for e in mv.models:
            key = e.get("key")
            st = mv.model_state.get(key)
            if st is None:
                continue
            iid = be.key_to_instance.get(key) if be else None
            h = be.slots.get(iid) if (be and iid) else None
            if h is not None and not st["loaded"]:               # show what is really in VRAM
                st["loaded"], st["instance_id"] = True, iid
            elif h is None and st["loaded"] and loading != key:
                st["loaded"], st["instance_id"] = False, None
            rows.append(dict(
                key=key, name=e.get("display_name") or os.path.basename(str(key)),
                quant=(e.get("quantization") or {}).get("name") or "", params=e.get("params_string") or "",
                size_bytes=e.get("size_bytes") or 0, mb=(e.get("size_bytes") or 0) / 1048576.0,
                ctx=(h.ctx if h else st.get("ctx", DEFAULT_CTX)), maxctx=e.get("max_context_length") or 0,
                loaded=h is not None, est=(h.est_vram_mb if h else 0.0), loading=(loading == key)))
        return rows

    def chat_row(self):
        for r in self.model_rows():
            if r["key"] == self.server_model and r["loaded"]:
                return r
        return None

    def vram_info(self):
        be = self.local_backend
        total = float(getattr(be, "TOTAL_VRAM_MB", LocalLlamaBackend.TOTAL_VRAM_MB))
        segs = []
        if be is not None:
            for h in list(be.slots.values()):
                segs.append((h.path, float(h.est_vram_mb)))
        if QWEN_VOICE.model is not None and QWEN_VOICE.vram_mb > 0:
            segs.append((VOICE_MODEL_KEY, float(QWEN_VOICE.vram_mb)))
        return total, float(LOCAL_VRAM_SAFETY_MARGIN_MB), segs

    def model_fit(self, r):
        """(label, colour key) for a model row that is not loaded."""
        be = self.local_backend
        if be is None:
            return "Backend missing", "hot"
        est = be._estimate_vram_mb(r["size_bytes"], r["ctx"])
        budget = be.TOTAL_VRAM_MB - LOCAL_VRAM_SAFETY_MARGIN_MB
        used = be._current_vram_mb()
        if self.ram_spillover:
            return ("Spills to RAM", "warn") if used + est > budget else ("Fits", "faint")
        if est > budget:
            return "Too large for VRAM", "hot"
        if used + est > budget:
            return "Needs %.1f GB more" % ((used + est - budget) / 1000.0), "hot"
        return "Fits", "faint"

    def _ctx_text_for(self, r):
        return format(int(r["ctx"]), ",") + " context"

    # ------------------------------------------------------------------ build / rebuild
    def build(self):
        for w in self.root.winfo_children():
            w.destroy()
        self.ledgers = []
        self.palette = self._toast = None
        self.root.configure(bg=C["bg"])
        self._mh = {}
        self.build_dock()
        self.build_vram_strip()
        self.build_topbar()
        self.body = tk.Frame(self.root, bg=C["bg"])
        self.body.pack(side="top", fill="both", expand=True)
        self.build_rail()
        tk.Frame(self.body, bg=C["line"], width=1).pack(side="left", fill="y")
        self.center = tk.Frame(self.body, bg=C["bg"])
        self.center.pack(side="left", fill="both", expand=True)
        self.insp_host = tk.Frame(self.body, bg=C["panel"], width=self.insp_width)
        self.insp_host.pack_propagate(False)
        if self.dock_open:
            self.dock.pack(side="bottom", fill="x", before=self.body)
            self.render_dock()
        self.show_ws(self.ws)
        self._refresh_chips()

    def show_ws(self, name):
        if getattr(self, "ws", None) == "projects" and name != "projects":
            self._proj_commit_edits()
        if getattr(self, "ws", None) == "persona" and name != "persona":
            self._pers_commit_edits()
        self.ws = name
        self.mode_kind = name if name in TOOL_WS else "chat"
        for key, b in self.rail_btns.items():
            b.set_active(key == name)
        if name in self.rail_btns:
            self.rail_reveal(name)
        try:
            self.gear_btn.set_active(name == "settings")
        except (AttributeError, tk.TclError):
            pass
        self.render_center()
        self.render_inspector()

    def _refresh_chrome(self):
        """Model, connection and VRAM changed: bring every visible piece in step."""
        try:
            self.update_model_chip()
            self._tabs_render()
            self._animate_ledger()
            if self.dock_open and self.dock_tab == "memory":
                self.render_dock()
            if self.ws == "home":
                self.render_center()
            if self.ws == "chat":
                self._refresh_header_sub()
                if not self.msgs and not self.awaiting_reply and not self._split:
                    self.render_center()
                else:
                    self._refresh_composer_ph()
            self.render_inspector()
        except tk.TclError:
            pass

    def _refresh_inspector_soft(self):
        try:
            if self.ws == "chat":
                self.render_inspector()
        except (tk.TclError, AttributeError):
            pass

    def _sync_reasoning_ui(self):
        seg = getattr(self, "comp_seg", None)
        try:
            if seg is not None and seg.winfo_exists():
                seg.value = self.reasoning_level if self.reasoning_enabled else "Off"
                seg._draw()
        except tk.TclError:
            pass

    def _set_tokens_text(self, text):
        lbl = getattr(self, "tok_lbl", None)
        try:
            if lbl is not None and lbl.winfo_exists():
                lbl.config(text=text.replace("Tokens: ", "") + (" tokens" if text.replace("Tokens: ", "").isdigit() else ""))
        except tk.TclError:
            pass

    # ------------------------------------------------------------------ top bar
    def build_topbar(self):
        bar = tk.Frame(self.root, bg=C["panel"], height=54)
        bar.pack(side="top", fill="x")
        bar.pack_propagate(False)
        tk.Frame(self.root, bg=C["line"], height=1).pack(side="top", fill="x")
        self._tab_strip = tk.Frame(bar, bg=C["panel"])
        self._tab_strip.pack(side="left", fill="y", padx=(18, 0))
        self.root.after(50, self._tabs_render)
        self.gear_btn = Btn(bar, "", lambda: self.show_ws("settings"), kind="ghost", icon="gear", height=32, radius=10,
                            active=(getattr(self, "ws", None) == "settings"))
        self.gear_btn.pack(side="right", padx=(0, 14))
        Btn(bar, "", self.cycle_theme, kind="ghost", icon="contrast", height=32, radius=10).pack(side="right", padx=2)
        self.model_chip = Chip(bar, "", command=lambda: self.toggle_dock("memory"), height=30, font=F["ui"], padx=12)
        self.model_chip.pack(side="right", padx=8)
        self.update_model_chip()
        trig = tk.Canvas(bar, width=300, height=34, bg=C["panel"], highlightthickness=0, bd=0, cursor="hand2")
        rrect(trig, 1, 1, 299, 33, 17, fill=C["bg"], outline=C["line"])
        draw_icon(trig, "search", 22, 17, 7, C["muted"])
        trig.create_text(40, 17, text="Search commands and models", anchor="w", fill=C["muted"], font=F["ui"])
        rrect(trig, 226, 7, 288, 27, 8, fill=C["raised"], outline=C["line"])
        trig.create_text(257, 17, text="Ctrl  K", fill=C["muted"], font=F["small"])
        trig.bind("<Button-1>", lambda e=None: self.open_palette())
        trig.pack(side="right", padx=(0, 6), pady=10)

    _CAFE_COMMIT_HTML = '<title>Cafe Commit</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,500;12..96,700;12..96,800&family=DM+Sans:wght@400;500;700&family=JetBrains+Mono:wght@400;500&display=swap">\n<style>\n/* Layout: one script window is the whole site. The top menu swaps which "file" the window shows. */\n:root{\n  --bg:#EDEFF3; --surface:#FFFFFF; --fg:#13171E; --muted:#586272; --line:#D3D8E0;\n  --accent:#B3550E; --accent-fg:#FFFFFF; --warn:#9A5B00;\n  --code-bg:#14181F; --code-fg:#D7DCE5; --code-muted:#7C8798; --code-accent:#F2A55E; --code-key:#8FB8F2; --code-str:#9CCB8F;\n  --f-display:\'Bricolage Grotesque\',\'Segoe UI\',system-ui,sans-serif;\n  --f-body:\'DM Sans\',\'Segoe UI\',system-ui,sans-serif;\n  --f-mono:\'JetBrains Mono\',Consolas,\'Courier New\',monospace;\n}\n@media (prefers-color-scheme: dark){:root:not([data-theme="light"]){\n  --bg:#0E1218; --surface:#161B23; --fg:#E7EAF0; --muted:#98A2B2; --line:#28303B;\n  --accent:#EE9A50; --accent-fg:#1B1108; --warn:#E3B04F;\n  --code-bg:#0A0D12; color-scheme:dark}}\n:root[data-theme="dark"]{\n  --bg:#0E1218; --surface:#161B23; --fg:#E7EAF0; --muted:#98A2B2; --line:#28303B;\n  --accent:#EE9A50; --accent-fg:#1B1108; --warn:#E3B04F;\n  --code-bg:#0A0D12; color-scheme:dark}\n\n*{box-sizing:border-box}\nbody{background:var(--bg);color:var(--fg);font:16px/1.6 var(--f-body);padding-inline:clamp(16px,4vw,48px);padding-block:0 56px}\n.wrap{max-width:1080px;margin-inline:auto}\n:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n\nheader.top{display:flex;justify-content:space-between;align-items:center;gap:12px 16px;flex-wrap:wrap;padding-block:14px;position:sticky;top:env(safe-area-inset-top,0px);z-index:5;background:var(--bg)}\n.brand{display:flex;align-items:center;gap:10px;font:800 20px/1 var(--f-display);letter-spacing:-.02em;background:none;border:0;color:var(--fg);cursor:pointer;padding:6px 0}\n.brand svg{width:26px;height:26px;color:var(--accent);flex:none}\n.nav{display:flex;gap:10px;flex-wrap:wrap;align-items:center}\n.btn{font:700 15px/1 var(--f-body);padding:14px 20px;border-radius:8px;border:1px solid var(--line);background:var(--surface);color:var(--fg);cursor:pointer;text-decoration:none;display:inline-flex;align-items:center;gap:8px}\n.btn:hover{border-color:var(--accent)}\n.btn[aria-current="page"]{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}\n\n/* The window */\n.win{--fs:clamp(13px,1.9vw,17px);--lh:1.8;--px:clamp(20px,4vw,40px);\n  background:var(--code-bg);border:1px solid color-mix(in srgb,var(--accent) 35%,var(--line));border-radius:16px;overflow:hidden;\n  box-shadow:0 40px 120px -40px color-mix(in srgb,var(--accent) 70%,transparent),0 2px 0 #ffffff0d inset;\n  width:100%;max-width:940px;min-width:0;scroll-margin-top:clamp(96px,22vw,140px);display:flex;flex-direction:column}\n.pages{display:grid;grid-auto-rows:1fr;gap:clamp(28px,6vw,56px);padding-top:clamp(8px,2vw,16px)}\n.win .bar{display:flex;align-items:center;gap:9px;padding:14px 18px;border-bottom:1px solid #ffffff14;font:400 13px var(--f-mono);color:var(--code-muted)}\n.win .dot{width:12px;height:12px;border-radius:50%;background:#ffffff26}\n.win .bar b{margin-left:8px;font-weight:500;color:var(--code-fg)}\n.doc{margin:clamp(18px,3vw,30px) var(--px) clamp(14px,2.4vw,22px);padding:clamp(16px,2.6vw,26px);background:#ffffff08;border:1px solid #ffffff22;border-radius:10px}\n.doc h1{font:800 clamp(30px,5.4vw,60px)/1.04 var(--f-display);letter-spacing:-.02em;color:#EEF1F6;margin:0 0 10px;max-width:18ch;text-wrap:balance}\n.doc h1 em{font-style:normal;color:var(--code-accent)}\n.win .cl,.win .q,.win pre{font:400 var(--fs)/var(--lh) var(--f-mono);margin:0}\n.win .q{color:var(--code-muted)}\n.doc pre{padding:0 !important}\n.win pre{padding:0 var(--px) clamp(22px,4vw,38px);color:var(--code-fg);white-space:pre-wrap;overflow-wrap:anywhere}\n.win .c{color:var(--code-muted)}\n.win .you{color:var(--code-accent);font-weight:500}\n.win .k{color:var(--code-key)}\n.win .s{color:var(--code-str)}\n.win .cur{display:inline-block;width:.45em;height:1.05em;background:var(--code-accent);vertical-align:-.15em;margin-left:2px;animation:blink 1.1s steps(1) infinite}\n@keyframes blink{50%{opacity:0}}\n@media (prefers-reduced-motion:reduce){.win .cur{animation:none}}\n.box{display:block;background:#ffffff08;border:1px solid #ffffff22;border-radius:10px;padding:.7em 1em;max-height:15em;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}\n.field{font:inherit;color:var(--code-str,#9CCB8F);background:#ffffff0d;border:1px solid #ffffff33;border-radius:6px;padding:.05em .55em;width:min(18ch,100%);outline:none}\n.field:focus{border-color:var(--code-accent);background:#ffffff14}\n.field::placeholder{color:var(--code-muted,#8a8f98)}\n.mini{font:500 .8em/1.5 var(--f-mono);padding:.05em .7em;margin-left:.7em;border:1px solid #ffffff33;border-radius:999px;background:transparent;color:var(--code-fg);cursor:pointer;text-decoration:none;display:inline-block;white-space:nowrap}\n.mini:hover{border-color:var(--code-accent);color:var(--code-accent)}\n\n.toast{position:fixed;left:50%;bottom:calc(24px + env(safe-area-inset-bottom,0px));transform:translate(-50%,20px);background:var(--fg);color:var(--bg);padding:10px 16px;border-radius:8px;font:500 14px var(--f-body);opacity:0;pointer-events:none;transition:.2s;z-index:10}\n.toast.on{opacity:1;transform:translate(-50%,0)}\n@media (prefers-reduced-motion:reduce){.toast{transition:none}}\n</style>\n\n<div class="wrap">\n  <header class="top">\n    <button class="brand" type="button" data-view="home" aria-label="Cafe Commit, home">\n      <svg viewBox="0 0 32 32" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 14h18v6a6 6 0 0 1-6 6h-6a6 6 0 0 1-6-6z"/><path d="M23 16h2.5a3 3 0 0 1 0 6H22"/><path d="M11 4c-1.5 2 1.5 3 0 5M17 4c-1.5 2 1.5 3 0 5"/></svg>\n      Cafe Commit\n    </button>\n    <nav class="nav" aria-label="Pages">\n      <a class="btn" id="devlink" href="https://github.com/sylivrisw-arch?tab=repositories" target="_blank" rel="noopener noreferrer">The dev</a>\n      <button class="btn" type="button" data-view="donate">Donate</button>\n      <button class="btn" type="button" data-view="donators">Donators</button>\n    </nav>\n  </header>\n\n  <main class="pages" id="pages"></main>\n</div>\n<div class="toast" id="toast" role="status"></div>\n\n<script>\n/* ============ EDIT THIS BLOCK ============ */\nconst CONFIG = {\n  creator: "@sylivris-arch",\n  github: "https://github.com/sylivrisw-arch?tab=repositories",\n  // Your PayID. An email address set up just for this is safer than your mobile number.\n  payid: { value: "", kind: "mobile" },\n  contact: "",  // optional, e.g. "message @sylivris-arch on X". Shown on the donate page if set.\n  sessions: [\n    { name: "casual session",         hours: "1-2 hours" },\n    { name: "deep diving / research", hours: "3-5 hours" },\n    { name: "the big one",            hours: "6-12 hours" }\n  ],\n  // Supporters shown on the home page and the donators page: { name:"@handle" }\n  regulars: []\n};\n/* ========================================= */\n\nconst $ = id => document.getElementById(id);\nconst esc = s => String(s).replace(/[&<>"\']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",\'"\':"&quot;","\'":"&#39;"}[c]));\nconst c = t => \'<span class="c">\'+esc(t)+\'</span>\';\nconst you = t => \'<span class="you">\'+esc(t)+\'</span>\';\nconst k = t => \'<span class="k">\'+esc(t)+\'</span>\';\nconst s = t => \'<span class="s">\'+esc(t)+\'</span>\';\nconst payidUnset = () => !CONFIG.payid.value || CONFIG.payid.value.indexOf("PASTE_") === 0;\n\nfunction toast(msg){ const t=$("toast"); t.textContent=msg; t.classList.add("on"); clearTimeout(toast.h); toast.h=setTimeout(()=>t.classList.remove("on"),1900); }\nasync function copyText(text, okMsg){\n  try { await navigator.clipboard.writeText(text); toast(okMsg); }\n  catch(e){ toast("Could not copy. Select the text and copy it by hand."); }\n}\n\nconst VIEWS = {\n  home(){\n    const names = CONFIG.regulars.map(r=>esc(r.name)).concat([you("@your_handle")]);\n    return {\n      file: "app.py",\n      boxed: true,\n      title: \'I build apps at cafe tables, <em>for fun</em>.\',\n      sub: c("# Built at a cafe table by ")+you(CONFIG.creator),\n      lines: [\n        c(\'"""\'),\n        c("# Supported by: ")+names.join(c(", "))+c("  <- could be you")+\'<span class="cur"></span>\',\n        k("from")+" flask "+k("import")+" Flask",\n        "app = Flask(__name__)",\n        c(\'"""\'),\n        c("# If you have a use for them, or see a future for the applications."),\n        c("# Send a tip by PayID and your ")+you("@handle")+c(" goes in the credits of my Python scripts."),\n        c(\'"""\'),\n        c("# More of my work is on GitHub."),\n        "github = "+s(\'"\'+CONFIG.github+\'"\')+\' <button class="mini" type="button" data-copy="github">copy</button>\'\n      ]\n    };\n  },\n  donate(){\n    const lines = ["sessions = "];\n    CONFIG.sessions.forEach(x=>lines.push("    "+s(\'"\'+x.name+\'"\')+": "+s(\'"\'+x.hours+\'"\')+","));\n    lines.push(c(\'"""\'), c("# Put your username in the payment description and I\'ll add it to the script."));\n    if(payidUnset()) lines.push("payid = None"+c("  # payment details not yet configured. This site is meant to represent my work."));\n    else lines.push("payid = "+s(\'"\'+CONFIG.payid.value+\'"\')+\' <button class="mini" type="button" data-copy="payid">copy</button>\');\n    if(CONFIG.contact) lines.push(c("# Forgot to add it? "+CONFIG.contact+"."));\n    return {\n      file: "donate.py",\n      boxed: true,\n      title: \'A coffee... or a meal, <em>donate what you like</em>.\',\n      sub: c("# Every tip goes into more hours at a cafe table, building things for fun."),\n      lines\n    };\n  },\n  donators(){\n    return {\n      file: "donators.py",\n      boxed: true,\n      title: \'People who keep the <em>coffee coming</em>.\',\n      sub: c("# Supporters get a spot here. Names are added by hand, by myself."),\n      lines: [\'handle = <input class="field" id="handle" type="text" maxlength="30" placeholder="@name $10" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Handle to add"> <button class="mini" type="button" data-add="1">add</button>\', "", \'<span class="box" id="slist"></span>\']\n    };\n  }\n};\n\nfunction winHTML(v){\n  const pre=\'<pre>\'+v.lines.join("\\n")+\'</pre>\';\n  const head=\'<h1>\'+v.title+\'</h1><div class="cl">\'+v.sub+\'</div>\';\n  return \'<div class="bar"><span class="dot"></span><span class="dot"></span><span class="dot"></span><b>\'+esc(v.file)+\'</b></div>\'\n    + (v.boxed ? \'<div class="doc">\'+head+pre+\'</div>\' : \'<div class="doc">\'+head+\'</div>\'+pre);\n}\nfunction buildAll(){\n  const root = $("pages"); root.innerHTML = "";\n  Object.keys(VIEWS).forEach(name=>{\n    const v = VIEWS[name]();\n    const w = document.createElement("section");\n    w.className = "win"; w.id = name; w.setAttribute("aria-label", v.file);\n    w.innerHTML = winHTML(v);\n    root.appendChild(w);\n  });\n}\nfunction parseEntry(raw){\n  const str=String(raw||"").trim(); if(!str) return null;\n  const m=str.match(/^@?([^\\s,$]+)[\\s,]*\\$?\\s*([\\d.]+)?\\s*$/);\n  if(!m) return null;\n  const amt=m[2]?parseFloat(m[2]):0;\n  return {name:"@"+m[1], tips:1, total:isFinite(amt)?amt:0};\n}\nlet supporters = CONFIG.regulars.map(r=>({name:r.name,tips:1,total:0}));\ntry{\n  const sv=JSON.parse(localStorage.getItem("cc_supporters")||"null");\n  if(Array.isArray(sv)){\n    supporters=[];\n    sv.forEach(x=>{\n      const e = typeof x==="string" ? parseEntry(x) : (x&&typeof x.name==="string" ? {name:x.name,tips:+x.tips||1,total:+x.total||0} : null);\n      if(!e) return;\n      const hit=supporters.find(y=>y.name.toLowerCase()===e.name.toLowerCase());\n      if(hit){ hit.tips+=e.tips; hit.total+=e.total; } else supporters.push(e);\n    });\n  }\n}catch(e){}\nfunction saveList(){ try{ localStorage.setItem("cc_supporters",JSON.stringify(supporters)); }catch(e){} }\nconst money = n => "$"+(Math.round(n*100)/100).toString();\nfunction renderList(){\n  const el=$("slist"); if(!el) return;\n  el.innerHTML = supporters.length\n    ? "supporters = {\\n"+supporters.map((x,i)=>{\n        let v=\'"tips": \'+x.tips+(x.total>0?\', "total": "\'+money(x.total)+\'"\':"");\n        return "    "+s(\'"\'+x.name+\'"\')+": {"+v+\'},<button class="mini" type="button" data-del="\'+i+\'" aria-label="Delete \'+esc(x.name)+\'">delete</button>\';\n      }).join("\\n")+"\\n}"\n    : "supporters = {}"+c("  # the first name goes here");\n}\nfunction addSupporter(){\n  const f=$("handle"); const e=parseEntry(f.value);\n  if(!e){ toast("Type a handle first, like @name or @name $10"); f.focus(); return; }\n  const hit=supporters.find(y=>y.name.toLowerCase()===e.name.toLowerCase());\n  if(hit){ hit.tips+=1; hit.total+=e.total; toast(hit.name+" now has "+hit.tips+" tips"); } else supporters.push(e);\n  saveList(); renderList(); f.value=""; f.focus();\n}\nfunction delSupporter(i){\n  const x=supporters[i]; if(!x) return;\n  if(x.tips>1){ x.tips-=1; } else supporters.splice(i,1);\n  saveList(); renderList();\n}\nconst reduceMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;\nfunction setActive(name){\n  document.querySelectorAll(".nav .btn").forEach(b=>{\n    if(b.dataset.view===name) b.setAttribute("aria-current","page"); else b.removeAttribute("aria-current");\n  });\n}\nfunction go(name){\n  const el = $(name); if(!el) return;\n  const behavior = reduceMotion ? "auto" : "smooth";\n  if(name==="home") window.scrollTo({top:0,behavior}); else el.scrollIntoView({behavior,block:"start"});\n  setActive(name);\n  try{ history.replaceState(null,"","#"+name); }catch(e){}\n}\n\ndocument.addEventListener("click",e=>{\n  const nav = e.target.closest("[data-view]");\n  if(nav){ go(nav.dataset.view); return; }\n  if(e.target.closest(\'[data-copy="payid"]\') && !payidUnset()) copyText(CONFIG.payid.value,"PayID copied");\n  if(e.target.closest("[data-add]")) addSupporter();\n  const del=e.target.closest("[data-del]"); if(del) delSupporter(+del.dataset.del);\n  if(e.target.closest(\'[data-copy="github"]\')) copyText(CONFIG.github,"Link copied");\n});\n\nlet start = "home";\ntry{ const h=(location.hash||"").slice(1); if(VIEWS[h]) start=h; }catch(e){}\n$("devlink").href = CONFIG.github;\nbuildAll();\nrenderList();\n$("handle").addEventListener("keydown",e=>{ if(e.key==="Enter"){ e.preventDefault(); addSupporter(); } });\nif("IntersectionObserver" in window){\n  const io = new IntersectionObserver(es=>{ es.forEach(e=>{ if(e.isIntersecting) setActive(e.target.id); }); },{rootMargin:"-35% 0px -60% 0px"});\n  document.querySelectorAll(".win").forEach(w=>io.observe(w));\n}\nif(start!=="home") requestAnimationFrame(()=>go(start));\n</script>\n'

    def _donate_window(self):
        """Cafe Commit button: write the embedded page to a temp file and open it in the default browser."""
        try:
            path = os.path.join(tempfile.gettempdir(), "voidloader_cafe_commit.html")
            with open(path, "w", encoding="utf-8") as f:
                f.write(self._CAFE_COMMIT_HTML)
            webbrowser.open("file:///" + path.replace("\\", "/").lstrip("/"))
        except Exception as ex:
            self.toast("Couldn't open Cafe Commit: %s" % ex)

    def update_model_chip(self):
        chip = getattr(self, "model_chip", None)
        if chip is None:
            return
        try:
            loading = self.http_bridge.loading
            if loading:
                chip.set("Loading %s" % os.path.splitext(os.path.basename(str(loading)))[0], C["warn"])
            elif self.server_connected and self.server_model:
                r = self.chat_row()
                nm = (r["name"] + ("  " + r["quant"] if r["quant"] else "")) if r else (self._active_model_name() or "Model")
                chip.set(nm, C["ok"])
            elif self.server_connected:
                chip.set("Connected, no model", C["warn"])
            else:
                chip.set("Disconnected", C["hot"])
        except tk.TclError:
            pass

    # ------------------------------------------------------------------ rail
    def build_rail(self):
        rail = tk.Frame(self.body, bg=C["panel"], width=76)
        rail.pack(side="left", fill="y")
        rail.pack_propagate(False)
        self.rail_btns = {}

        # Scrollable area: add new workspaces to RAIL_TOP / RAIL_MID (RAIL_BOT follows them). It scrolls one whole button per
        # wheel notch and trims its own height so a button is never cut in half.
        holder = tk.Frame(rail, bg=C["panel"])
        holder.pack(side="top", fill="both", expand=True)
        cv = tk.Canvas(holder, bg=C["panel"], width=76, height=10, highlightthickness=0, bd=0)
        cv.pack(side="top", anchor="nw")
        inner = tk.Frame(cv, bg=C["panel"])
        cv.create_window(0, 0, window=inner, anchor="nw", width=76)
        thumb = tk.Frame(holder, bg=C["line_hi"], width=3)
        self.rail_canvas, self.rail_inner, self.rail_holder, self.rail_thumb = cv, inner, holder, thumb
        self.rail_off, self.rail_valid = 0, [0]

        class _Snap:                      # the global mouse-wheel handler (_wheel) calls yview_scroll on this
            def yview_scroll(_s, n, _what="units"):
                self._rail_step(1 if n > 0 else -1)
        cv._scroll_target = _Snap()
        inner.bind("<Configure>", lambda e=None: self._rail_apply())
        holder.bind("<Configure>", lambda e=None: self._rail_apply())

        def add(key, label, icon):
            b = RailButton(inner, label, icon, lambda k=key: self.show_ws(k), active=(key == self.ws))
            b.pack(side="top", pady=2)
            self.rail_btns[key] = b
        tk.Frame(inner, bg=C["panel"], height=8).pack(side="top")
        def divider():
            tk.Frame(inner, bg=C["line"], height=1, width=40).pack(side="top", pady=6)

        add("home", "Home", "home")
        qb = RailButton(inner, "Quick launch", "play", self._quick_folder_toggle)   # opens a folder of tiles, not a page
        qb.pack(side="top", pady=2)
        self.rail_btns["quick"] = qb
        divider()
        for k, l, i in RAIL_TOP[1:]:                  # talk: Chat, Persona, Projects
            add(k, l, i)
        divider()
        for k, l, i in RAIL_MID:                      # create: Images, Draw, Music, Blocks
            add(k, l, i)
        vb = RailButton(inner, "VoidEngine", "gear", self.open_void_engine)     # runs the engine menu script; not a page
        vb.pack(side="top", pady=2)
        self.rail_btns["voidengine"] = vb
        divider()
        for k, l, i in RAIL_BOT:                      # system: Power, Bugs
            add(k, l, i)
        tk.Frame(inner, bg=C["panel"], height=8).pack(side="top")

    def _rail_apply(self, off=None, reveal=None):
        """Lay the rail out on whole-button boundaries. `off` = wanted scroll offset in px,
        `reveal` = (top, bottom) span that must end up fully visible."""
        try:
            inner, cv, holder = self.rail_inner, self.rail_canvas, self.rail_holder
            spans = sorted((b.winfo_y() - 2, b.winfo_y() + b.winfo_height() + 2)
                           for b in inner.winfo_children() if isinstance(b, RailButton))
            H = holder.winfo_height()
            if not spans or H < 20:
                return
            content = spans[-1][1]
            valid = [0]
            if content > H:
                for t in [0] + [t for t, _ in spans[1:]]:
                    if t not in valid:
                        valid.append(t)
                    if content <= t + H:
                        break
            cur = self.rail_off if off is None else off
            if reveal is not None:
                if reveal[0] < cur:
                    cur = max(v for v in valid if v <= reveal[0])
                elif reveal[1] > cur + H:
                    cur = next((v for v in valid if v + H >= reveal[1]), valid[-1])
            cur = min(valid, key=lambda v: abs(v - cur))
            fit = [bt for _, bt in spans if bt <= cur + H]
            h = max(1, (max(fit) if fit else H) - cur)
            cv.configure(height=h, scrollregion=(0, cur, 76, cur + h))
            cv.yview_moveto(0)
            self.rail_off, self.rail_valid = cur, valid
            if len(valid) <= 1:
                self.rail_thumb.place_forget()
            else:
                self.rail_thumb.place(x=72, y=int(cur / content * H) + 2, width=3,
                                      height=max(16, int(h / content * H) - 4))
        except (AttributeError, tk.TclError, ValueError):
            pass

    def _rail_step(self, direction):
        """One wheel notch = one whole button up or down."""
        valid = self.rail_valid
        i = min(range(len(valid)), key=lambda k: abs(valid[k] - self.rail_off))
        i = max(0, min(len(valid) - 1, i + direction))
        self._rail_apply(off=valid[i])

    def rail_reveal(self, key):
        """Scroll the rail so the button for `key` is fully visible."""
        try:
            b = self.rail_btns[key]
            if b.master is not self.rail_inner:
                return          # pinned button, nothing to scroll
            self.rail_inner.update_idletasks()
            self._rail_apply(reveal=(b.winfo_y() - 2, b.winfo_y() + b.winfo_height() + 2))
        except (AttributeError, KeyError, tk.TclError):
            pass

    # ------------------------------------------------------------------ status row and VRAM ledger
    def _clock_tick(self):
        """Once a second: system time (24 h), the time this session started, and how long it has been running."""
        try:
            if getattr(self, "_clock_after", None):
                self.root.after_cancel(self._clock_after)
        except (tk.TclError, ValueError):
            pass
        self._clock_after = None
        vals = getattr(self, "_clock_vals", None) or {}
        try:
            now = time.time()
            t0 = getattr(self, "_session_t0", now)
            secs = max(0, int(now - t0))
            started = time.strftime("%H:%M", time.localtime(t0))
            if time.strftime("%Y%m%d", time.localtime(t0)) != time.strftime("%Y%m%d", time.localtime(now)):
                started += time.strftime(" (%d %b)", time.localtime(t0))
            text = {"now": time.strftime("%H:%M:%S", time.localtime(now)), "start": started,
                    "len": "%d:%02d:%02d" % (secs // 3600, secs % 3600 // 60, secs % 60)}
            for k, lbl in vals.items():
                lbl.config(text=text[k])
            self._clock_after = self.root.after(1000, self._clock_tick)
        except tk.TclError:                       # the labels were rebuilt or the window is closing
            pass

    def build_vram_strip(self):
        """The VRAM bar, across the very top of the window. Click VRAM to open Memory panel,
        click the power bar to open the Power workspace."""
        bar = tk.Frame(self.root, bg=C["panel"], height=40)
        bar.pack(side="top", fill="x")
        bar.pack_propagate(False)
        row = tk.Frame(bar, bg=C["panel"])
        row.pack(fill="both", expand=True, padx=14)
        # VRAM canvas (left, expands)
        cv = tk.Canvas(row, height=26, bg=C["panel"], highlightthickness=0, bd=0, cursor="hand2")
        cv.pack(side="left", fill="x", expand=True, pady=7)
        cv.bind("<Configure>", lambda e=None: self.draw_ledger(cv, False))
        cv.bind("<Button-1>", lambda e=None: self.toggle_dock("memory"))
        self.ledgers.append((cv, False))
        # separator
        tk.Frame(row, bg=C["line"], width=1).pack(side="left", fill="y", padx=(10, 0), pady=6)
        self._power_chip_cv = None
        # the old second row lives here now: session clock, tokens, API / Phone chips, Console, About
        if not hasattr(self, "_session_t0"):
            self._session_t0 = time.time()
        tk.Label(row, text="Session", bg=C["panel"], fg=C["faint"], font=F["small"]).pack(side="left", padx=(10, 5))
        v = tk.Label(row, text="", bg=C["panel"], fg=C["text"], font=F["small_b"])
        v.pack(side="left")
        self._clock_vals = {"len": v}
        self._clock_tick()
        self.tok_lbl = tk.Label(row, text=str(self.total_tokens) + " tokens", bg=C["panel"], fg=C["muted"], font=F["small"])
        self.tok_lbl.pack(side="left", padx=14)
        self.api_chip = Chip(row, "API %s:%s" % (BRIDGE_HOST, BRIDGE_PORT), C["faint"],
                             command=self._toggle_http_bridge, height=24)
        self.api_chip.pack(side="left", padx=4)
        self.phone_chip = Chip(row, "Phone", C["faint"], command=self._toggle_phone_app, height=24)
        self.phone_chip.pack(side="left", padx=4)
        Btn(row, "Console", lambda: self._toggle_console(), kind="ghost", icon="terminal", height=26,
            font=F["small"]).pack(side="left", padx=(8, 0))
        Btn(row, "Cafe Commit", self._donate_window, kind="ghost", height=26, font=F["small"]).pack(side="left", padx=(4, 0))
        tk.Frame(self.root, bg=C["line"], height=1).pack(side="top", fill="x")

    def _draw_power_chip(self, cv=None):
        """Draw the compact power bar on the VRAM strip. Called by the power sampler and on resize."""
        if cv is None:
            cv = getattr(self, "_power_chip_cv", None)
        if cv is None:
            return
        try:
            if not cv.winfo_exists():
                return
            cv.delete("all")
            W, H = cv.winfo_width(), cv.winfo_height()
            if W < 60:
                return
            pw = self.pw
            st = pw.get("stat", {})
            running = self._power_running()
            # --- battery bar (only when on battery and percent is known) ---
            pct_txt = st.get("charge", "---")
            on_batt = st.get("source", "") == "Battery"
            try:
                pct = float(pct_txt.replace("%", "").replace("~", "").strip())
            except (ValueError, AttributeError):
                pct, on_batt = None, False
            BAR_W = 38
            x = 4
            if pct is not None:
                col = C["ok"] if pct >= 40 else (C["warn"] if pct >= 15 else C["hot"])
                inner = int(BAR_W * pct / 100.0)
                # battery outline
                cv.create_rectangle(x, H//2-5, x+BAR_W, H//2+5, outline=C["line"], fill=C["panel"])
                cv.create_rectangle(x+BAR_W, H//2-2, x+BAR_W+3, H//2+2, outline=C["line"], fill=C["line"])
                if inner > 0:
                    cv.create_rectangle(x+1, H//2-4, x+inner, H//2+4, outline="", fill=col)
                cv.create_text(x + BAR_W//2, H//2, text="%d%%" % pct, fill=C["bg"], font=F["small_b"], anchor="center")
                x += BAR_W + 8
            else:
                cv.create_text(x, H//2, text="BAT", fill=C["faint"], font=F["small"], anchor="w")
                x += 26
            # --- total watts ---
            sys_txt = st.get("system", "---")
            gpu_txt = st.get("gpu", "---")
            chg_txt = st.get("charger", "---")
            cpu_txt = st.get("cpu", "---")
            ac = (st.get("source", "") == "AC")
            # main number: charger draw on AC (where known), system draw on battery
            if ac and chg_txt not in ("---", ""):
                main = chg_txt.split("/")[0].strip()           # e.g. "~24.0 W"
                label = "AC"
            elif sys_txt not in ("---", ""):
                main = sys_txt.replace("~", "~")
                label = "SYS"
            else:
                main = "---"
                label = ""
            cv.create_text(x, H//2, text=label, fill=C["faint"], font=F["small"], anchor="w")
            x += cv.tk.call("font", "measure", F["small"], label) + 4
            heat = C["muted"]
            try:
                w_val = float(main.replace("~", "").replace("W", "").strip())
                heat = C["ok"] if w_val < 30 else (C["warn"] if w_val < 60 else C["hot"])
            except (ValueError, AttributeError):
                pass
            cv.create_text(x, H//2, text=main, fill=heat, font=F["small_b"], anchor="w")
            x += cv.tk.call("font", "measure", F["small_b"], str(main)) + 8
            # GPU watts
            if gpu_txt not in ("---", "off", ""):
                cv.create_text(x, H//2, text="GPU", fill=C["faint"], font=F["small"], anchor="w")
                x += cv.tk.call("font", "measure", F["small"], "GPU") + 4
                cv.create_text(x, H//2, text=gpu_txt, fill=C["muted"], font=F["small_b"], anchor="w")
                x += cv.tk.call("font", "measure", F["small_b"], str(gpu_txt)) + 8
            # CPU
            if cpu_txt not in ("---", ""):
                cv.create_text(x, H//2, text="CPU", fill=C["faint"], font=F["small"], anchor="w")
                x += cv.tk.call("font", "measure", F["small"], "CPU") + 4
                cv.create_text(x, H//2, text=cpu_txt, fill=C["muted"], font=F["small_b"], anchor="w")
                x += cv.tk.call("font", "measure", F["small_b"], str(cpu_txt)) + 8
            # not monitoring
            if not running:
                cv.create_text(x, H//2, text="(off)", fill=C["faint"], font=F["small"], anchor="w")
                x += cv.tk.call("font", "measure", F["small"], "(off)") + 4
            # snap canvas width to content so there's no blank gap
            cv.config(width=max(40, int(x)))
        except tk.TclError:
            pass

    def _refresh_chips(self):
        try:
            br = self.http_bridge
            self.api_chip.set(dot=C["ok"] if br.running else C["faint"])
            self.phone_chip.set(dot=C["ok"] if (br.running and br.lan) else C["faint"])
        except (tk.TclError, AttributeError):
            pass
        if self.ws == "chat":
            self._refresh_inspector_soft()

    def redraw_ledgers(self):
        live = []
        for cv, tall in self.ledgers:
            try:
                if cv.winfo_exists():
                    self.draw_ledger(cv, tall)
                    live.append((cv, tall))
            except tk.TclError:
                pass
        self.ledgers = live

    def draw_ledger(self, cv, tall):
        cv.delete("all")
        W, H = cv.winfo_width(), cv.winfo_height()
        if W < 80:
            return
        total, margin, _segs = self.vram_info()
        usable = max(1.0, total - margin)
        used = sum(self.seg_cur.values())
        ratio = used / usable
        heat = C["ok"] if ratio < .7 else (C["warn"] if ratio < .93 else C["hot"])
        free = max(0, usable - used)
        track = C["line"] if not tall else C["bg"]
        if tall:
            x0, x1, by, bh = 2, W - 2, 6, 26
        else:
            x0, x1, by, bh = 168, W - 118, H / 2 - 5, 10
            cv.create_text(0, H / 2, text="VRAM", anchor="w", fill=C["faint"], font=F["small"])
            cv.create_text(46, H / 2, text="%.1f of %.1f GB" % (used / 1000, total / 1000), anchor="w",
                           fill=C["text"], font=F["small_b"])
            cv.create_text(W - 4, H / 2, text="%.1f GB free" % (free / 1000), anchor="e", fill=heat, font=F["small_b"])
        bw = x1 - x0
        rrect(cv, x0, by, x1, by + bh, 4, fill=track, outline=C["line"] if tall else track)
        mw = margin / total * bw
        rrect(cv, x1 - mw, by, x1, by + bh, 4, fill=mix(track, C["hot"], .16), outline="")
        for gx in range(int(x1 - mw) + 4, int(x1) - 2, 4):
            cv.create_line(gx, by + 2, gx - 3, by + bh - 2, fill=mix(C["faint"], track, .35))
        x = x0
        names = {r["key"]: r["name"] for r in self.model_rows()}
        order = {r["key"]: i for i, r in enumerate(self.model_rows())}
        names[VOICE_MODEL_KEY] = VOICE_MODEL_NAME
        order[VOICE_MODEL_KEY] = len(order)
        for key, mb in self.seg_cur.items():
            if mb < 2:
                continue
            sw = mb / total * bw
            col = C["seg"][order.get(key, 0) % 4]
            rrect(cv, x, by, x + sw - 2, by + bh, 4, fill=col, outline=col)
            if tall and sw > 120:
                cv.create_text(x + 10, by + bh / 2, text=names.get(key, os.path.basename(str(key))), anchor="w",
                               fill=C["bg"], font=F["small_b"])
            x += sw
        if tall:
            ty = by + bh + 12
            cv.create_text(x0, ty, text="Loaded %.1f GB" % (used / 1000), anchor="w", fill=C["muted"], font=F["small"])
            cv.create_text(x + max(0, (x1 - mw - x)) / 2, ty, text="Free %.1f GB" % (free / 1000), fill=heat,
                           font=F["small_b"])
            cv.create_text(x1, ty, text="Reserved %.1f GB" % (margin / 1000), anchor="e", fill=C["muted"], font=F["small"])

    def _animate_ledger(self, steps=14, i=0, start=None):
        if start is None:
            start = dict(self.seg_cur)
            if self._anim_job is not None:
                try:
                    self.root.after_cancel(self._anim_job)
                except tk.TclError:
                    pass
        _t, _m, segs = self.vram_info()
        target = {k: v for k, v in segs}
        e = 1 - (1 - (i + 1) / steps) ** 3
        for k in set(start) | set(target):
            s0, s1 = start.get(k, 0.0), target.get(k, 0.0)
            self.seg_cur[k] = s0 + (s1 - s0) * e
        for k in [k for k, v in self.seg_cur.items() if v < 0.5 and k not in target]:
            del self.seg_cur[k]
        self.redraw_ledgers()
        if i + 1 < steps:
            self._anim_job = self.root.after(18, lambda: self._animate_ledger(steps, i + 1, start))
        else:
            self._anim_job = None

    # ------------------------------------------------------------------ dock (Memory, Load output, Console)
    def build_dock(self):
        self.dock = tk.Frame(self.root, bg=C["panel"], height=312)
        self.dock.pack_propagate(False)
        tk.Frame(self.dock, bg=C["line"], height=1).pack(side="top", fill="x")
        tabs = tk.Frame(self.dock, bg=C["panel"])
        tabs.pack(side="top", fill="x", padx=14, pady=(6, 0))
        self.dock_tabs = {}
        for key, label in (("memory", "Memory"), ("log", "Load output"), ("console", "Console")):
            b = Btn(tabs, label, lambda k=key: self.toggle_dock(k, force_open=True), kind="tab", height=30,
                    active=(key == self.dock_tab))
            b.pack(side="left", padx=(0, 4))
            self.dock_tabs[key] = b
        Btn(tabs, "", lambda: self.toggle_dock(), kind="ghost", icon="close", height=28, radius=14, width=30).pack(side="right")
        self.dock_body = tk.Frame(self.dock, bg=C["panel"])
        self.dock_body.pack(side="top", fill="both", expand=True)
        self._build_persistent_dock_widgets()

    @property
    def console_visible(self):
        return bool(self.dock_open and self.dock_tab == "console")

    def toggle_dock(self, tab=None, force_open=False):
        if tab and self.dock_open and self.dock_tab != tab:
            self.dock_tab = tab
            self.render_dock()
            return
        if tab and not self.dock_open:
            self.dock_tab = tab
        if force_open and self.dock_open:
            return
        self.dock_open = not self.dock_open
        if self.dock_open:
            self.dock.pack(side="bottom", fill="x", before=self.body)
            self.render_dock()
        else:
            self.dock.pack_forget()
            if self.comp_text is not None:
                try:
                    self.comp_text.focus_set()
                except tk.TclError:
                    pass

    def _toggle_console(self, show=None):
        if show is None:
            show = not self.console_visible
        if show == self.console_visible:
            return
        if show:
            self.dock_tab = "console"
            if not self.dock_open:
                self.toggle_dock("console")
            else:
                self.render_dock()
            if not self.con_buf:
                self._con_print("Voidloader console - type 'help' for commands, ` or Esc to close.", "c_dim")
            self.console_entry.focus_set()
        else:
            self.toggle_dock()

    def render_dock(self):
        if not self.dock_open:
            return
        for k, b in self.dock_tabs.items():
            b.set_active(k == self.dock_tab)
        keep = (self.console_frame, self.log_frame)
        for w in self.dock_body.winfo_children():
            if w in keep:
                w.pack_forget()
            else:
                w.destroy()
        self.ledgers = [(cv, t) for cv, t in self.ledgers if not t]
        getattr(self, "dock_" + self.dock_tab)(self.dock_body)

    def _build_persistent_dock_widgets(self):
        """The console and the load output keep their text while you switch tabs."""
        p = self.dock_body
        # load output
        self.log_frame = tk.Frame(p, bg=C["panel"])
        tk.Label(self.log_frame, text="llama.cpp's own log while a model loads.", bg=C["panel"], fg=C["muted"],
                 font=F["small"]).pack(anchor="w", padx=18, pady=(10, 6))
        wrap = tk.Frame(self.log_frame, bg=C["code"])
        wrap.pack(fill="both", expand=True, padx=16, pady=(0, 14))
        self.log_text = tk.Text(wrap, bg=C["code"], fg=C["muted"], font=F["mono"], relief="flat", bd=0, height=3,
                                highlightthickness=0, padx=12, pady=8, wrap="none", spacing1=2, state="disabled")
        self.log_text.pack(fill="both", expand=True)
        self.log_text.bind("<KeyPress-grave>", self._on_grave)
        if self.log_buf:
            self.log_text.config(state="normal")
            self.log_text.insert("end", self.log_buf)
            self.log_text.config(state="disabled")
        # console. The input row is packed first, to the bottom, so a short dock can never squeeze it
        # out; the output box then takes whatever height is left (its own height is only a minimum).
        self.console_frame = tk.Frame(p, bg=C["panel"])
        row = tk.Frame(self.console_frame, bg=C["code"])
        row.pack(side="bottom", fill="x", padx=16, pady=(6, 14))
        tk.Label(row, text=">", bg=C["code"], fg=C["accent"], font=F["mono"]).pack(side="left", padx=(12, 6))
        self.console_entry = tk.Entry(row, bg=C["code"], fg=C["text"], insertbackground=C["accent"], relief="flat",
                                      bd=0, highlightthickness=0, font=F["mono"])
        self.console_entry.pack(side="left", fill="x", expand=True, ipady=7)
        wrap = tk.Frame(self.console_frame, bg=C["code"])
        wrap.pack(side="top", fill="both", expand=True, padx=16, pady=(10, 0))
        self.console_out = tk.Text(wrap, bg=C["code"], fg=C["text"], font=F["mono"], relief="flat", bd=0, height=3,
                                   highlightthickness=0, padx=12, pady=8, wrap="word", spacing1=2, state="disabled")
        self.console_out.pack(fill="both", expand=True)
        for tag, key in (("c_cmd", "accent"), ("c_ok", "ok"), ("c_err", "hot"), ("c_dim", "muted")):
            self.console_out.tag_configure(tag, foreground=C[key])
        self.console_out.bind("<KeyPress-grave>", self._on_grave)
        self.console_entry.bind("<Return>", self._con_on_return)
        self.console_entry.bind("<Up>", lambda e: self._con_history(-1))
        self.console_entry.bind("<Down>", lambda e: self._con_history(1))
        self.console_entry.bind("<Tab>", self._con_tab)
        self.console_entry.bind("<Escape>", lambda e: (self._toggle_console(False), "break")[1])
        self.console_entry.bind("<KeyPress-grave>", self._on_grave)
        if self.con_buf:
            self.console_out.config(state="normal")
            for text, tag in self.con_buf:
                self.console_out.insert("end", text + "\n", (tag,) if tag else ())
            self.console_out.config(state="disabled")
            self.console_out.see("end")

    def _con_print(self, text="", tag=None):
        self.con_buf.append((str(text), tag))
        del self.con_buf[:-2000]
        w = self.console_out
        try:
            w.config(state="normal")
            w.insert("end", str(text) + "\n", (tag,) if tag else ())
            w.see("end")
            w.config(state="disabled")
        except tk.TclError:
            pass

    def _con_ok(self, text):
        self._con_print(text, "c_ok")

    def _con_err(self, text):
        self._con_print(text, "c_err")

    def _con_clear_screen(self):
        self.con_buf = []
        self.console_out.config(state="normal")
        self.console_out.delete("1.0", "end")
        self.console_out.config(state="disabled")

    def dock_log(self, parent):
        self.log_frame.pack(fill="both", expand=True)
        self.log_text.see("end")

    def dock_console(self, parent):
        self.console_frame.pack(fill="both", expand=True)
        self.console_entry.focus_set()

    def _log_add(self, text):
        """llama.cpp load output (and anything else Main routed to the muted log tag)."""
        if not text:
            return
        self.log_buf += text
        if len(self.log_buf) > 200000:
            self.log_buf = self.log_buf[-150000:]
        try:
            self.log_text.config(state="normal")
            self.log_text.insert("end", text)
            self.log_text.config(state="disabled")
            self.log_text.see("end")
        except tk.TclError:
            pass

    def dock_memory(self, parent):
        if not self.server_connected:
            box = tk.Frame(parent, bg=C["panel"])
            box.pack(fill="both", expand=True, padx=18, pady=16)
            tk.Label(box, text="Not connected.", bg=C["panel"], fg=C["text"], font=F["h3"]).pack(anchor="w")
            if self.backend is None:
                msg = "llama-cpp-python isn't installed here. Install it with: pip install llama-cpp-python"
            else:
                msg = "Models folder: %s\nAuthenticate checks that the folder exists, then lists its .gguf files." % self.local_models_root
            tk.Label(box, text=msg, bg=C["panel"], fg=C["muted"], font=F["ui"], justify="left").pack(anchor="w", pady=(4, 12))
            row = tk.Frame(box, bg=C["panel"])
            row.pack(anchor="w")
            Btn(row, "Authenticate", self.connect_server, kind="primary", height=32).pack(side="left")
            Btn(row, "Models folder", lambda: self.show_ws_settings("Startup"), kind="ghost", height=32).pack(side="left", padx=8)
            return
        cv = tk.Canvas(parent, height=58, bg=C["panel"], highlightthickness=0, bd=0, cursor="hand2")
        cv.pack(fill="x", padx=16, pady=(12, 8))
        cv.bind("<Configure>", lambda e=None: self.draw_ledger(cv, True))
        self.ledgers.append((cv, True))
        foot = tk.Frame(parent, bg=C["panel"])
        foot.pack(side="bottom", fill="x", padx=16, pady=(0, 8))
        Btn(foot, "Disconnect", self.disconnect_server, kind="ghost", height=26, font=F["small"]).pack(side="right")
        Btn(foot, "Refresh list", self.fetch_model_catalog, kind="ghost", height=26, font=F["small"]).pack(side="right", padx=6)
        tk.Label(foot, text="llama-cpp-python is pinned, so newer quant formats (e.g. MXFP4) won't load until it is upgraded.",
                 bg=C["panel"], fg=C["warn"], font=F["small"]).pack(side="left")
        outer = tk.Frame(parent, bg=C["panel"])
        outer.pack(fill="both", expand=True, padx=16)
        sc = Scroller(outer, C["panel"])
        sc.pack(fill="both", expand=True)
        g = tk.Frame(sc.inner, bg=C["panel"])
        g.pack(fill="x")
        g.columnconfigure(2, weight=1)
        rows = self.model_rows()
        if not rows:
            tk.Label(g, text="No .gguf files found under %s." % self.local_models_root, bg=C["panel"], fg=C["muted"],
                     font=F["ui"]).grid(row=0, column=0, sticky="w", pady=8)
        for r, m in enumerate(rows):
            col = C["seg"][r % 4]
            sw = tk.Canvas(g, width=12, height=12, bg=C["panel"], highlightthickness=0, bd=0)
            rrect(sw, 0, 0, 12, 12, 3, fill=col if m["loaded"] else "", outline=col, width=1.5)
            sw.grid(row=r, column=0, padx=(0, 10), pady=4)
            tk.Label(g, text=m["name"], bg=C["panel"], fg=C["text"], font=F["ui_b"], anchor="w").grid(row=r, column=1, sticky="w")
            detail = ", ".join(x for x in (m["params"], m["quant"], "%.1f GB" % (m["mb"] / 1000.0)) if x)
            tk.Label(g, text=detail, bg=C["panel"], fg=C["muted"], font=F["small"]).grid(row=r, column=2, sticky="w", padx=16)
            tk.Label(g, text=self._ctx_text_for(m), bg=C["panel"], fg=C["muted"], font=F["small"]).grid(row=r, column=3, padx=12)
            is_chat = m["loaded"] and m["key"] == self.server_model
            if m["loading"]:
                st, sc_ = "Loading", C["warn"]
            elif m["loaded"]:
                st, sc_ = ("Loaded, chat" if is_chat else "Loaded"), C["ok"]
            else:
                lab, ck = self.model_fit(m)
                st, sc_ = lab, C[ck]
            tk.Label(g, text=st, bg=C["panel"], fg=sc_, font=F["small_b"], width=18, anchor="w").grid(row=r, column=4)
            bf = tk.Frame(g, bg=C["panel"])
            bf.grid(row=r, column=5, pady=2)
            if m["loaded"]:
                if not is_chat:
                    Btn(bf, "Use", lambda k=m["key"]: self._pick_model(k), kind="soft", height=26, font=F["small"],
                        padx=10).pack(side="left", padx=(0, 4))
                Btn(bf, "Unload", lambda k=m["key"]: self._unload_key(k), kind="soft", height=26, font=F["small"],
                    padx=12).pack(side="left")
            else:
                fits = self.model_fit(m)[1] != "hot"
                Btn(bf, "Load", lambda k=m["key"]: self._pick_model(k), kind="primary" if fits else "ghost",
                    height=26, font=F["small"], padx=12).pack(side="left")
            for wdg in [sw] + list(g.grid_slaves(row=r)):
                wdg.bind("<Button-3>", lambda e, mm=m: self.model_menu(e, mm))
        self._voice_model_panel_row(g, len(rows) if rows else 1)      # row 0 holds the "no .gguf files" note

    def _voice_model_panel_row(self, g, r):
        """The Qwen3-TTS voice model: listed with the others, but only for voice cloning (no Use / chat button)."""
        v = self._voice_model_row()
        col = C["seg"][r % 4]
        sw = tk.Canvas(g, width=12, height=12, bg=C["panel"], highlightthickness=0, bd=0)
        rrect(sw, 0, 0, 12, 12, 3, fill=col if v["loaded"] else "", outline=col, width=1.5)
        sw.grid(row=r, column=0, padx=(0, 10), pady=(10, 4))
        tk.Label(g, text=VOICE_MODEL_NAME, bg=C["panel"], fg=C["text"], font=F["ui_b"], anchor="w").grid(
            row=r, column=1, sticky="w", pady=(10, 0))
        detail = "Voice cloning only. Not a chat model" + (", %.1f GB" % (v["size_mb"] / 1000.0) if v["size_mb"] else "")
        tk.Label(g, text=detail, bg=C["panel"], fg=C["muted"], font=F["small"]).grid(
            row=r, column=2, sticky="w", padx=16, pady=(10, 0))
        tk.Label(g, text=("on " + str(QWEN_VOICE.device)) if v["loaded"] else "", bg=C["panel"], fg=C["muted"],
                 font=F["small"]).grid(row=r, column=3, padx=12, pady=(10, 0))
        if v["loading"]:
            st, sc_ = "Loading", C["warn"]
        elif v["loaded"]:
            st, sc_ = "Loaded, voice", C["ok"]
        elif v["err"]:
            st, sc_ = "Needs setup", C["hot"]
        else:
            st, sc_ = "Not loaded", C["faint"]
        tk.Label(g, text=st, bg=C["panel"], fg=sc_, font=F["small_b"], width=18, anchor="w").grid(
            row=r, column=4, pady=(10, 0))
        bf = tk.Frame(g, bg=C["panel"])
        bf.grid(row=r, column=5, pady=(10, 2))
        if v["loaded"]:
            Btn(bf, "Unload", self._voice_model_unload, kind="soft", height=26, font=F["small"], padx=12).pack(side="left")
        elif not v["loading"]:
            Btn(bf, "Load", self._voice_model_load, kind="primary" if not v["err"] else "ghost", height=26,
                font=F["small"], padx=12).pack(side="left")
        if v["err"] and not v["loaded"]:
            tk.Label(g, text=v["err"], bg=C["panel"], fg=C["hot"], font=F["small"], anchor="w", justify="left",
                     wraplength=640).grid(row=r + 1, column=1, columnspan=5, sticky="w")

    def _unload_key(self, key):
        mv = self._ensure_models_viewer()
        idx = next((i for i, e in enumerate(mv.models) if e.get("key") == key), None)
        if idx is not None:
            mv._unload(idx)

    def _viewer_index(self, key):
        mv = self._ensure_models_viewer()
        return next((i for i, e in enumerate(mv.models) if e.get("key") == key), None)

    def model_menu(self, e, m):
        menu = tk.Menu(self.root, tearoff=0, bg=C["raised"], fg=C["text"], activebackground=C["accent"],
                       activeforeground=C["on_accent"], bd=0, font=F["ui"])
        mv = self._ensure_models_viewer()
        idx = self._viewer_index(m["key"])
        info = ("Key: %s" % m["key"], "Quantization: %s" % (m["quant"] or "?"), "Size: %.1f GB" % (m["mb"] / 1000.0),
                "Max context: %s" % (format(m["maxctx"], ",") if m["maxctx"] else "?"),
                "Context length: %s" % format(int(m["ctx"]), ","))
        for line in info:
            menu.add_command(label=line, state="disabled")
        menu.add_separator()
        menu.add_command(label="Edit context length", command=lambda: self.edit_ctx_for(m["key"]))
        if m["loaded"]:
            menu.add_command(label="Unload model", command=lambda: self._unload_key(m["key"]))
            menu.add_command(label="Reload model", command=lambda: self._reload_key(m["key"]))
        else:
            menu.add_command(label="Load model", command=lambda: self._pick_model(m["key"]))
        menu.add_separator()
        menu.add_command(label="Copy key", command=lambda: (self.root.clipboard_clear(), self.root.clipboard_append(m["key"])))
        try:
            menu.tk_popup(e.x_root, e.y_root)
        finally:
            menu.grab_release()

    def _reload_key(self, key):
        mv = self._ensure_models_viewer()
        idx = self._viewer_index(key)
        if idx is None:
            return
        state = mv.model_state[key]
        mv._reload_with_context(idx, state["ctx"])

    def edit_ctx_for(self, key):
        """Selects the model so the Chat inspector's context row edits it."""
        mv = self._ensure_models_viewer()
        self._ctx_key = key
        idx = self._viewer_index(key)
        if idx is not None:
            mv._select_index(idx)
        self.inspector_open = True
        self.show_ws("chat")
        self.toast("Set the context length in the inspector, under Model.")



    # ------------------------------------------------------------------ centre: header + composer + content
    def render_center(self):
        for w in self.center.winfo_children():
            w.destroy()
        self._mh = {}
        self.chat = None
        if self.ws != "home":
            self.build_header(self.center)
        self.comp_text = None
        self._blk_panel, self._comp_wrap, self._blk_chip_row, self._blk_chips = None, None, None, {}
        self._pane_chat, self._pane_ph, self._pane_ui = {}, {}, {}
        if (self.ws == "chat" and not self._split) or self.ws in PLACEHOLDERS:
            self.build_composer(self.center)
        self.content = tk.Frame(self.center, bg=C["bg"])
        self.content.pack(side="top", fill="both", expand=True)
        getattr(self, "ws_" + self.ws)(self.content)
        if self.prefill and self.comp_text is not None:
            self.comp_text.delete("1.0", "end")
            self.comp_text.insert("1.0", self.prefill)
            self.comp_text.configure(fg=C["text"])
            self.comp_has_ph = False
            self.comp_text.focus_set()
            self.prefill = None
        if self.ws == "chat":
            self._blk_panel = tk.Frame(self.center, bg=C["line_hi"])
            self._blk_render()

    def _chat_subtitle(self):
        base = self._chat_subtitle_base()
        p, pe = self._active_project(), self._active_persona()
        if not p and not pe:
            return base
        base = base.rstrip(".")
        if p:
            base += ", project " + p["name"]
        if pe:
            base += ", persona " + pe["name"]
        return base

    def _chat_subtitle_base(self):
        r = self.chat_row()
        if r:
            bits = [r["name"]] + ([r["quant"]] if r["quant"] else []) + [format(int(r["ctx"]), ",") + " context"]
            return ", ".join(bits)
        if not self.server_connected:
            return "Not connected."
        return "No model loaded."

    def build_header(self, parent):
        h = tk.Frame(parent, bg=C["bg"])
        h.pack(side="top", fill="x", padx=28, pady=(18, 6))
        left = tk.Frame(h, bg=C["bg"])
        left.pack(side="left")
        title, sub = TITLES[self.ws]
        if self.ws == "chat":
            sub = self._chat_subtitle()
        tk.Label(left, text=title, bg=C["bg"], fg=C["text"], font=F["title"]).pack(anchor="w")
        self._hdr_sub = tk.Label(left, text=sub or "", bg=C["bg"], fg=C["muted"], font=F["ui"])
        self._hdr_sub.pack(anchor="w", pady=(1, 0))
        right = tk.Frame(h, bg=C["bg"])
        right.pack(side="right")
        for label, kind, icon in reversed(HEADER_ACTIONS[self.ws]):
            if self.ws == "power" and label == "Stop" and not self._power_running():
                label, icon = "Start", "play"
            Btn(right, label, lambda l=label: self.header_action(l), kind=kind, icon=icon, height=32).pack(
                side="right", padx=(6, 0))

    def _refresh_header_sub(self):
        lb = getattr(self, "_hdr_sub", None)
        try:
            if lb is not None and lb.winfo_exists() and self.ws == "chat":
                lb.config(text=self._chat_subtitle())
        except tk.TclError:
            pass

    def _refresh_composer_ph(self):
        if self.comp_text is None:
            return
        try:
            if self.comp_has_ph:
                ph = self._placeholder()
                self.comp_text.delete("1.0", "end")
                self.comp_text.insert("1.0", ph)
                self.comp_ph = ph
        except tk.TclError:
            pass

    def _placeholder(self):
        if self.ws == "chat":
            r = self.chat_row()
            return ("Message %s" % r["name"]) if r else "Load a model to start chatting"
        return PLACEHOLDERS[self.ws]

    def header_action(self, label):
        ws = self.ws
        try:
            if label == "New chat":
                self.new_chat()
            elif label == "Save log":
                self._save_log_ui()
            elif ws == "saved" and label == "Save current chat":
                self._saved_save_current()
            elif ws == "projects":
                if label == "New project":
                    self._proj_new()
                elif label == "Save chat here":
                    self._proj_save_chat()
            elif ws == "persona" and label == "New persona":
                self._pers_new()
            elif ws == "blocks" and label == "Open in browser":
                self._open_block_editor()
            elif ws == "voice" and label == "Voice settings":
                self.show_ws_settings("Clone voice config")
            elif ws == "simworld":
                host = self._sim_host(create=False)
                if host is not None:
                    {"Backend view": host.ctl.backend_window, "Set up world": host.ctl.open_wizard}[label]()
            elif ws == "power":
                self._power_header(label)
            elif ws in TOOL_WS:
                win = self._mode_win(ws)
                acts = {
                    "draw": {"Replay": "_replay", "Copy SVG": "_copy", "Save SVG": "_save"},
                    "music": {"Save MIDI": "_save_midi", "Save WAV": "_save_wav"},
                    "images": {"Open folder": "_open_folder", "Save as": "_save_as"},
                }[ws]
                if label == "New":
                    self._mode_new(ws)
                    self.render_center()
                elif label in acts:
                    getattr(win, acts[label])()
        except Exception as exc:                                        # noqa: BLE001
            self.toast("%s: %s" % (label, exc))

    def new_chat(self):
        """Clears the conversation: wipes the message history sent to the model, resets the token
        counter and the visible chat. Doesn't touch whatever model is loaded. Blocked mid-reply."""
        if self.awaiting_reply or self.mode_busy or self._story_busy:
            return
        self.conversation = []
        self._mem_used = set()
        self._ctx_from = 0
        self._story_upto = 0
        self._mode_reset()
        self.total_tokens = 0
        self.token_lbl.config(text="Tokens: 0")
        self.msgs = []
        self._ap_cur, self._ap_mode = None, None
        self.last_response_text = ""
        self._tabs_render()
        if self.ws != "chat":
            self.show_ws("chat")
        else:
            self.render_center()

    # ---- chat tabs: every tab owns its conversation, model and reply, and can generate at the same time ----
    def _tabs_ensure(self):
        if not hasattr(self, "_tabs"):
            self._tabs = [{"id": 1}]
            self._tab_cur = 0
            self._tab_seq = 1
            self._split, self._split_ids = False, []         # side-by-side view: which two tabs are shown
            self._pane_chat, self._pane_ph, self._pane_ui = {}, {}, {}

    def _ctx_tab(self):
        """The tab the running code belongs to: a worker thread's own tab, otherwise the one on screen."""
        return getattr(_TAB_TL, "tab", None) or self._tabs[self._tab_cur]

    def _bg(self):
        """True when this code is serving a tab that is not on screen at all (so it must not touch the widgets)."""
        t = getattr(_TAB_TL, "tab", None)
        if t is None or t is self._tabs[self._tab_cur]:
            return False
        return not (self._split and t.get("id") in self._pane_chat)

    def _fg(self):
        """True when this code is serving the focused tab (the one the shared status widgets describe)."""
        t = getattr(_TAB_TL, "tab", None)
        return t is None or t is self._tabs[self._tab_cur]

    def _split_on(self):
        return bool(self._split and self.ws == "chat" and self._pane_chat)

    def _chat_w(self):
        """The scroll area that shows the current tab's messages."""
        if self._split:
            w = self._pane_chat.get(self._ctx_tab().get("id"))
            if w is not None:
                return w
        return self.chat

    def _run_in(self, tab, fn, *args):
        prev = getattr(_TAB_TL, "tab", None)
        _TAB_TL.tab = tab
        try:
            return fn(*args)
        finally:
            _TAB_TL.tab = prev

    def _ra(self, fn, *args):
        """root.after(0, ...) that keeps the calling tab, so a background tab's reply lands in the right place."""
        self.root.after(0, self._run_in, self._ctx_tab(), fn, *args)

    def _tab_label(self, i):
        t = self._tabs[i]
        conv = t.get("conversation", [])
        key = t.get("server_model")
        first = next((m["content"] for m in conv if m.get("role") == "user"), "")
        first = " ".join(str(first).split())
        model = os.path.splitext(os.path.basename(str(key)))[0] if key else "no model"
        if len(model) > 16:
            model = model[:15] + "\u2026"
        if len(first) > 16:
            first = first[:15] + "\u2026"
        dot = "\u25cf " if t.get("awaiting_reply") else ""
        return dot + model + ("  \u00b7  " + first if first else "")

    def _tabs_render(self):
        try:
            self._tabs_ensure()
            strip = self._tab_strip
            if not strip.winfo_exists():
                return
            for w in strip.winfo_children():
                w.destroy()
            for i in range(len(self._tabs)):
                cur = (i == self._tab_cur)
                pill = TabPill(strip, self._tab_label(i), command=lambda k=i: self._tab_switch(k),
                               on_close=lambda k=i: self._tab_close(k), active=cur, height=28)
                pill.pack(side="left", pady=9, padx=(0, 5))
            TabPill(strip, "+", command=self._tab_new, height=28, font=F["title"], fg=C["accent"],
                    min_w=34).pack(side="left", pady=9, padx=(0, 0))
            TabPill(strip, "Tabs" if self._split else "Split", command=self._split_toggle, height=28,
                    padx=16).pack(side="left", padx=(8, 0), pady=9)
            self._panes_refresh()
        except (tk.TclError, AttributeError):
            pass

    def _tab_by_id(self, tid):
        return next((t for t in self._tabs if t.get("id") == tid), None)

    def _split_toggle(self):
        self._tabs_ensure()
        if self._split:
            self._split = False
        else:
            if len(self._tabs) < 2:
                self._tab_seq += 1
                self._tabs.append({"id": self._tab_seq})
            cur = self._tabs[self._tab_cur]
            other = self._tabs[(self._tab_cur + 1) % len(self._tabs)]
            self._split_ids = [t["id"] for t in self._tabs if t is cur or t is other]
            self._split = True
        self._tabs_render()
        if self.ws != "chat":
            self.show_ws("chat")
        else:
            self.render_center()

    def _ws_split(self, parent):
        wrap = tk.Frame(parent, bg=C["bg"])
        wrap.pack(fill="both", expand=True, padx=14, pady=(0, 14))
        cur = self._tabs[self._tab_cur]
        for k, tid in enumerate(self._split_ids):
            t = self._tab_by_id(tid)
            if t is None:
                continue
            col = tk.Frame(wrap, bg=C["bg"], highlightthickness=2, highlightbackground=C["line"])
            col.pack(side="left", fill="both", expand=True, padx=(0 if k == 0 else 6, 0))
            head = tk.Label(col, text="", bg=C["panel"], fg=C["muted"], font=F["small_b"], anchor="w", padx=10,
                            pady=6, cursor="hand2")
            head.pack(side="top", fill="x")
            head.bind("<Button-1>", lambda _e=None, i=tid: self._pane_focus(i))
            comp = tk.Frame(col, bg=C["raised"])
            comp.pack(side="bottom", fill="x")
            Btn(comp, "", lambda i=tid: self._pane_send(i), kind="primary", icon="send", height=30, radius=15,
                width=38).pack(side="right", padx=6, pady=6)           # packed first so a wide text box can't squeeze it out
            tx = tk.Text(comp, height=2, width=1, wrap="word", bg=C["raised"], fg=C["text"], insertbackground=C["accent"],
                         relief="flat", bd=0, highlightthickness=0, font=F["ui"], padx=8, pady=6, undo=True,
                         selectbackground=C["line_hi"])
            tx.pack(side="left", fill="x", expand=True)
            tx.bind("<FocusIn>", lambda _e=None, i=tid: self._pane_focus(i))
            tx.bind("<Return>", lambda _e=None, i=tid: (self._pane_send(i), "break")[1])
            tx.bind("<Shift-Return>", lambda _e=None: None)
            sc = Scroller(col, C["bg"], maxw=900, pad=12)
            sc.pack(side="top", fill="both", expand=True)
            sc.bind("<Button-1>", lambda _e=None, i=tid: self._pane_focus(i))
            self._pane_chat[tid] = sc
            self._pane_ui[tid] = {"col": col, "head": head, "tx": tx}
            msgs = t.get("msgs", [])
            if not msgs:
                ph = tk.Label(sc.inner, text="Load a model for this pane (click its title, then use the model chip), "
                              "then type below.", bg=C["bg"], fg=C["faint"], font=F["ui"], wraplength=360,
                              justify="left")
                ph.pack(anchor="w", pady=40, padx=10)
                self._pane_ph[tid] = ph
            else:
                for m in msgs:
                    self._run_in(t, self.render_message, m)
            sc.to_bottom()
            self.root.after(80, sc.to_bottom)
            if t is cur:
                self.chat, self.comp_text, self.comp_has_ph = sc, tx, False
        if self.chat is None or self._tabs[self._tab_cur].get("id") not in self._pane_ui:
            first = next(iter(self._pane_ui), None)
            if first is not None:
                self._tab_cur = self._tabs.index(self._tab_by_id(first))
                self.chat, self.comp_text, self.comp_has_ph = self._pane_chat[first], self._pane_ui[first]["tx"], False
        self._panes_refresh()

    def _panes_refresh(self):
        try:
            curid = self._tabs[self._tab_cur].get("id")
            for tid, ui in self._pane_ui.items():
                i = next((n for n, t in enumerate(self._tabs) if t.get("id") == tid), None)
                if i is None:
                    continue
                ui["head"].config(text=self._tab_label(i))
                focused = (tid == curid)
                ui["col"].config(highlightbackground=C["accent"] if focused else C["line"])
                ui["head"].config(fg=C["text"] if focused else C["muted"])
        except (tk.TclError, AttributeError):
            pass

    def _pane_focus(self, tid):
        t = self._tab_by_id(tid)
        ui = self._pane_ui.get(tid)
        if t is None or ui is None:
            return
        self.chat, self.comp_text, self.comp_has_ph = self._pane_chat[tid], ui["tx"], False
        if self._tabs[self._tab_cur] is t:
            return
        self._tab_cur = self._tabs.index(t)
        try:
            self.token_lbl.config(text="Tokens: %d" % self.total_tokens)
            busy = bool(self.awaiting_reply)
            self.send_btn.config(state=tk.DISABLED if busy else tk.NORMAL, text="\u2026" if busy else "Send")
            self.new_chat_btn.config(state=tk.DISABLED if busy else tk.NORMAL)
        except (tk.TclError, AttributeError):
            pass
        self._tabs_render()
        self.update_model_chip()
        self._refresh_chrome()
        self.render_inspector()

    def _pane_send(self, tid):
        self._pane_focus(tid)
        ui = self._pane_ui.get(tid)
        if ui is not None:
            self.chat, self.comp_text, self.comp_has_ph = self._pane_chat[tid], ui["tx"], False
            self.on_send()

    def _tab_enter(self):
        """The tab on screen just changed: make the model, buttons and token count match it."""
        key = self.server_model
        be = self.local_backend
        inst = be.key_to_instance.get(key) if (be is not None and key) else None
        if key and not inst:
            self.toast("This tab's model (%s) isn't loaded any more. Pick one from the model chip." %
                       os.path.splitext(os.path.basename(str(key)))[0])
            self.server_model, self.server_instance_id = None, None
        elif inst:
            self.server_instance_id = inst
        busy = bool(self.awaiting_reply)
        try:
            self.token_lbl.config(text="Tokens: %d" % self.total_tokens)
            self.send_btn.config(state=tk.DISABLED if busy else tk.NORMAL, text="\u2026" if busy else "Send")
            self.new_chat_btn.config(state=tk.DISABLED if busy else tk.NORMAL)
            self._activity = "idle"
            if busy:
                self._set_activity("thinking")
                self.stage.set_activity("answering" if self._stream_answer_started else "thinking")
            else:
                self.stage.set_activity("idle")
        except (tk.TclError, AttributeError):
            pass
        self._tabs_render()
        self.update_model_chip()
        if self.ws != "chat":
            self.show_ws("chat")
        else:
            self.render_center()
        self._refresh_chrome()

    def _tab_switch(self, i):
        self._tabs_ensure()
        if self._split:
            t = self._tabs[i]
            if self.ws == "chat" and t.get("id") in self._pane_ui:
                self._pane_focus(t["id"])
                return
            if t.get("id") not in self._split_ids:
                keep = self._tabs[self._tab_cur] if self._tabs[self._tab_cur] is not t else t
                self._split_ids = [x["id"] for x in self._tabs if x is t or x is keep]
            self._tab_cur = i
            self._tab_enter()
            return
        if i == self._tab_cur:
            if self.ws != "chat":
                self.show_ws("chat")
            return
        self._tab_cur = i
        self._tab_enter()

    def _tab_new(self):
        self._tabs_ensure()
        self._tab_seq += 1
        prev = self._tabs[self._tab_cur]
        self._tabs.append({"id": self._tab_seq})            # a new tab starts empty, with no model
        self._tab_cur = len(self._tabs) - 1
        if self._split:
            self._split_ids = [prev["id"], self._tab_seq]
        self._tab_enter()

    def _tab_close(self, i):
        self._tabs_ensure()
        if self._tabs[i].get("awaiting_reply"):
            self.toast("That tab is still replying. Wait for it to finish before closing it.")
            return
        if len(self._tabs) == 1:
            self.new_chat()                      # last tab: just start it afresh
            return
        cur = self._tabs[self._tab_cur]
        del self._tabs[i]
        self._tab_cur = self._tabs.index(cur) if cur in self._tabs else min(i, len(self._tabs) - 1)
        if self._split:
            now = self._tabs[self._tab_cur]
            others = [t for t in self._tabs if t is not now]
            if not others:
                self._split = False
            else:
                other = next((t for t in others if t["id"] in self._split_ids), others[0])
                self._split_ids = [t["id"] for t in self._tabs if t is now or t is other]
        self._tab_enter()

    def _transcript_text(self):
        out = []
        for m in self.msgs:
            if m["role"] == "user":
                out.append(("You" if not m.get("label") else m["label"]) + "\n" + m["text"].strip() + "\n")
            elif m["role"] == "assistant":
                if m.get("think"):
                    out.append("Thinking\n" + m["think"].strip() + "\n")
                out.append((m.get("label") or "Assistant") + "\n" + m["text"].strip() + "\n")
            else:
                out.append(m["text"].strip() + "\n")
        return "\n".join(out)

    def _save_log_file(self, name=None):
        text = self._transcript_text()
        if not text.strip():
            return None, "The chat log is empty."
        name = name or time.strftime("chat_%Y%m%d_%H%M%S.txt")
        path = name if os.path.isabs(name) else os.path.join(self.save_folder or os.getcwd(), name)
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(text)
        except OSError as exc:
            return None, str(exc)
        return path, None

    def _save_log_ui(self):
        path, err = self._save_log_file()
        self.toast(("Saved " + path) if path else err)

    # ------------------------------------------------------------------ composer
    def build_composer(self, parent):
        wrap = tk.Frame(parent, bg=C["bg"])
        wrap.pack(side="bottom", fill="x", pady=(4, 18))
        self._comp_wrap = wrap
        card = Card(wrap, fill=C["raised"], outline=C["line_hi"], radius=22, pad=14)
        card.pack(fill="x", padx=28)
        wrap.bind("<Configure>", lambda e=None: card.pack_configure(padx=max(28, (e.width - 800) // 2)))
        body = card.body
        ph = self._placeholder()
        # the message box is its own inset panel (same look as the chip bar below it)
        tbox = tk.Frame(body, bg=C["bg"], highlightthickness=1, highlightbackground=C["line"],
                        highlightcolor=C["accent"])
        tbox.pack(fill="x")
        tx = tk.Text(tbox, height=4, wrap="word", bg=C["bg"], fg=C["text"], insertbackground=C["accent"],
                     relief="flat", bd=0, highlightthickness=0, font=F["ui_l"], padx=8, pady=8, undo=True,
                     selectbackground=C["line_hi"])
        tx.pack(fill="x", padx=2, pady=2)
        self.comp_text, self.comp_ph, self.comp_has_ph = tx, ph, True
        tx.insert("1.0", ph)
        tx.configure(fg=C["faint"])

        def focus_in(_e):
            if self.comp_has_ph:
                tx.delete("1.0", "end")
                tx.configure(fg=C["text"])
                self.comp_has_ph = False

        def focus_out(_e):
            if not tx.get("1.0", "end").strip():
                tx.delete("1.0", "end")
                tx.insert("1.0", self._placeholder())
                tx.configure(fg=C["faint"])
                self.comp_has_ph = True

        def grow(_e=None):
            try:
                n = tx.count("1.0", "end-1c", "displaylines")
                tx.configure(height=max(4, min(12, int(n[0]) if n else 1)))
            except tk.TclError:
                pass

        tx.bind("<FocusIn>", focus_in)
        tx.bind("<FocusOut>", focus_out)
        tx.bind("<KeyRelease>", grow)
        tx.bind("<Return>", lambda e=None: (self.on_send(), "break")[1])
        tx.bind("<Shift-Return>", lambda e=None: None)
        tx.bind("<Control-k>", lambda e=None: (self.open_palette(), "break")[1])
        tx.bind("<KeyPress-grave>", self._on_grave)
        tx.bind("<Escape>", self._on_input_escape)
        if self.ws == "chat":
            # the chip bar is its own inset panel at the bottom of the card, not loose chips under the text
            dock = tk.Frame(body, bg=C["bg"], highlightthickness=1, highlightbackground=C["line"],
                            highlightcolor=C["line"])
            dock.pack(fill="x", pady=(10, 0))
            dbg = C["bg"]
            row = tk.Frame(dock, bg=dbg)
            row.pack(fill="x", padx=8, pady=(8, 0))
        else:
            dbg = C["raised"]
            row = tk.Frame(body, bg=C["raised"])
            row.pack(fill="x", pady=(8, 0))
        if self.ws == "chat":
            eff_lbl = tk.Label(row, text="Effort", bg=dbg, fg=C["faint"], font=F["small"])
            eff_lbl.pack(side="left", padx=(4, 6))
            cur = self.reasoning_level if self.reasoning_enabled else "Off"
            seg = Segmented(row, REASONING_LEVELS, cur, self._set_reasoning,
                            gap_before=("High",),
                            tints={"High": ("#e0a468", "#d98a3d"), "Extreme": ("#d9908a", "#c0584d"), "Ultra": ("#e0706a", "#b8332d")})
            seg.pack(side="left", padx=(0, 10))
            self.comp_seg = seg
            self.think_btn = Chip(row, self._think_btn_text(), dot=self._think_btn_dot(),
                                  command=self._toggle_thinking_btn, height=26)
            self.think_btn.pack(side="left", padx=(0, 10))
            extra = tk.Frame(dock, bg=dbg)                  # rows 2 and 3 of the chip bar (hidden by the toggle)
            extra.pack(fill="x", padx=8)
            row2 = tk.Frame(extra, bg=dbg)
            row2.pack(fill="x", pady=(6, 8))
            self.unload_btn = Chip(row2, self._unload_btn_text(), dot=self._unload_btn_dot(),
                                   command=self._toggle_unload_btn, height=26)
            self.unload_btn.pack(side="left", padx=(4, 10))
            self.vael_btn = Chip(row2, self._vael_btn_text(), dot=self._vael_btn_dot(),
                                 command=self._toggle_vael_btn, height=26)
            self.vael_btn.pack(side="left", padx=(0, 10))
            self.artist_btn = Chip(row2, self._artist_btn_text(), dot=self._artist_btn_dot(),
                                   command=self._toggle_artist_btn, height=26)
            self.artist_btn.pack(side="left", padx=(0, 10))
            self.temp_btn = Chip(row2, self._temp_btn_text(), dot=None,
                                 command=self._cycle_temp_btn, height=26)
            self.temp_btn.pack(side="left", padx=(0, 10))
            self.len_btn = Chip(row2, self._len_btn_text(), dot=None,
                                command=self._cycle_len_btn, height=26)
            self.len_btn.pack(side="left", padx=(0, 10))
            row3 = tk.Frame(extra, bg=dbg)                  # Personality / Topics chips, only while a persona is on
            self._chips_row3 = row3
            self._blk_chip_row = tk.Frame(row3, bg=dbg)
            self._blk_chip_row.pack(side="left", padx=(0, 0))
        else:
            tk.Label(row, text="Esc stops a running job", bg=C["raised"], fg=C["faint"], font=F["small"]).pack(side="left", padx=10)
        self._send_btn_w = Btn(row, "", self._send_or_stop, kind="primary", height=34, radius=17, width=44,
                               icon="stop" if (self.ws == "chat" and self.awaiting_reply) else "send")
        self._send_btn_w.pack(side="right")
        if self.ws == "chat":
            self._chips_row1 = [eff_lbl, seg, self.think_btn]
            self._chips_extra = extra
            self._chips_dock = dock
            self.chips_toggle = Chip(row, self._chips_toggle_text(), command=self._toggle_chips, height=26)
            self.chips_toggle.pack(side="right", padx=(0, 10))
            self._apply_chips_visibility()
            self._blk_row_visibility()

    def _chips_toggle_text(self):
        return "Show controls" if self.chips_hidden else "Hide controls"

    def _apply_chips_visibility(self):
        try:
            for w in self._chips_row1:
                w.pack_forget()
            if not self.chips_hidden:
                self._chips_row1[0].pack(side="left", padx=(4, 6))
                self._chips_row1[1].pack(side="left", padx=(0, 10))
                self._chips_row1[2].pack(side="left", padx=(0, 10))
            if self.chips_hidden:
                self._chips_extra.pack_forget()
            else:
                self._chips_extra.pack(fill="x", padx=8)
            self._chips_row_pad()
            self.chips_toggle.set(self._chips_toggle_text())
        except (tk.TclError, AttributeError):
            pass

    def _chips_row_pad(self):
        # keep a little breathing room under the top row when the other two rows are hidden
        try:
            self._chips_row1[0].master.pack_configure(pady=(8, 8 if self.chips_hidden else 0))
        except (tk.TclError, AttributeError, IndexError):
            pass

    def _toggle_chips(self):
        self.chips_hidden = not self.chips_hidden
        self._settings_store(chips_hidden=self.chips_hidden)
        try:
            self._blk_panel.place_forget()
        except Exception:
            pass
        self._apply_chips_visibility()

    def _set_reasoning(self, v):
        if v == "Off":
            self.reasoning_var.set(False)
        else:
            self.reasoning_var.set(True)
            self.reasoning_level_var.set(v)
        self._on_reasoning_changed()
        self._refresh_inspector_soft()

    def _composer_text(self):
        tx = self.comp_text
        if tx is None or self.comp_has_ph:
            return ""
        try:
            return tx.get("1.0", "end-1c").strip()
        except tk.TclError:
            return ""

    def _composer_clear(self):
        tx = self.comp_text
        if tx is None:
            return
        tx.delete("1.0", "end")
        tx.configure(height=4, fg=C["text"])
        self.comp_has_ph = False

    def _on_input_escape(self, _e=None):
        if self.mode_busy and self._mode_stop():
            return "break"
        return None

    def on_send(self):
        text = self._composer_text()
        if not text:
            return
        if self.ws == "chat":
            self._send_chat(text)
        elif self.ws in TOOL_WS:
            self._send_tool(text)
        elif self.ws == "blocks":
            self._send_blocks(text)

    def _on_mode_pick(self, key):
        self.show_ws(key)

    def _send_tool(self, text):
        if self.awaiting_reply or self.mode_busy:
            self.toast("Wait for the current job to finish first (Esc stops it).")
            return
        self.mode_kind = self.ws
        self._composer_clear()
        self._send_mode(text)

    def _send_chat(self, text):
        if self.awaiting_reply or self.mode_busy:
            return
        if self._story_busy:
            self.toast("Still writing the story notes. One moment.")
            return
        self._composer_clear()
        fid, self._followup_card = self._followup_card, None          # Ask him more: tag the reply that answers it
        self._turn_followup = fid if (fid and text.startswith(FOLLOWUP_PREFIX)) else None
        self._turn_recall = []
        self._add_msg({"role": "user", "text": text})
        if not self.server_connected:
            self._append("Not connected. Open Memory (the model chip) and press Authenticate, then load a model.\n\n", "system_msg")
            return
        if not self.server_model:
            self._append("No model loaded. Open Memory and load one.\n\n", "system_msg")
            return
        self.conversation.append({"role": "user", "content": text})
        self._tabs_render()
        self.awaiting_reply = True
        self._set_activity("thinking")
        self.send_btn.config(state=tk.DISABLED, text="\u2026")
        self.new_chat_btn.config(state=tk.DISABLED)
        self._begin_stream_turn()
        self._live_started = time.time()
        _tab, _model = self._ctx_tab(), self.server_model

        def _run_chat():
            _TAB_TL.tab = _tab
            self._chat_worker(_model)
        threading.Thread(target=_run_chat, daemon=True).start()

    # ------------------------------------------------------------------ chat workspace
    def ws_chat(self, parent):
        if self._split and len(self._split_ids) == 2:
            self._ws_split(parent)
            return
        self.chat = Scroller(parent, C["bg"], maxw=800, pad=28)          # wallpaper is Home-only
        self.chat.pack(fill="both", expand=True)
        if not self.msgs:
            self.empty_state()
            return
        for m in self.msgs:
            self.render_message(m)
        self.chat.to_bottom()
        self.root.after(80, self.chat.to_bottom)

    def _home_blurb(self, key):
        if key == "saved":
            n = len(self._all_saved_chats())
            return ("%d saved. Open one to carry on." % n) if n else "Nothing saved yet. Keep a chat and find it here."
        return HOME_BLURBS.get(key, TITLES[key][1] or "")

    def ws_home(self, parent):
        """The front cover. Drawn straight onto the wallpaper canvas: text is canvas text, so the wallpaper shows
        through; buttons, tiles and the notepad are solid widgets sitting on top of it."""
        sc = Scroller(parent, C["bg"], pad=28, wall=self.wall, free=True)
        sc.pack(fill="both", expand=True)
        cv = sc.cv
        txt = lambda t, font, fg: cv.create_text(0, 0, text=t, anchor="nw", font=font, fill=fg)   # noqa: E731
        win = lambda w: cv.create_window(0, 0, anchor="nw", window=w)                              # noqa: E731
        for i, w in enumerate((32, 23, 13)):
            rrect(cv, 8, 10 + i * 12, 8 + w, 16 + i * 12, 3, fill=C["seg"][i], outline=C["seg"][i], tags="logo")
        logo_at = [0, 0]
        t_title = txt(APP_TITLE, F["hero"], C["text"])
        t_sub = txt("Local models on your own machine. Nothing leaves it.", F["ui_l"], C["muted"])

        r = self.chat_row()
        total, margin, _segs = self.vram_info()
        free = max(0.0, total - margin - sum(self.seg_cur.values())) / 1000.0
        if r:
            line = "%s is loaded and ready.  %.1f GB of VRAM free." % (r["name"], free)
        elif not self.server_connected:
            line = "Not connected yet. Authenticate to see your models."
        else:
            line = "Connected, no model loaded.  %.1f GB of VRAM free." % free
        t_line = txt(line, F["ui"], C["text"])
        btns = []
        disc = not self.server_connected                  # not connected: Authenticate is the one thing to do
        if disc:
            btns.append(Btn(cv, "Authenticate", self.connect_server, kind="primary", height=34))
        main = "soft" if disc else "primary"
        if self.msgs:
            btns.append(Btn(cv, "Resume chat", lambda: self.show_ws("chat"), kind=main, icon="chat", height=34))
            btns.append(Btn(cv, "New chat", self.new_chat, kind="soft", icon="plus", height=34))
        else:
            btns.append(Btn(cv, "Start chatting", lambda: self.show_ws("chat"), kind=main, icon="chat", height=34))
        if not disc:
            btns.append(Btn(cv, "Load a model", lambda: self.toggle_dock("memory", force_open=True), kind="soft",
                            height=34))
        btn_wins = [win(b) for b in btns]

        t_ws = txt("Workspaces", F["small_b"], C["faint"])
        tiles = []
        for k, icon in HOME_TILES:
            tiles.append(HomeTile(cv, icon, TITLES[k][0], self._home_blurb(k), lambda key=k: self.show_ws(key)))
        tile_wins = [win(t) for t in tiles]
        for t in tiles:
            self.wall.register_glass(t)                  # these let the wallpaper show through (Settings > Wallpaper)

        def height_of(item):
            bb = cv.bbox(item)
            return (bb[3] - bb[1]) if bb else 0

        def layout(_e=None):
            W = cv.winfo_width()
            if W < 120:
                return
            pad, gap, rw = 28, 56, 430
            avail = W - 2 * pad
            if avail >= 420 + gap + rw:
                lw = min(avail - gap - rw, 700)
                x0 = (W - (lw + gap + rw)) // 2
                xr, two = x0 + lw + gap, True
            else:
                lw = rw = max(260, min(avail, 700))
                x0 = xr = (W - lw) // 2
                two = False
            y = 44
            cv.move("logo", x0 - logo_at[0], y - logo_at[1])
            logo_at[0], logo_at[1] = x0, y
            y += 48 + 14
            for item, after, wrap in ((t_title, 4, lw), (t_sub, 20, lw), (t_line, 12, lw)):
                cv.coords(item, x0, y)
                cv.itemconfigure(item, width=wrap)
                y += height_of(item) + after
            x = x0
            for b, wn in zip(btns, btn_wins):
                cv.coords(wn, x, y)
                x += b.winfo_reqwidth() + 8
            y += 34 + 28
            # Workspaces: under the title block, in the left column (two across when there's room)
            cv.coords(t_ws, x0, y)
            y += height_of(t_ws) + 8
            cols = 1                                           # same tiles as before, one per row
            gap_t = 12
            tw = int(rw)
            for n, wn in enumerate(tile_wins):
                cx = x0 + (n % cols) * (tw + gap_t)
                cy = y + (n // cols) * (HomeTile.H + gap_t)
                cv.coords(wn, cx, cy)
                cv.itemconfigure(wn, width=tw, height=HomeTile.H)
            y += ((len(tile_wins) + cols - 1) // cols) * (HomeTile.H + gap_t)
            yr = y
            sc.set_height(max(y, yr) + 28)

        cv.bind("<Configure>", layout, add="+")
        cv.after_idle(layout)

    # ---- Bug notes (left rail > Bugs) ----------------------------------------------------------------------
    def ws_bugs(self, parent):
        sc = Scroller(parent, C["bg"], maxw=800, pad=28)
        sc.pack(fill="both", expand=True)
        if not hasattr(self, "bug_notes"):
            self.bug_notes, self.bug_edit, self.bug_draft = load_bugnotes(), None, ""
        card = Card(sc.inner, fill=C["panel"], outline=C["line"], radius=14, pad=18)
        card.pack(fill="x", pady=(10, 24))
        self._bug_bg = C["panel"]
        self._bug_box = tk.Frame(card.body, bg=C["panel"])
        self._bug_box.pack(fill="x")
        self._bug_render()

    # ---- Bug notepad -----------------------------------------------------------------------------------
    def _bug_render(self):
        box = self._bug_box
        bg = getattr(self, "_bug_bg", C["bg"])
        for w in box.winfo_children():
            w.destroy()
        editing = next((n for n in self.bug_notes if n["id"] == self.bug_edit), None)
        if editing is None:
            self.bug_edit = None
        head = tk.Frame(box, bg=bg)
        head.pack(fill="x")
        tk.Label(head, text="Bug notes", bg=bg, fg=C["text"], font=F["ui_b"]).pack(side="left")
        tk.Label(head, text="%d saved" % len(self.bug_notes), bg=bg, fg=C["faint"],
                 font=F["small"]).pack(side="left", padx=(10, 0))
        tk.Label(box, text="Jot down anything that misbehaves while you use the app. Saved on this machine.",
                 bg=bg, fg=C["muted"], font=F["small"]).pack(anchor="w", pady=(2, 8))
        tw = tk.Text(box, height=5, width=20, wrap="word", bg=C["raised"], fg=C["text"], insertbackground=C["accent"],
                     relief="flat", bd=0, highlightthickness=1, highlightbackground=C["line"],
                     highlightcolor=C["accent"], font=F["ui"], padx=12, pady=10, undo=True,
                     selectbackground=C["line_hi"])
        tw.pack(fill="x")
        tw.insert("1.0", self.bug_draft)

        def keep(_e=None):
            self.bug_draft = tw.get("1.0", "end-1c")
        tw.bind("<KeyRelease>", keep)
        tw.bind("<Control-Return>", lambda e=None: (self._bug_save(tw), "break")[1])
        row = tk.Frame(box, bg=bg)
        row.pack(anchor="w", pady=(8, 0))
        Btn(row, "Update note" if editing else "Save", lambda: self._bug_save(tw), kind="primary",
            height=30, font=F["small"]).pack(side="left")
        if editing:
            Btn(row, "Cancel edit", self._bug_cancel, kind="ghost", height=30, font=F["small"]).pack(
                side="left", padx=(8, 0))
        elif self.bug_draft.strip():
            Btn(row, "Clear", self._bug_cancel, kind="ghost", height=30, font=F["small"]).pack(
                side="left", padx=(8, 0))
        for n in self.bug_notes:
            card = Card(box, fill=C["raised"], outline=C["accent"] if n["id"] == self.bug_edit else C["line"],
                        radius=12, pad=12)
            card.pack(fill="x", pady=(10, 0))
            stamp = n["when"] + ("  \u00b7  edited " + n["edited"] if n.get("edited") else "")
            tk.Label(card.body, text=stamp, bg=C["raised"], fg=C["faint"], font=F["small"]).pack(anchor="w")
            tk.Label(card.body, text=n["text"], bg=C["raised"], fg=C["text"], font=F["ui"], justify="left",
                     wraplength=680).pack(anchor="w", pady=(4, 8))
            br = tk.Frame(card.body, bg=C["raised"])
            br.pack(anchor="w")
            Btn(br, "Edit", lambda i=n["id"]: self._bug_begin_edit(i), kind="ghost", height=24,
                font=F["small"], padx=8).pack(side="left")
            Btn(br, "Delete", lambda i=n["id"]: self._bug_delete(i), kind="ghost", height=24,
                font=F["small"], padx=8).pack(side="left", padx=(6, 0))

    def _bug_persist(self):
        if not save_bugnotes(self.bug_notes):
            self.toast("Could not write %s (read-only folder?). Notes last this session." % BUGNOTES_FILE)

    def _bug_save(self, tw):
        text = tw.get("1.0", "end-1c").strip()
        if not text:
            self.toast("Type a note first.")
            return
        stamp = time.strftime("%d %b %Y, %H:%M")
        note = next((n for n in self.bug_notes if n["id"] == self.bug_edit), None)
        if note is not None:
            note["text"], note["edited"] = text, stamp
            self.toast("Note updated.")
        else:
            self.bug_notes.insert(0, {"id": int(time.time() * 1000), "text": text, "when": stamp, "edited": ""})
            self.toast("Note saved.")
        self.bug_edit, self.bug_draft = None, ""
        self._bug_persist()
        self._bug_render()

    def _bug_begin_edit(self, nid):
        note = next((n for n in self.bug_notes if n["id"] == nid), None)
        if note is None:
            return
        self.bug_edit, self.bug_draft = nid, note["text"]
        self._bug_render()

    def _bug_cancel(self):
        self.bug_edit, self.bug_draft = None, ""
        self._bug_render()

    def _bug_delete(self, nid):
        note = next((n for n in self.bug_notes if n["id"] == nid), None)
        if note is None:
            return
        if not messagebox.askyesno("Delete note", "Delete this bug note?\n\n%s" % note["text"][:160], parent=self.root):
            return
        self.bug_notes = [n for n in self.bug_notes if n["id"] != nid]
        if self.bug_edit == nid:
            self.bug_edit, self.bug_draft = None, ""
        self._bug_persist()
        self._bug_render()

    # ---- Quick launch (Home): connect, then load the chosen model -------------------------------------------
    @staticmethod
    def _quick_key(qid):
        return "quick_ctx" if qid == "mistral" else "quick_ctx_" + qid       # Mistral keeps its old settings key

    def _quick_choice(self, qid):
        """The model file this tile is set to ("" = pick by name, as before). A file that has gone is ignored."""
        path = str(APP_SETTINGS.get("quick_model_" + qid) or "")
        return path if path and os.path.isfile(path) else ""

    def _quick_label(self, ql):
        path = self._quick_choice(ql["id"])
        return os.path.splitext(os.path.basename(path))[0] if path else ql["label"]

    def _quick_pick_menu(self, qid, event):
        """The drop-down on a Quick launch tile: every .gguf in the models folder, or back to the automatic pick."""
        ql = next((q for q in QUICK_LAUNCHES if q["id"] == qid), None)
        root = getattr(self, "local_models_root", "")
        if ql is None or not root or not os.path.isdir(root):
            self.toast("Models folder not found. Set it in Settings first.")
            return
        found = []
        for dirpath, _dirs, files in os.walk(root):
            for fn in files:
                if fn.lower().endswith(".gguf"):
                    p = os.path.join(dirpath, fn)
                    try:
                        found.append((os.path.splitext(fn)[0], p, os.path.getsize(p)))
                    except OSError:
                        pass
        found.sort(key=lambda t: t[0].lower())
        cur = self._quick_choice(qid)
        menu = self._mk_menu()
        menu.add_command(label=("\u2713 " if not cur else "    ") + "Automatic: %s (found by name)" % ql["label"],
                         command=lambda: self._quick_set_model(qid, ""))
        menu.add_separator()
        if not found:
            menu.add_command(label="No .gguf files found in the models folder", state="disabled")
        for name, path, size in found[:80]:
            menu.add_command(label=("\u2713 " if path == cur else "    ") + "%s   (%.1f GB)" % (name, size / 1e9),
                             command=lambda p=path: self._quick_set_model(qid, p))
        if len(found) > 80:
            menu.add_command(label="\u2026 %d more, use the Memory panel" % (len(found) - 80), state="disabled")
        self._popup(menu, event.x_root, event.y_root)

    def _quick_set_model(self, qid, path):
        self._settings_store(**{"quick_model_" + qid: path})
        if getattr(self, "_qf", None) is not None:            # the folder is open: redraw it with the new name
            self._quick_folder_open(rebuild=True)

    def quick_launch(self, qid="mistral"):
        if getattr(self, "_quick", False):
            self.toast("Quick launch is already running.")
            return
        if self.backend is None:
            self.toast("llama-cpp-python isn't installed, so there is nothing to connect to.")
            return
        try:
            ctx = int(str(self._quick_var(qid).get()).replace(",", "").strip())
            if ctx < 256:
                raise ValueError
        except ValueError:
            self.toast("Context must be a whole number of tokens, 256 or more.")
            return
        self._quick_ctx, self._quick_id = ctx, qid
        self._settings_store(**{self._quick_key(qid): ctx})
        self._quick = True
        self.toast("Quick launch: connecting\u2026")
        if self.server_connected:
            self.fetch_model_catalog()          # already connected: just refresh the list, then load
        else:
            self.connect_server()               # on success this fetches the catalog, which continues below

    def _quick_abort(self, msg):
        self._quick = False
        self.toast(msg)

    def _quick_continue(self):
        """Called once the model list is in: find the chosen quick-launch model and load it."""
        self._quick = False
        ql = next((q for q in QUICK_LAUNCHES if q["id"] == getattr(self, "_quick_id", "mistral")), QUICK_LAUNCHES[0])
        mv = self._ensure_models_viewer()
        chosen = self._quick_choice(ql["id"])
        if chosen:
            idx = next((i for i, e in enumerate(mv.models) if os.path.normcase(str(e.get("key", ""))) ==
                        os.path.normcase(chosen)), None)
        else:
            idx = next((i for i, e in enumerate(mv.models)
                        if all(w in ("%s %s" % (e.get("display_name", ""), e.get("key", ""))).lower()
                               for w in ql["words"])), None)
        if idx is None:
            self.toast("Quick launch: no %s model found in your models folder." % self._quick_label(ql))
            return
        entry = mv.models[idx]
        key = entry.get("key")
        name = entry.get("display_name") or key
        ctx = self._quick_ctx
        state = mv.model_state[key]
        if state["loaded"] and state["ctx"] == ctx:
            self.toast("%s is already loaded at %d tokens." % (name, ctx))
        elif state["loaded"]:
            self.toast("Quick launch: reloading %s at %d tokens\u2026" % (name, ctx))
            mv._reload_with_context(idx, ctx)
        else:
            self.toast("Quick launch: loading %s at %d tokens\u2026" % (name, ctx))
            state["ctx"] = ctx                      # the tile's value wins over Auto-max context
            mv._set_status("Loading %s\u2026" % name)
            self.http_bridge.loading, self.http_bridge.load_error = key, None
            threading.Thread(target=mv._load_worker, args=(idx, key, ctx), daemon=True).start()
        self.show_ws("chat")

    def empty_state(self):
        f = tk.Frame(self.chat.inner, bg=C["bg"])
        f.pack(fill="x", pady=(64, 0))
        r = self.chat_row()
        if r:
            total, margin, _segs = self.vram_info()
            title = "%s is loaded and idle." % r["name"]
            sub = "%.1f GB of VRAM is free. Nothing leaves this machine." % (max(0, total - margin - sum(self.seg_cur.values())) / 1000.0)
        elif not self.server_connected:
            title = "Not connected."
            sub = "Open Memory from the status bar and press Authenticate."
        else:
            title = "No model is loaded."
            sub = "Open Memory from the status bar and pick one."
        tk.Label(f, text=title, bg=C["bg"], fg=C["text"], font=F["hero"]).pack(anchor="w")
        tk.Label(f, text=sub, bg=C["bg"], fg=C["muted"], font=F["ui_l"]).pack(anchor="w", pady=(6, 30))
        for ws, text, dest in SUGGESTIONS:
            SuggestRow(f, ws, text, dest, lambda w=ws, t=text: self.use_suggestion(w, t)).pack(fill="x")

    def use_suggestion(self, ws, text):
        self.prefill = text
        if ws == self.ws:
            self.render_center()
        else:
            self.show_ws(ws)

    def _tags(self, tw):
        tw.tag_configure("b", font=(F["body"][0], 12, "bold"))

    @staticmethod
    def _fit(tw):
        """Grow a read-only Text to exactly the height of its content."""
        try:
            res = tw.count("1.0", "end", "update", "ypixels")
            if isinstance(res, (tuple, list)):
                res = res[0]
            ls = tkfont.Font(font=tw.cget("font")).metrics("linespace")
            h = max(1, -(-int(res) // ls))
            if int(tw.cget("height")) != h:
                tw.configure(height=h)
        except (tk.TclError, TypeError, ValueError):
            pass

    def _msg_right_click(self, event):
        tw = event.widget
        has = bool(tw.tag_ranges(tk.SEL))
        menu = tk.Menu(self.root, tearoff=0, bg=C["raised"], fg=C["text"], activebackground=C["accent"],
                       activeforeground=C["on_accent"], bd=0, font=F["ui"])

        def copy():
            self.root.clipboard_clear()
            self.root.clipboard_append(tw.get(tk.SEL_FIRST, tk.SEL_LAST))

        def count():
            messagebox.showinfo("Highlighted Text Count", f"{len(tw.get(tk.SEL_FIRST, tk.SEL_LAST))} character(s) selected.")
        menu.add_command(label="Copy", command=copy, state=tk.NORMAL if has else tk.DISABLED)
        menu.add_command(label="Highlighted Text Count", command=count, state=tk.NORMAL if has else tk.DISABLED)
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def render_message(self, m):
        row = tk.Frame(self._chat_w().inner, bg=C["bg"])
        row.pack(fill="x", pady=(0, 22))
        h = {"row": row, "shown": 0}
        self._mh[id(m)] = h
        if m["role"] == "user":
            card = Card(row, fill=C["raised"], outline=C["line"], radius=18, pad=14, autow=True)
            card.pack(anchor="e")
            if m.get("label"):
                tk.Label(card.body, text=m["label"], bg=C["raised"], fg=C["faint"], font=F["small"]).pack(anchor="w")
            lbl = tk.Label(card.body, text=m["text"].strip(), bg=C["raised"], fg=C["text"], font=F["ui_l"],
                           justify="left", wraplength=520)
            lbl.pack()
            h["lbl"] = lbl
            return h
        if m["role"] == "note":
            row.pack_configure(pady=(0, 8))
            tk.Label(row, text=m["text"], bg=C["bg"], fg=C["hot"], font=F["small"], justify="left", wraplength=720).pack(anchor="w")
            return h
        live = m.get("live", False)
        spine = tk.Frame(row, bg=C["accent"] if live else mix(C["accent"], C["bg"], .55), width=3)
        spine.pack(side="left", fill="y", padx=(0, 18))
        col = tk.Frame(row, bg=C["bg"])
        col.pack(side="left", fill="both", expand=True)
        head = tk.Frame(col, bg=C["bg"])
        head.pack(fill="x", pady=(0, 6))
        r = self.chat_row()
        who = m.get("label") or (r["name"] if r else "Assistant")
        tk.Label(head, text=who, bg=C["bg"], fg=C["text"], font=F["ui_b"]).pack(side="left")
        meta = tk.Label(head, text="", bg=C["bg"], fg=C["muted"], font=F["small"])
        meta.pack(side="left", padx=(10, 0))
        h.update(spine=spine, meta=meta, col=col)
        tw = tk.Text(col, height=1, wrap="word", bg=C["bg"], fg=C["text"], font=F["body"], relief="flat", bd=0,
                     highlightthickness=0, padx=0, pady=0, spacing2=5, cursor="arrow",
                     selectbackground=C["line_hi"], inactiveselectbackground=C["line_hi"])
        self._tags(tw)
        tw.pack(fill="x")
        tw.bind("<Configure>", lambda e=None: self._fit(tw))
        tw.bind("<Button-3>", self._msg_right_click)
        h["tw"] = tw
        h["foot"] = tk.Frame(col, bg=C["bg"])
        h["foot"].pack(fill="x", pady=(10, 0))
        self._sync_message(m)
        return h

    def _think_block(self, m, h):
        f = tk.Frame(h["col"], bg=C["bg"])
        f.pack(fill="x", pady=(0, 10), before=h["tw"])
        hd = tk.Frame(f, bg=C["bg"], cursor="hand2")
        hd.pack(fill="x")
        chev = tk.Canvas(hd, width=14, height=14, bg=C["bg"], highlightthickness=0, bd=0)
        chev.pack(side="left")
        lbl = tk.Label(hd, text="Thinking", bg=C["bg"], fg=C["muted"], font=F["small"])
        lbl.pack(side="left", padx=(4, 0))
        body = tk.Label(f, text="", bg=C["bg"], fg=C["muted"], font=(F["ui"][0], 10, "italic"),
                        justify="left", wraplength=640)
        state = {"open": False}

        def paint():
            chev.delete("all")
            draw_icon(chev, "chev_down" if state["open"] else "chev_right", 7, 7, 5, C["muted"])

        def toggle(_e=None):
            state["open"] = not state["open"]
            if state["open"]:
                body.pack(fill="x", pady=(6, 0), padx=(18, 0))
            else:
                body.pack_forget()
            paint()
        for w in (hd, chev, lbl):
            w.bind("<Button-1>", toggle)
        paint()
        h["think_lbl"], h["think_body"] = lbl, body

    def _sync_message(self, m):
        """Brings the widgets of one message in line with its data (text so far, thinking, finished state)."""
        h = self._mh.get(id(m))
        if not h:
            return
        try:
            if m["role"] == "user":
                h["lbl"].config(text=m["text"].strip())
                return
            if m["role"] != "assistant":
                return
            if m.get("think") and self.show_thinking and "think_lbl" not in h:
                self._think_block(m, h)
            if h.get("think_body") is not None:
                h["think_body"].config(text=m["think"].strip())
                if m.get("live"):
                    if m["text"]:
                        h["think_lbl"].config(text="Thought for %.1f seconds" % (m.get("t_ans", time.time()) - m["t0"]))
                    else:
                        h["think_lbl"].config(text="Thinking" + "." * (int(time.time() * 3) % 4))
                else:
                    h["think_lbl"].config(text="Thought for %.1f seconds" % (m.get("t_ans", m["t0"]) - m["t0"]))
            tw = h["tw"]
            new = m["text"].lstrip("\n")[h["shown"]:] if h["shown"] else m["text"].lstrip("\n")
            if new:
                tw.configure(state="normal")
                tw.insert("end", new)
                h["shown"] += len(new)
                self._fit(tw)
            if not m.get("live", False) and not h.get("done"):
                h["done"] = True
                tw.configure(state="disabled")
                h["spine"].config(bg=mix(C["accent"], C["bg"], .55))
                if m.get("secs") is not None:
                    h["meta"].config(text="%.1f seconds, %d tokens per second" % (m["secs"], m.get("tps", 0)))
                self._fill_footer(h, m)
            w = self._chat_w()
            if w is not None:
                w.to_bottom()
        except tk.TclError:
            pass

    def _fill_footer(self, h, m):
        foot = h["foot"]
        if m["text"].strip():
            Btn(foot, "Copy", lambda t=m["text"]: (self.root.clipboard_clear(), self.root.clipboard_append(t.strip()),
                                                   self.toast("Reply copied.")),
                kind="ghost", height=24, font=F["small"], padx=8).pack(side="left")
            Btn(foot, "Save as memory", lambda t=m["text"]: self._mem_from_reply(t),
                kind="ghost", height=24, font=F["small"], padx=8).pack(side="left", padx=(4, 0))
            fc = m.get("followup_card")
            tgt = self._mem_card_title(fc) if fc else None
            if tgt is not None:
                Btn(foot, "Add to \u201c%s\u201d" % tgt, lambda t=m["text"], f=fc: self._mem_add_to_card(f[0], f[1], t),
                    kind="ghost", height=24, font=F["small"], padx=8).pack(side="left", padx=(4, 0))
            if m.get("recalled"):
                tk.Label(foot, text="Recalled: " + ", ".join(m["recalled"]), bg=foot.cget("bg"), fg=C["accent"],
                         font=F["small"]).pack(side="left", padx=(12, 0))
    # ---- message store ------------------------------------------------------------------------
    def _add_msg(self, m):
        m.setdefault("text", "")
        if m.get("role") == "assistant":
            if self._turn_recall:                                   # the Recalled chip under the reply
                m["recalled"], self._turn_recall = self._turn_recall, []
            if self._turn_followup:                                 # the Add to card button under the reply
                m["followup_card"], self._turn_followup = self._turn_followup, None
        self.msgs.append(m)
        if self.ws != "chat" or getattr(self, "chat", None) is None or self._bg():
            return
        try:
            if self._split_on():
                ph = self._pane_ph.pop(self._ctx_tab().get("id"), None)
                if ph is not None:
                    ph.destroy()
                w = self._chat_w()
                self.render_message(m)
                w.to_bottom()
            elif len(self.msgs) == 1:
                self.render_center()
                if self.comp_text is not None:
                    self.comp_text.focus_set()
            else:
                self.render_message(m)
                self.chat.to_bottom()
        except tk.TclError:
            pass

    def _live_msg(self):
        for m in reversed(self.msgs):
            if m["role"] == "assistant" and m.get("live"):
                return m
        return None

    def _finish_live(self):
        for m in self.msgs:
            if m["role"] == "assistant" and m.get("live"):
                m["live"] = False
                now = time.time()
                m["t_ans"] = m.get("t_ans", now)
                m["secs"] = max(0.1, now - m["t0"])
                toks = 0
                if self._stream_usage and m is self._ap_cur:
                    toks = int(self._stream_usage.get("completion_tokens") or 0)
                if not toks:
                    toks = max(1, len((m["text"] + m.get("think", ""))) // 4)
                m["tps"] = int(toks / m["secs"])
                self._sync_message(m)

    # ---- Main's _append, turned into messages --------------------------------------------------
    def _ap_touch(self):
        if self._ap_timer is not None:
            try:
                self.root.after_cancel(self._ap_timer)
            except tk.TclError:
                pass
        self._ap_timer = self.root.after(1500, self._run_in, self._ctx_tab(), self._ap_idle)

    def _ap_idle(self):
        self._ap_timer = None
        if not self.awaiting_reply:
            self._finish_live()

    def _ap_close(self):
        self._ap_mode = None

    def _append(self, text, tag=None):
        """The rest of the app writes everything through here; the tag says what the text is."""
        try:
            if tag == "load_log":
                self._log_add(text)
                return
            if tag == "system_msg":
                self._ap_close()
                s = text.strip()
                if s:
                    self._add_msg({"role": "note", "text": s})
                    if self._fg():
                        self.toast(s.split("\n")[0][:160])
                return
            if tag == "who_user":
                self._finish_live()
                lab = text.strip()
                m = {"role": "user", "text": "", "label": "" if lab == "You" else lab}
                self._ap_cur, self._ap_mode = m, "user"
                self._add_msg(m)
                return
            if tag == "who_reasoning":
                lab = text.strip()
                m = {"role": "assistant", "text": "", "think": "", "label": "" if lab in ("Thinking", "Assistant") else lab.replace("Thinking", "").strip(" ()"),
                     "live": True, "t0": time.time()}
                if lab.startswith("Thinking (") and lab.endswith(")"):
                    m["label"] = "Assistant " + lab[len("Thinking "):]
                self._ap_cur, self._ap_mode = m, "think"
                self._add_msg(m)
                return
            if tag == "reasoning_text":
                m = self._ap_cur
                if m is None or self._ap_mode != "think":
                    m = {"role": "assistant", "text": "", "think": "", "label": "", "live": True, "t0": time.time()}
                    self._ap_cur, self._ap_mode = m, "think"
                    self._add_msg(m)
                m["think"] += text
                self._sync_message(m)
                self._ap_touch()
                return
            if tag == "who_assistant":
                lab = text.strip()
                if self._ap_mode == "think" and self._ap_cur is not None:
                    m = self._ap_cur
                else:
                    m = {"role": "assistant", "text": "", "think": "", "live": True, "t0": time.time()}
                    self._ap_cur = m
                    self._add_msg(m)
                if lab not in ("Assistant", ""):
                    m["label"] = lab
                m["t_ans"] = time.time()
                self._ap_mode = "answer"
                return
            # untagged text
            m = self._ap_cur
            if self._ap_mode in ("user", "answer") and m is not None:
                m["text"] += text
                self._sync_message(m)
                self._ap_touch()
            elif text.strip():
                self._add_msg({"role": "note", "text": text.strip()})
        except tk.TclError:
            pass

    # ------------------------------------------------------------------ inspector resize / lock
    def _insp_toggle_lock(self, lbl):
        self.insp_locked = not self.insp_locked
        APP_SETTINGS["insp_locked"] = self.insp_locked
        save_app_settings(APP_SETTINGS)
        try:
            lbl.config(text=("🔒" if self.insp_locked else "🔓"),
                       fg=C["accent"] if self.insp_locked else C["muted"])
        except tk.TclError:
            pass

    # ------------------------------------------------------------------ chat inspector
    def render_inspector(self):
        for w in self.insp_host.winfo_children():
            w.destroy()
        self.inspector_open = True                       # no way to close it any more
        show = self.ws not in NO_INSPECTOR
        if not show:
            self.insp_host.pack_forget()
            return
        if not self.insp_host.winfo_manager():
            self.insp_host.pack(side="right", fill="y", before=self.center)
        tk.Frame(self.insp_host, bg=C["line"], width=1).pack(side="left", fill="y")
        # ---- lock button ------------------------------------------------------------
        lock_col = tk.Frame(self.insp_host, bg=C["panel"], width=22)
        lock_col.pack(side="left", fill="y")
        lock_col.pack_propagate(False)
        lk = tk.Label(lock_col, text=("🔒" if self.insp_locked else "🔓"),
                      bg=C["panel"], fg=C["muted"], font=("Segoe UI Emoji", 9), cursor="hand2")
        lk.pack(anchor="n", pady=6)
        lk.bind("<Button-1>", lambda e: self._insp_toggle_lock(lk))
        self._insp_lock_lbl = lk
        sc = Scroller(self.insp_host, C["panel"], align="left")
        sc.pack(side="left", fill="both", expand=True)
        inner = tk.Frame(sc.inner, bg=C["panel"])
        inner.pack(fill="x", padx=20, pady=18)
        titles = {"chat": "Chat controls", "draw": "Drawing controls", "music": "Music controls",
                  "images": "Image controls", "blocks": "Block library",
                  "power": "Monitor controls", "simworld": "SimWorld controls"}
        tk.Label(inner, text=titles.get(self.ws, TITLES.get(self.ws, "Controls")), bg=C["panel"], fg=C["text"], font=F["h3"]).pack(anchor="w", pady=(0, 14))
        self._insp_wrap_labels = []
        self._insp_content_w = max(100, self.insp_width - 70)   # border+lock+scrollbar+padding
        getattr(self, "insp_" + self.ws)(inner)

    def _quick_folder_close(self):
        f = getattr(self, "_qf", None)
        self._qf = None
        try:
            if f is not None and f.winfo_exists():
                f.destroy()
        except tk.TclError:
            pass

    def _quick_folder_toggle(self):
        if getattr(self, "_qf", None) is not None:
            self._quick_folder_close()
        else:
            self._quick_folder_open()

    def _quick_folder_open(self, rebuild=False):
        """Quick launch as a phone-style folder: a card that pops out beside the left menu with the tiles inside.
        It closes on Esc, on the cross, or when you click anywhere outside it."""
        self._quick_folder_close()
        root = self.root
        f = tk.Frame(root, bg=C["panel"], highlightthickness=1, highlightbackground=C["line_hi"])
        self._qf = f
        pad = tk.Frame(f, bg=C["panel"])
        pad.pack(fill="both", expand=True, padx=16, pady=14)
        head = tk.Frame(pad, bg=C["panel"])
        head.pack(fill="x", pady=(0, 10))
        draw = tk.Canvas(head, width=22, height=22, bg=C["panel"], highlightthickness=0, bd=0)
        draw.pack(side="left", padx=(0, 8))
        draw_icon(draw, "play", 11, 11, 8, C["accent"], w=1.8)
        tk.Label(head, text="Quick launch", bg=C["panel"], fg=C["text"], font=F["title"]).pack(side="left")
        x = tk.Label(head, text="\u00d7", bg=C["panel"], fg=C["muted"], font=F["title"], cursor="hand2")
        x.pack(side="right")
        x.bind("<Button-1>", lambda _e=None: self._quick_folder_close())
        self._quick_ui(pad, tip=True)
        f.update_idletasks()
        try:
            b = self.rail_btns["quick"]
            top = b.winfo_rooty() - root.winfo_rooty()
            left = b.winfo_rootx() - root.winfo_rootx() + b.winfo_width() + 8
        except (AttributeError, KeyError, tk.TclError):
            top, left = 120, 90
        h = f.winfo_reqheight()
        top = max(8, min(top, root.winfo_height() - h - 12))
        f.place(x=left, y=top, width=310)
        f.lift()

        def outside(e):
            fr = getattr(self, "_qf", None)
            if fr is None:
                return
            try:
                if not str(e.widget).startswith(str(fr)):
                    b2 = self.rail_btns.get("quick")
                    if b2 is not None and e.widget is b2:
                        return                                   # the rail button toggles it itself
                    self._quick_folder_close()
            except tk.TclError:
                pass
        if not getattr(self, "_qf_bound", False):
            self._qf_bound = True
            root.bind("<Button-1>", outside, add="+")
            root.bind("<Escape>", lambda _e=None: self._quick_folder_close(), add="+")

    def _quick_var(self, qid):
        if not hasattr(self, "_quick_ctx_vars"):
            self._quick_ctx_vars = {}
        if qid not in self._quick_ctx_vars:
            self._quick_ctx_vars[qid] = tk.StringVar(value=str(APP_SETTINGS.get(self._quick_key(qid)) or DEFAULT_CTX))
        return self._quick_ctx_vars[qid]

    def _quick_ui(self, b, tip=False):
        """The Quick launch tiles, as compact cards for the side panel: click the name to swap the model,
        set the context, press Launch."""
        if tip:
            tk.Label(b, text="Set the context, then press Launch to connect to llama.cpp and load it. "
                             "Click a model name to swap it.", bg=C["panel"], fg=C["muted"], font=F["small"],
                     wraplength=270, justify="left").pack(anchor="w", pady=(0, 10))
        for ql in QUICK_LAUNCHES:
            qid = ql["id"]
            card = tk.Frame(b, bg=C["raised"], highlightthickness=1, highlightbackground=C["line"])
            card.pack(fill="x", pady=(0, 8))
            inner = tk.Frame(card, bg=C["raised"])
            inner.pack(fill="x", padx=10, pady=8)
            name = tk.Label(inner, text=self._quick_label(ql) + "  \u25be", bg=C["raised"], fg=C["text"], font=F["ui_b"],
                            anchor="w", cursor="hand2", wraplength=max(80, getattr(self, "_insp_content_w", 260) - 30), justify="left")
            name.pack(fill="x")
            name.bind("<Button-1>", lambda e, q=qid: self._quick_pick_menu(q, e))
            row = tk.Frame(inner, bg=C["raised"])
            row.pack(fill="x", pady=(6, 0))
            tk.Label(row, text="Context", bg=C["raised"], fg=C["muted"], font=F["small"]).pack(side="left", padx=(0, 6))
            e = tk.Entry(row, width=7, textvariable=self._quick_var(qid), font=F["ui"], bg=C["panel"], fg=C["text"],
                         insertbackground=C["accent"], relief="flat", highlightthickness=1,
                         highlightbackground=C["line"], highlightcolor=C["accent"], justify="right")
            e.pack(side="left")
            e.bind("<Return>", lambda _e=None, q=qid: (self._quick_folder_close(), self.quick_launch(q)))
            Btn(row, "Launch", lambda q=qid: (self._quick_folder_close(), self.quick_launch(q)), kind="soft", icon="play", height=28,
                font=F["small"]).pack(side="right")

    def _lbl(self, p, text, pady=(0, 5)):
        lbl = tk.Label(p, text=text, bg=C["panel"], fg=C["muted"], font=F["small"],
                       wraplength=max(80, self._insp_content_w), justify="left")
        lbl.pack(anchor="w", pady=pady)
        self._insp_wrap_labels.append(lbl)

    def _note(self, p, text, pady=(0, 10)):
        lbl = tk.Label(p, text=text, bg=C["panel"], fg=C["muted"], font=F["small"],
                       wraplength=max(80, self._insp_content_w), justify="left")
        lbl.pack(anchor="w", pady=pady)
        self._insp_wrap_labels.append(lbl)

    def _trow(self, p, label, value, cmd=None, hint=None):
        f = tk.Frame(p, bg=C["panel"])
        f.pack(fill="x", pady=(0, 12))
        top = tk.Frame(f, bg=C["panel"])
        top.pack(fill="x")
        lbl_w = max(60, self._insp_content_w - 46)   # reserve 46px for toggle + gap
        trow_lbl = tk.Label(top, text=label, bg=C["panel"], fg=C["text"], font=F["ui"],
                            wraplength=lbl_w, justify="left")
        trow_lbl.pack(side="left", fill="x", expand=True)
        self._insp_wrap_labels.append(trow_lbl)
        t = Toggle(top, value, cmd)
        t.pack(side="right")
        if hint:
            hint_lbl = tk.Label(f, text=hint, bg=C["panel"], fg=C["muted"], font=F["small"],
                                wraplength=max(80, self._insp_content_w), justify="left")
            hint_lbl.pack(anchor="w", pady=(3, 0))
            self._insp_wrap_labels.append(hint_lbl)
        return t

    def _srow(self, p, label, lo, hi, val, step, fmt, cmd=None):
        self._lbl(p, label)
        s = Slider(p, lo, hi, val, step, fmt, cmd)
        s.pack(fill="x", pady=(0, 10))
        return s

    def _selrow(self, p, label, options, val, cmd=None):
        self._lbl(p, label)
        s = Select(p, options, val, cmd)
        s.pack(fill="x", pady=(0, 12))
        return s

    def _entry(self, p, label, value, parent_bg=None, var=None):
        bg = parent_bg or C["panel"]
        if label:
            tk.Label(p, text=label, bg=bg, fg=C["muted"], font=F["small"]).pack(anchor="w", pady=(0, 5))
        e = tk.Entry(p, bg=C["raised"], fg=C["text"], insertbackground=C["accent"], relief="flat", bd=0,
                     highlightthickness=1, highlightbackground=C["line"], highlightcolor=C["accent"], font=F["ui"],
                     textvariable=var)
        if var is None:
            e.insert(0, value)
        e.pack(fill="x", ipady=6, pady=(0, 12))
        return e

    def _btns(self, p, *items):
        f = tk.Frame(p, bg=C["panel"])
        f.pack(fill="x", pady=(2, 10))
        for label, kind, cmd in items:
            Btn(f, label, cmd, kind=kind, height=30, font=F["small"]).pack(side="left", padx=(0, 6))

    def insp_chat(self, p):
        mv = self._ensure_models_viewer()
        rows = self.model_rows()
        cur = self.chat_row()
        s = Section(p, "Model")
        s.pack(fill="x", pady=(0, 14))
        b = s.body
        if not self.server_connected:
            self._note(b, "Not connected. Authenticate to list the models in %s." % self.local_models_root)
            self._btns(b, ("Authenticate", "primary", self.connect_server))
        else:
            names = [r["name"] for r in rows] or ["No models found"]
            self._selrow(b, "Active model", names, cur["name"] if cur else "None loaded", self._pick_model_name)
            if cur:
                bits = [x for x in (cur["params"] and cur["params"] + " parameters", cur["quant"], "%.1f GB on disk" % (cur["mb"] / 1000.0)) if x]
                self._note(b, ", ".join(bits))
            self._ctx_editor(b, mv, rows)
        self._trow(b, "Unload after each reply", bool(self.auto_unload_var.get()), lambda v: self._set_auto_unload(v),
                   "Frees VRAM, but the next message waits for a reload.")

        s = Section(p, "Connections", meta=("On" if self.http_bridge.running else "Off"))
        s.pack(fill="x", pady=(0, 6))
        b = s.body
        br = self.http_bridge
        self._trow(b, "HTTP API", br.running and not br.lan, self._set_api,
                   "Listens on %s:%s. No PIN needed on this machine." % (BRIDGE_HOST, BRIDGE_PORT))
        self._trow(b, "Phone app over Wi-Fi", br.running and br.lan, self._set_phone,
                   "Serves the phone page behind a six digit PIN.")
        self._btns(b, ("Show QR code", "soft", self._show_phone_qr))
        if br.running and br.lan:
            self._note(b, "PIN  %s" % br.token, (0, 2))
            self._note(b, "http://%s:%s" % (lan_ip(), BRIDGE_PORT), (0, 6))
        else:
            self._note(b, "The PIN shows here once Phone app over Wi-Fi is on.", (0, 6))

    # ---- inspector handlers (they drive the same variables the old menus did) -------------------
    def _pick_model_name(self, name):
        r = next((x for x in self.model_rows() if x["name"] == name), None)
        if r is not None:
            self._ctx_key = r["key"]
        if r is not None and not (r["loaded"] and r["key"] == self.server_model):
            self._pick_model(r["key"])

    def _ctx_editor(self, b, mv, rows):
        pick = getattr(self, "_ctx_key", None)
        keys = [x["key"] for x in rows]
        key = pick if pick in keys else (self.server_model if self.server_model in keys else (mv._sel_key if mv._sel_key in keys else None))
        r = next((x for x in rows if x["key"] == key), None) or (rows[0] if rows else None)
        if r is None:
            return
        if mv._sel_key != r["key"]:
            idx = self._viewer_index(r["key"])
            if idx is not None:
                mv._select_index(idx)
        auto = self.auto_max_context
        self._lbl(b, "Context length (tokens)")
        e = tk.Entry(b, bg=C["raised"], fg=C["text"] if not auto else C["faint"], insertbackground=C["accent"], relief="flat",
                     bd=0, highlightthickness=1, highlightbackground=C["line"], highlightcolor=C["accent"], font=F["ui"],
                     textvariable=mv.ctx_var, disabledbackground=C["raised"], disabledforeground=C["faint"])
        e.pack(fill="x", ipady=6, pady=(0, 6))
        if auto or mv._ctx_busy:
            e.config(state="disabled")
        e.bind("<Return>", lambda _e=None: mv._apply_ctx())
        self._note(b, "%s%s" % (r["name"], ("  (max %s)" % format(r["maxctx"], ",")) if r["maxctx"] else ""), (0, 6))
        label = "Apply and reload" if r["loaded"] else "Save"
        self._btns(b, (label, "soft", mv._apply_ctx))
        if auto:
            self._note(b, "Auto-max context is on, so every load uses the model's maximum.")

    def _set_auto_max(self, v):
        self.auto_max_ctx_var.set(bool(v))
        self._on_auto_max_ctx_toggle()
        self._refresh_inspector_soft()

    def _set_spill(self, v):
        self.ram_spill_var.set(bool(v))
        self._on_ram_spill_toggle()
        self._refresh_chrome()

    def _set_gpu_share(self, pct):
        """pct = GPU share of layers (0-100) or None for Auto. Persisted; used by the next load."""
        self.gpu_share_pct = pct
        if pct is None:
            APP_SETTINGS.pop("gpu_share_pct", None)
            save_app_settings(APP_SETTINGS)
        else:
            self._settings_store(gpu_share_pct=int(pct))

    def _split_ui(self, p, divider=True):
        """Layer split (GPU / RAM), shown on Settings > Context."""
        tk.Label(p, text="Layer split (GPU / RAM)", bg=C["bg"], fg=C["text"], font=F["ui_l"]).pack(anchor="w")
        tk.Label(p, text="How many of the model's layers go to video memory and how many stay in system RAM. "
                         "Applies to the next model load.", bg=C["bg"], fg=C["muted"], font=F["small"],
                 wraplength=620, justify="left").pack(anchor="w", pady=(2, 8))
        cur = self.gpu_share_pct
        gv = tk.StringVar(value="" if cur is None else str(cur))
        rv = tk.StringVar(value="" if cur is None else str(100 - cur))
        busy = [False]

        def mirror(src, dst):
            if busy[0]:
                return
            t = src.get().strip()
            busy[0] = True
            try:
                dst.set(str(100 - int(t)) if t.isdigit() and int(t) <= 100 else "")
            finally:
                busy[0] = False
        gv.trace_add("write", lambda *_: mirror(gv, rv))
        rv.trace_add("write", lambda *_: mirror(rv, gv))

        for name, var in (("GPU (VRAM) %", gv), ("RAM (CPU) %", rv)):
            row = tk.Frame(p, bg=C["bg"])
            row.pack(anchor="w", pady=(0, 6))
            tk.Label(row, text=name, bg=C["bg"], fg=C["text"], font=F["ui"], width=13, anchor="w").pack(side="left")
            e = tk.Entry(row, textvariable=var, bg=C["raised"], fg=C["text"], insertbackground=C["accent"],
                         relief="flat", bd=0, highlightthickness=1, highlightbackground=C["line"],
                         highlightcolor=C["accent"], font=F["ui"], justify="center", width=8)
            e.pack(side="left", ipady=7)
            e.bind("<Return>", lambda _e=None: apply())

        def apply():
            t = gv.get().strip()
            if not (t.isdigit() and 0 <= int(t) <= 100):
                self.toast("Enter a whole number from 0 to 100.")
                return
            self._set_gpu_share(int(t))
            self.toast("GPU %d%% / RAM %d%% - applies to the next model load." % (int(t), 100 - int(t)))
            self.render_center()

        def auto():
            self._set_gpu_share(None)
            self.toast("Split cleared - Auto.")
            self.render_center()
        brow = tk.Frame(p, bg=C["bg"])
        brow.pack(anchor="w", pady=(6, 6))
        Btn(brow, "Apply", apply, kind="primary", height=30, font=F["small"]).pack(side="left", padx=(0, 6))
        Btn(brow, "Auto", auto, kind="soft", height=30, font=F["small"]).pack(side="left")
        if cur is None:
            tk.Label(p, text="Auto: uses the spill rules above. Type a number in either box and the other fills in.",
                     bg=C["bg"], fg=C["muted"], font=F["small"], wraplength=620, justify="left").pack(anchor="w")
        if divider:
            tk.Frame(p, bg=C["line"], height=1).pack(fill="x", pady=(14, 14))

