    # ---- Artist mode: describe a scene in chat, Stable Diffusion draws it ----------------------------------
    def _artist_btn_text(self):
        return "Artist: on" if self.artist_on else "Artist: off"

    def _artist_btn_dot(self):
        return C["ok"] if self.artist_on else C["faint"]

    def _toggle_artist_btn(self):
        self.artist_on = not self.artist_on
        self._settings_store(artist_mode=self.artist_on)
        b = getattr(self, "artist_btn", None)
        try:
            if b is not None and b.winfo_exists():
                b.set(self._artist_btn_text(), self._artist_btn_dot())
        except tk.TclError:
            pass
        self.toast("Artist mode on: ask for a scene and the picture is drawn after the reply." if self.artist_on
                   else "Artist mode off.")

    def _artist_after_reply(self, reply):
        """Reply finished with Artist mode on: pull out the IMAGE PROMPT line (or fall back to the reply's own words)
        and hand it to Stable Diffusion through the same job machinery the Images page uses."""
        if not self.artist_on or self._mode_job is not None:
            return
        found = _ART_LINE.findall(reply or "")
        if found:
            prompt = found[-1].strip()
        else:
            return                                          # not a "show me" turn, so draw nothing
        if len(prompt) < 8:
            return
        prompt = prompt.rstrip(". ") + ", " + str(APP_SETTINGS.get("artist_style", ARTIST_STYLE))
        self.root.after(700, self._artist_generate, prompt)     # a beat later, so auto-unload can free VRAM first

    def _artist_generate(self, prompt):
        if self._mode_job is not None:
            return
        kind = "images"
        self.ws_state[kind]["prompt"] = prompt
        try:
            win = self._mode_win(kind)
        except Exception as exc:                                    # noqa: BLE001
            self._append(f"Images: couldn't open the tool ({exc}).\n\n", "system_msg")
            return
        job = {"kind": kind, "win": win, "text": prompt, "idle_n": 0, "status": "", "stopped": False,
               "prev": None, "artist": True}
        self._mode_job = job
        self.mode_busy = True
        self.stage.set_activity("thinking")
        self._mode_hook(kind, win)
        try:
            self._mode_start_images(job)
        except _ModeSetup as exc:
            self._mode_end(job, error=str(exc), show_window=True)
            return
        except Exception as exc:                                    # noqa: BLE001
            self._mode_end(job, error=f"{type(exc).__name__}: {exc}")
            return
        self.root.after(400, self._mode_poll, job)

