    def _set_api(self, v):
        br = self.http_bridge
        if bool(v) == (br.running and not br.lan):
            return
        if br.running and br.lan:                    # phone mode owns the port: switch it to plain API
            self._toggle_phone_app()
        if bool(v) != br.running:
            self._toggle_http_bridge()
        self._refresh_chips()
        self.render_inspector()

    def _set_phone(self, v):
        br = self.http_bridge
        if bool(v) == bool(br.running and br.lan):
            return
        self._toggle_phone_app()
        self._refresh_chips()
        self.render_inspector()



    # ==========================================================================================
    #  TOOL WORKSPACES. The tool windows (Drawing, Music, Images, Power Monitor) still do
    #  the work, kept hidden; these pages drive them and show what they produce.
    # ==========================================================================================
    def _tool_win(self, kind):
        return self._mode_win(kind)

    def _tool_win_if_any(self, kind):
        win = getattr(self, self._MODE_WIN_ATTR[kind], None)
        try:
            if win is not None and win.win.winfo_exists():
                return win
        except tk.TclError:
            pass
        return None

    def _canvas_size(self, big, mid, small):
        try:
            avail = self.root.winfo_height() - 300
        except tk.TclError:
            avail = 600
        return big if avail >= 500 else (mid if avail >= 400 else small)

    def _ws_status_label(self, parent, kind):
        lb = tk.Label(parent, text=self.ws_state[kind].get("status", ""), bg=C["bg"], fg=C["muted"], font=F["small"],
                      anchor="w", justify="left", wraplength=900)
        self.ws_state[kind]["status_lbl"] = lb
        return lb

    def _mode_line(self, text):
        job = self._mode_job
        kind = job["kind"] if job else self.mode_kind
        st = self.ws_state.get(kind)
        if st is None:
            return
        st["status"] = text
        lb = st.get("status_lbl")
        try:
            if lb is not None and lb.winfo_exists():
                lb.config(text=text, fg=C["accent"] if self.mode_busy else C["muted"])
        except tk.TclError:
            pass

    def _mode_line_clear(self):
        job = self._mode_job
        kind = job["kind"] if job else self.mode_kind
        st = self.ws_state.get(kind)
        if st is not None:
            st["status"] = ""
            lb = st.get("status_lbl")
            try:
                if lb is not None and lb.winfo_exists():
                    lb.config(text="")
            except tk.TclError:
                pass

    def _ws_refresh(self, kind):
        if self.ws == kind:
            try:
                self.render_center()
            except tk.TclError:
                pass

    def _hook_log(self, win, kind, attr):
        """Mirrors a tool window's log lines into this page."""
        if getattr(win, "_ws_log_hooked", False):
            return
        win._ws_log_hooked = True
        orig = getattr(win, attr)

        def logger(*a, **kw):
            orig(*a, **kw)
            text = a[0] if a else ""
            self.root.after(0, self._ws_log_add, kind, str(text))
        setattr(win, attr, logger)

    def _ws_log_add(self, kind, text):
        st = self.ws_state[kind]
        buf = st.setdefault("log", [])
        buf.append(text)
        del buf[:-300]
        tw = st.get("log_tw")
        try:
            if tw is not None and tw.winfo_exists():
                tw.config(state="normal")
                tw.insert("end", text + "\n")
                tw.config(state="disabled")
                tw.see("end")
        except tk.TclError:
            pass

    def _log_box(self, parent, kind, height=7):
        st = self.ws_state[kind]
        box = tk.Frame(parent, bg=C["code"], height=height * 17, highlightbackground=C["line"], highlightthickness=1)
        box.pack(side="bottom", fill="x", padx=28, pady=(0, 12))
        box.pack_propagate(False)
        tw = tk.Text(box, bg=C["code"], fg=C["muted"], font=F["mono"], relief="flat", bd=0, highlightthickness=0,
                     padx=12, pady=6, wrap="word", spacing1=1, state="disabled")
        tw.pack(fill="both", expand=True)
        tw.insert("1.0", "\n".join(st.get("log", [])))
        tw.config(state="disabled")
        tw.see("end")
        st["log_tw"] = tw

    # ---- mode job hooks (replace the old chat-log rendering) --------------------------------------
    def _mode_on_piece(self, kind, k, text):
        job = self._mode_job
        if not job or job["kind"] != kind:
            return
        st = self.ws_state[kind]
        if k == "reasoning":
            st["think"] = st.get("think", "") + text
            tw = st.get("think_lbl")
            try:
                if tw is not None and tw.winfo_exists():
                    tw.config(text=st["think"][-600:])
            except tk.TclError:
                pass
            return
        try:
            if kind == "draw":
                if job.get("renderer") is not None:
                    job["renderer"].feed(text)
                src = st.get("src_tw")
                if src is not None and src.winfo_exists():
                    src.config(state="normal")
                    src.insert("end", text)
                    src.config(state="disabled")
                    src.see("end")
            elif kind == "music" and job.get("roll") is not None:
                job["roll"].score = job["win"].score
                job["roll"].refresh()
        except tk.TclError:
            pass

    def _mode_start_draw(self, job):
        win = job["win"]
        job["prev"] = win.svg_text
        win.entry.delete(0, tk.END)
        win.entry.insert(0, job["text"])
        self.ws_state["draw"]["think"] = ""
        win._start()
        if not win.busy:                                            # no model loaded, etc. (status says why)
            return
        cv = self.ws_state["draw"].get("live_cv")
        w, h = self.ws_state["draw"].get("live_size", (520, 390))
        if cv is not None:
            cv.delete("all")
            job["canvas"] = cv
            job["renderer"] = _FixedSvgRenderer(cv, w, h)
        src = self.ws_state["draw"].get("src_tw")
        try:
            if src is not None and src.winfo_exists():
                src.config(state="normal")
                src.delete("1.0", "end")
                src.config(state="disabled")
        except tk.TclError:
            pass
        self._mode_line("Starting\u2026   (Esc to stop)")

    def _mode_start_music(self, job):
        win = job["win"]
        job["prev"] = len(win.messages)
        win.entry.delete(0, tk.END)
        win.entry.insert(0, job["text"])
        self.ws_state["music"]["think"] = ""
        win._start()
        if not win.busy:
            return
        cv = self.ws_state["music"].get("live_cv")
        w, h = self.ws_state["music"].get("live_size", (560, 220))
        if cv is not None:
            job["canvas"] = cv
            roll = _RollProxy(_FixedCanvas(cv, w, h))
            job["roll"] = roll
            roll.refresh()
        self._mode_line("Starting\u2026   (Esc to stop)")

    def _card_images(self, job, path):
        if path not in self._img_history:
            self._img_history.insert(0, path)
        self.ws_state["images"]["sel"] = path
        self._ws_refresh("images")
        if job.get("artist"):
            self._append("Picture drawn: %s\nIt's also on the Images page." % path, "system_msg")

    def _card_draw(self, job):
        self._ws_refresh("draw")

    def _card_music(self, job):
        self._ws_refresh("music")

    def _mode_buttons(self, specs):
        pass

    def _mode_embed(self, width, height, bg):
        return None

    # ---- Drawing ---------------------------------------------------------------------------------
    def _svg_to_text(self, tx, ln):
        pos = 0
        for mt in re.finditer(r'(</?\w+|/?>)|([\w-]+)(?==)|("[^"]*")', ln):
            tx.insert("end", ln[pos:mt.start()])
            tag = "tag" if mt.group(1) else ("attr" if mt.group(2) else "val")
            tx.insert("end", mt.group(0), tag)
            pos = mt.end()
        tx.insert("end", ln[pos:])

    def ws_draw(self, parent):
        st = self.ws_state["draw"]
        win = self._tool_win_if_any("draw")
        self._mode_hook("draw", self._tool_win("draw"))
        win = self._tool_win_if_any("draw")
        self._ws_status_label(parent, "draw").pack(side="bottom", fill="x", padx=28, pady=(0, 8))
        if win is not None and win.think_var.get():
            tl = tk.Label(parent, text=st.get("think", "")[-600:], bg=C["bg"], fg=C["muted"],
                          font=(F["ui"][0], 9, "italic"), anchor="w", justify="left", wraplength=900, height=2)
            tl.pack(side="bottom", fill="x", padx=28)
            st["think_lbl"] = tl
        split = tk.Frame(parent, bg=C["bg"])
        split.pack(fill="both", expand=True, padx=28, pady=(6, 10))
        src = tk.Frame(split, bg=C["code"], width=320, highlightbackground=C["line"], highlightthickness=1)
        src.pack(side="right", fill="y", padx=(16, 0))
        src.pack_propagate(False)
        hd = tk.Frame(src, bg=C["code"])
        hd.pack(fill="x", padx=14, pady=(12, 4))
        tk.Label(hd, text="Source", bg=C["code"], fg=C["text"], font=F["ui_b"]).pack(side="left")
        n = len(win.renderer.records) if (win is not None and getattr(win, "renderer", None) is not None) else 0
        tk.Label(hd, text="%d shapes" % n, bg=C["code"], fg=C["muted"], font=F["small"]).pack(side="right")
        tx = tk.Text(src, bg=C["code"], fg=C["muted"], font=F["mono"], relief="flat", bd=0, highlightthickness=0,
                     padx=14, pady=6, wrap="none", spacing1=3)
        tx.pack(fill="both", expand=True)
        tx.tag_configure("tag", foreground=C["accent"])
        tx.tag_configure("attr", foreground=C["seg"][1])
        tx.tag_configure("val", foreground=C["ok"])
        svg = (win.svg_text if win is not None else "") or ""
        for ln in svg.splitlines():
            self._svg_to_text(tx, ln)
            tx.insert("end", "\n")
        tx.configure(state="disabled")
        st["src_tw"] = tx
        area = tk.Frame(split, bg=C["bg"])
        area.pack(side="left", fill="both", expand=True)
        w, h = self._canvas_size((640, 480), (520, 390), (400, 300))
        cv = tk.Canvas(area, width=w, height=h, bg="#ffffff", highlightthickness=1, highlightbackground=C["line_hi"])
        cv.place(relx=0.5, rely=0.5, anchor="center")
        st["live_cv"], st["live_size"] = cv, (w, h)
        if svg.strip():
            try:
                _FixedSvgRenderer(cv, w, h).feed(svg)
            except Exception:                                           # noqa: BLE001
                pass
        elif not self.mode_busy:
            cv.create_text(w / 2, h / 2, text="Describe something to draw", fill="#9aa0a6", font=F["ui_l"])

    def insp_draw(self, p):
        win = self._tool_win("draw")
        self._trow(p, "Show thinking", bool(win.think_var.get()), lambda v: self._tool_thinking(win, v))
        self._note(p, "Typing again edits the current drawing. New drawing starts clean.")
        self._btns(p, ("New drawing", "soft", lambda: (self._mode_new("draw"), self.render_center())))

    def _tool_thinking(self, win, v):
        win.think_var.set(bool(v))
        win._toggle_thinking()
        self.render_center()

    # ---- Music -----------------------------------------------------------------------------------
    def ws_music(self, parent):
        st = self.ws_state["music"]
        self._mode_hook("music", self._tool_win("music"))
        win = self._tool_win_if_any("music")
        self._ws_status_label(parent, "music").pack(side="bottom", fill="x", padx=28, pady=(0, 8))
        if win is not None and win.think_var.get():
            tl = tk.Label(parent, text=st.get("think", "")[-600:], bg=C["bg"], fg=C["muted"],
                          font=(F["ui"][0], 9, "italic"), anchor="w", justify="left", wraplength=900, height=2)
            tl.pack(side="bottom", fill="x", padx=28)
            st["think_lbl"] = tl
        bar = tk.Frame(parent, bg=C["bg"])
        bar.pack(fill="x", padx=28, pady=(6, 10))
        Btn(bar, "Play / Stop", lambda: self._music_play(win), kind="primary", icon="play", height=32).pack(side="left")
        info = ""
        if win is not None and win.score and score_note_count(win.score):
            secs = score_end_beat(win.score) * 60.0 / win.score["tempo"]
            info = "%d notes, %.0fs at %.0f bpm" % (score_note_count(win.score), secs, win.score["tempo"])
        tk.Label(bar, text=info, bg=C["bg"], fg=C["muted"], font=F["ui"]).pack(side="right")
        area = tk.Frame(parent, bg=C["bg"])
        area.pack(fill="both", expand=True, padx=28, pady=(0, 10))
        w, h = self._canvas_size((820, 320), (680, 260), (560, 220))
        cv = tk.Canvas(area, width=w, height=h, bg="#1b1c1d", highlightthickness=1, highlightbackground=C["line_hi"])
        cv.place(relx=0.5, rely=0.5, anchor="center")
        st["live_cv"], st["live_size"] = cv, (w, h)
        if win is not None and win.score and score_note_count(win.score):
            roll = _RollProxy(_FixedCanvas(cv, w, h))
            roll.score = win.score
            roll.refresh()
            st["roll"] = roll
        elif not self.mode_busy:
            cv.create_text(w / 2, h / 2, text="Describe the music you want", fill="#9aa0a6", font=F["ui_l"])

    def _music_play(self, win):
        if win is None or not win.score or not score_note_count(win.score):
            self.toast("Nothing to play yet.")
            return
        win._toggle_play()

    def insp_music(self, p):
        win = self._tool_win("music")
        self._trow(p, "Show thinking", bool(win.think_var.get()), lambda v: self._tool_thinking(win, v))
        self._note(p, "Typing again edits the last result. New starts fresh.")
        self._btns(p, ("New", "soft", lambda: (self._mode_new("music"), self.render_center())))

    # ---- Images ----------------------------------------------------------------------------------
    def _thumb(self, path, box):
        try:
            img = tk.PhotoImage(file=path)
            f = max(1, math.ceil(max(img.width(), img.height()) / float(box)))
            return img.subsample(f) if f > 1 else img
        except tk.TclError:
            return None

    def ws_images(self, parent):
        st = self.ws_state["images"]
        win = self._tool_win("images")
        self._mode_hook("images", win)
        self._hook_log(win, "images", "_log")
        self._log_box(parent, "images", 6)
        self._ws_status_label(parent, "images").pack(side="bottom", fill="x", padx=28, pady=(0, 4))
        host = tk.Frame(parent, bg=C["bg"])
        host.pack(fill="both", expand=True, padx=28, pady=(8, 10))
        sel = st.get("sel") or win.last_path
        top = tk.Frame(host, bg=C["bg"])
        top.pack(anchor="w")
        main = tk.Canvas(top, width=420, height=420, bg=C["raised"], highlightthickness=1, highlightbackground=C["line"])
        main.pack(side="left")
        photo = self._thumb(sel, 410) if sel and os.path.isfile(sel) else None
        if photo is not None:
            self._mode_photos.append(photo)
            st["photo"] = photo
            main.create_image(210, 210, image=photo)
        else:
            main.create_text(210, 210, text="Describe an image to create", fill=C["muted"], font=F["ui_l"])
        info = tk.Frame(top, bg=C["bg"])
        info.pack(side="left", anchor="n", padx=(28, 0))
        if sel:
            tk.Label(info, text=os.path.basename(sel), bg=C["bg"], fg=C["text"], font=F["h3"], wraplength=380,
                     justify="left").pack(anchor="w", pady=(2, 10))
            for t in ("%sx%s, %s steps, CFG %s" % (win.w_var.get(), win.h_var.get(), win.steps_var.get(), win.cfg_var.get()),
                      "Sampler %s, seed %s" % (win.sampler_var.get(), win.seed_var.get())):
                tk.Label(info, text=t, bg=C["bg"], fg=C["muted"], font=F["ui"]).pack(anchor="w", pady=1)
        if self._img_history:
            tk.Label(host, text="Recent results", bg=C["bg"], fg=C["muted"], font=F["small"]).pack(anchor="w", pady=(18, 6))
            strip = tk.Frame(host, bg=C["bg"])
            strip.pack(anchor="w")
            for pth in self._img_history[:8]:
                th = self._thumb(pth, 92) if os.path.isfile(pth) else None
                if th is None:
                    continue
                self._mode_photos.append(th)
                cv = tk.Canvas(strip, width=96, height=96, bg=C["raised"], highlightthickness=2,
                               highlightbackground=C["accent"] if pth == sel else C["bg"], bd=0, cursor="hand2")
                cv.pack(side="left", padx=(0, 12))
                cv.create_image(48, 48, image=th)
                cv.bind("<Button-1>", lambda e=None, q=pth: (st.__setitem__("sel", q), self.render_center()))

    def insp_images(self, p):
        win = self._tool_win("images")
        sizes = list(SD_SIZES)
        self._selrow(p, "Width", sizes, win.w_var.get(), lambda v: win.w_var.set(v))
        self._selrow(p, "Height", sizes, win.h_var.get(), lambda v: win.h_var.set(v))
        self._srow(p, "Steps", 4, 60, self._num(win.steps_var.get(), 20), 1, "{:.0f}", lambda v: win.steps_var.set(str(int(v))))
        self._srow(p, "CFG scale", 1, 14, self._num(win.cfg_var.get(), 7.0), 0.5, "{:.1f}", lambda v: win.cfg_var.set("%.1f" % v))
        self._selrow(p, "Sampler", list(SD_SAMPLERS), win.sampler_var.get(), lambda v: win.sampler_var.set(v))
        self._entry(p, "Seed (-1 is random)", "", var=win.seed_var)
        self._entry(p, "Negative prompt", "", var=win.neg_var)
        s = Section(p, "Files", open_=False)
        s.pack(fill="x")
        self._entry(s.body, "sd.cpp executable", "", var=win.exe_var)
        self._entry(s.body, "Checkpoint", "", var=win.model_var)
        self._btns(s.body, ("Browse exe", "ghost", lambda: self._after_pick(win._pick_exe)),
                   ("Browse checkpoint", "ghost", lambda: self._after_pick(win._pick_model)))
        self._btns(s.body, ("Scan again", "soft", lambda: win._scan(overwrite=True)), ("Quick test", "ghost", win._quick_test))

    def _after_pick(self, fn):
        fn()
        self.render_inspector()

    @staticmethod
    def _num(s, default):
        try:
            return float(s)
        except (TypeError, ValueError):
            return default

    # ---- Blocks ----------------------------------------------------------------------------------
    def ws_blocks(self, parent):
        b = self._blocks
        code = tk.Frame(parent, bg=C["code"], height=236, highlightbackground=C["line"], highlightthickness=1)
        code.pack(side="bottom", fill="x", padx=28, pady=(0, 10))
        code.pack_propagate(False)
        hd = tk.Frame(code, bg=C["code"])
        hd.pack(fill="x", padx=14, pady=(8, 0))
        tk.Label(hd, text="app.py", bg=C["code"], fg=C["text"], font=F["ui_b"]).pack(side="left")
        self._blocks_status = tk.Label(hd, text=b.get("note", ""), bg=C["code"], fg=C["ok"], font=F["small"])
        self._blocks_status.pack(side="left", padx=8)
        for label, cmd in (("Run", self._blocks_run), ("Save", self._blocks_save), ("Copy", self._blocks_copy)):
            Btn(hd, label, cmd, kind="ghost", height=24, font=F["small"], padx=8).pack(side="right")
        tx = tk.Text(code, bg=C["code"], fg=C["text"], font=F["mono"], relief="flat", bd=0, highlightthickness=0,
                     padx=14, pady=4, wrap="none", spacing1=1)
        tx.pack(fill="both", expand=True)
        tx.tag_configure("kw", foreground=C["accent"])
        tx.tag_configure("str", foreground=C["ok"])
        for ln in (b["code"] or "# Describe an app below, or load a demo from the inspector.").splitlines():
            if not b["code"]:
                tx.insert("end", ln + "\n")
                continue
            pos = 0
            for mt in re.finditer(r'\b(import|def|as|from|class|return|if|else|for|in)\b|("[^"]*"|\'[^\']*\')', ln):
                tx.insert("end", ln[pos:mt.start()])
                tx.insert("end", mt.group(0), "kw" if mt.group(1) else "str")
                pos = mt.end()
            tx.insert("end", ln[pos:] + "\n")
        tx.configure(state="disabled")
        cv = canvas_view(parent, self.paint_graph)
        cv.pack(fill="both", expand=True, padx=28, pady=(6, 10))

    def _graph_layout(self, graph):
        blocks = {bl["id"]: bl for bl in graph.get("blocks", [])}
        depth = {i: 0 for i in blocks}
        for _ in range(len(blocks) + 1):
            for w in graph.get("wires", []):
                a, c = w.get("from_block"), w.get("to_block")
                if a in depth and c in depth and depth[c] < depth[a] + 1 and depth[a] + 1 <= len(blocks):
                    depth[c] = depth[a] + 1
        cols = {}
        for i in blocks:
            cols.setdefault(depth[i], []).append(i)
        return blocks, cols

    def paint_graph(self, cv, w, h):
        for gx in range(10, w, 26):
            for gy in range(10, h, 26):
                cv.create_oval(gx, gy, gx + 1.6, gy + 1.6, fill=C["line"], outline="")
        graph = self._blocks.get("graph")
        if not graph or not graph.get("blocks"):
            cv.create_text(w / 2, h / 2, text="Describe the app you want to build", fill=C["muted"], font=F["ui_l"])
            return
        blocks, cols = self._graph_layout(graph)
        ncol = max(cols) + 1
        nw, nh = 158, 50
        gap_x = max(30, (w - 40 - nw * ncol) / max(1, ncol - 1)) if ncol > 1 else 0
        pos = {}
        for c, ids in cols.items():
            gap_y = max(14, (h - 20 - nh * len(ids)) / (len(ids) + 1))
            for r, bid in enumerate(ids):
                x = 20 + c * (nw + gap_x)
                y = 10 + gap_y * (r + 1) + nh * r
                pos[bid] = (x, y)

        def port(bid, side, name):
            lib = LIB.get(blocks[bid]["type"], {})
            ports = list((lib.get("out" if side == "out" else "in") or {}).items())
            names = [n for n, _t in ports]
            idx = names.index(name) if name in names else 0
            x, y = pos[bid]
            n = max(1, len(names))
            py = y + 12 + (nh - 20) * (idx + 0.5) / n
            ptype = dict(ports).get(name, "text")
            return (x + (nw if side == "out" else 0), py, ptype)
        for wr in graph.get("wires", []):
            a, c = wr.get("from_block"), wr.get("to_block")
            if a not in pos or c not in pos:
                continue
            x1, y1, t = port(a, "out", wr.get("from_port"))
            x2, y2, _t = port(c, "in", wr.get("to_port"))
            mx = (x1 + x2) / 2
            cv.create_line(x1, y1, mx, y1, mx, y2, x2, y2, fill=C[BLOCK_PORT_COLORS.get(t, "seg1")], width=2, smooth=True)
        for bid, (x, y) in pos.items():
            bl = blocks[bid]
            rrect(cv, x, y, x + nw, y + nh, 10, fill=C["raised"], outline=C["line_hi"])
            cv.create_text(x + 12, y + 16, text=bl["type"], anchor="w", fill=C["text"], font=F["ui_b"])
            sets = bl.get("settings") or {}
            first = next((str(v) for v in sets.values() if str(v).strip()), bid)
            cv.create_text(x + 12, y + 35, text=first[:22], anchor="w", fill=C["muted"], font=F["small"])
            lib = LIB.get(bl["type"], {})
            for side in ("in", "out"):
                for name, ptype in (lib.get(side) or {}).items():
                    px, py, _t = port(bid, "out" if side == "out" else "in", name)
                    col = C[BLOCK_PORT_COLORS.get(ptype, "seg1")]
                    cv.create_oval(px - 5, py - 5, px + 5, py + 5, fill=col, outline=C["bg"], width=2)

    def _blocks_set(self, graph, note=""):
        self._blocks["graph"] = graph
        try:
            self._blocks["code"] = generate(graph)
        except Exception as exc:                                        # noqa: BLE001
            self._blocks["code"] = "# Fix the problems above to generate code.\n# (%s)\n" % exc
        self._blocks["note"] = note
        self._blocks["busy"] = False
        if self.ws == "blocks":
            self.render_center()

    def _send_blocks(self, text):
        b = self._blocks
        if b["busy"]:
            self.toast("Still building the last one.")
            return
        if not self.server_connected or not self.server_model:
            self.toast("Authenticate and load a model first (Memory), then press Build.")
            return
        b["busy"] = True
        self._composer_clear()
        b["note"] = "Building\u2026"
        try:
            self._blocks_status.config(text="Building\u2026", fg=C["accent"])
        except (tk.TclError, AttributeError):
            pass
        cfg = {"temperature": 0.2, "auto_test": bool(b.get("auto_test", True))}

        def work():
            try:
                res = ask_model(text, cfg)
            except Exception as exc:                                    # noqa: BLE001
                self.root.after(0, self._blocks_failed, str(exc))
                return
            self.root.after(0, self._blocks_done, res)
        threading.Thread(target=work, daemon=True).start()

    def _blocks_failed(self, msg):
        self._blocks["busy"] = False
        self._blocks["note"] = ""
        self.toast("Block Editor: " + msg)
        if self.ws == "blocks":
            self.render_center()

    def _blocks_done(self, res):
        errs = res.get("errors") or []
        test = res.get("test")
        if errs:
            note = "%d problem(s) after %d attempt(s): %s" % (len(errs), res.get("attempts", 1), errs[0][:80])
        elif test is not None:
            fails = test.get("failures") or []
            note = ("tested headless, %d failure(s)" % len(fails)) if fails else "generated, tested headless"
        else:
            note = "generated"
        self._blocks_set(res.get("graph") or {"blocks": [], "wires": []}, note)

    def _blocks_copy(self):
        if self._blocks["code"].strip():
            self.root.clipboard_clear()
            self.root.clipboard_append(self._blocks["code"])
            self.toast("Code copied.")

    def _blocks_save(self):
        code = self._blocks["code"]
        if not code.strip():
            return
        path = filedialog.asksaveasfilename(parent=self.root, title="Save app", defaultextension=".py",
                                            initialfile="app.py", filetypes=[("Python", "*.py"), ("All files", "*.*")])
        if path:
            with open(path, "w", encoding="utf-8") as f:
                f.write(code)
            self.toast("Saved " + path)

    def _blocks_run(self):
        code = self._blocks["code"]
        if not code.strip() or code.lstrip().startswith("# Fix"):
            self.toast("Nothing to run yet.")
            return
        path = os.path.join(tempfile.gettempdir(), f"block_app_{int(time.time())}.py")
        with open(path, "w", encoding="utf-8") as f:
            f.write(code)
        py = _be_python()
        if not py:
            self.toast("Python wasn't found on PATH, so the app can't run. Save the .py and run it yourself.")
            return
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        proc = subprocess.Popen([py, path], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, creationflags=flags)
        try:
            out, _ = proc.communicate(timeout=1.5)
            self.toast(("The app exited." if proc.returncode == 0 else "The app failed: " + (out or "")[-200:]))
        except subprocess.TimeoutExpired:
            self.toast("App is running in its own window.")

    def insp_blocks(self, p):
        self._trow(p, "Test run after building", bool(self._blocks.get("auto_test", True)),
                   lambda v: self._blocks.__setitem__("auto_test", bool(v)),
                   "Runs the generated app headless with simulated network and files.")
        be = self.block_editor
        self._note(p, "Browser editor: %s" % (be.url if be.running else "off"))
        self._btns(p, ("Open in browser", "soft", self._open_block_editor),
                   *((("Stop server", "ghost", self._stop_block_editor_ui),) if be.running else ()))
        self._btns(p, ("URL fetcher demo", "ghost", lambda: self._blocks_set(json.loads(json.dumps(DEMO)), "demo")),
                   ("Clock demo", "ghost", lambda: self._blocks_set(json.loads(json.dumps(CLOCK_DEMO)), "demo")))
        for title, cat in (("Interface", "ui"), ("Input and output", "io"), ("Logic", "logic")):
            names = [n for n, bl in LIB.items() if bl.get("cat") == cat]
            if not names:
                continue
            self._lbl(p, title, (6, 6))
            f = tk.Frame(p, bg=C["panel"])
            f.pack(fill="x", pady=(0, 8))
            fnt, rowf, used = tkfont.Font(font=F["small"]), None, 0
            for n in names:
                wd = fnt.measure(n) + 26
                if rowf is None or used + wd > 262:
                    rowf = tk.Frame(f, bg=C["panel"])
                    rowf.pack(anchor="w", pady=2)
                    used = 0
                Chip(rowf, n, command=lambda n=n: self._block_info(n), height=26).pack(side="left", padx=(0, 6))
                used += wd
        self._note(p, "Port colours: interface, flow, text. Click a block to see what it does.", (8, 0))

    def _block_info(self, name):
        bl = LIB[name]
        ins = ", ".join("%s (%s)" % kv for kv in bl["in"].items()) or "none"
        outs = ", ".join("%s (%s)" % kv for kv in bl["out"].items()) or "none"
        self.toast("%s: %s   In: %s   Out: %s" % (name, bl["desc"], ins, outs))

    def _stop_block_editor_ui(self):
        self._stop_block_editor()
        self.render_inspector()

    # ---- Power Monitor ---------------------------------------------------------------------------
    def _power_ensure(self):
        win = getattr(self, "_power_win", None)
        try:
            if win is not None and win.win.winfo_exists():
                return win
        except tk.TclError:
            pass
        if sys.platform != "win32":
            return None
        self._power_win = win = PowerMonitorWindow(self.root, self.t, self)
        win.win.withdraw()
        orig_handle, orig_append = win._handle, win._append

        def handle(when, b, gpu):
            orig_handle(when, b, gpu)
            self._power_sample(when, b, gpu)

        def append(text, tag=None):
            orig_append(text, tag)
            self._power_log(text)
        win._handle, win._append = handle, append
        win.win.protocol("WM_DELETE_WINDOW", lambda: None)
        return win

    def _power_running(self):
        win = getattr(self, "_power_win", None)
        try:
            return bool(win is not None and win.win.winfo_exists() and win.running)
        except tk.TclError:
            return False

    # Where the power goes. Windows only reports the BATTERY's rate (+ charging / - discharging) and
    # nvidia-smi reports the GPU, so:
    #   on battery:  system = battery discharge (measured);  rest of system = system - GPU (measured)
    #   on AC:       charger = system + battery charge. The charge rate and GPU are measured, but the
    #                rest of the system is not, so it is ESTIMATED from CPU % using a straight line
    #                learned from the user's own on-battery samples (saved in gguf_settings.json).
    def _pw_cal(self):
        pw = self.pw
        if pw.get("cal") is None:
            c = APP_SETTINGS.get("power_cal")
            ok = isinstance(c, dict) and all(isinstance(c.get(k), (int, float)) for k in ("n", "sx", "sy", "sxx", "sxy"))
            pw["cal"] = dict(c) if ok else {"n": 0, "sx": 0.0, "sy": 0.0, "sxx": 0.0, "sxy": 0.0}
        return pw["cal"]

    def _pw_cal_add(self, cpu, other):
        if cpu is None or other is None:
            return
        c = self._pw_cal()
        c["n"] += 1
        c["sx"] += cpu
        c["sy"] += other
        c["sxx"] += cpu * cpu
        c["sxy"] += cpu * other
        if c["n"] > 3000:                                   # keep it adaptive: halve the old weight
            for k in c:
                c[k] *= 0.5
        if int(c["n"]) % 25 == 0:
            APP_SETTINGS["power_cal"] = dict(c)
            save_app_settings(APP_SETTINGS)

    def _pw_cal_predict(self, cpu):
        c = self._pw_cal()
        if cpu is None or c["n"] < 10:
            return None
        n = float(c["n"])
        mx, my = c["sx"] / n, c["sy"] / n
        var = c["sxx"] / n - mx * mx
        if var < 4.0:                                       # CPU barely varied while calibrating: use the mean
            return max(my, 0.0)
        slope = max(0.0, min(1.5, (c["sxy"] / n - mx * my) / var))
        return max(my - slope * mx + slope * cpu, 0.0)

    def _power_sample(self, when, b, gpu):
        pw = self.pw
        win = self._power_win
        si = getattr(win, "sysinfo", None) or {}
        st = {"gpu": (("%.1f W" % gpu) if gpu is not None else ("off" if not win._poll_gpu else "---"))}
        st.update(_pm_sys_strings(si))
        gpu_w = gpu or 0.0
        cw = float(pw.get("charger_w", 170.0))
        if b is None:
            st.update({"source": "---", "charge": "---", "battery": "---", "system": "---", "left": "---",
                       "charger": "---", "split": "No battery data from Windows."})
        else:
            batt = b["watts"]                                   # + charging, - discharging
            chg = max(batt, 0.0)
            on_batt = (not b["ac"]) and b["state"] == "discharging"
            if on_batt:
                system = -batt
                other = max(system - gpu_w, 0.0)
                self._pw_cal_add(si.get("cpu"), other)
                est = False
            else:
                other = self._pw_cal_predict(si.get("cpu"))
                system = (other + gpu_w) if other is not None else None
                est = True
            runtime_h = (b["remaining_wh"] / system) if (on_batt and system and b["remaining_wh"]) else None
            st["source"] = "AC" if b["ac"] else "Battery"
            st["charge"] = ("%.0f %%" % b["percent"]) if b["percent"] is not None else "---"
            st["battery"] = ("%+.1f W" % batt) if b["state"] != "idle" else "0 W"
            st["system"] = ("%.1f W" % system) if on_batt else (("~%.1f W" % system) if system is not None else "---")
            st["left"] = ("%.1f h" % runtime_h) if runtime_h else "---"
            gtxt = ("GPU %.1f" % gpu) if gpu is not None else "GPU (not polled)"
            if on_batt:
                st["charger"] = "---"
                st["split"] = ("Drawing %.1f W from the battery  =  %s  +  rest of system %.1f   (measured)"
                               % (system, gtxt, other))
            elif b["ac"]:
                if system is not None:
                    total = system + batt
                    st["charger"] = "~%.1f / %.0f W" % (max(total, 0.0), cw)
                    st["split"] = ("Charger ~%.1f W  =  battery %+.1f  +  %s  +  rest of system ~%.1f (estimated from CPU load)"
                                   % (max(total, 0.0), batt, gtxt, other))
                else:
                    st["charger"] = ">= %.1f / %.0f W" % (chg + gpu_w, cw)
                    st["split"] = ("Charger >= %.1f W  =  battery charging %.1f  +  %s  +  rest of system (can't be measured on AC "
                                   "- run on battery for a minute so it can learn your laptop)" % (chg + gpu_w, chg, gtxt))
            else:
                st["charger"] = "---"
                st["split"] = ""
            pw["state"] = b["state"]
            pw["hist"].append((gpu_w, other, chg, est))
        del pw["hist"][:-120]
        pw["stat"] = st
        self._draw_power_chip()
        cv = pw.get("cv")
        try:
            for k, lb in pw.get("lbls", {}).items():
                if lb.winfo_exists():
                    lb.config(text=st.get(k, "---"))
            if getattr(self, "_pw_state", None) is not None and self._pw_state.winfo_exists():
                self._pw_state.config(text="Monitoring, %s" % pw.get("state", "") if self._power_running() else "Stopped")
            if cv is not None and cv.winfo_exists():
                cv.redraw()
        except tk.TclError:
            pass

    def _power_log(self, text):
        pw = self.pw
        pw["rows"].append(text)
        del pw["rows"][:-200]
        tw = pw.get("log")
        try:
            if tw is not None and tw.winfo_exists():
                tw.config(state="normal")
                tw.insert("end", text + "\n")
                if int(tw.index("end-1c").split(".")[0]) > 200:
                    tw.delete("1.0", "2.0")
                tw.config(state="disabled")
                tw.see("end")
        except tk.TclError:
            pass

    def _power_header(self, label):
        win = self._power_ensure()
        if win is None:
            self.toast("The Power Monitor needs Windows (PowerShell + battery WMI).")
            return
        if label == "Clear":
            win._clear_log()
            self.pw["sys"], self.pw["gpu"], self.pw["util"], self.pw["rows"], self.pw["hist"] = [], [], [], [], []
            self.render_center()
        else:
            win._toggle_run()
            self.render_center()

