    def _wall_style(self, name):
        self.wall.set_style(name)
        self.root.after(700, self._wall_refresh)

    def _wall_refresh(self):
        """Redraw the Wallpaper page once the video has had a moment to start (so a problem shows up there)."""
        if self.ws == "settings" and self.settings_tab == "Wallpaper":
            self.render_center()

    def _wall_video_style(self):
        """The video wallpaper the Choose / Use buttons act on: the selected one (Earth if none is)."""
        return self.wall.style if self.wall.is_video() else "Earth"

    def _wall_pick_video(self):
        st = self._wall_video_style()
        cur = self.wall.find_video(st)
        path = filedialog.askopenfilename(
            title="Choose a wallpaper video" if st != "Custom" else "Choose a wallpaper picture or video",
            initialdir=os.path.dirname(cur) if cur else _app_dir(),
            filetypes=([("Picture or video", "*.png *.jpg *.jpeg *.bmp *.webp *.tif *.tiff "
                                             "*.mp4 *.m4v *.mov *.avi *.mkv *.webm")] if st == "Custom"
                       else [("Video", "*.mp4 *.m4v *.mov *.avi *.mkv *.webm")]) + [("All files", "*.*")])
        if path:
            self.wall.set_video(path, st)
            self.wall.set_style(st)
            self.root.after(700, self._wall_refresh)
        self.render_center()

    def _wall_reset_video(self):
        self.wall.set_video("", self._wall_video_style())
        self.root.after(700, self._wall_refresh)
        self.render_center()

