    def set_colours(self, p):
        self._sec_title(p, "Colours", "Themes apply straight away. No restart needed.")
        row = tk.Frame(p, bg=C["bg"])
        row.pack(fill="x")
        cells = []
        for name in THEMES:
            cell = tk.Frame(row, bg=C["bg"])
            cells.append(cell)
            t = THEMES[name]
            on = name == self.theme_name
            cv = tk.Canvas(cell, width=208, height=136, bg=C["bg"], highlightthickness=0, bd=0, cursor="hand2")
            cv.pack()
            rrect(cv, 2, 2, 206, 134, 14, fill=t["bg"], outline=C["accent"] if on else C["line"], width=2 if on else 1)
            cv.create_rectangle(3, 14, 38, 122, fill=t["panel"], outline="")
            for i in range(4):
                rrect(cv, 11, 24 + i * 22, 30, 38 + i * 22, 4, fill=t["accent"] if i == 0 else t["line_hi"], outline="")
            rrect(cv, 130, 28, 196, 52, 10, fill=t["raised"], outline=t["line"])
            cv.create_line(52, 66, 180, 66, fill=t["muted"], width=3)
            cv.create_line(52, 80, 150, 80, fill=t["muted"], width=3)
            rrect(cv, 52, 100, 196, 122, 11, fill=t["raised"], outline=t["line"])
            cv.create_oval(180, 106, 192, 118, fill=t["accent"], outline="")
            for i, col in enumerate(t["seg"]):
                cv.create_rectangle(52 + i * 14, 42, 62 + i * 14, 48, fill=col, outline="")
            cv.bind("<Button-1>", lambda e=None, n=name: self.set_theme_name(n))
            tk.Label(cell, text=name + ("  (current)" if on else ""), bg=C["bg"], fg=C["text"] if on else C["muted"],
                     font=F["ui_b"] if on else F["ui"]).pack(anchor="w", pady=(6, 0))

        def flow(_e=None, state={"cols": 0}):
            """As many previews per line as fit; the rest wrap onto the next line."""
            cols = max(1, (row.winfo_width() + 18) // 226)
            if cols == state["cols"]:
                return
            state["cols"] = cols
            for i, c in enumerate(cells):
                c.grid(row=i // cols, column=i % cols, padx=(0, 18), pady=(0, 14), sticky="nw")
        row.bind("<Configure>", flow)
        flow()
        tk.Frame(p, bg=C["bg"], height=18).pack()
        r = self._srow_set(p, "Accent colour", "Replaces the theme's accent. Custom colours may be hard to read on some themes.")
        Btn(r, "Reset", self._reset_accent, kind="ghost", height=30).pack(side="right", padx=(6, 0))
        Btn(r, "Custom\u2026", self._pick_accent_custom, kind="soft", height=30).pack(side="right")
        r = self._srow_set(p, "Transparent window", "The whole window, text included, goes see-through. On Linux this "
                                                     "needs a compositing window manager.")
        Toggle(r, bool(self._theme_state.get("transparent")), self._set_transparent).pack()
        r = self._srow_set(p, "Transparency level", "How opaque the window is while transparency is on.")
        levels = ["90", "75", "60", "45", "30"]
        cur = str(int(self._theme_state.get("opacity", 60)))
        Segmented(r, levels, cur if cur in levels else "60", lambda v: self._set_opacity(int(v))).pack()

