def preset(name: str) -> dict:
    key = _slug_id(name)
    if key not in PRESETS:
        hint = _did_you_mean(key, list(PRESETS))
        raise ValueError(f"no built-in example called '{name}'{hint}. Available: {', '.join(PRESETS)}")
    d = copy.deepcopy(PRESETS[key])
    d.setdefault("format", PROFILE_FORMAT)
    d.setdefault("version", PROFILE_VERSION)
    return d


def default_profile() -> dict:
    """What a brand-new world is built from when nobody has filled the setup in (scripts, tests, --yes)."""
    return preset("starter_room")


def list_presets_text() -> str:
    return "\n".join(f"  {k:<14} {v}" for k, v in PRESET_BLURB.items())


# ####################################################################################################
##### SECTION: debug
# ####################################################################################################

"""Developer views.  Plain text renderers over world / character state / events.

`render_world` is the ADMIN view: it shows hidden truth and, for every fact the
world holds, whether the character has learned it - so you can see the knowledge gap
between the environment and the character.
"""

import json


BAR = "=" * 64


def _conf(x) -> str:
    return f"{x:.2f}"


BAND = {0: "fine", 1: "a little", 2: "quite", 3: "very"}


def _nm(cs) -> str:
    return (cs.identity.get("name") or "The character").strip()


def render_body(world, cs) -> str:
    nm = _nm(cs)
    L = [BAR, f"BODY  (ADMIN VIEW - {nm} only ever feels the band, never the number)", BAR,
         f"{'need':<9} {'true value':>10}  {'true band':<10} {nm + ' feels':<10}"]
    for n, val in world.body.items():
        felt = cs.needs.get(n, {}).get("band", 0)
        L.append(f"{n:<9} {val:>10.1f}  {BAND[world.band(n)]:<10} {BAND[felt]:<10}")
    rel = cs.extra.get("relief", {})
    L += ["", f"What {nm} has learned relieves each need: " + (", ".join(f"{k}: {', '.join(v)}" for k, v in rel.items()) or "nothing yet"),
          "Light sources now: " + (", ".join(f"{o.name} (+{o.emits[o.state]})" for o in world.objects.values()
                                              if o.emits.get(o.state)) or "none") + f"   total light {world.lighting()}",
          "Food supplies: " + (", ".join(f"{o.name} ({o.truth.get('count', 'endless')})" for o in world.objects.values()
                                         if o.use_handler == "food_store") or "none")]
    return "\n".join(L)


def render_world(world, cs) -> str:
    nm = _nm(cs)
    L = [BAR, f"WORLD STATE  (authoritative / ADMIN VIEW - {nm} cannot see all of this)", BAR,
         f"Sim time: {world.clock.now}   light level: {world.lighting()}   "
         f"{nm} is at: {world.actor_spot()} ({world.rooms[world.spots[world.actor_spot()].room].name})", ""]
    imp = [f"{r.id}: {'invented' if r.improvise.get('done') else 'PENDING (not yet visited)'}"
           for r in world.rooms.values() if r.improvise]
    if imp:
        L.append("Improvised rooms: " + "; ".join(imp))
    shown = {k: v for k, v in world.flags.items() if not k.startswith("rule:") and k not in ("packs", "patched")}
    L.append(f"Story flags: {shown or 'none'}   packs applied: {world.flags.get('packs', []) or 'none'}")
    L.append("Body (true): " + ", ".join(f"{n}={v:.0f}" for n, v in world.body.items()) + "   (see `body`)")
    L.append("")
    total = known = 0
    for o in world.objects.values():
        flags = ", ".join(f for f in [("HIDDEN" if o.hidden else ""), ("HELD" if o.location == "cs" else ""),
                                      (f"GENERATED by {o.truth.get('narrator')}" if o.truth.get("generated") else ""),
                                      (f"{len(o.rules)} rule(s)" if o.rules else "")] if f)
        L.append(f"{o.id:<16} {o.name:<11} location={o.location:<18} state={o.state:<14} inspections={o.inspections}"
                 + (f"  [{flags}]" if flags else ""))
        if o.truth:
            L.append(f"    TRUTH (admin only): {json.dumps(o.truth, ensure_ascii=False)}")
        for d in o.details:
            total += 1
            info = cs.perceived_keys.get(d.key)
            if info:
                known += 1
                status = f"{nm} knows" if info["completeness"] >= 0.99 else f"{nm} knows PARTLY ({info['completeness']:.1f})"
            else:
                status = f"NOT known to {nm}"
            cond = []
            if d.depth:
                cond.append(f"needs inspection #{d.depth}")
            if d.requires_state:
                cond.append(f"needs state={d.requires_state}")
            if d.min_light:
                cond.append(f"needs light>={d.min_light}")
            L.append(f"    - {d.key:<30} {status:<24} {('(' + ', '.join(cond) + ')') if cond else ''}")
    L += ["", f"Knowledge gap: {nm} has perceived {known} of {total} perceivable details the world holds.",
          "Scheduled world changes: " + (", ".join(f"{s['object']}->{s['to']} @ {s['at']}{' (done)' if s.get('done') else ''}"
                                                   for s in world.schedule) or "none")]
    return "\n".join(L)


def render_char(cs, char, raw: bool = False) -> str:
    if raw:
        return json.dumps(cs.to_dict(), indent=2, ensure_ascii=False)
    nm = _nm(cs)
    L = [BAR, f"{nm.upper()}'S INTERNAL STATE  (only what {nm} has perceived, learned or started with)", BAR,
         f"Identity:   {cs.identity.get('self_description')}",
         f"Location:   {cs.current_location.get('room_label')} / {cs.current_location.get('spot_label')}",
         f"Activity:   {cs.current_activity}",
         f"Holding:    {', '.join(char._name(i) for i in cs.inventory) or 'nothing'}",
         "Feels:      " + (", ".join(f"{BAND[v['band']]} {n}" for n, v in cs.needs.items() if v["band"]) or "fine"),
         "Relieved by: " + (", ".join(f"{k}: {', '.join(v)}" for k, v in cs.extra.get("relief", {}).items()) or "nothing learned yet"),
         "", "GOALS"]
    L += [f"  [{g['status']:<6}] {g['text']}" for g in cs.goals] or ["  (none)"]
    L += ["", "KNOWN PLACES:  " + (", ".join(p["label"] for p in cs.known_places.values()) or "none"),
          "KNOWN OBJECTS: " + (", ".join(f"{o['name']}{' (held)' if o.get('held') else ''}" for o in cs.known_objects.values()) or "none"),
          "KNOWN PEOPLE:  " + (", ".join(f"{p['label']} (identity={p['identity']}, familiarity={_conf(p['familiarity'])})"
                                        for p in cs.known_people.values()) or "none"),
          "RELATIONSHIPS: " + (json.dumps(cs.relationships) if cs.relationships else "none yet"), "",
          "BELIEFS"]
    L += [f"  ({_conf(b['confidence'])}) {b['text']}  [{b['source']}{', revised x' + str(b['revisions']) if b.get('revisions') else ''}]"
          for b in cs.beliefs] or ["  (none)"]
    L += ["", "UNCERTAINTIES"]
    L += [f"  [{u['status']:<8}] {u['question']}" + (f"  - {u['notes']}" if u["notes"] else "") for u in cs.uncertainties]
    L += ["", "MEMORIES  (effective confidence now, after time decay)"]
    for m in cs.memories:
        sup = f"  (superseded by {m['superseded_by']})" if m.get("superseded_by") else ""
        L.append(f"  {m['id']} @{short(m['time'])} conf={_conf(char.effective_confidence(m))} src={m['source']}"
                 f"{' INCOMPLETE' if m['incomplete'] else ''}{sup}\n      {m['text']}")
    L += ["", f"LATENT IMPRESSIONS (unplaced familiarity {nm} started with): " + json.dumps(cs.impressions)]
    return "\n".join(L)


def render_events(events, n: int = 15) -> str:
    rows = events.recent(n)
    return "\n".join([BAR, f"RECENT EVENTS (raw log, last {len(rows)} of {len(events.events)})", BAR]
                     + [e.describe() for e in rows])


def render_dashboard(rt) -> str:
    w, v, c = rt.world, rt.cs, rt.char
    L = [BAR, f"DEVELOPER DASHBOARD   sim time {w.clock.now}   light {w.lighting()}", BAR, "", "WORLD STATE (compact)"]
    for o in w.objects.values():
        L.append(f"  {o.id:<16} @ {o.location:<18} state={o.state}{'  [hidden]' if o.hidden else ''}")
    L += ["", f"{_nm(v).upper()} STATE (summary)",
          f"  at: {v.current_location.get('spot_label')}   activity: {v.current_activity}   "
          f"holding: {', '.join(c._name(i) for i in v.inventory) or 'nothing'}",
          "  body (true): " + ", ".join(f"{n}={x:.0f}" for n, x in w.body.items()) + "   feels: "
          + (", ".join(f"{BAND[b['band']]} {n}" for n, b in v.needs.items() if b["band"]) or "fine"), "", "RECENT EVENTS"]
    L += [f"  {e.describe()}" for e in rt.events.recent(8)]
    L += ["", "RECENT OBSERVATIONS (experiences)"]
    for o in v.recent_observations[-5:]:
        L.append(f"  {o['id']} @{short(o['time'])} {o['kind']:<8} light={o['light']}  new={len(o['new'])} upgraded={len(o['upgraded'])}"
                 f" memory={o['memory_formed'] or '-'}")
        for t in o["perceived"][:3]:
            L.append(f"      saw: {t}")
    L += ["", "MEMORIES (most recent 6)"]
    L += [f"  {m['id']} conf={_conf(c.effective_confidence(m))}{' INCOMPLETE' if m['incomplete'] else ''}: {m['text']}"
          for m in v.memories[-6:]]
    L += ["", "BELIEFS"] + [f"  ({_conf(b['confidence'])}) {b['text']}" for b in v.beliefs[-8:]]
    L += ["", "UNCERTAINTIES (open)"] + [f"  {u['question']}" for u in v.uncertainties if u["status"] == "open"]
    L += ["", "GOALS (active)"] + [f"  {g['text']}" for g in v.goals if g["status"] == "active"]
    L += ["", "RECENT STATE CHANGES"] + [f"  @{short(s['time'])} {s['field']}: {s['change']}" for s in v.state_changes[-8:]]
    return "\n".join(L)


def render_clock(world) -> str:
    L = [f"Sim time: {world.clock.now}   (+{world.clock.ticks} min since start)   light level: {world.lighting()}",
         f"Sky: {world.sky_state()}.  Daylight 0.95 / dusk 0.7 / night 0.35 in rooms with sky, each room's own ambient light otherwise, plus lit things in the room. Fine detail needs 0.5-0.85.",
         "Scheduled world changes:"]
    L += [f"  {x['at']}  {x['object']} -> {x['to']}  {'(done)' if x.get('done') else '(pending)'}" for x in world.schedule]
    return "\n".join(L)


def _bar(v: float, width: int = 10, invert: bool = False) -> str:
    n = int(round(max(0.0, min(100.0, v)) / 100 * width))
    return "[" + "#" * n + "." * (width - n) + "]"


def curiosity(cs) -> float:
    """Derived from what the character knows (never world truth): things not yet looked at closely + unanswered questions."""
    objs = list(cs.known_objects.values())
    unexplored = sum(1 for o in objs if o.get("inspections", 0) < 1) / max(1, len(objs))
    open_q = sum(1 for u in cs.uncertainties if u["status"] == "open")
    return round(100 * (0.6 * unexplored + 0.4 * min(1.0, open_q / 5)), 0)


ACTIVITY_KINDS = ("eat", "drink", "sleep", "read", "watch", "browse", "pastime", "look_out")
INNER_BARS = [("Mood", "mood"), ("Comfort", "comfort"), ("Orientation", "orientation"), ("Knowledge", "knowledge"),
              ("Routine", "routine")]


def _circular_spread(minutes_of_day: list) -> float:
    """Average distance (minutes) of a set of clock times from their own typical time, going round the 24h clock."""
    import math
    ang = [m / 1440 * 2 * math.pi for m in minutes_of_day]
    mid = math.atan2(sum(math.sin(a) for a in ang), sum(math.cos(a) for a in ang))
    diffs = [abs((a - mid + math.pi) % (2 * math.pi) - math.pi) / (2 * math.pi) * 1440 for a in ang]
    return sum(diffs) / len(diffs)


def inner_state(world, cs) -> dict:
    """Five 0-100 measures of how the character is doing, all worked out from things the program already tracks (higher = better).
    Admin view only: the character never sees these numbers."""
    now = world.clock.now
    body = [world.body[n] for n in ("hunger", "thirst", "fatigue", "boredom") if n in world.body]
    act = cs.extra.get("activity", [])

    def recent(kinds, mins):
        return [k for t, k in act if k in kinds and 0 <= minutes_between(t, now) <= mins]
    clamp = lambda x: int(round(max(0.0, min(100.0, x))))

    # MOOD: up after eating, resting, a film or a good read, something new; down when needs are neglected or nothing happens
    mood = 60 - 0.25 * sum(max(0, n - 35) for n in body)
    mood += min(32, 8 * len(recent(("eat", "drink", "sleep"), 240)))
    mood += min(18, 6 * len(recent(("read", "watch", "browse", "pastime", "look_out"), 240)))
    fresh = sum(1 for m in cs.memories[-40:] if m.get("source") != "diary" and not str(m.get("text", "")).startswith("The person asked")
                and 0 <= minutes_between(str(m.get("time")), now) <= 120)
    mood += min(8, 1.5 * fresh)
    if not recent(ACTIVITY_KINDS, 180) and world.body.get("boredom", 0) > 25:
        mood -= 8
    mood -= max(0, 60 - world.health) * 0.3

    # COMFORT: light, a window, daytime, some sound; worn down by long spells in the dark and by being worn out
    room = world.room_of_spot(world.actor_spot())
    here = [o for o in world.objects.values() if world.spots.get(world.spot_of(o)) and world.spots[world.spot_of(o)].room == room.id]
    light = world.lighting()
    comfort = 25 + min(1.0, light / 0.7) * 35
    comfort += 15 if any(o.use_handler == "window" for o in here) else 0
    comfort += 0 if (world.sky_state() == "night" and light < 0.5) else 15
    comfort += 10 if any(o.use_handler == "audio" and o.state == "on" for o in here) else 0
    comfort -= min(30, cs.extra.get("dim", 0) / 6)
    comfort -= max(0, world.body.get("fatigue", 0) - 70) * 0.3 + max(0, max(world.body.get("hunger", 0), world.body.get("thirst", 0)) - 70) * 0.15

    # ORIENTATION: knows where they are and roughly what the sky is doing
    sky = max((float(b.get("confidence", 0)) for b in cs.beliefs if "outside" in str(b.get("text", ""))), default=0.0)
    open_q = [u for u in cs.uncertainties if u.get("status") == "open"]
    orient = 30 * bool(cs.flags.get("has_looked")) + 10 * (not any(u.get("key") == "where_am_i" for u in open_q)) + 40 * sky \
        + 20 * (not any("outside now" in str(u.get("question")) for u in open_q))

    # KNOWLEDGE: how much of the world they have looked at closely
    things, seen = {}, {}
    for o in world.objects.values():
        if o.hidden:
            continue
        k = o.name if o.id.startswith("door_") else o.id          # a door is two objects; count it once
        things[k] = True
        seen[k] = seen.get(k, False) or o.inspections > 0
    know = 100 * sum(seen.values()) / max(1, len(things))

    # ROUTINE: do meals and sleep happen at about the same times each day?
    scores = []
    for kind in ("eat", "sleep"):
        mins = [parse(t).hour * 60 + parse(t).minute for t, k in act if k == kind][-6:]
        if len(mins) >= 3:
            scores.append(100 - min(100.0, _circular_spread(mins) / 3.6))
    routine = sum(scores) / len(scores) if scores else 50
    return {"mood": clamp(mood), "comfort": clamp(comfort), "orientation": clamp(orient), "knowledge": clamp(know),
            "routine": clamp(routine)}


def render_status(world, cs, compact: bool = False) -> str:
    rows = [("Health", world.health, False)] + [(n.capitalize(), world.body[n], True)
                                                 for n in ("hunger", "thirst", "fatigue", "boredom")] \
        + [("Curiosity", curiosity(cs), False)]
    inner = inner_state(world, cs)
    if compact:
        return "  ".join(f"{n[:4]} {_bar(v, 5)}{int(v):>3}" for n, v, _ in rows)
    L = [BAR, f"STATUS  (ADMIN VIEW - {_nm(cs)} only feels bands, never these numbers)", BAR]
    for n, v, need in rows:
        tag = "  (higher = worse)" if need else ""
        L.append(f"{n:<10} {_bar(v, 20)} {v:>5.0f}{tag}")
    L.append("Curiosity is derived from what the character knows: unexplored things + open questions.")
    L.append("")
    for label, key in INNER_BARS:
        L.append(f"{label:<12} {_bar(inner[key], 20)} {inner[key]:>4}")
    L.append("Inner state (higher = better): mood, comfort, orientation, knowledge of the world, regularity of routine.")
    return "\n".join(L)


# ####################################################################################################
##### SECTION: brain
# ####################################################################################################

"""BRAIN: the pluggable "voice and decision" layer.

A Brain never touches the world or the character's state.  It receives a BrainContext
(a read-only snapshot built from the character's state + the current observation) and
returns either text (`generate_response`) or a proposed action
(`decide_action`).  The runtime validates and executes whatever it proposes, so
a brain cannot cheat: it cannot see world truth and cannot mutate anything.

Swap `MockBrain` for `PromptBrain(your_llm_function)` to drive the character with a
local GGUF model - nothing else in the project changes.
"""

import re
from abc import ABC, abstractmethod
from dataclasses import dataclass, field, asdict
from typing import Callable, Optional



# --------------------------------------------------------------------------- context
@dataclass
class BrainContext:
    intent: str                              # look|arrive|inspect|take|drop|use|remember|talk|idle|wake|ambient|fail|decide
    time: str
    cs: dict                               # snapshot of the character's OWN state (never world truth)
    observation: Optional[dict] = None       # {"kind","subject_label","room_label","percepts":[...],"light"}
    learned: dict = field(default_factory=dict)   # {"new":[..],"upgraded":[..],"nothing_new":bool}
    recognitions: list = field(default_factory=list)
    evidence: list = field(default_factory=list)  # retrieved memories/beliefs/uncertainties for a question
    utterance: Optional[str] = None
    action_result: dict = field(default_factory=dict)
    notes: list = field(default_factory=list)

    def to_dict(self) -> dict:
        return asdict(self)

    # Intents voiced from a SHORT, strictly grounded prompt: only the facts of the thing in front of him.
    GROUNDED_INTENTS = ("inspect", "take", "drop", "use", "ambient", "idle", "body")
    NEED_ADJ = {"thirst": "thirsty", "hunger": "hungry", "fatigue": "tired", "boredom": "bored"}

    def who(self) -> str:
        return (self.cs.get("identity", {}).get("name") or "Me").strip()

    def persona(self) -> str:
        """'You are Ingrid, a caretaker (she/her), ...' - built from the character's own profile."""
        i = self.cs.get("identity", {})
        name = (i.get("name") or "a character").strip()
        role = (i.get("role") or "").strip()
        s = f"You are {name}" + (f", {role}" if role else "") + ", going about your life in the place described below. Never mention being simulated, a program, a game or a model."
        if i.get("voice"):
            s += f" Your manner: {i['voice']}."
        return s

    def _earlier_about(self, subject: str) -> list:
        """What he has already noted about THIS thing (and nothing else), from his own memories and beliefs."""
        head = (subject or "").lower().split()[-1:] or [""]
        if len(head[0]) < 3:
            return []
        v = self.cs
        pool = [m["text"] for m in v["recent_memories"]] + [b["text"] for b in v["beliefs"]]
        return [t for t in pool if head[0] in t.lower()][-3:]

    def _grounded_prompt(self) -> str:
        v, obs = self.cs, self.observation or {}
        loc = v["location"]
        spot = loc.get("spot_label") or ""
        subject = obs.get("subject_label") or ""
        percepts = [p["text"] for p in obs.get("percepts", []) if p.get("narrate", True)]
        fresh_t = set(self.learned.get("new", [])) | set(self.learned.get("upgraded", []))
        word = ["not at all", "a little", "quite", "very"]
        feel = "; ".join(f"{self.NEED_ADJ.get(n, n)}: {word[min(3, int(b))]}" for n, b in v.get("needs", {}).items() if int(b) >= 1)
        near = [o["name"] for o in v["known_objects"]
                if o.get("held") or (o.get("room") in (None, loc.get("room")) and spot and o.get("place_label") == spot)]
        facts = [f"{loc.get('room_label', '')} {spot}"]
        lines = [
            self.persona() + " Answer in the first person, in ONE or TWO short sentences, in character.",
            "STRICT RULES: mention ONLY things that appear in the lists below. Add no objects, sounds, people, places or history that are not listed.",
            "Do not mention a clock, ticking, or anything else not listed. Do not announce plans. Never write numbers in brackets.",
            "Vary your wording. Do not start with \"I've just\" or \"I've discovered\".",
            "",
            f"Where I am: {loc.get('room_label', 'unsure')}" + (f", at {spot}" if spot else ""),
        ]
        if self.intent == "inspect":
            fresh = [t for t in percepts if t in fresh_t]
            known = [t for t in percepts if t not in fresh_t]
            lines.append(f"I am looking closely at: the {subject}")
            if fresh:
                lines += ["NEW to me just now:"] + [f"- {t}" for t in fresh]
            if known:
                lines += ["Already known to me (not new):"] + [f"- {t}" for t in known]
            if not fresh:
                lines.append("NOTHING here is new to me; I have examined this before. Say briefly, in your own words, that it looks as I "
                             "remembered or that I notice nothing more. Do NOT say I discovered or noticed it just now.")
            elif known:
                lines.append("Only the NEW things are fresh to me. Treat the rest as already known.")
            earlier = self._earlier_about(subject)
            if earlier:
                lines += ["What I noted about it before:"] + [f"- {t}" for t in earlier]
            sh = (subject.lower().split() or [""])[-1]
            looks = sum(n for k, n in v.get("attempts", {}).items()
                        if k.startswith("inspect:") and sh and sh in k.lower())
            self._first_look = looks <= 1                 # this very look is the first one
            if self._first_look:
                lines.append("This is my FIRST close look at it: do not say I examined it before or that I recall it.")
            facts += percepts + earlier + [subject]
        elif self.intent in ("take", "drop"):
            lines.append(f"I just {'picked up' if self.intent == 'take' else 'put down'}: the {subject}")
            lines += ["What I perceived:"] + [f"- {t}" for t in percepts]
            lines.append("Holding: " + (", ".join(v["inventory"]) or "nothing"))
            facts += percepts + [subject] + v["inventory"]
        elif self.intent == "use":
            lines.append(f"I just used: the {subject}")
            lines += ["What happened:"] + [f"- {t}" for t in percepts]
            if self.learned.get("nothing_new") and percepts:
                lines.append("I have done this before, so none of it is new to me.")
            facts += percepts + [subject]
        elif self.intent == "ambient":
            lines += ["Something changed around me:"] + [f"- {t}" for t in percepts]
            facts += percepts
        elif self.intent == "body":
            lines += ["How my body feels:"] + [f"- {t}" for t in percepts]
            facts += percepts
        else:   # idle: a wait is voiced from what he can perceive and feel, never from his whole history
            mins = self.action_result.get("waited", 0)
            lines.append(f"I have just waited about {mins} minutes, doing nothing in particular.")
            out = [b["text"] for b in v["beliefs"] if "outside" in b["text"].lower()][-1:]
            if out:
                lines.append("What I believe about outside: " + out[0])
                facts.append(out[0])
            lines.append("Things within reach or in my hands: " + (", ".join(near) or "nothing in particular"))
            facts += near
            if feel:
                lines.append("How I feel: " + feel)
            qs = v["open_uncertainties"]
            if qs:
                q = qs[sum(ord(c) for c in self.time) % len(qs)]["question"]
                lines.append("Something on my mind: " + q)
                facts.append(q)
        self._facts = " ".join(facts).lower()
        lines += ["", f"Intent: {self.intent}.  {self.who()}:"]
        return "\n".join(lines)

    def to_prompt(self) -> str:
        """Render the context as a prompt for a text-completion LLM."""
        if self.intent in self.GROUNDED_INTENTS:
            return self._grounded_prompt()
        v = self.cs
        lines = [
            self.persona(),
            "Answer in the first person, in ONE or TWO short sentences, in character.",
            "Say only what you just perceived or feel. Do NOT announce plans or next steps. Do NOT mention any object,",
            "tool, person or event that is not listed below. Never write numbers in brackets.",
            "RULES: use ONLY the facts listed below. If something is not listed, say you don't know,",
            "don't remember, or aren't certain. NEVER invent details to seem knowledgeable.",
            "Match your confidence to the confidence values given.",
            "",
            f"Time: {self.time}",
            f"Who I am: {v['identity'].get('self_description', '')}",
            f"Where I am: {v['location'].get('room_label', 'unsure')} - {v['location'].get('spot_label', '')}",
            f"What I'm doing: {v['activity']}",
            f"Holding: {', '.join(v['inventory']) or 'nothing'}",
            "Goals: " + "; ".join(v["goals"]),
            "Open questions I can't answer: " + "; ".join(u["question"] for u in v["open_uncertainties"]),
            "Beliefs: " + "; ".join(f"{b['text']} ({b['confidence']})" for b in v["beliefs"]),
            "Recent memories: " + " | ".join(f"{m['text']} ({m['confidence']})" for m in v["recent_memories"]),
        ]
        if self.intent == "talk":
            word = ["not at all", "a little", "quite", "very"]
            feel = [f"{n}: {word[min(3, int(b))]}" for n, b in v.get("needs", {}).items()]
            if feel:
                lines.append("How I feel right now (hunger/thirst/fatigue/boredom): " + "; ".join(feel))
            tally = v.get("tally") or []
            if tally:
                lines.append(f"What I have done since {v.get('since', 'I woke here')}, most often first (counts are exact): "
                             + "; ".join(f"{a} x{c}" for a, c in tally))
            lines.append("If asked how I feel about my routine, base it on these feelings and counts, honestly, in my own words.")
        if self.observation:
            lines += ["", f"JUST NOW ({self.observation['kind']}), I perceived:"]
            lines += [f"- {p['text']}" for p in self.observation["percepts"]]
        if self.recognitions:
            lines += ["Recognition: " + "; ".join(f"{r['label']}: {r['status']} (familiarity {r['familiarity']})"
                                                   for r in self.recognitions)]
        if self.evidence:
            lines += ["", "Relevant to the question (from my memory/beliefs):"]
            lines += [f"- [{e['kind']}, confidence {e.get('confidence')}] {e['text']}" for e in self.evidence]
        if self.action_result:
            lines += ["", f"Result of my action: {self.action_result}"]
        if self.utterance:
            lines += ["", f'The person says: "{self.utterance}"']
        lines += ["", f"Intent: {self.intent}.  {self.who()}:"]
        self._facts = "\n".join(lines).lower()
        return "\n".join(lines)


# --------------------------------------------------------------------------- interface
class CharacterBrain(ABC):
    """Anything that can voice the character and propose their next action."""

    @abstractmethod
    def generate_response(self, context: BrainContext) -> str: ...

    def decide_action(self, context: BrainContext) -> Optional[dict]:
        """Return {"cmd": "inspect", "arg": "desk"} or None to do nothing."""
        return None

    def write_diary(self, facts: list, day: str) -> str:
        """Condense one simulated day (a list of short first-person facts from HIS OWN memory) into a diary entry."""
        if not facts:
            return "A quiet day. Nothing worth writing down."
        return " ".join(f if f[-1:] in ".!?" else f + "." for f in facts[:7])


# --------------------------------------------------------------------------- helpers
def _lower_first(s: str) -> str:
    return s[:1].lower() + s[1:] if s and not s.startswith("I ") else s


def _strip_remember(text: str) -> str:
    return re.sub(r"^I remember\s+", "", text)


def _hedge(conf: float) -> str:
    if conf >= 0.75:
        return ""
    if conf >= 0.5:
        return "I think "
    return "It's vague, but maybe "


def nice_list(names: list) -> str:
    items = [f"the {n}" for n in names]
    return items[0] if len(items) == 1 else ", ".join(items[:-1]) + " and " + items[-1]


def narrate(percepts: list) -> str:
    """Join percept texts into prose.  Percepts with `attach_to` become ', and ...' clauses."""
    keys = {p["key"] for p in percepts}
    attached: dict = {}
    for p in percepts:
        if p.get("attach_to") in keys:
            attached.setdefault(p["attach_to"], []).append(p)
    out = []
    for p in percepts:
        if p.get("attach_to") in keys:
            continue
        s = p["text"].strip()
        s = s[:1].upper() + s[1:]
        for a in attached.get(p["key"], []):
            s = s.rstrip(".") + ", and " + a["text"].strip().rstrip(".")
        out.append(s if s.endswith((".", "!", "?", ".'", "!'", "?'")) else s + ".")
    return " ".join(out)


def recognition_sentence(recs: list) -> str:
    unknown = [r for r in recs if r["status"] == "unknown"]
    familiar = [r for r in recs if r["status"] == "familiar"]
    known = [r for r in recs if r["status"] == "known"]
    parts = []
    if unknown:
        parts.append("I don't recognize " + " or ".join(r["label"] for r in unknown))
    if familiar:
        f = familiar[0]
        tail = "looks strangely familiar" + (f", though I can't place {f['pronoun']}" if unknown else "")
        txt = f"{f['label']} {tail}"
        parts.append(("... but " + txt) if unknown else (txt[:1].upper() + txt[1:] + ", but I can't place " + f["pronoun"]))
    if known:
        parts.append(" ".join(f"That's {r['identity']}" for r in known))
    if not parts:
        return ""
    s = parts[0] if len(parts) == 1 else parts[0] + parts[1]
    if len(parts) > 2:
        s += ". " + parts[2]
    return s.rstrip(".") + "."


# --------------------------------------------------------------------------- mock brain
class MockBrain(CharacterBrain):
    """Deterministic, template-based.  Every sentence is composed from the
    context it is given (percepts, recognitions, evidence, confidences) - there
    is no scripted conversation - but there is no learning or language model."""

    FAIL = {
        "unknown_object": "I'm not sure what you mean by '{term}'. I don't see anything like that.",
        "unknown_place": "I don't know of a place like '{term}'.",
        "not_portable": "I can't carry that.",
        "must_hold": "I'd need to be holding it to do that.",
        "already_held": "I'm already holding it.",
        "not_held": "I'm not holding that.",
        "no_path": "I can't see a way to get there.",
        "already_there": "I'm already there.",
        "no_term": "Which one do you mean?",
        "unknown_command": "I'm not sure what you want me to do. (Try `help` for commands.)",
        "not_needed": "I don't need that right now.",
        "empty": "There's nothing left.",
        "dont_know_where": "I don't know where I could do that here.",
        "no_screen_here": "I'd have to be at the screen to watch that.",
        "nothing_more": "I've already done all I can with the {term}.",
    }
    NEED_ADJ = {"thirst": "thirsty", "hunger": "hungry", "fatigue": "tired", "boredom": "bored"}
    BAND_WORD = {1: "a little", 2: "quite", 3: "very"}
    # What a sensible person would try for each need before having learned anything: this is the
    # stand-in for an LLM's common sense.  It only ever names things the character already KNOWS about.
    # (what a thing LOOKS like it is for comes from the object's `hint`, seen when the character first looked at it)
    NEED_PRIORITY = ["thirst", "hunger", "fatigue", "boredom"]

    # ---- responses ------------------------------------------------------
    def generate_response(self, ctx: BrainContext) -> str:
        fn = getattr(self, f"_on_{ctx.intent}", None)
        return fn(ctx) if fn else "..."

    def _percepts(self, ctx, only_new=False) -> list:
        ps = [p for p in (ctx.observation or {}).get("percepts", []) if p.get("narrate", True)]
        if only_new:
            fresh = set(ctx.learned.get("new_keys", [])) | set(ctx.learned.get("upgraded_keys", []))
            ps = [p for p in ps if p["key"] in fresh]
        return ps

    def _on_look(self, ctx):
        return " ".join(x for x in [narrate(self._percepts(ctx)), recognition_sentence(ctx.recognitions)] if x)

    def _on_arrive(self, ctx):
        lead = f"I head over to {ctx.action_result.get('moved_to', 'there')}." if ctx.action_result.get("moved_to") else ""
        body = narrate(self._percepts(ctx)) or "Nothing new catches my eye."
        return f"{lead} {body}".strip()

    def _on_inspect(self, ctx):
        ps = self._percepts(ctx, only_new=True)
        if not ps:
            return "I don't notice anything more than I already had."
        text = narrate(ps)
        if ctx.learned.get("upgraded"):
            text += " I can make that out better than before."
        return " ".join(x for x in [text, recognition_sentence(ctx.recognitions)] if x)

    def _on_take(self, ctx):
        ps = self._percepts(ctx)
        extra = ps[0]["text"].split(". ", 1)[1] if ps and ". " in ps[0]["text"] else ""
        return ("I've got it. " + extra).strip()

    def _on_drop(self, ctx):
        return "I've set it down."

    def _on_use(self, ctx):
        ps = self._percepts(ctx, only_new=True) or self._percepts(ctx)
        text = narrate(ps) if ps else "Nothing seems to happen."
        if ctx.learned.get("nothing_new") and ps and ctx.action_result.get("ok"):
            text = "Nothing changes. " + text
        if ctx.learned.get("upgraded"):
            text += " I can make that out better than before."
        return text + (" " + recognition_sentence(ctx.recognitions) if ctx.recognitions else "")

    def _on_ambient(self, ctx):
        return narrate(self._percepts(ctx)) or "Something has changed, but I can't tell what."

    def _on_fail(self, ctx):
        tpl = self.FAIL.get(ctx.action_result.get("reason", ""), "I can't do that.")
        return tpl.format(term=ctx.action_result.get("term", ""))

    def _on_remember(self, ctx):
        if not ctx.evidence:
            return "I don't remember anything about that." if ctx.utterance else "I don't remember anything yet."
        lines = []
        for e in ctx.evidence:
            if e.get("faded"):
                lines.append("There's something there, but I can't recall it clearly.")
            else:
                lines.append(_hedge(e["confidence"]) + e["text"])
        return lines[0] if len(lines) == 1 else "\n".join(f"- {l}" for l in lines)

    def _on_body(self, ctx):
        return narrate(self._percepts(ctx)) or "Something doesn't feel quite right."

    def _feelings(self, needs: dict) -> str:
        parts = [f"{self.BAND_WORD[b]} {self.NEED_ADJ[n]}" for n, b in needs.items() if b >= 1]
        if not parts:
            return ""
        return parts[0] if len(parts) == 1 else ", ".join(parts[:-1]) + " and " + parts[-1]

    def _on_report(self, ctx):
        r = ctx.action_result.get("report") or {}
        acts = r.get("acts") or []
        if not acts:
            return "I haven't really done anything since then."

        def times(c):
            return "" if c == 1 else " twice" if c == 2 else f" {c} times"
        bits = [f"{a}{times(c)}" for a, c in acts]
        said = bits[0] if len(bits) == 1 else ", ".join(bits[:-1]) + " and " + bits[-1]
        out = [f"Since you left me to it, I {said}."]
        if r.get("learned"):
            out.append(f"I got to know {r['learned']} new thing{'s' if r['learned'] != 1 else ''} around me.")
        hl = [h.rstrip(".") for h in r.get("highlights", [])]
        if hl:
            out.append("What stands out: " + ". ".join(hl) + ".")
        feel = self._feelings(r.get("needs", {}))
        out.append(f"Right now I feel {feel}." if feel else "Right now I feel fine.")
        return " ".join(out)

    IDLE_LINES = ["Time passes. I keep coming back to one thing: {q} I still don't know.",
                  "I let my mind drift. {q} I can't answer it yet.",
                  "Time passes. Nothing seems to change.",
                  "I wait, turning a question over: {q}",
                  "Another quiet stretch. Nothing stirs."]

    def _on_idle(self, ctx):
        qs = ctx.cs["open_uncertainties"]
        if ctx.action_result.get("waited", 0) and qs:
            k = sum(ord(c) for c in ctx.time)             # vary the line without randomness
            q = qs[k % len(qs)]["question"]
            return self.IDLE_LINES[k % len(self.IDLE_LINES)].format(q=q)
        return "Time passes. Nothing seems to change."

    def _on_wake(self, ctx):
        v = ctx.cs
        loc = v["location"].get("room_label")
        parts = ["I'm here again." + (f" I was in {loc}." if loc and v["location"].get("spot") else "")]
        if ctx.notes:
            parts += ctx.notes
        else:
            parts.append(f"I'm holding {nice_list(v['inventory'])}." if v["inventory"] else "My hands are empty.")
        return " ".join(parts)

    def _on_talk(self, ctx):
        u = (ctx.utterance or "").lower().strip().rstrip("?!. ")
        v = ctx.cs
        if re.fullmatch(r"(hello|hi|hey|greetings)( there)?( " + re.escape(ctx.who().lower()) + ")?", u):
            return "I'm here. What do you need?"
        if re.search(r"\bwho are you\b|\byour name\b", u):
            return v["identity"].get("self_description") or f"I'm {ctx.who()}."
        if re.search(r"\bhow did you (get|come|end up)\b|\bhow are you here\b|\bwhy are you here\b", u):
            if any(q["question"].startswith("How did I get here") for q in v["open_uncertainties"]):
                return "I don't remember how I got here."
        if re.search(r"\bwhere (are|am) (you|i)\b|\bwhere is this\b", u):
            loc = v["location"]
            if loc.get("room"):
                return f"I'm in {loc['room_label']}, at {loc.get('spot_label')}."
            return "I'm not sure yet. I haven't really looked around."
        if re.search(r"\b(holding|carrying|have you got|in your hands?|inventory)\b", u):
            return f"I'm holding {nice_list(v['inventory'])}." if v["inventory"] else "My hands are empty."
        if re.search(r"\bhow (are|do) you( feel| feeling)?\b|\bare you (ok|okay|alright|tired|hungry|thirsty|bored)\b|"
                     r"\bdo you (need|want) (anything|something)\b|\bhow('s| is) (your|the) (body|health)\b", u):
            feel = self._feelings(v.get("needs", {}))
            return f"I feel {feel}." if feel else "I'm fine. No real complaints."
        if re.search(r"\b(goal|want|plan|trying|doing|next)\b", u):
            g = v["goals"]
            return f"Right now I'm {v['activity']}. " + (f"I want to {g[0][:1].lower() + g[0][1:]}." if g else "")
        if re.search(r"\bwhat time\b|\bis it (day|night|dark|late)\b|\bweather\b", u):
            tod = [b for b in v["beliefs"] if "outside" in b["text"]]
            if tod:
                b = tod[-1]
                h = _hedge(b["confidence"])
                return (h + _lower_first(b["text"]) if h else b["text"]) + " I don't have a clock, though."
            return "I don't know. I haven't looked outside."
        ev = ctx.evidence
        if not ev:
            return "I don't remember." if re.search(r"\bremember|recall\b", u) else "I don't know."
        return self._answer_from_evidence(ev)

    def _answer_from_evidence(self, ev: list) -> str:
        out, first = [], None
        for e in ev:
            k, c, t = e["kind"], e.get("confidence", 0.5), e["text"]
            if first is not None:
                if k == first or (k == "uncertainty" and first in ("memory", "person", "belief", "forgotten")) \
                        or (k == "forgotten" and first == "memory"):
                    continue
            if k == "person":
                if e.get("identity"):
                    out.append(f"That's {e['identity']}.")
                elif e.get("familiarity", 0) >= 0.3:
                    out.append(f"{t.capitalize()} looks familiar, but I can't place {e.get('pronoun', 'them')}.")
                else:
                    out.append(f"I don't recognize {t}.")
            elif k == "memory":
                body = _strip_remember(t).rstrip(".").rstrip("…")
                out.append(_hedge(c) + "I remember " + body + ("... but the rest is hazy." if e.get("incomplete") else "."))
            elif k == "belief":
                out.append(("I believe " if c >= 0.75 else "I'm not certain, but ") + _lower_first(t.rstrip(".")) + ".")
            elif k == "uncertainty":
                out.append("I don't know. " + e["text"].rstrip(".") + (f" - {e['notes']}" if e.get("notes") else ""))
            elif k == "forgotten":
                out.append(f"I did notice {t}, but I can't recall what it was.")
            first = first or k
            if len(out) == 2:
                break
        return " ".join(out)

    # ---- autonomous behaviour -------------------------------------------
    def decide_action(self, ctx: BrainContext) -> Optional[dict]:
        """Chosen only from the character's OWN state: what they feel, what they have learned relieves it,
        what they believe about the room, and what they are still curious about.  Every choice carries a
        short `why`, so a run can be read as reasoning instead of a list of commands."""
        v = ctx.cs
        if not v["flags"].get("has_looked"):
            return {"cmd": "look", "why": "I should get my bearings first."}
        att, fails = v["attempts"], v["failures"]
        here = v["location"].get("room")
        everything = v["known_objects"]
        # things I can reach right now: held, or last seen in this room
        objs = [o for o in everything if o["held"] or o.get("room") in (None, here)]
        names = [o["name"] for o in objs]
        elsewhere = {o["name"]: o for o in everything if o not in objs}
        needs, states = v.get("needs", {}), v.get("states", {})
        hint_of = {o["name"]: o.get("hint", "") for o in everything}
        lamps = [x for x in names if hint_of.get(x) == "light"]
        views = [x for x in names if hint_of.get(x) == "view"]
        continuous = bool(ctx.action_result.get("continuous"))
        now, last_att = v["now"], v.get("last_att", {})

        def n(c, name): return att.get(f"{c}:{name}", 0)
        def f(c, name): return fails.get(f"{c}:{name}", 0)

        def age(key):
            """Minutes since I last did that, or None if I never have."""
            t = last_att.get(key)
            return minutes_between(t, now) if t else None

        def relief(need):
            """An action that should ease `need`, or None.  Learned relief first, common sense second."""
            adj = self.NEED_ADJ.get(need, need)

            def cooling(x):   # it failed recently (e.g. nothing left): leave it a while before trying again
                t = v.get("last_fail", {}).get(f"use:{x}")
                return bool(t) and minutes_between(t, v["now"]) < 360
            def blocked(x):   # it has failed three times - but only recently; an empty fridge gets restocked, a locked door opens
                t = v.get("last_fail", {}).get(f"use:{x}")
                return f("use", x) >= 3 and (not t or minutes_between(t, v["now"]) < 360)
            learned = [x for x in v.get("relief", {}).get(need, []) if x in names and not cooling(x) and not blocked(x)]
            guess = [x for x in names if hint_of.get(x) == need and not blocked(x) and n("use", x) < 2]
            pool = learned or guess
            if need == "boredom" and needs.get("boredom", 0) < 2:       # mildly bored: not the thing I did an hour ago
                pool = [x for x in pool if age(f"use:{x}") is None or age(f"use:{x}") >= 240]
            if not pool:
                # nothing to hand here: I remember something somewhere else that should help
                far = [x for x in v.get("relief", {}).get(need, []) if x in elsewhere and elsewhere[x].get("place_label")
                       and not cooling(x) and not blocked(x)] or [x for x in elsewhere if hint_of.get(x) == need and elsewhere[x].get("place_label")
                                               and not blocked(x) and n("use", x) < 2]
                if far:
                    where = elsewhere[far[0]]["place_label"]
                    return {"cmd": "move", "arg": where, "why": f"I'm {adj}, and I remember something that should help over by {where}."}
                return None
            pick = min(pool, key=lambda x: (n("use", x), pool.index(x)))
            return {"cmd": "use", "arg": pick, "why": f"I'm {adj}; the {pick} should help."}

        def redirect():
            """Restless and nothing new to explore: re-check what I've half forgotten, or go back to somewhere I've not been for hours."""
            def since(tag):
                t = v.get("tags", {}).get(tag)
                return minutes_between(t, now) if t else 99999
            if since("recheck") >= 180:                                  # at most one "let me look again" every few hours
                for name in v.get("stale", []):
                    a = age(f"inspect:{name}")
                    if name in names and f("inspect", name) < 1 and (a is None or a >= 240):
                        return {"cmd": "inspect", "arg": name, "tag": "recheck",
                                "why": f"I've half forgotten what the {name} looked like."}
            rooms = v.get("rooms", {})
            away = [(minutes_between(t, now), rid) for rid, t in v.get("room_last", {}).items() if rid != here and rid in rooms]
            away = [x for x in away if x[0] >= 240]
            if away and since("revisit") >= 240:                         # a few times a day, not a patrol
                rid = max(away)[1]
                spot = next((sp["label"] for sp in v.get("spots", []) if sp["room"] == rid and f("move", sp["label"]) < 3), None)
                if spot:
                    return {"cmd": "move", "arg": spot, "tag": "revisit",
                            "why": f"I haven't been back to {rooms[rid]} for hours; I want to see if anything has changed."}
            return None

        # 1. pressing bodily needs
        for need in sorted((k for k, b in needs.items() if b >= 2), key=lambda k: (-needs[k], self.NEED_PRIORITY.index(k))):
            if need == "boredom" and continuous:
                act = redirect()
                if act:
                    return act
            lit = next((x for x in lamps if states.get(x) == "on"), None)
            if need == "fatigue" and lit:
                return {"cmd": "use", "arg": lit, "why": f"I'd rather switch the {lit} off before I sleep."}
            act = relief(need)
            if act:
                return act
        # 2. too dark to see properly and I know where the lamp is
        light = v.get("last_light")
        unlit = next((x for x in lamps if states.get(x) != "on" and f("use", x) < 2), None)
        if light is not None and light < 0.6 and unlit:
            return {"cmd": "use", "arg": unlit, "why": f"It's too dim to see properly, and I know where the {unlit} is."}
        # 2b. I lost track of the outside while asleep: go and look
        look_out = next((x for x in views if f("use", x) < 3), None)
        if any("outside now" in u["question"] for u in v["open_uncertainties"]) and look_out:
            return {"cmd": "use", "arg": look_out, "why": "I lost track of what it's like outside while I slept."}
        # 2c. something the person asked me to do (watch films, read the note, go to the door...)
        for g in v.get("goal_acts", []):
            act = self._goal_action(g, objs, everything, names, f, n)
            if act:
                act["why"] = f"you asked me to: {g['text']}."
                return act
        # 2d. something slid across the floor: a lead worth following (read the note once I know where it is)
        if any("slid across the floor" in u["question"] for u in v["open_uncertainties"]):
            for o in objs:
                if "note" in o["name"] and n("use", o["name"]) == 0 and f("use", o["name"]) < 2:
                    return {"cmd": "use", "arg": o["name"], "why": "Something slid across the floor and I want to know what it says."}
            door = next((o["name"] for o in everything if hint_of.get(o["name"]) == "passage" and o.get("place_label")), None)
            if door and not any("note" in o["name"] for o in everything) and f("move", v["location"].get("spot_label") or "") < 3 \
                    and (age("inspect:" + door) is None or age("inspect:" + door) >= 120):
                return {"cmd": "inspect", "arg": door, "why": "Something slid across the floor by the door; I want to see what it was."}
        # 3. curiosity (as before)
        holding_key = any(hint_of.get(i) == "key" or "key" in i for i in v["inventory"])
        for o in objs:   # I believe something is locked and I'm holding a key: try it
            if holding_key and any(b["text"] == f"The {o['name']} is locked." for b in v["beliefs"]) and n("use", o["name"]) < 2:
                return {"cmd": "use", "arg": o["name"], "why": f"I'm holding a key and I think the {o['name']} is locked."}
        for o in objs:
            if n("inspect", o["name"]) == 0:
                return {"cmd": "inspect", "arg": o["name"], "why": f"I haven't looked at the {o['name']} properly yet."}
        for o in objs:
            if o["portable"] and not o["held"] and n("take", o["name"]) == 0 and f("take", o["name"]) == 0:
                return {"cmd": "take", "arg": o["name"], "why": f"I might want to carry the {o['name']}."}
        for o in objs:
            if n("inspect", o["name"]) < 2 and f("inspect", o["name"]) < 1:
                return {"cmd": "inspect", "arg": o["name"], "why": f"I want a second, closer look at the {o['name']}."}
        for o in objs:   # a collection I know has more in it (a box of discs...): keep going through it
            if any(u["question"] == f"What else is in the {o['name']}?" for u in v["open_uncertainties"]) \
                    and f("inspect", o["name"]) < 1:
                return {"cmd": "inspect", "arg": o["name"], "why": f"The {o['name']} has more in it."}
        for o in objs:
            if n("use", o["name"]) == 0 and f("use", o["name"]) < 2:
                return {"cmd": "use", "arg": o["name"], "why": f"I haven't tried the {o['name']} yet."}
        # 3a. something is lying over at a place I can see but haven't been to: go and look
        here_spot = v["location"].get("spot_label") or ""
        for u in v["open_uncertainties"]:
            m = re.fullmatch(r"What is lying at (.+)\?", u["question"])
            if not m:
                continue
            lead = m.group(1)
            sp = next((x for x in v.get("spots", []) if x["label"] == lead), None)
            if sp and lead != here_spot and (sp.get("room") in (None, here)) and f("move", lead) < 2 and n("move", lead) < 2:
                return {"cmd": "move", "arg": lead, "why": f"Something is lying over by {lead} and I want to know what it is."}
        # 3b. a door I believe is open or unlocked and have not gone through: go through it
        for o in objs:
            if hint_of.get(o["name"]) == "passage" and states.get(o["name"]) in ("unlocked", "open") and n("use", o["name"]) < 4:
                return {"cmd": "use", "arg": o["name"], "why": f"The {o['name']} is open and I haven't gone through it."}
        # 4. mild needs
        for need in sorted((k for k, b in needs.items() if b == 1), key=self.NEED_PRIORITY.index):
            if need == "boredom" and continuous:
                act = redirect()
                if act:
                    return act
            act = relief(need)
            if act:
                act["why"] = f"I'm a little {self.NEED_ADJ.get(need, need)}; I may as well deal with it."
                return act
        # 4b. something I noticed in another room and never looked at: go there
        for o in everything:
            if o in objs or not o.get("place_label"):
                continue
            if n("inspect", o["name"]) + f("inspect", o["name"]) == 0:
                return {"cmd": "move", "arg": o["place_label"], "why": f"I noticed the {o['name']} earlier and never looked at it."}
        # 5. nothing left to explore
        if not continuous:
            return None
        bored = needs.get("boredom", 0) >= 1
        if bored:
            act = redirect()
            if act:
                return act

        def pastime(x):
            return x in names and f("use", x) < 1          # a thing that has said "nothing more" is not a pastime
        learned = [x for x in v.get("relief", {}).get("boredom", []) if pastime(x)]
        habits = [x for x in names if hint_of.get(x) == "boredom" and pastime(x) and x not in learned]
        pool = learned + habits
        rested = [x for x in pool if (age(f"use:{x}") is None or age(f"use:{x}") >= 240)]   # not something I did an hour ago
        pool = rested or pool
        if pool and bored:
            pick = min(pool, key=lambda x: (n("use", x), pool.index(x)))
            return {"cmd": "use", "arg": pick, "why": f"I'm restless; the {pick} is a way to pass the time."}
        return {"cmd": "wait", "arg": "30", "why": "Nothing needs doing right now, so I'll rest a while."}

    def _goal_action(self, g, objs, everything, names, f, n):
        """One step toward a goal the person gave me, using only what I know and can reach."""
        cmd, arg = g["cmd"], g.get("arg", "")
        if g["progress"] >= g.get("count", 1):
            return None
        if cmd == "watch":
            tgt = next((x for x in names if any(k in x for k in ("player", "screen", "tv", "television", "telly"))), None)
            if tgt and f("use", tgt) < 3:
                return {"cmd": "use", "arg": tgt}
            far = next((o for o in everything if o.get("place_label") and any(k in o["name"] for k in ("player", "screen", "tv", "television", "telly"))), None)
            return {"cmd": "move", "arg": far["place_label"]} if far and f("move", far["place_label"]) < 3 else None
        if cmd == "move":
            return {"cmd": "move", "arg": arg} if f("move", arg) < 3 else None
        want = {w.rstrip("s") for w in re.findall(r"[a-z0-9]+", arg.lower())}
        for o in objs:
            if want <= {w.rstrip("s") for w in re.findall(r"[a-z0-9]+", o["name"].lower())} and f(cmd, o["name"]) < 3:
                if cmd == "take" and o.get("held"):
                    return None
                return {"cmd": cmd, "arg": o["name"]}
        for o in everything:                                   # I know where it is - it's just not here
            if o not in objs and o.get("place_label") and want <= {w.rstrip("s") for w in re.findall(r"[a-z0-9]+", o["name"].lower())} \
                    and f("move", o["place_label"]) < 3:
                return {"cmd": "move", "arg": o["place_label"]}
        return None


# --------------------------------------------------------------------------- LLM adapter
class PromptBrain(CharacterBrain):
    """Drop-in adapter for a local LLM.

        brain = PromptBrain(lambda prompt: my_llm(prompt, max_tokens=120))

    The model only ever sees `context.to_prompt()` - the character's own knowledge - so
    hidden world facts cannot leak.  Falls back to MockBrain if the model
    returns nothing (or raises), so the simulation keeps running."""

    # Props a small model likes to invent. Only allowed if the facts (or something he knows) actually include them.
    BAN_PROPS = ("clock", "ticking", "tick-tock", "mirror", "painting", "candle", "fireplace", "curtain", "carpet",
                 "bookshelf", "bookcase", "chandelier")
    NOVELTY = re.compile(r"\b(discover(?:ed|ing)?|just noticed|new item|for the first time)\b", re.I)
    # invented atmosphere / posture / odd framing words: only allowed when the facts themselves contain them
    BAN_WORDS = ("seat", "stool", "sofa", "armchair", "newcomer", "glow", "illuminat", "twinkl", "celestial", "stars",
                 "hums", "whir", "flicker", "hush", "star chart", "charts", "testament", "countless", "tells stories", "tell stories",
                 "tapestry", "symphony", "whisper", "weathering", "elements")
    STATE_CLAIMS = ("being on", "is on", "was on", "switched on", "turned on", "is lit", "was lit", "being lit", "light is on",
                    "lamp is on")
    PREVIOUS = re.compile(r"\b(previous(?:ly)?|earlier|last time|recall(?:ing|s|ed)?|once more|anew|again)\b", re.I)

    def __init__(self, complete_fn: Callable[[str], str], fallback: Optional[CharacterBrain] = None,
                 llm_actions: bool = False):
        self.complete_fn = complete_fn
        self.fallback = fallback or MockBrain()
        self.last_prompt = ""
        self.llm_actions = llm_actions        # opt-in: the model THINKS and picks his next action (scripted brain is the safety net)
        self.last_thought = ""
        self.thoughts: list = []
        self.recent_choices: list = []
        self.reasoning = False                # becomes True once the model prints <think>...</think>
        # token ceilings (live-editable: `tokens` command / Tokens window)
        self.tok_voice = 90                   # one spoken line
        self.tok_voice_think = 900            # a spoken line once a reasoning model is recognised
        self.think_tokens = 3000              # a DECISION once a reasoning model is recognised: let it finish thinking
        self.tok_choose = 200                 # a decision from a plain (non-reasoning) model
        self.tok_diary = 200
        self.ctx_window = getattr(complete_fn, "ctx", None)    # known for --model; for a server it is set in that program
        self.calls: list = []                 # the last few model calls (prompt, reply, budget, seconds) for the backend panel
        self.last_reasoning = ""              # the model's own <think> text for the last decision (shown with `think show`)
        self.show_reasoning = False

    # ---- talking ----------------------------------------------------------
    def _call(self, prompt: str, max_tokens: Optional[int] = None, temperature: float = 0.6, decision: bool = False) -> str:
        import time as _t
        if max_tokens is None:
            max_tokens = self.tok_voice
        if self.reasoning:                               # a reasoning model needs room to think before it answers
            max_tokens = max(max_tokens, self.think_tokens if decision else self.tok_voice_think)
        if self.ctx_window:                              # prompt + reply must fit the model's window
            max_tokens = max(64, min(max_tokens, int(self.ctx_window) - len(prompt) // 3 - 64))
        t0 = _t.time()
        try:
            raw = self.complete_fn(prompt, max_tokens=max_tokens, temperature=temperature)
        except TypeError:                                # a plain one-argument function
            raw = self.complete_fn(prompt)
        self.calls = (self.calls + [{"prompt": prompt, "raw": raw or "", "max_tokens": max_tokens,
                                     "seconds": round(_t.time() - t0, 1), "decision": decision}])[-6:]
        low = (raw or "").lower()
        if "<think" in low or "</think>" in low:
            self.reasoning = True                        # seen once: give every later call the bigger budget
            if "</think>" not in low and decision and max_tokens < self.think_tokens:
                # it ran out of tokens in the middle of thinking: give it room and let it finish this step
                return self._call(prompt, self.think_tokens, temperature, decision)
        if decision:
            m = re.search(r"(?:<think>)?(.*?)</think>", raw or "", re.S | re.I)
            self.last_reasoning = re.sub(r"\s+", " ", m.group(1)).strip() if m else ""
        return strip_think(raw)

    def grounded(self, text: str, ctx: BrainContext) -> bool:
        """True if a line he is about to say sticks to the facts he was given (and nothing invented sneaks in)."""
        if ctx.intent not in ctx.GROUNDED_INTENTS:
            return True
        low, facts = text.lower(), getattr(ctx, "_facts", "")
        known = [o["name"].lower() for o in ctx.cs["known_objects"]]
        for p in self.BAN_PROPS:
            if re.search(r"\b" + re.escape(p), low) and p not in facts and not any(p in k for k in known):
                return False
        if ctx.intent == "inspect" and ctx.learned.get("nothing_new") and self.NOVELTY.search(text):
            return False                                 # "I discovered..." about something he has already seen
        nm = ctx.who()
        if re.search(r"^(They|He|She)\b", text.strip()) or (nm.lower() not in facts and re.search(r"\b" + re.escape(nm) + r"\b", text)):
            return False                                 # they speak as themselves, not about themselves
        for phrase in self.STATE_CLAIMS:
            if phrase in low and phrase not in facts:
                return False                             # "the light being on" when the lamp is off
        for w in self.BAN_WORDS:
            if w in low and w not in facts and not any(w in k for k in known):
                return False
        if ctx.intent == "inspect" and getattr(ctx, "_first_look", False) and self.PREVIOUS.search(text):
            return False                                 # "recalling my previous examination" on a first look
        if ctx.intent in ("inspect", "use", "take"):
            subj = ((ctx.observation or {}).get("subject_label") or "").lower().split()[-1:]
            subj = subj[0] if subj else ""
            others = [n.split()[-1] for n in known if len(n.split()[-1]) >= 3 and n.split()[-1] != subj]
            named_other = any(re.search(r"\b" + re.escape(o) + r"s?\b", low) for o in others)
            if subj and named_other and not re.search(r"\b" + re.escape(subj), low):
                return False                             # the line is about some OTHER object (terminal voiced as the notebook)
        for name in known:                               # blending in some OTHER thing he knows about
            head = name.split()[-1]
            if len(head) >= 3 and re.search(r"\b" + re.escape(head) + r"s?\b", low) and head not in facts:
                return False
        return True

    def generate_response(self, context: BrainContext) -> str:
        if context.intent in ("report", "fail", "look", "arrive", "ambient"):
            # facts must stay exact: numbers, "I can't do that" reasons, what is in the room, and changes around him
            # (a model embroiders these: stars, hush, glass) are never re-worded
            return self.fallback.generate_response(context)
        self.last_prompt = context.to_prompt()
        self.persona_line = context.persona()
        text = ""
        try:
            text = tidy_speech(self._call(self.last_prompt))
            if text and not self.grounded(text, context):         # one stricter retry, then the scripted line
                text = tidy_speech(self._call(self.last_prompt + "\n(My last attempt mentioned things that are not listed. "
                                              "Use ONLY the listed facts, in new words.)\n" + context.who() + ":", temperature=0.3))
                if text and not self.grounded(text, context):
                    text = ""
        except Exception:
            text = ""
        return text or self.fallback.generate_response(context)

    def write_diary(self, facts: list, day: str) -> str:
        plain = self.fallback.write_diary(facts, day)
        if len(facts) < 2:
            return plain
        prompt = (getattr(self, "persona_line", "You are a character going about your life in a quiet place. Never mention being simulated, a program, a game or a model.")
                  + " Write a short private diary entry about your day.\n"
                  "Use ONLY these facts, in the first person, in three or four plain sentences. Say what mattered and what you are still "
                  "wondering about. Do not list counts or statistics. Do not add anything else.\n"
                  + "\n".join(f"- {f.rstrip('.')}" for f in facts[:9]) + "\n\nDiary entry:")
        try:
            text = tidy_speech(self._call(prompt, max_tokens=self.tok_diary, temperature=0.6), max_sentences=4)
        except Exception:
            text = ""
        return text or plain

    # ---- choosing actions (opt-in) ---------------------------------------
    def decide_action(self, context: BrainContext) -> Optional[dict]:
        proposal = self.fallback.decide_action(context)
        self.persona_line = context.persona()
        self.last_thought = ""
        self.last_reasoning = ""
        if not self.llm_actions or proposal is None:
            return proposal
        v = context.cs
        if any(int(b) >= 2 for b in v.get("needs", {}).values()) or \
                any(g["progress"] < g.get("count", 1) for g in v.get("goal_acts", [])):
            proposal["by"] = "script: a pressing need or something you asked for"
            return proposal               # pressing needs and things the person asked for are never left to a language model
        self._skip = "no answer"
        try:
            act = self._llm_choose(context, proposal)
        except Exception as e:
            act, self._skip = None, f"model error: {type(e).__name__}"
        if act:
            return act
        proposal["by"] = f"script: {self._skip}"
        return proposal

    def _options(self, ctx: BrainContext) -> list:
        """Every action that makes sense right now, as (cmd, arg, label). He can only pick from what he knows about."""
        v = ctx.cs
        att, fails = v["attempts"], v["failures"]
        here = v["location"].get("room")
        objs = [o for o in v["known_objects"] if o["held"] or o.get("room") in (None, here)]
        away = [o for o in v["known_objects"] if o not in objs and o.get("place_label")]
        fresh, rest = [], []
        holding_key = any("key" in o["name"].lower() and o["held"] for o in objs)
        for o in objs:
            nm = o["name"]
            ni, nu = att.get(f"inspect:{nm}", 0), att.get(f"use:{nm}", 0)
            is_key = "key" in nm.lower() and o["held"]
            if fails.get(f"inspect:{nm}", 0) < 2 and ni < 3:
                (fresh if ni == 0 else rest).append(("inspect", nm, f"inspect {nm} (" + (f"looked {ni}x)" if ni else "never looked)")))
            if o["portable"] and not o["held"] and att.get(f"take:{nm}", 0) == 0 and fails.get(f"take:{nm}", 0) == 0:
                fresh.append(("take", nm, f"take {nm}"))
            if is_key:
                continue                                  # a key does nothing on its own: it works on a door, so the door carries the hint
            if fails.get(f"use:{nm}", 0) < 2:
                tail = ("; I am holding a key" if holding_key and "door" in nm.lower() else "")
                (fresh if nu == 0 else rest).append(("use", nm, f"use {nm} (" + (f"tried {nu}x{tail})" if nu else f"never tried{tail})")))
        places = []
        for o in away:
            pl = o["place_label"]
            if pl not in [p[1] for p in places] and fails.get(f"move:{pl}", 0) < 3:
                places.append(("move", pl, f"go to {pl}"))
        return (fresh + places + rest)[:22] + [("wait", "30", "wait 30 minutes"), ("look", "", "look around")]

    @staticmethod
    def _base(label: str) -> str:
        return re.sub(r"\s*\(.*?\)\s*$", "", label).strip().lower()

    def _thought_ok(self, thought: str, cmd: str, arg: str, label: str, ctx: BrainContext) -> bool:
        """A reason must be about the thing he chose (it names it) and must not claim 'never looked' about something he has."""
        if not thought:
            return False
        low = thought.lower()
        if cmd in ("inspect", "use", "take"):
            head = arg.lower().split()[-1]
            if not re.search(r"\b" + re.escape(head), low):
                return False                     # (a reason may mention other things: "this key might open the door" is reasoning)
        if "(looked" in label or "(tried" in label:
            if re.search(r"\b(haven't|have not|not yet|never|first)\b", low):
                return False
        return True

    @staticmethod
    def _plain_reason(cmd: str, arg: str, label: str) -> str:
        if cmd == "inspect":
            return (f"I haven't looked at the {arg} properly yet." if "never looked" in label
                    else f"I want a second, closer look at the {arg}.")
        if cmd == "use":
            return f"I want to see what the {arg} does." if "never tried" in label else f"I want to try the {arg} again."
        if cmd == "take":
            return f"I want to pick up the {arg}."
        if cmd == "move":
            return f"I want to go over to {arg}."
        return "I will look about and wait a little." if cmd == "wait" else "I want to take stock of the room."

    def _llm_choose(self, ctx: BrainContext, proposal: dict) -> Optional[dict]:
        v = ctx.cs
        opts = self._options(ctx)
        word = ["not at all", "a little", "quite", "very"]
        feel = "; ".join(f"{BrainContext.NEED_ADJ.get(n, n)}: {word[min(3, int(b))]}" for n, b in v.get("needs", {}).items() if int(b) >= 1)
        loc = v["location"]
        lines = [
            ctx.persona() + " Decide what to do next. Think briefly, then choose ONE action from the list.",
            "Prefer something you have not done yet, or something that could answer a question on your mind. Do not repeat what you just did.",
            f"Where I am: {loc.get('room_label', 'unsure')}" + (f", at {loc['spot_label']}" if loc.get("spot_label") else ""),
            "Holding: " + (", ".join(v["inventory"]) or "nothing"),
            "How I feel: " + (feel or "fine"),
            "Open questions I can't answer: " + ("; ".join(u["question"] for u in v["open_uncertainties"][:4]) or "none"),
            "What I recently learned: " + (" | ".join(m["text"] for m in v["recent_memories"][-4:]) or "nothing yet"),
        ]
        if self.thoughts:
            lines.append("What I was thinking just before: " + " | ".join(self.thoughts[-3:]))
        lines += ["", "Options:"] + [f"- {label}" for _, _, label in opts]
        lines += ["", "Reply in exactly this form:", "THOUGHT: <ONE short sentence that names the thing you chose and why>",
                  "ACTION: <one option copied exactly from the list, without the brackets>"]
        raw = self._call("\n".join(lines), max_tokens=self.tok_choose, temperature=0.5, decision=True)
        m = re.search(r"ACTION\s*:\s*(.+)", raw, re.I)
        if not m:
            self._skip = "the reply had no ACTION line"
            return None
        choice = self._base(re.sub(r"[`*\"<>]", "", m.group(1).splitlines()[0]).strip().rstrip("."))
        bases = {self._base(label): (cmd, arg, label) for cmd, arg, label in opts}
        hit = bases.get(choice)
        if hit is None:
            close = difflib.get_close_matches(choice, list(bases), 1, 0.85)
            hit = bases[close[0]] if close else None
        if hit is None:
            self._skip = f"'{choice[:40]}' is not one of the options"
            return None
        cmd, arg, label = hit
        if self.recent_choices[-3:].count(label) >= 2:           # stuck repeating himself: let the scripted brain take over
            self._skip = "it was repeating itself"
            return None
        t = re.search(r"THOUGHT\s*:\s*(.+?)(?=\n\s*ACTION\s*:|$)", raw, re.I | re.S)
        thought = tidy_speech(re.sub(r"[<>]", "", t.group(1)), max_sentences=1)[:200] if t else ""
        by = "model"
        if not self._thought_ok(thought, cmd, arg, label, ctx):
            thought = self._plain_reason(cmd, arg, label)     # his choice stands; only the sloppy explanation is replaced
            by = "model, reason rewritten"
        self.recent_choices = (self.recent_choices + [label])[-6:]
        if thought:
            self.thoughts = (self.thoughts + [thought])[-4:]
        self.last_thought = thought
        return {"cmd": cmd, "arg": arg, "why": thought or "my own judgement", "by": by}


# ####################################################################################################
##### SECTION: character
# ####################################################################################################

"""CHARACTER: how the character's internal state changes when they perceive something.

This module never imports `world`.  Its only inputs are Observations (already
filtered by perception.py) and the passage of time.  It owns the transitions

    OBSERVATION -> EXPERIENCE -> MEMORY
                -> BELIEFS / UNCERTAINTIES / KNOWN_* / GOALS

and the retrieval used when the character is asked about themselves or the world.

Memory is deliberately NOT a copy of world truth: it stores the character's lossy,
confidence-weighted account of what he experienced.  Low-salience details may
be dropped when a memory forms (deterministically, from a seeded RNG), and
confidence decays with simulated time.
"""

import random
import re
from dataclasses import dataclass, field
from typing import Optional


MIN_MEMORY_SALIENCE = 0.3
HALF_LIFE_MINUTES = 24 * 60          # memory confidence halves every simulated day
SYNONYMS = {"photo": "picture", "pic": "picture", "lady": "woman", "guy": "man", "movie": "film", "films": "film",
            "exit": "door", "inscription": "writing", "year": "date"}
# Question words widen the search, but only against *labels* (what a thing is about),
# never against free text - otherwise "where?" would match "I can't place him".
EXPAND = {"where": {"place", "location"}, "when": {"date", "time"}, "who": {"person"}, "someone": {"person"},
          "whose": {"person"}}
MUTABLE_ATTRS = ("time_of_day", "state")       # beliefs about things that change while unobserved
NEED_ORDER = ("thirst", "hunger", "fatigue", "boredom")
NEED_GOAL = {"thirst": "Get something to drink", "hunger": "Find something to eat", "fatigue": "Get some sleep",
             "boredom": "Find something to occupy my mind"}
MAX_MEMORIES = 300
MAX_DIARIES = 60
KIND_PRIORITY = {"person": 0, "memory": 1, "belief": 2, "forgotten": 3, "uncertainty": 4}
QSTOP = {"what", "who", "where", "when", "why", "how", "do", "does", "did", "you", "your", "know", "about", "is", "are",
         "was", "were", "there", "remember", "tell", "me", "see", "saw", "can", "could", "it", "its", "i", "of",
         "in", "on", "that", "this", "the", "a", "an", "to", "and", "or", "any", "anything", "have", "has", "recall",
         "think", "say", "look", "looked", "looks", "like"}


def _stem_word(t: str) -> str:
    """watched / watching / watches -> watch, so a question and a memory worded differently still meet."""
    for suf in ("ing", "ed", "es", "s"):
        if t.endswith(suf) and len(t) - len(suf) >= 4:
            return t[:-len(suf)]
    return t


def _tokens(text: str) -> set:
    toks = {SYNONYMS.get(_stem_word(t), _stem_word(t)) for t in re.findall(r"[a-z0-9']+", text.lower())}
    return {t for t in toks if t not in QSTOP and len(t) > 1}


@dataclass
class Delta:
    """Everything that changed in the character because of one observation (for debugging)."""
    new: list = field(default_factory=list)
    upgraded: list = field(default_factory=list)
    repeats: list = field(default_factory=list)
    voice: list = field(default_factory=list)      # things the character would say aloud (vs. debug `notes`)
    recognitions: list = field(default_factory=list)
    memories: list = field(default_factory=list)
    notes: list = field(default_factory=list)

    @property
    def learned_something(self) -> bool:
        return bool(self.new or self.upgraded)

    def lines(self) -> list:
        out = []
        for p in self.new:
            out.append(f"+ learned [{p.key}] {p.gist or p.text}")
        for p in self.upgraded:
            out.append(f"^ upgraded [{p.key}] (now {p.completeness:.1f}) {p.gist or p.text}")
        if self.repeats and not (self.new or self.upgraded):
            out.append(f"= nothing new ({len(self.repeats)} already-known percepts)")
        out += [f"~ {n}" for n in self.notes]
        for m in self.memories:
            out.append(f"* memory {m['id']} ({m['confidence']}, {m['source']}"
                       f"{', incomplete' if m['incomplete'] else ''}): {m['text']}")
        return out


class Character:
    def __init__(self, state: CharState):
        self.s = state
        self.now = ""

    # ------------------------------------------------------------------ small helpers
    def _next(self, name: str) -> int:
        self.s.counters[name] = self.s.counters.get(name, 0) + 1
        return self.s.counters[name]

    def _changed(self, field_: str, change: str):
        self.s.state_changes.append({"time": self.now, "field": field_, "change": change})
        del self.s.state_changes[:-300]

    def _name(self, oid: str) -> str:
        return self.s.known_objects.get(oid, {}).get("name", oid)

    # ------------------------------------------------------------------ uncertainty & goals
    def open_uncertainty(self, key: str, question: str, about: Optional[str] = None, notes: str = "",
                         goal: bool = True) -> bool:
        if any(u["key"] == key and u["status"] == "open" for u in self.s.uncertainties):
            return False
        self.s.uncertainties.append({"id": f"u_{self._next('uncertainty'):04d}", "key": key, "question": question,
                                     "about": about, "status": "open", "raised": self.now, "resolved": None,
                                     "notes": notes})
        self._changed("uncertainties", f"opened: {question}")
        if goal and key not in ("where_am_i", "how_here"):
            self._add_goal(f"Find out: {question}", key)
        return True

    def resolve_uncertainty(self, key: str, note: str = "") -> bool:
        hit = False
        for u in self.s.uncertainties:
            if u["key"] == key and u["status"] == "open":
                u.update(status="resolved", resolved=self.now, notes=(note or u["notes"]))
                self._changed("uncertainties", f"resolved: {u['question']} -> {note}")
                hit = True
        if hit:
            for g in self.s.goals:
                if g.get("link") == key and g["status"] == "active":
                    g["status"] = "done"
                    self._changed("goals", f"done: {g['text']}")
            if key == "where_am_i":
                for g in self.s.goals:
                    if g["id"] == "g_orient":
                        g["status"] = "done"
        return hit

    def _add_goal(self, text: str, link: str):
        for g in self.s.goals:
            if g.get("link") == link:
                if g["status"] != "active" and link.startswith("need:"):
                    g["status"] = "active"
                    self._changed("goals", f"again: {text}")
                return
        self.s.goals.append({"id": f"g_{len(self.s.goals) + 1:03d}", "text": text, "status": "active",
                             "priority": 5, "created": self.now, "link": link})
        self._changed("goals", f"new: {text}")

    # ------------------------------------------------------------------ beliefs
    def update_belief(self, about: str, attr: str, value, text: str, confidence: float, source: str,
                      evidence: Optional[str] = None) -> Optional[str]:
        """Add / confirm / revise a belief.  Returns 'new' | 'confirmed' | 'revised'."""
        for b in self.s.beliefs:
            if b["about"] == about and b["attr"] == attr:
                if b["value"] == value:
                    b["confidence"] = round(max(b["confidence"], confidence), 2)
                    b["updated"] = self.now
                    return "confirmed"
                b.setdefault("history", []).append({"value": b["value"], "text": b["text"], "until": self.now})
                b.update(value=value, text=text, confidence=round(confidence, 2), updated=self.now,
                         source=source, revisions=b.get("revisions", 0) + 1)
                self._changed("beliefs", f"revised: {text}")
                return "revised"
        self.s.beliefs.append({"id": f"b_{self._next('belief'):04d}", "about": about, "attr": attr, "value": value,
                               "text": text, "confidence": round(confidence, 2), "source": source,
                               "evidence": [evidence] if evidence else [], "formed": self.now, "updated": self.now,
                               "revisions": 0})
        self._changed("beliefs", f"new: {text}")
        return "new"

    # ------------------------------------------------------------------ main entry point
    def perceive(self, obs: Observation, now: str) -> Delta:
        s, d = self.s, Delta()
        self.now = now
        obs.id = f"o_{self._next('observation'):04d}"
        held_before = list(s.inventory)

        if obs.place and obs.kind not in ("inventory", "body"):   # touch / bodily feelings alone doesn't tell him where he is
            loc = {"room": obs.room, "room_label": obs.room_label, "spot": obs.place, "spot_label": obs.place_label}
            if loc != s.current_location:
                self._changed("current_location", f"{obs.room_label}, {obs.place_label}")
            s.current_location = loc
            s.extra.setdefault("room_last", {})[obs.room] = now
            s.known_places.setdefault(obs.room, {"label": obs.room_label, "kind": "room", "first_seen": now})
            s.known_places.setdefault(obs.place, {"label": obs.place_label, "kind": "spot", "room": obs.room,
                                                  "first_seen": now})
        activity = obs.activity or {"look": "looking around", "arrive": "getting my bearings",
                                    "inspect": f"examining the {obs.subject_label}", "take": f"holding the {obs.subject_label}",
                                    "drop": "standing here", "use": f"using the {obs.subject_label}",
                                    "ambient": s.current_activity, "inventory": s.current_activity,
                                    "body": s.current_activity}.get(obs.kind, "idle")
        if activity != s.current_activity:
            self._changed("current_activity", activity)
            s.current_activity = activity

        statuses = []
        for p in obs.percepts:
            status = self._status(p)
            statuses.append((p, status))
            {"new": d.new, "upgraded": d.upgraded, "repeat": d.repeats}[status].append(p)
            self._integrate(p, obs, status, d)

        if obs.kind == "inspect" and obs.subject:
            ko = s.known_objects.setdefault(obs.subject, {"name": obs.subject_label or obs.subject})
            ko.setdefault("name", obs.subject_label or obs.subject)
            ko["inspections"] = ko.get("inspections", 0) + 1
            if not any(p.key.endswith(".too_dark") for p in obs.percepts):
                self.resolve_uncertainty(f"partial:{obs.subject}.too_dark", "I could see it properly this time.")
        if obs.kind == "use" and obs.subject:
            ko = s.known_objects.setdefault(obs.subject, {"name": obs.subject_label or obs.subject})
            ko.setdefault("name", obs.subject_label or obs.subject)
            ko["uses"] = ko.get("uses", 0) + 1
        if obs.kind == "look" or any(p.kind == "room" for p in obs.percepts):
            s.flags["has_looked"] = True
            self.resolve_uncertainty("where_am_i", f"I'm in {obs.room_label}.")
        if obs.kind == "inventory":
            self._reconcile_inventory(obs, held_before, d)

        self._consolidate(obs, statuses, d)
        self._record_experience(obs, d)
        self._log_acts(obs)
        pk = s.perceived_keys
        if len(pk) > 700:                       # one-off keys ("...@time") are never needed again
            for k in [k for k in pk if "@" in k][:-250]:
                del pk[k]
        return d

    # ------------------------------------------------------------------ the body
    def _apply_body(self, p: Percept, d: Delta):
        """A bodily sensation: update what the character feels, set/clear need goals, learn what relieves what."""
        s, need, band = self.s, p.body["need"], p.body["band"]
        old = s.needs.get(need, {"band": 0, "since": self.now})
        if band != old["band"]:
            s.needs[need] = {"band": band, "since": self.now}
            self._changed("needs", f"{need}: {old['band']} -> {band}")
        else:
            s.needs[need] = old
        link = f"need:{need}"
        if band >= 2:
            self._add_goal(NEED_GOAL[need], link)
        elif band <= 1:
            for g in s.goals:
                if g.get("link") == link and g["status"] == "active":
                    g["status"] = "done"
                    self._changed("goals", f"done: {g['text']}")
        if p.body.get("relief") and p.subject:
            known = s.extra.setdefault("relief", {}).setdefault(need, [])
            name = p.subject_label
            if name not in known:
                known.append(name)
                d.notes.append(f"learned: the {name} relieves {need}")

    def _age_beliefs(self, minutes: int, d: Delta):
        """Time passed unobserved (sleep): beliefs about changeable things become less certain."""
        hit = False
        for b in self.s.beliefs:
            if b["attr"] in MUTABLE_ATTRS and b["source"] == "direct_observation" and not b["about"].startswith("link:"):
                new = round(max(0.15, b["confidence"] * 0.5 ** (minutes / 480)), 2)
                if new < b["confidence"]:
                    b["confidence"], hit = new, True
                    b["stale"] = True
        if hit:
            d.notes.append("some of what I believed may be out of date after the time that passed")
            self.open_uncertainty("stale:time", "What is it like outside now? I lost track of the time.", "time_of_day",
                                  "I slept, so what I last saw may have changed.", goal=False)

    # ------------------------------------------------------------------ activity log (for `report`)
    def log_act(self, text: str):
        if not text:
            return
        tot = self.s.extra.setdefault("activity_totals", {})
        tot[text] = tot.get(text, 0) + 1
        days = self.s.extra.setdefault("day_acts", {})
        today = days.setdefault((self.now or "")[:10], {})
        today[text] = today.get(text, 0) + 1
        for old in sorted(days)[:-3]:                       # only the last few days are needed for the diary
            del days[old]
        self._check_goals()

    def _log_acts(self, obs: Observation):
        acts = [p.act for p in obs.percepts if p.act]
        if not acts:
            sl = obs.subject_label
            derived = {"inspect": f"looked closely at the {sl}", "take": f"picked up the {sl}", "drop": f"put down the {sl}",
                       "look": "looked around", "use": f"used the {sl}" if sl else ""}.get(obs.kind, "")
            acts = [derived] if derived else []
        for a in acts[:1]:
            self.log_act(a)

    def _lasting_keys(self) -> int:
        return sum(1 for k in self.s.perceived_keys if "@" not in k)

    def mark_session(self):
        s = self.s
        s.extra["session"] = {"start": self.now, "totals": dict(s.extra.get("activity_totals", {})),
                              "keys": self._lasting_keys(), "memories": s.counters.get("memory", 0),
                              "objects": len(s.known_objects)}

    def session_report(self) -> dict:
        s = self.s
        sess = s.extra.get("session") or {"start": (s.memories[0]["time"] if s.memories else self.now), "totals": {},
                                          "keys": 0, "memories": 0}
        tot = s.extra.get("activity_totals", {})
        acts = [(a, c - sess["totals"].get(a, 0)) for a, c in tot.items() if c - sess["totals"].get(a, 0) > 0]
        acts = self._collapse_acts(acts)
        basics = [a for a in acts if re.match(r"(slept|drank|ate)\b", a[0])]
        acts = (basics + [a for a in acts if a not in basics])[:8]        # staying alive always makes the report
        notable = self.notable_memories(after_id=sess["memories"], limit=3)           # what happened, not the daily routine
        return {"since": sess["start"], "until": self.now, "acts": acts,
                "learned": max(0, len(s.known_objects) - sess.get("objects", 0)),
                "needs": {n: v["band"] for n, v in s.needs.items()},
                "highlights": [self.as_fact(m["text"]) for m in notable],
                "minutes": minutes_between(sess["start"], self.now) if self.now else 0}

    @staticmethod
    def _collapse_acts(acts: list, keep_total: bool = False) -> list:
        """'looked closely at the desk twice, ... the door twice ...' -> 'looked closely at 14 different things'."""
        out, groups, weight = [], {}, {}
        for a, c in acts:
            for pre, plural in (("looked closely at the ", "looked closely at {n} different things"),
                                ("picked up the ", "picked up {n} different things"),
                                ("used the ", "used {n} different things")):
                if a.startswith(pre):
                    g = groups.setdefault(pre, [plural, 0, []])
                    g[1] += c
                    g[2].append((a, c))
                    break
            else:
                out.append((a, c))
        for pre, (plural, total, items) in groups.items():
            if len(items) >= 3:
                t = plural.format(n=len(items))
                out.append((t, total if keep_total else 1))
                weight[t] = total
            else:
                out += items
        out.sort(key=lambda x: -weight.get(x[0], x[1]))
        return out

    def _prune_memories(self):
        diaries = [m for m in self.s.memories if m["source"] == "diary"]
        if len(diaries) > MAX_DIARIES:                       # the oldest pages eventually go
            gone = {m["id"] for m in diaries[:len(diaries) - MAX_DIARIES]}
            self.s.memories = [m for m in self.s.memories if m["id"] not in gone]
        live = [m for m in self.s.memories if m["source"] not in ("background", "diary")]
        if len(live) <= MAX_MEMORIES:
            return
        cull = sorted(live, key=lambda m: (self.effective_confidence(m), m["time"]))[:len(live) - MAX_MEMORIES]
        ids = {m["id"] for m in cull}
        self.s.memories = [m for m in self.s.memories if m["id"] not in ids]

    # ------------------------------------------------------------------ percept handling
    def _status(self, p: Percept) -> str:
        old = self.s.perceived_keys.get(p.key)
        if not old:
            return "new"
        return "upgraded" if p.completeness > old["completeness"] + 0.05 else "repeat"

    def _integrate(self, p: Percept, obs: Observation, status: str, d: Delta):
        s = self.s
        if p.place and p.place not in s.known_places and p.place_label:
            s.known_places[p.place] = {"label": p.place_label, "kind": "spot", "room": obs.room, "first_seen": self.now}
            d.notes.append(f"new place known: {p.place_label}")
        if p.subject:
            is_new_object = p.subject not in s.known_objects
            o = s.known_objects.setdefault(p.subject, {"name": p.subject_label, "first_seen": self.now, "inspections": 0,
                                                      "uses": 0, "held": p.subject in s.inventory,
                                                      "last_known_place": None})
            o.setdefault("name", p.subject_label or p.subject)
            if is_new_object or o.get("first_seen") is None:
                o.setdefault("first_seen", self.now)
            if is_new_object:
                d.notes.append(f"new object known: {p.subject_label}")
                self._changed("known_objects", f"+{p.subject_label}")
            o["last_seen"] = self.now
            if obs.room and p.subject not in s.inventory and p.kind != "held":
                o["room"] = obs.room                       # where I last met it (so I can walk back for it)
            if p.kind == "sighting" and p.place and p.place_label:
                o["place_label"] = p.place_label
            if getattr(p, "hint", ""):
                o["hint"] = p.hint                        # what it LOOKS like it is for (food, water, a bed, a door...)
            if p.kind == "sighting" and p.mobile:
                o["looks_portable"] = True        # small and loose: visibly something one could pick up
            if p.kind == "sighting" and p.place and p.mobile:
                o["last_known_place"] = p.place
                self.update_belief(p.subject, "location", p.place, f"The {p.subject_label} is at {p.place_label}.",
                                   0.8 if p.completeness >= 1 else 0.6, "direct_observation", p.key)
            if p.kind == "sighting" and p.place and (p.mobile or p.loose):
                if p.completeness >= 1:
                    self.resolve_uncertainty(f"q:{p.place}.unidentified",
                                             f"It was {('an' if p.subject_label[:1] in 'aeiou' else 'a')} {p.subject_label}.")
        if p.holds:
            if p.holds not in s.inventory:
                s.inventory.append(p.holds)
                self._changed("inventory", f"+{self._name(p.holds)}")
            s.known_objects.setdefault(p.holds, {"name": p.subject_label})["held"] = True
            s.known_objects[p.holds]["last_known_place"] = "me"
            self.update_belief(p.holds, "location", "me", f"I have the {p.subject_label}.", 0.95,
                               "direct_observation", p.key)
        if p.releases:
            if p.releases in s.inventory:
                s.inventory.remove(p.releases)
                self._changed("inventory", f"-{self._name(p.releases)}")
            s.known_objects.setdefault(p.releases, {"name": p.subject_label})["held"] = False
            s.known_objects[p.releases]["last_known_place"] = obs.place
            self.update_belief(p.releases, "location", obs.place,
                               f"The {p.subject_label} is where I left it, at {obs.place_label}.", 0.9,
                               "direct_observation", p.key)

        if p.body:
            self._apply_body(p, d)
        if p.stale_minutes:
            self._age_beliefs(p.stale_minutes, d)

        if status != "repeat":
            s.perceived_keys[p.key] = {"completeness": p.completeness, "label": p.label, "time": self.now,
                                       "subject": p.subject}
        for k in p.resolves:
            self.resolve_uncertainty(k, p.text)

        if status != "repeat":
            if p.recognizable:
                self._recognize(p, d)
            if p.unresolved:
                self.open_uncertainty(f"q:{p.key}", p.unresolved, p.subject)
            if p.completeness < 0.99 and p.kind == "fact":
                self.open_uncertainty(f"partial:{p.key}", f"What does {p.label or 'it'} say, exactly?", p.subject,
                                      "I could only make out part of it.", goal=False)
            if p.kind == "sensation" and p.key.endswith(".too_dark"):
                self.open_uncertainty(f"partial:{p.key}", f"What am I missing about {p.label}?",
                                      p.subject, "It was too dark to make them out.", goal=False)
            if status == "upgraded" and p.completeness >= 0.99:
                self.resolve_uncertainty(f"partial:{p.key}", "I can read it clearly now.")
            self._link_topics(p, d)
        if p.belief:
            res = self.update_belief(p.subject or obs.room, p.belief["attr"], p.belief["value"], p.belief["text"],
                                     p.belief.get("confidence", 0.7), "direct_observation", p.key)
            if res == "revised":
                d.notes.append(f"belief revised: {p.belief['text']}")
            if p.belief["attr"] == "time_of_day":
                self.resolve_uncertainty("stale:time", "I've seen the sky again.")

    def _recognize(self, p: Percept, d: Delta):
        s, r = self.s, p.recognizable
        imp = s.impressions.get(r["tag"], {})
        strength, identity = imp.get("strength", 0.0), imp.get("identity")
        status = "known" if identity else ("familiar" if strength >= 0.3 else "unknown")
        pid = f"person:{r['tag']}"
        if pid not in s.known_people:
            s.known_people[pid] = {"label": r["label"], "description": p.gist, "first_seen": self.now,
                                   "identity": identity, "familiarity": strength, "pronoun": r.get("pronoun", "them"),
                                   "seen_in": p.subject}
            self._changed("known_people", f"{r['label']} ({status})")
        d.recognitions.append({"key": p.key, "label": r["label"], "pronoun": r.get("pronoun", "them"), "status": status,
                               "familiarity": strength, "identity": identity, "description": p.text})
        if status in ("unknown", "familiar"):
            self.open_uncertainty(f"who:{r['tag']}", f"Who is {r['label']} in the {self._name(p.subject)}?", p.subject,
                                  "Looks familiar, but I can't place it." if status == "familiar" else "")
        if status == "familiar":
            self.update_belief(pid, "familiarity", "familiar", f"I feel I've seen {r['label']} before, but I can't place "
                               f"{r.get('pronoun', 'them')}.", strength * 0.85, "impression", p.key)

    def _link_topics(self, p: Percept, d: Delta):
        if not p.topics:
            return
        for topic in p.topics:
            entries = self.s.topic_index.setdefault(topic, [])
            if p.subject:
                for e in [e for e in entries if e["subject"] and e["subject"] != p.subject]:
                    self._link_belief(p, e, topic, d)
            if not any(e["key"] == p.key for e in entries):
                entries.append({"key": p.key, "subject": p.subject, "gist": p.gist, "time": self.now})

    def _link_belief(self, p: Percept, other: dict, topic: str, d: Delta):
        a, b = sorted([p.subject, other["subject"]])
        about = f"link:{a}|{b}"
        existing = next((x for x in self.s.beliefs if x["about"] == about), None)
        topics = sorted(set((existing["value"] if existing else []) + [topic]))
        if existing and topic in existing["value"]:
            return
        conf = min(0.75, 0.3 + 0.15 * len(topics))
        text = (f"The {self._name(a)} and the {self._name(b)} seem to be connected "
                f"({self._name(p.subject)}: {p.gist}; {self._name(other['subject'])}: {other['gist']}).")
        self.update_belief(about, "connection", topics, text, conf, "inference", p.key)
        d.notes.append(f"inferred a connection: {self._name(a)} <-> {self._name(b)} ({topic})")

    def _reconcile_inventory(self, obs: Observation, held_before: list, d: Delta):
        """On resume: does what I *feel* in my hands match what I believed?"""
        actual = set(obs.extra.get("held", []))
        for oid in held_before:
            if oid not in actual:
                n = self._name(oid)
                self.s.inventory.remove(oid)
                self.s.known_objects[oid]["held"] = False
                self.update_belief(oid, "location", "unknown", f"I thought I had the {n}, but I don't - I'm not sure where it is.",
                                   0.4, "direct_observation")
                self.open_uncertainty(f"lost:{oid}", f"Where is the {n}? I thought I was holding it.", oid)
                d.notes.append(f"I thought I was holding the {n}, but I'm not.")
                d.voice.append(f"I thought I was holding the {n}, but I'm not. I don't know where it is.")
        for oid in actual:
            if oid not in held_before:
                n = self._name(oid)
                self.s.known_objects.setdefault(oid, {"name": n})["held"] = True
                self.open_uncertainty(f"unexplained:{oid}", f"Why am I holding the {n}? I don't remember picking it up.", oid)
                d.notes.append(f"I'm holding the {n}, but I don't remember picking it up.")
                d.voice.append(f"I'm holding the {n}, but I don't remember picking it up.")

    # ------------------------------------------------------------------ memory
    def _consolidate(self, obs: Observation, statuses: list, d: Delta):
        s = self.s
        episode = [p for p, st in statuses if st != "repeat" and p.narrate and p.salience >= MIN_MEMORY_SALIENCE and p.gist]
        if not episode:
            for m in s.memories:
                if obs.subject and m.get("subject") == obs.subject:
                    floor = 0.55 if obs.kind == "inspect" else 0.0       # a fresh, deliberate look re-fixes a faded memory
                    m["confidence"] = round(min(0.95, max(m["confidence"] + 0.03, floor)), 2)
                    m["refreshed"] = self.now
            return
        mid = f"m_{self._next('memory'):04d}"
        seed = s.extra.get("rng_seed", 0)
        kept, dropped = [], 0
        for p in episode:
            rnd = random.Random(f"{seed}:{mid}:{p.key}").random()
            if p.salience >= 0.6 or rnd < p.salience + 0.25:
                kept.append(p)
            else:
                dropped += 1
        if not kept:
            kept = [max(episode, key=lambda x: x.salience)]
            dropped = len(episode) - 1
        label = obs.subject_label or obs.room_label
        if obs.kind in ("take", "drop"):
            text = f"I remember {kept[0].gist}."
        else:
            verb = {"look": f"looking around {obs.room_label}", "arrive": f"walking over to {obs.place_label}",
                    "inspect": f"examining the {label}", "use": f"using the {label}",
                    "ambient": "noticing a change", "inventory": "checking my hands",
                    "body": "noticing how my body felt"}.get(obs.kind, "being here")
            text = f"I remember {verb}: " + "; ".join(p.gist.rstrip(".") for p in kept) + ("..." if dropped else ".")
        conf = sum(p.salience * p.completeness for p in kept) / len(kept) + 0.12
        mem = {"id": mid, "time": self.now, "text": text, "confidence": round(max(0.2, min(0.95, conf)), 2),
               "source": "self_action" if obs.kind in ("take", "drop", "arrive") else "direct_observation",
               "subject": obs.subject, "place": obs.place, "percept_keys": [p.key for p in kept],
               "event_ids": list(obs.event_ids), "incomplete": bool(dropped) or any(p.completeness < 0.99 for p in kept),
               "recalled": 0, "last_recalled": None, "tags": sorted({t for p in kept for t in p.topics})}
        upgraded_keys = {p.key for p in d.upgraded}
        for old in s.memories:   # a clearer view supersedes the older, hazier one
            if old.get("subject") == obs.subject and set(old["percept_keys"]) & upgraded_keys and not old.get("superseded_by"):
                old["superseded_by"] = mid
        s.memories.append(mem)
        d.memories.append(mem)
        self._prune_memories()
        self._changed("memories", f"{mid}: {text}")

    def _record_experience(self, obs: Observation, d: Delta):
        s = self.s
        s.recent_observations.append({
            "id": obs.id, "time": obs.time, "kind": obs.kind, "subject": obs.subject, "place": obs.place,
            "light": obs.light, "event_ids": list(obs.event_ids),
            "perceived": [p.text for p in obs.percepts if p.narrate][:6],
            "new": [p.key for p in d.new], "upgraded": [p.key for p in d.upgraded],
            "memory_formed": [m["id"] for m in d.memories]})
        del s.recent_observations[:-25]

    # ------------------------------------------------------------------ recall & retrieval
    def effective_confidence(self, m: dict) -> float:
        if m["source"] == "background":
            return m["confidence"]
        age = max(0, minutes_between(m.get("refreshed") or m["time"], self.now)) if self.now else 0
        life = HALF_LIFE_MINUTES * (7 if m["source"] == "diary" else 1)     # a diary entry outlasts the day it describes
        return round(m["confidence"] * 0.5 ** (age / life), 2)

    def _live_memories(self) -> list:
        return [m for m in self.s.memories if not m.get("superseded_by")]

    def recall(self, topic: Optional[str] = None, limit: int = 6) -> list:
        want = _tokens(topic) if topic else set()
        out = []
        for m in reversed(self._live_memories()):
            hay = _tokens(m["text"]) | set(m.get("tags", [])) | _tokens(self._name(m["subject"]) if m.get("subject") else "")
            if want and not (want & hay):
                continue
            eff = self.effective_confidence(m)
            m["recalled"] += 1
            m["last_recalled"] = self.now
            out.append({"kind": "memory", "id": m["id"], "text": m["text"], "confidence": eff,
                        "incomplete": m["incomplete"], "time": m["time"], "faded": eff < 0.15})
            if len(out) >= limit:
                break
        return out

    def retrieve(self, question: str, limit: int = 4) -> list:
        """Evidence relevant to a question - drawn only from the character's own state."""
        words = set(re.findall(r"[a-z0-9']+", question.lower()))
        q = _tokens(question)
        q_exp = set().union(*[EXPAND[w] for w in words if w in EXPAND]) if words & set(EXPAND) else set()
        if not q and not q_exp:
            return []
        s, found = self.s, []

        def add(kind, text, conf, hay_text, label_text="", **kw):
            score = len(q & _tokens(hay_text)) + len(q_exp & _tokens(label_text))
            if score:
                found.append({"kind": kind, "text": text, "confidence": conf, "score": score, **kw})

        def labels(keys):
            return " ".join(s.perceived_keys.get(k, {}).get("label", "") for k in keys)

        for m in self._live_memories():
            if m["source"] in ("conversation", "hearsay"):      # reachable via "what did I ask you?" - never mixed into topical answers
                continue
            eff = self.effective_confidence(m)
            add("memory", m["text"], eff, m["text"] + " " + " ".join(m.get("tags", [])) + " " + self._name(m.get("subject") or ""),
                labels(m["percept_keys"]), incomplete=m["incomplete"], faded=eff < 0.15)
        for b in s.beliefs:
            add("belief", b["text"], b["confidence"], b["text"])
        for u in s.uncertainties:
            if u["status"] == "open":
                add("uncertainty", u["question"], 0.0, u["question"] + " " + u["notes"], u["question"], notes=u["notes"])
        for pid, p in s.known_people.items():
            add("person", p["label"], p["familiarity"], p["label"] + " " + (p["description"] or ""), "person",
                identity=p["identity"], familiarity=p["familiarity"], pronoun=p["pronoun"])
        remembered = {k for m in self._live_memories() for k in m["percept_keys"]}
        for key, info in s.perceived_keys.items():
            if key not in remembered and info["label"]:
                add("forgotten", info["label"], 0.0, info["label"], info["label"])
        found.sort(key=lambda e: (-e["score"], KIND_PRIORITY[e["kind"]], -e["confidence"]))
        return found[:limit]

    # ------------------------------------------------------------------ conversations become memories
    QUESTION_RE = re.compile(r"(?i)\?\s*$|^\s*(what|who|where|when|why|how|which|do|does|did|is|are|was|were|can|could|have|has|"
                             r"tell|describe|explain)\b")

    def remember_talk(self, said: str, replied: str, told: bool = False):
        """What the person said (and what I answered) is remembered like anything else: timestamped, lossy, hearsay.
        It never becomes a BELIEF about the world - being told something is not seeing it."""
        said = re.sub(r"\s+", " ", said).strip()
        if not said:
            return
        asked = bool(self.QUESTION_RE.search(said)) and not told
        first = re.split(r"(?<=[.!?])\s+", re.sub(r"\s+", " ", replied or "").strip())[0]
        if len(first) > 90:
            first = first[:90].rsplit(" ", 1)[0] + "..."
        if "The person" in first or '"' in first:               # an answer made of other conversations is not worth quoting
            first = ""
        if asked:
            first = first.rstrip(".")
            text = f'The person asked me: "{said[:140]}"' + (f' and I answered: "{first}"' if first else "")
            conf, src, tags = 0.8, "conversation", ["conversation", "person", "asked"]
        else:
            text = f'The person told me: "{said[:160]}"'
            conf, src, tags = 0.55, "hearsay", ["conversation", "person", "told"]
        mid = f"m_{self._next('memory'):04d}"
        self.s.memories.append({"id": mid, "time": self.now, "text": text, "confidence": conf, "source": src, "subject": None,
                                "place": None, "percept_keys": [], "event_ids": [], "incomplete": False, "recalled": 0,
                                "last_recalled": None, "tags": tags})
        self._prune_memories()
        self._changed("memories", f"{mid}: {text}")

    # ------------------------------------------------------------------ goals the person gives me
    GOAL_VERBS = {"read": "use", "use": "use", "try": "use", "play": "use", "open": "use", "inspect": "inspect", "examine": "inspect",
                  "study": "inspect", "check": "inspect", "look at": "inspect", "take": "take", "grab": "take", "pick up": "take",
                  "go to": "move", "visit": "move", "explore": "move", "walk to": "move", "head to": "move"}
    NUMWORDS = {"a": 1, "one": 1, "once": 1, "two": 2, "twice": 2, "three": 3, "four": 4, "five": 5, "six": 6}

    @classmethod
    def parse_goal(cls, text: str) -> Optional[dict]:
        t = text.lower().strip().rstrip(".!")
        t = re.sub(r"^(please |you should |you could |try to |i want you to |i'd like you to |go and |could you |can you |"
                   r"would you |start to |start by |make sure you |i want you to )+", "", t).strip()
        m = re.match(r"^(?:watch|see)\s+(?:(\d+|a|one|two|three|four|five|six)\s+)?(?:more\s+)?(?:films?|movies?|dvds?)\b", t)
        if m:
            n = m.group(1)
            return {"cmd": "watch", "arg": "", "count": int(n) if n and n.isdigit() else cls.NUMWORDS.get(n or "a", 1)}
        verbs = sorted(cls.GOAL_VERBS, key=len, reverse=True)
        m = re.match(r"^(" + "|".join(re.escape(v) for v in verbs) + r")\s+(?:the\s+|a\s+|an\s+|my\s+)?(.+?)"
                     r"(?:\s+(\d+|once|twice|two|three|four|five)(?:\s+times)?)?$", t)
        if m and m.group(2):
            n = m.group(3)
            return {"cmd": cls.GOAL_VERBS[m.group(1)], "arg": m.group(2).strip(), "count": int(n) if n and n.isdigit()
                    else cls.NUMWORDS.get(n or "once", 1)}
        return None

    @staticmethod
    def _words(text: str) -> set:
        return {re.sub(r"s$", "", w) for w in re.findall(r"[a-z0-9]+", text.lower()) if w not in ("the", "a", "an", "my")}

    def _goal_count(self, act: dict) -> int:
        s = self.s
        if act["cmd"] == "watch":
            return sum(v for k, v in s.extra.get("activity_totals", {}).items() if k.startswith("watched "))
        want = self._words(act["arg"])
        return sum(v for k, v in s.extra.get("attempts", {}).items()
                   if k.startswith(act["cmd"] + ":") and want <= self._words(k.split(":", 1)[1]))

    def goal_progress(self, g: dict) -> int:
        return max(0, self._goal_count(g["act"]) - g.get("baseline", 0)) if g.get("act") else 0

    def add_user_goal(self, text: str) -> dict:
        act = self.parse_goal(text)
        gid = f"ug_{self._next('goal'):03d}"
        g = {"id": gid, "text": text.strip().rstrip("."), "status": "active", "priority": 2, "created": self.now,
             "link": f"person:{gid}", "source": "person", "act": act, "baseline": self._goal_count(act) if act else 0}
        self.s.goals.append(g)
        self._changed("goals", f"new (from the person): {g['text']}")
        return g

    def user_goals(self) -> list:
        return [g for g in self.s.goals if g.get("source") == "person"]

    def _check_goals(self):
        for g in self.s.goals:
            if g.get("source") == "person" and g["status"] == "active" and g.get("act"):
                if self.goal_progress(g) >= g["act"].get("count", 1):
                    g["status"] = "done"
                    g["finished"] = self.now
                    self._changed("goals", f"done: {g['text']}")
                    self.s.extra.setdefault("goal_news", []).append(g["text"])

    def conversation_summary(self, limit: int = 6) -> str:
        talk = [m for m in self._live_memories() if m["source"] in ("conversation", "hearsay")][-limit:]
        if not talk:
            return "We haven't really talked yet."
        asked = [re.match(r'The person asked me: "(.*?)"(?: and I answered|$)', m["text"]) for m in talk if m["source"] == "conversation"]
        told = [re.match(r'The person told me: "(.*)"$', m["text"]) for m in talk if m["source"] == "hearsay"]
        parts = []
        if any(asked):
            parts.append("You asked me " + "; then ".join(f'"{a.group(1)}"' for a in asked if a) + ".")
        if any(told):
            parts.append("You also told me " + "; and ".join(f'"{t.group(1)}"' for t in told if t) + ".")
        return " ".join(parts)

    def pop_goal_news(self) -> list:
        news, self.s.extra["goal_news"] = self.s.extra.get("goal_news", []), []
        return news

    # ------------------------------------------------------------------ the diary
    _TENSE = [(r"^examining the ", "I examined the "), (r"^using the ", "I used the "), (r"^looking around ", "I looked around "),
              (r"^walking over to ", "I walked over to "), (r"^noticing a change", "I noticed a change"),
              (r"^noticing how my body felt", "I noticed how my body felt"), (r"^checking my hands", "I checked my hands"),
              (r"^being here", "I was here")]

    def as_fact(self, text: str) -> str:
        """'I remember examining the notebook: a star chart.' -> 'I examined the notebook - a star chart'."""
        t = re.sub(r"^I remember\s+", "", text).rstrip(".…").strip()
        for pat, rep in self._TENSE:
            if re.match(pat, t):
                t = re.sub(pat, rep, t, count=1)
                break
        else:
            t = "I remember " + t
        return t.replace(": ", " - ", 1)

    def notable_memories(self, day: Optional[str] = None, after_id: int = 0, limit: int = 6) -> list:
        """What actually HAPPENED, as opposed to routine upkeep: his clearest memory per thing, minus eating/drinking/sleeping."""
        upkeep = {n.lower() for need in ("thirst", "hunger", "fatigue") for n in self.s.extra.get("relief", {}).get(need, [])}
        best: dict = {}
        for m in self._live_memories():
            if m["source"] not in ("direct_observation", "self_action"):
                continue
            if day and m["time"][:10] != day:
                continue
            if int(m["id"].split("_")[1]) <= after_id:
                continue
            low = m["text"].lower()
            if any(k in low for k in ("noticing how my body felt", "checking my hands")) or any(f"using the {n}:" in low for n in upkeep):
                continue
            key = m.get("subject") or m["id"]
            if key not in best or m["confidence"] > best[key]["confidence"]:
                best[key] = m
        before = {m.get("subject") for m in self._live_memories() if m.get("subject") and day and m["time"][:10] < day}
        top = sorted(best.values(), key=lambda m: -(m["confidence"] - (0.3 if m.get("subject") in before else 0.0)))[:limit]
        return sorted(top, key=lambda m: m["time"])

    def day_facts(self, day: str) -> list:
        """Short first-person facts about one simulated day, taken ONLY from my own record of it: what happened, not tallies."""
        notable = self.notable_memories(day=day, limit=8)
        changes = [m for m in notable if m["text"].startswith("I remember noticing a change")]
        out = [self.as_fact(m["text"]) for m in notable if m not in changes][:6]
        if changes:                                                     # sounds and weather: one line, not one per sound
            out.append("I noticed the world change around me - " + "; ".join(
                re.sub(r"^I remember noticing a change:\s*", "", m["text"]).rstrip(".…") for m in changes[:3]))
        for g in self.s.goals:
            if g.get("source") == "person" and str(g.get("finished", ""))[:10] == day:
                out.append(f"I finished what the person asked of me: {g['text']}")
        mems = [m for m in self._live_memories() if m["time"][:10] == day]
        qs = [re.match(r'The person asked me: "(.*?)"(?: and I answered|$)', m["text"]) for m in mems if m["source"] == "conversation"]
        qs = [q.group(1) for q in qs if q]
        told = [re.match(r'The person told me: "(.*)"$', m["text"]) for m in mems if m["source"] == "hearsay"]
        told = [t.group(1) for t in told if t]
        if qs:
            out.append(f"The person asked me {len(qs)} question{'s' if len(qs) > 1 else ''}, including \"{qs[-1][:70]}\"")
        if told:
            out.append(f"The person told me: \"{told[-1][:80]}\"")
        acts = self._collapse_acts(list(self.s.extra.get("day_acts", {}).get(day, {}).items()), keep_total=True)
        if acts and acts[0][1] >= 4:                                   # one line about the rhythm of the day, never a tally
            out.append(f"For much of the day I {acts[0][0]}")
        from datetime import date, timedelta
        recent = (date.fromisoformat(day) - timedelta(days=1)).isoformat()
        wondering = [u["question"] for u in self.s.uncertainties if u["status"] == "open" and str(u.get("raised", ""))[:10] >= recent]
        if wondering:
            q = wondering[-1].rstrip("?. ")
            out.append(f"I'm still wondering: {q[:1].lower() + q[1:]}?")
        dedup, keys = [], set()
        for f in out:
            if f.lower() not in keys:
                keys.add(f.lower())
                dedup.append(f)
        return dedup

    def add_diary(self, day: str, text: str):
        mid = f"m_{self._next('memory'):04d}"
        self.s.memories.append({"id": mid, "time": self.now, "text": f"Diary, {day}: {text}", "confidence": 0.85, "source": "diary",
                                "subject": None, "place": None, "percept_keys": [], "event_ids": [], "incomplete": False,
                                "recalled": 0, "last_recalled": None, "tags": ["diary", "day", "yesterday", "night", "morning"]})
        self._changed("memories", f"{mid}: diary for {day}")

    # ------------------------------------------------------------------ attempts (for autonomy)
    def note_activity(self, kind: str, when: str):
        log = self.s.extra.setdefault("activity", [])
        log.append([when, kind])
        del log[:-150]

    def note_attempt(self, cmd: str, name: str, ok: bool):
        if not ok:
            self.s.extra.setdefault("last_fail", {})[f"{cmd}:{name}"] = self.now
        bucket = self.s.extra.setdefault("attempts" if ok else "failures", {})
        k = f"{cmd}:{name}"
        bucket[k] = bucket.get(k, 0) + 1
        if ok and cmd == "use":                                  # it works now: old failures (empty, locked...) no longer count
            self.s.extra.get("failures", {}).pop(k, None)
        if ok:
            self.s.extra.setdefault("last_att", {})[k] = self.now
        self._check_goals()

    # ------------------------------------------------------------------ context for the brain
    def snapshot(self) -> dict:
        s = self.s
        recent = [{"text": m["text"], "confidence": self.effective_confidence(m)}
                  for m in self._live_memories()[-5:]]
        return {
            "identity": dict(s.identity), "location": dict(s.current_location), "activity": s.current_activity,
            "inventory": [self._name(i) for i in s.inventory],
            "goals": [g["text"] for g in s.goals if g["status"] == "active"],
            "goal_acts": [{"id": g["id"], "text": g["text"], **g["act"], "progress": self.goal_progress(g)}
                          for g in s.goals if g.get("source") == "person" and g["status"] == "active" and g.get("act")],
            "open_uncertainties": [{"question": u["question"], "notes": u["notes"]} for u in s.uncertainties
                                   if u["status"] == "open"],
            "beliefs": [{"text": b["text"], "confidence": b["confidence"]} for b in s.beliefs
                        if b["attr"] != "location" and not b["about"].startswith("link:")][-8:]
                       + [{"text": b["text"], "confidence": b["confidence"]} for b in s.beliefs
                          if b["about"].startswith("link:")][-3:],
            "recent_memories": recent,
            "known_objects": [{"name": o.get("name") or oid, "held": o.get("held", False), "inspections": o.get("inspections", 0),
                               "uses": o.get("uses", 0), "portable": o.get("looks_portable", False),
                               "room": o.get("room"), "place_label": o.get("place_label"), "hint": o.get("hint", "")}
                              for oid, o in s.known_objects.items()],
            "flags": dict(s.flags),
            "needs": {n: v["band"] for n, v in s.needs.items()},
            "relief": {n: list(v) for n, v in s.extra.get("relief", {}).items()},
            "states": {self._name(b["about"]): b["value"] for b in s.beliefs
                       if b["attr"] == "state" and b["about"] in s.known_objects},
            "last_light": (s.recent_observations[-1]["light"] if s.recent_observations else None),
            "tally": self._collapse_acts(list(s.extra.get("activity_totals", {}).items()), keep_total=True)[:10],
            "since": (s.memories[0]["time"] if s.memories else self.now),
            "now": self.now, "last_fail": dict(s.extra.get("last_fail", {})),
            "attempts": dict(s.extra.get("attempts", {})), "failures": dict(s.extra.get("failures", {})),
            "last_att": dict(s.extra.get("last_att", {})), "room_last": dict(s.extra.get("room_last", {})),
            "tags": dict(s.extra.get("act_tags", {})),
            "rooms": {rid: p.get("label", rid) for rid, p in s.known_places.items() if p.get("kind") == "room"},
            "spots": [{"label": p.get("label", ""), "room": p.get("room")} for p in s.known_places.values() if p.get("kind") == "spot"],
            "stale": self._stale_names(),
        }

    def _stale_names(self) -> list:
        """Things I once looked at whose memory has faded below recall: the honest reason to go and look again."""
        best: dict = {}
        for m in self._live_memories():
            if m.get("subject") and m["source"] in ("direct_observation", "self_action"):
                best[m["subject"]] = max(best.get(m["subject"], 0.0), self.effective_confidence(m))
        faded = sorted((c, oid) for oid, c in best.items() if c < 0.2 and oid in self.s.known_objects)
        return [self._name(oid) for _, oid in faded]

    def build_context(self, intent: str, obs: Optional[Observation] = None, delta: Optional[Delta] = None,
                      utterance: Optional[str] = None, evidence: Optional[list] = None,
                      action_result: Optional[dict] = None, notes: Optional[list] = None,
                      fresh_extra: Optional[list] = None) -> BrainContext:
        observation = None
        if obs is not None:
            observation = {"kind": obs.kind, "subject_label": obs.subject_label, "room_label": obs.room_label,
                           "light": obs.light,
                           "percepts": [{"key": p.key, "text": p.text, "attach_to": p.attach_to, "kind": p.kind,
                                         "narrate": p.narrate} for p in obs.percepts]}
        learned = {}
        if delta is not None:
            learned = {"new": [p.text for p in delta.new], "upgraded": [p.text for p in delta.upgraded],
                       "new_keys": [p.key for p in delta.new] + list(fresh_extra or []),
                       "upgraded_keys": [p.key for p in delta.upgraded],
                       "nothing_new": not delta.learned_something}
        return BrainContext(intent=intent, time=self.now, cs=self.snapshot(), observation=observation,
                            learned=learned, recognitions=(delta.recognitions if delta else []),
                            evidence=evidence or [], utterance=utterance, action_result=action_result or {},
                            notes=notes or (delta.voice if delta and intent == "wake" else []))


# ####################################################################################################
##### SECTION: narrator
# ####################################################################################################

"""NARRATOR: invents places the author did not script.

Why a separate component?  The character's brain must never create world facts, or the line between "what is
true" and "what they believe" blurs.  The Narrator is on the WORLD side: when the character first enters a room
marked `improvise` (a place with a "to be imagined" seed in the setup), the Narrator is asked to invent it.  Whatever it
returns is validated, written into the world as ordinary rooms/spots/objects (and saved in the save file), and the
character then perceives it like anything else.  The same place therefore looks the same every time, and survives save/load.

    MockNarrator    deterministic, template-based (seeded) - needs nothing
    PromptNarrator  wraps any `complete(prompt) -> str` (e.g. a local GGUF); it must return JSON, which is
                    validated and clamped; anything malformed falls back to MockNarrator.

Narrator input is WORLD information only: the author's seed text, the time of day, what already exists.
"""

import json
import random
import re
from abc import ABC, abstractmethod
from typing import Callable, Optional


MAX_SPOTS, MAX_OBJECTS, MAX_DETAILS, MAX_TEXT = 3, 5, 2, 220


class Narrator(ABC):
    name = "narrator"

    def generate_plot(self, title: str) -> dict:
        return mock_plot(title)

    @abstractmethod
    def generate_place(self, req: dict) -> dict:
        """req: {room_id, name, seed, time_of_day, existing: [names]} -> see PLACE SCHEMA in apply_generated."""


# --------------------------------------------------------------------------- templates
def O(name, aliases, near, far, details, kind="item", portable=False, spot=0):
    return {"name": name, "aliases": aliases, "kind": kind, "portable": portable, "near_text": near,
            "far_text": far, "details": [{"text": t, "gist": g} for t, g in details], "spot": spot}


